// ユーザーの市区町村訪問履歴から「都道府県コンプリートバッジ（同県内で3都市以上訪問で県マスター獲得）」＋「特別称号バッジ」を計算する関数
const computeEarnedTitleBadges = (municipalBadges = []) => {
  const safeBadges = Array.isArray(municipalBadges) ? municipalBadges : [];
  const unlockedList = [];

  // 1) 特別・地方・シークレット称号の判定
  SPECIAL_TITLE_BADGES.forEach(tb => {
    const isUnlocked = tb.checkUnlocked(safeBadges);
    const prog = tb.getProgress(safeBadges);
    if (isUnlocked) {
      unlockedList.push({
        ...tb,
        isUnlocked: true,
        progress: prog
      });
    }
  });
  // 2) 各都道府県コンプリートバッジ（その都道府県の全市区町村すべてを訪問し終えた時のみ「〇〇県コンプリート」バッジが解放）
  const byPref = {};
  safeBadges.forEach(b => {
    if (!b.prefecture) return;
    if (!byPref[b.prefecture]) byPref[b.prefecture] = [];
    byPref[b.prefecture].push(b);
  });

  Object.keys(byPref).forEach(pref => {
    const list = byPref[pref];
    const totalMuniCount = OFFICIAL_MUNICIPALITY_COUNT_BY_PREF[pref] || (FULL_MUNICIPALITIES_BY_PREF[pref] || []).length || 30;
    if (list.length >= totalMuniCount) {
      const meta = getPrefMeta(pref);
      unlockedList.push({
        id: `title_pref_${pref}`,
        category: 'prefecture',
        rarity: 'UR',
        icon: meta.icon,
        name: `${pref}コンプリート`,
        condHint: `${pref}の全${totalMuniCount}市区町村をすべて完全制覇！`,
        secretHint: `${pref}内の全${totalMuniCount}市区町村をすべて訪れる`,
        color: meta.color,
        isUnlocked: true,
        progress: { current: list.length, max: totalMuniCount, label: `${list.length}/${totalMuniCount}全制覇` }
      });
    }
  });

  return unlockedList;
};

