// ★ 自宅の最寄り駅ラベルを取得するヘルパー
const getHomeDepartureLabel = (user) => {
  return user?.station
    ? `${user.station}（自宅・最寄り駅）`
    : user?.residence && user.residence !== '未設定'
    ? `${user.residence}${user.city || ''}（自宅）`
    : '東京駅（自宅・最寄り駅）';
};

// ★ よく使う出発地点（自分が登録したお気に入り出発地のみ・初期状態は空）を取得・保存するヘルパー
const getSavedDeparturePoints = () => {
  const saved = safeParse('tabitabi_saved_departures_user', []);
  return Array.isArray(saved) ? saved : [];
};

const addSavedDeparturePoint = (pointStr) => {
  const clean = (pointStr || '').trim();
  if (!clean) return;
  try {
    const saved = getSavedDeparturePoints();
    const next = Array.from(new Set([clean, ...saved])).slice(0, 15);
    localStorage.setItem('tabitabi_saved_departures_user', JSON.stringify(next));
  } catch (e) {}
};

const removeSavedDeparturePoint = (pointStr) => {
  try {
    const saved = getSavedDeparturePoints();
    const next = saved.filter(item => item !== pointStr);
    localStorage.setItem('tabitabi_saved_departures_user', JSON.stringify(next));
    return next;
  } catch (e) {
    return [];
  }
};

// ★ Yahoo!ショッピングの配送先選択風に「🏠 自宅（最寄り駅）」「⭐ 登録先」「✏️ その他」を直感的に選べるコンポーネント
function DepartureSelectorBox({
  user,
  value,
  onChange,
  saveForNext,
  onChangeSaveForNext,
  extraQuickPoint = '',
  extraQuickLabel = '直前の予定地',
  label = '出発地点',
  compact = false
}) {
  const homePoint = useMemo(() => getHomeDepartureLabel(user), [user]);
  const [savedPoints, setSavedPoints] = useState(() => getSavedDeparturePoints());

  useEffect(() => {
    setSavedPoints(getSavedDeparturePoints());
  }, [value]);

  const [mode, setMode] = useState(() => {
    if (!value || value === homePoint) return 'home';
    if (extraQuickPoint && value === extraQuickPoint) return 'prev';
    if (savedPoints.includes(value)) return 'saved';
    return 'custom';
  });

  const handleSelectMode = (nextMode) => {
    const latestSaved = getSavedDeparturePoints();
    setSavedPoints(latestSaved);
    setMode(nextMode);
    if (nextMode === 'home') {
      onChange(homePoint);
      if (onChangeSaveForNext) onChangeSaveForNext(false);
    } else if (nextMode === 'prev' && extraQuickPoint) {
      onChange(extraQuickPoint);
      if (onChangeSaveForNext) onChangeSaveForNext(false);
    } else if (nextMode === 'saved') {
      if (latestSaved.length > 0) {
        const target = latestSaved.includes(value) ? value : latestSaved[0];
        onChange(target);
      }
      if (onChangeSaveForNext) onChangeSaveForNext(false);
    } else if (nextMode === 'custom') {
      if (value === homePoint || latestSaved.includes(value) || value === extraQuickPoint) {
        onChange('');
      }
    }
  };

  const handleDeleteSaved = (targetPt) => {
    const nextList = removeSavedDeparturePoint(targetPt);
    setSavedPoints(nextList);
    if (nextList.length > 0) {
      onChange(nextList[0]);
    } else {
      onChange(homePoint);
    }
    customAlert(`「${targetPt}」を登録先から削除しました`);
  };

  return (
    <div className={`${compact ? 'p-2.5 space-y-1.5' : 'p-3 space-y-2'} bg-stone-50/90 border border-stone-200/90 rounded-2xl overflow-hidden`}>
      <div className="flex items-center justify-between gap-2 min-w-0">
        <span className="text-xs font-extrabold text-stone-700 flex items-center gap-1 shrink-0">
          <Navigation size={12} className="text-[#7A9D8C] shrink-0" /> {label}
        </span>
        {mode === 'home' ? (
          <span className="text-[11px] font-extrabold text-[#4A6B5D] bg-[#7A9D8C]/15 px-2 py-0.5 rounded-full truncate">
            🏠 {homePoint.replace(/（.*?）/g, '')}
          </span>
        ) : mode === 'prev' && extraQuickPoint ? (
          <span className="text-[11px] font-extrabold text-sky-800 bg-sky-100 px-2 py-0.5 rounded-full truncate">
            📍 {extraQuickPoint}
          </span>
        ) : savedPoints.length > 0 ? (
          <span className="text-[10px] font-bold text-stone-400 shrink-0">
            登録済 {savedPoints.length}件
          </span>
        ) : null}
      </div>

      {/* セグメントタブ（スマホでも文字が「自...」と切れないよう、4項目の時は見やすい2列×2段グリッドに自動最適化） */}
      <div className={`grid ${extraQuickPoint ? 'grid-cols-2 sm:grid-cols-4' : 'grid-cols-3'} gap-1.5 bg-stone-200/75 p-1 rounded-xl`}>
        <button
          type="button"
          onClick={() => handleSelectMode('home')}
          className={`py-1.5 px-2 rounded-lg text-[11px] font-extrabold transition-all flex items-center justify-center gap-1 whitespace-nowrap ${
            mode === 'home'
              ? 'bg-white text-[#4A6B5D] shadow-xs ring-1 ring-[#7A9D8C]/35'
              : 'text-stone-600 hover:text-stone-800'
          }`}
        >
          <span>🏠 自宅</span>
        </button>

        {extraQuickPoint && (
          <button
            type="button"
            onClick={() => handleSelectMode('prev')}
            className={`py-1.5 px-2 rounded-lg text-[11px] font-extrabold transition-all flex items-center justify-center gap-1 whitespace-nowrap ${
              mode === 'prev'
                ? 'bg-white text-[#4A6B5D] shadow-xs ring-1 ring-[#7A9D8C]/35'
                : 'text-stone-600 hover:text-stone-800'
            }`}
          >
            <span>📍 {extraQuickLabel}</span>
          </button>
        )}

        <button
          type="button"
          onClick={() => handleSelectMode('saved')}
          className={`py-1.5 px-2 rounded-lg text-[11px] font-extrabold transition-all flex items-center justify-center gap-1 whitespace-nowrap ${
            mode === 'saved'
              ? 'bg-white text-[#4A6B5D] shadow-xs ring-1 ring-[#7A9D8C]/35'
              : 'text-stone-600 hover:text-stone-800'
          }`}
        >
          <span>⭐ 登録先{savedPoints.length > 0 ? `(${savedPoints.length})` : ''}</span>
        </button>

        <button
          type="button"
          onClick={() => handleSelectMode('custom')}
          className={`py-1.5 px-2 rounded-lg text-[11px] font-extrabold transition-all flex items-center justify-center gap-1 whitespace-nowrap ${
            mode === 'custom'
              ? 'bg-white text-[#4A6B5D] shadow-xs ring-1 ring-[#7A9D8C]/35'
              : 'text-stone-600 hover:text-stone-800'
          }`}
        >
          <span>✏️ その他</span>
        </button>
      </div>

      {/* ⭐登録先 または ✏️その他 のときだけ下段を展開して省スペース化 */}
      {mode === 'saved' && (
        savedPoints.length === 0 ? (
          <div className="px-3 py-2 bg-white rounded-xl border border-dashed border-stone-300 flex items-center justify-between gap-2">
            <span className="text-xs font-bold text-stone-500 truncate">
              まだ登録された出発先がありません
            </span>
            <button
              type="button"
              onClick={() => {
                handleSelectMode('custom');
                if (onChangeSaveForNext) onChangeSaveForNext(true);
              }}
              className="px-2.5 py-1 bg-[#7A9D8C]/15 hover:bg-[#7A9D8C]/25 text-[#4A6B5D] rounded-lg text-xs font-extrabold shrink-0 transition-colors"
            >
              ＋ 登録する
            </button>
          </div>
        ) : (
          <div className="flex items-center gap-1.5">
            <select
              value={savedPoints.includes(value) ? value : savedPoints[0]}
              onChange={e => onChange(e.target.value)}
              className="flex-1 min-w-0 p-2 bg-white border border-stone-200 rounded-xl text-xs font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
            >
              {savedPoints.map(pt => (
                <option key={pt} value={pt}>⭐ {pt}</option>
              ))}
            </select>
            <button
              type="button"
              onClick={() => handleDeleteSaved(savedPoints.includes(value) ? value : savedPoints[0])}
              className="p-2 bg-white hover:bg-red-50 text-stone-400 hover:text-red-500 border border-stone-200 rounded-xl shrink-0 transition-colors"
              title="選択中の登録先を削除"
            >
              <Trash2 size={14} />
            </button>
          </div>
        )
      )}

      {mode === 'custom' && (
        <div className="space-y-1.5 animate-in fade-in duration-150">
          <StationSearchInput
            value={value}
            onChange={(val) => onChange(val)}
            placeholder="駅名・空港・ホテル名を入力 (駅名は自動候補表示)"
            allowCustomText
            compact
          />
          {onChangeSaveForNext && (
            <label className="flex items-center gap-2 text-[11px] font-bold text-[#557465] cursor-pointer pl-1 select-none">
              <input
                type="checkbox"
                checked={Boolean(saveForNext)}
                onChange={e => onChangeSaveForNext(e.target.checked)}
                className="w-3.5 h-3.5 rounded accent-[#7A9D8C]"
              />
              <span>「⭐ 登録先」に保存して次回も使う</span>
            </label>
          )}
        </div>
      )}
    </div>
  );
}

// ★ モーダル・ポップアップ表示中に背景のスクロールや揺れを完全にロックするカスタムフック
function useLockBodyScroll(isLocked = true) {
  useEffect(() => {
    if (!isLocked || typeof document === 'undefined') return;
    const originalOverflow = document.body.style.overflow;
    const originalOverflowX = document.body.style.overflowX;
    const originalOverscroll = document.body.style.overscrollBehavior;
    const htmlOverflowX = document.documentElement.style.overflowX;
    document.body.style.overflow = 'hidden';
    document.body.style.overflowX = 'hidden';
    document.body.style.overscrollBehavior = 'none';
    document.documentElement.style.overflowX = 'hidden';
    return () => {
      document.body.style.overflow = originalOverflow;
      document.body.style.overflowX = originalOverflowX;
      document.body.style.overscrollBehavior = originalOverscroll;
      document.documentElement.style.overflowX = htmlOverflowX;
    };
  }, [isLocked]);
}

