const initialNotifications = [];

// --- Utils ---
const generateId = () => Math.random().toString(36).substr(2, 9);
const generateTripCode = () => 'TABI-' + Math.random().toString(36).substr(2, 8).toUpperCase();
const getTodayString = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
const safeParse = (key, fallback) => { try { const item = localStorage.getItem(key); return item ? JSON.parse(item) : fallback; } catch (e) { return fallback; } };

// ==========================================
// ★ Supabase クラウド共有エンジン（写真はクラウドに保存せずテキスト＆軽量アバターのみ同期）
// ==========================================
const getSupabaseCredentials = () => {
  try {
    const rawUrl =
      (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_SUPABASE_URL) ||
      (typeof window !== 'undefined' && window.__SUPABASE_URL__) ||
      '';
    const rawKey =
      (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_SUPABASE_ANON_KEY) ||
      (typeof window !== 'undefined' && window.__SUPABASE_ANON_KEY__) ||
      '';
    const url = String(rawUrl).trim().replace(/^['"]|['"]$/g, '').replace(/\/+$/, '');
    const key = String(rawKey).trim().replace(/^['"]|['"]$/g, '');
    return { url, key, enabled: Boolean(url && key) };
  } catch (e) {
    return { url: '', key: '', enabled: false };
  }
};

// ★ 重要：Supabaseの新しい `sb_publishable_...` キーは JWT ではないため、
// Authorization: Bearer にそのまま入れると 401 Invalid JWT エラーで弾かれます。
// eyJ... で始まる従来キーの時のみ Authorization ヘッダーを付与し、両方のキー形式に完全対応させます。
const buildSupabaseHeaders = (key, extraHeaders = {}) => {
  const headers = {
    apikey: key,
    ...extraHeaders
  };
  if (key && key.startsWith('eyJ')) {
    headers.Authorization = `Bearer ${key}`;
  }
  return headers;
};

// LINEの招待文まるごとペーストや全角ハイフン・空白混入から「TABI-XXXXXXXX」を正確に抜き出すヘルパー
const normalizeInviteCode = (rawInput) => {
  const str = String(rawInput || '')
    .toUpperCase()
    .replace(/[ー−―‐]/g, '-')
    .trim();
  const match = str.match(/TABI-[A-Z0-9]{4,12}/);
  if (match) return match[0];
  return str.replace(/\s+/g, '');
};

// クラウドに保存するしおりデータから「思い出写真（photos）」を除外し、メンバーのアバターは軽量サイズで残すサニタイズ関数
const stripTripPhotosForCloud = (trip) => {
  if (!trip || typeof trip !== 'object') return trip;
  const cleanEvents = (trip.events || []).map(({ photos, ...restEvent }) => ({
    ...restEvent,
    photos: []
  }));
  const cleanMembers = (trip.members || []).map((m) => ({
    id: m.id,
    name: m.name,
    color: m.color || '#7A9D8C',
    avatar: m.avatar && String(m.avatar).length < 45000 ? m.avatar : ''
  }));
  const { photos, ...restTrip } = trip;
  return {
    ...restTrip,
    members: cleanMembers,
    events: cleanEvents,
    photos: []
  };
};

// クラウドから同期した際、自分のスマホ内に保存されている思い出写真を消さずにマージする関数
const mergeCloudTripWithLocalPhotos = (cloudTrip, localTrip) => {
  if (!localTrip) return cloudTrip;
  const localEventsMap = new Map((localTrip.events || []).map((ev) => [ev.id, ev]));
  const mergedEvents = (cloudTrip.events || []).map((cEv) => {
    const lEv = localEventsMap.get(cEv.id);
    return {
      ...cEv,
      photos: Array.isArray(lEv?.photos) ? lEv.photos : []
    };
  });
  return {
    ...cloudTrip,
    events: mergedEvents,
    photos: Array.isArray(localTrip.photos) ? localTrip.photos : []
  };
};

const syncSharedTripToCloud = async (trip) => {
  const { url, key, enabled } = getSupabaseCredentials();
  if (!enabled || !trip || trip.isSoloTrip) {
    return { ok: false, reason: !enabled ? 'ENV_MISSING' : 'SOLO_TRIP' };
  }
  const cleanCode = normalizeInviteCode(trip.id);
  const payload = stripTripPhotosForCloud({ ...trip, id: cleanCode });
  const nowIso = new Date().toISOString();

  // パターン1：万能テーブル（idがuuidで、code / invite_code / share_code / data / trip_data カラムがある場合）
  try {
    const resUniversal = await fetch(`${url}/rest/v1/shared_trips?on_conflict=code`, {
      method: 'POST',
      headers: buildSupabaseHeaders(key, {
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates,return=minimal'
      }),
      body: JSON.stringify({
        code: cleanCode,
        invite_code: cleanCode,
        share_code: cleanCode,
        data: payload,
        trip_data: payload,
        trip: payload,
        updated_at: nowIso
      })
    });
    if (resUniversal.ok) {
      return { ok: true };
    }
  } catch (e) {
    // フォールバックへ進む
  }

  // パターン2：invite_code のみがあるテーブル構造の場合
  try {
    const resInvite = await fetch(`${url}/rest/v1/shared_trips?on_conflict=invite_code`, {
      method: 'POST',
      headers: buildSupabaseHeaders(key, {
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates,return=minimal'
      }),
      body: JSON.stringify({
        invite_code: cleanCode,
        trip_data: payload,
        updated_at: nowIso
      })
    });
    if (resInvite.ok) {
      return { ok: true };
    }
  } catch (e) {
    // フォールバックへ進む
  }

  // パターン3：id カラムが text 型で主キーになっているテーブル構造の場合
  try {
    const resIdText = await fetch(`${url}/rest/v1/shared_trips?on_conflict=id`, {
      method: 'POST',
      headers: buildSupabaseHeaders(key, {
        'Content-Type': 'application/json',
        Prefer: 'resolution=merge-duplicates,return=minimal'
      }),
      body: JSON.stringify({
        id: cleanCode,
        data: payload,
        updated_at: nowIso
      })
    });
    if (resIdText.ok) {
      return { ok: true };
    }
    const errText = await resIdText.text().catch(() => '');
    console.error('Supabase sync error:', resIdText.status, errText);
    return { ok: false, status: resIdText.status, error: errText };
  } catch (e) {
    console.error('Supabase sync network error:', e);
    return { ok: false, error: e?.message || 'NETWORK_ERROR' };
  }
};

const fetchSharedTripFromCloud = async (tripCode) => {
  const { url, key, enabled } = getSupabaseCredentials();
  const cleanCode = normalizeInviteCode(tripCode);
  if (!enabled || !cleanCode) return null;

  const extractTripDataFromRow = (row) => {
    if (!row || typeof row !== 'object') return null;
    return row.data || row.trip_data || row.trip || null;
  };

  // 1) まず code / invite_code / share_code カラムのいずれかで検索（idがuuid型でもエラーにならない安全なクエリ）
  const candidateQueries = [
    `code=eq.${encodeURIComponent(cleanCode)}`,
    `invite_code=eq.${encodeURIComponent(cleanCode)}`,
    `share_code=eq.${encodeURIComponent(cleanCode)}`,
    `id=eq.${encodeURIComponent(cleanCode)}`
  ];

  for (const queryFilter of candidateQueries) {
    try {
      const res = await fetch(
        `${url}/rest/v1/shared_trips?${queryFilter}&select=*&limit=1`,
        {
          headers: buildSupabaseHeaders(key)
        }
      );
      if (!res.ok) continue;
      const rows = await res.json();
      if (Array.isArray(rows) && rows.length > 0) {
        const extracted = extractTripDataFromRow(rows[0]);
        if (extracted) return extracted;
      }
    } catch (e) {
      // 次のカラム候補を試す
    }
  }

  return null;
};

// ★ 共有できない原因をその場で特定するためのクラウド接続診断関数（どんなカラム構成のshared_tripsでも正しくOK判定）
const diagnoseSupabaseConnection = async () => {
  const { url, key, enabled } = getSupabaseCredentials();
  if (!enabled) {
    return {
      ok: false,
      code: 'ENV_MISSING',
      message: '環境変数（VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY）が読み込まれていません。VercelやStackBlitzの環境変数設定を確認してください。'
    };
  }
  try {
    // 特定カラム名に依存しない select=* でテーブルの存在と権限を診断
    const res = await fetch(`${url}/rest/v1/shared_trips?select=*&limit=1`, {
      headers: buildSupabaseHeaders(key)
    });
    if (res.ok) {
      return {
        ok: true,
        code: 'CONNECTED',
        message: 'クラウド共有サーバー（Supabase）と正常に接続されています！リアルタイム共有が可能です。'
      };
    }
    const errText = await res.text().catch(() => '');
    if (res.status === 404 || errText.includes('PGRST205') || errText.includes('relation "public.shared_trips" does not exist')) {
      return {
        ok: false,
        code: 'TABLE_MISSING',
        message: 'Supabase内に「shared_trips」テーブルが見つからないか、スキーマキャッシュが未更新です。SQL Editorで作成SQLを実行してください。'
      };
    }
    if (res.status === 401 || res.status === 403 || errText.includes('JWT')) {
      return {
        ok: false,
        code: 'AUTH_OR_RLS_ERROR',
        message: `認証または権限エラー（HTTP ${res.status}）です。APIキーの値、またはRLSポリシー作成SQLが実行済みか確認してください。`
      };
    }
    return {
      ok: false,
      code: 'HTTP_ERROR',
      message: `サーバー応答エラー（HTTP ${res.status}）: ${errText.slice(0, 100)}`
    };
  } catch (e) {
    return {
      ok: false,
      code: 'NETWORK_ERROR',
      message: 'Supabase URLへの通信に失敗しました。VITE_SUPABASE_URLが「https://〇〇.supabase.co」の形式か確認してください。'
    };
  }
};

// スマホ標準の共有シート（AirDrop / LINE / メール等）で写真を直接共有するヘルパー
const sharePhotoViaNativeSheet = async (photoUrl, title = '旅の思い出写真') => {
  try {
    if (navigator.share) {
      if (photoUrl.startsWith('data:')) {
        const res = await fetch(photoUrl);
        const blob = await res.blob();
        const file = new File([blob], `tabitabi_memory_${Date.now()}.jpg`, { type: blob.type || 'image/jpeg' });
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
          await navigator.share({
            files: [file],
            title
          });
          return;
        }
      }
      await navigator.share({
        title,
        text: `${title}（たびたび）`,
        url: photoUrl.startsWith('http') ? photoUrl : window.location.href
      });
      return;
    }
  } catch (e) {
    if (e?.name === 'AbortError') return;
  }
  const lineUrl = `https://line.me/R/msg/text/?${encodeURIComponent(`${title}\n${photoUrl.startsWith('http') ? photoUrl : '※スマホの共有メニューまたは長押し保存からLINE・AirDropで送信できます'}`)}`;
  window.open(lineUrl, '_blank', 'noopener,noreferrer');
};

// ==========================================
// ★ ドラムロール式ホイール日付選択コンポーネント (WheelDateRangePicker)
// 上が「出発日：YYYY年M月D日(曜)」、下が「最終日：YYYY年M月D日(曜)」（時間表示なし）
// タップするとその行のすぐ下にクルクル回せるドラムロール式ホイール（「11月10日 火」形式・時間なし）がスッと開く
// ==========================================
const WEEKDAY_JA = ['日', '月', '火', '水', '木', '金', '土'];

const formatJapaneseDateWithDay = (dateStr) => {
  if (!dateStr) return '未設定';
  const parts = String(dateStr).split('-');
  if (parts.length !== 3) return dateStr;
  const y = Number(parts[0]);
  const m = Number(parts[1]);
  const d = Number(parts[2]);
  if (isNaN(y) || isNaN(m) || isNaN(d)) return dateStr;
  const dt = new Date(y, m - 1, d);
  const w = WEEKDAY_JA[dt.getDay()] || '';
  return `${y}年${m}月${d}日(${w})`;
};

function WheelDateRangePicker({
  startDate,
  endDate,
  onChangeStart,
  onChangeEnd,
  singleDateMode = false,
  startLabel = '出発日',
  endLabel = '最終日',
  compact = false
}) {
  const safeStart = startDate || getTodayString();
  const safeEnd = singleDateMode ? safeStart : (endDate && endDate >= safeStart ? endDate : safeStart);

  const [isOpen, setIsOpen] = useState(false);
  // カレンダー内で選択中の仮日程（決定ボタンを押すまで確定しない）
  const [draftStart, setDraftStart] = useState(safeStart);
  const [draftEnd, setDraftEnd] = useState(safeEnd);
  // 'pick_start': 出発日を選択中 / 'pick_end': 最終日を選択中 / 'confirm_ready': 区間選択完了（確認・決定待ち）
  const [selectingPhase, setSelectingPhase] = useState('confirm_ready');

  const initialMonthParts = safeStart.split('-').map(Number);
  const [viewYear, setViewYear] = useState(() => initialMonthParts[0] || new Date().getFullYear());
  const [viewMonth, setViewMonth] = useState(() => (initialMonthParts[1] || new Date().getMonth() + 1) - 1);

  useEffect(() => {
    const nextS = startDate || getTodayString();
    const nextE = singleDateMode ? nextS : (endDate && endDate >= nextS ? endDate : nextS);
    setDraftStart(nextS);
    setDraftEnd(nextE);
    const parts = nextS.split('-').map(Number);
    if (parts.length === 3 && !isNaN(parts[0]) && !isNaN(parts[1])) {
      setViewYear(parts[0]);
      setViewMonth(parts[1] - 1);
    }
  }, [startDate, endDate, singleDateMode]);

  const toDateStr = (y, mZero, d) =>
    `${y}-${String(mZero + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

  const calendarCells = useMemo(() => {
    const firstDayWeek = new Date(viewYear, viewMonth, 1).getDay();
    const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < firstDayWeek; i++) {
      cells.push(null);
    }
    for (let d = 1; d <= daysInMonth; d++) {
      cells.push({
        day: d,
        dateStr: toDateStr(viewYear, viewMonth, d),
        dow: (firstDayWeek + d - 1) % 7
      });
    }
    return cells;
  }, [viewYear, viewMonth]);

  const handlePrevMonth = () => {
    if (viewMonth === 0) {
      setViewYear(y => y - 1);
      setViewMonth(11);
    } else {
      setViewMonth(m => m - 1);
    }
  };

  const handleNextMonth = () => {
    if (viewMonth === 11) {
      setViewYear(y => y + 1);
      setViewMonth(0);
    } else {
      setViewMonth(m => m + 1);
    }
  };

  // 日付セルをタップした時はカレンダーを閉じず、区間ハイライトを更新して確認状態にする
  const handleSelectDateCell = (clickedDateStr) => {
    if (singleDateMode) {
      setDraftStart(clickedDateStr);
      setDraftEnd(clickedDateStr);
      setSelectingPhase('confirm_ready');
      return;
    }

    if (selectingPhase === 'pick_start' || selectingPhase === 'confirm_ready') {
      // 1回目のタップ（または区間確認後の再タップ）：新しい出発日をセットし、次は最終日待ちへ
      setDraftStart(clickedDateStr);
      setDraftEnd(clickedDateStr);
      setSelectingPhase('pick_end');
    } else if (selectingPhase === 'pick_end') {
      if (clickedDateStr < draftStart) {
        // 出発日より前の日付をタップした場合は、その日を新しい出発日として設定し直す
        setDraftStart(clickedDateStr);
        setDraftEnd(clickedDateStr);
        setSelectingPhase('pick_end');
      } else {
        // 2回目のタップ：最終日をセットし、閉じずに区間プレビュー確認状態へ移行
        setDraftEnd(clickedDateStr);
        setSelectingPhase('confirm_ready');
      }
    }
  };

  // 「この日程で決定する」ボタンを押した時のみ親へ反映してカレンダーを閉じる
  const handleConfirmDates = () => {
    const finalStart = draftStart || safeStart;
    const finalEnd = singleDateMode ? finalStart : (draftEnd >= finalStart ? draftEnd : finalStart);
    if (onChangeStart) onChangeStart(finalStart);
    if (onChangeEnd) onChangeEnd(finalEnd);
    setIsOpen(false);
  };

  const handleCancelOpen = () => {
    setDraftStart(safeStart);
    setDraftEnd(safeEnd);
    setSelectingPhase('confirm_ready');
    setIsOpen(false);
  };

  const committedDiffDays = useMemo(() => {
    const s = new Date(safeStart);
    const e = new Date(safeEnd);
    const diff = Math.round((e - s) / 86400000) + 1;
    return isNaN(diff) || diff < 1 ? 1 : diff;
  }, [safeStart, safeEnd]);

  const draftDiffDays = useMemo(() => {
    const s = new Date(draftStart);
    const e = new Date(draftEnd);
    const diff = Math.round((e - s) / 86400000) + 1;
    return isNaN(diff) || diff < 1 ? 1 : diff;
  }, [draftStart, draftEnd]);

  return (
    <div
      data-no-swipe="true"
      className="bg-white rounded-2xl border border-stone-200/90 overflow-hidden shadow-2xs"
    >
      {/* 上部サマリーバー：タップでカレンダーを開閉 */}
      <button
        type="button"
        onClick={() => {
          if (!isOpen) {
            setDraftStart(safeStart);
            setDraftEnd(safeEnd);
            setSelectingPhase('pick_start');
            setIsOpen(true);
          } else {
            handleCancelOpen();
          }
        }}
        className={`w-full ${
          compact ? 'px-3 py-2' : 'px-3.5 py-2.5'
        } flex items-center justify-between gap-2 text-left hover:bg-stone-50/80 active:bg-stone-100/70 transition-colors cursor-pointer select-none`}
      >
        <div className="flex items-center gap-2 min-w-0 flex-1">
          <div className="w-7 h-7 rounded-xl bg-[#7A9D8C]/15 text-[#4A6B5D] flex items-center justify-center shrink-0">
            <Calendar size={14} />
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-1.5 text-[10px] font-extrabold text-stone-400">
              <span>{singleDateMode ? startLabel : `${startLabel} 〜 ${endLabel}`}</span>
              {!singleDateMode && (
                <span className="px-1.5 py-0.2 rounded-full bg-[#7A9D8C]/15 text-[#4A6B5D] text-[9px] font-extrabold">
                  {committedDiffDays <= 1 ? '日帰り' : `${committedDiffDays - 1}泊${committedDiffDays}日`}
                </span>
              )}
            </div>
            <div className="text-xs sm:text-sm font-extrabold text-stone-800 truncate mt-0.5">
              {singleDateMode ? (
                formatJapaneseDateWithDay(safeStart)
              ) : (
                <span>
                  {formatJapaneseDateWithDay(safeStart)} <span className="text-[#7A9D8C] mx-0.5">〜</span> {formatJapaneseDateWithDay(safeEnd)}
                </span>
              )}
            </div>
          </div>
        </div>
        <span className="px-2.5 py-1 rounded-xl bg-stone-100 text-stone-700 text-[11px] font-extrabold shrink-0">
          {isOpen ? '閉じる ▲' : 'カレンダー ▼'}
        </span>
      </button>

      {/* 展開される期間選択カレンダー（最初と最後をタップして区間を確認後、「決定」ボタンで確定） */}
      {isOpen && (
        <div className="p-3 bg-stone-50/80 border-t border-stone-200/80 space-y-2.5 animate-in fade-in duration-150">
          {/* 分かりやすい3ステップ案内＆選択中区間のプレビューボックス */}
          {!singleDateMode && (
            <div className="bg-white p-2.5 rounded-2xl border border-stone-200/90 shadow-2xs space-y-2">
              {/* 現在の操作ステップ案内バッジ */}
              <div className="flex items-center justify-between gap-1.5">
                <span
                  className={`text-[11px] font-extrabold px-2.5 py-0.5 rounded-full flex items-center gap-1 ${
                    selectingPhase === 'pick_start'
                      ? 'bg-[#7A9D8C] text-white'
                      : selectingPhase === 'pick_end'
                      ? 'bg-amber-500 text-white animate-pulse'
                      : 'bg-emerald-100 text-emerald-900 border border-emerald-300'
                  }`}
                >
                  {selectingPhase === 'pick_start' && 'STEP 1：まず「出発日」をタップ'}
                  {selectingPhase === 'pick_end' && 'STEP 2：続けて「最終日」をタップ'}
                  {selectingPhase === 'confirm_ready' && '✅ 区間を選択中（下の決定ボタンで確定）'}
                </span>

                {selectingPhase !== 'pick_start' && (
                  <button
                    type="button"
                    onClick={() => setSelectingPhase('pick_start')}
                    className="text-[10px] font-extrabold text-stone-500 hover:text-stone-800 underline shrink-0 cursor-pointer"
                  >
                    選び直す
                  </button>
                )}
              </div>

              {/* 出発日 ➔ 最終日 の視覚的プレビューカード */}
              <div className="grid grid-cols-2 gap-1.5">
                <button
                  type="button"
                  onClick={() => setSelectingPhase('pick_start')}
                  className={`p-2 rounded-xl border text-left transition-all cursor-pointer ${
                    selectingPhase === 'pick_start'
                      ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 ring-2 ring-[#7A9D8C]/25'
                      : 'border-stone-200 bg-stone-50/70 hover:bg-stone-100'
                  }`}
                >
                  <span className="text-[9px] font-extrabold text-stone-400 block">① {startLabel}</span>
                  <span className="text-xs font-extrabold text-stone-800 block mt-0.5">
                    {formatJapaneseDateWithDay(draftStart).replace(/^\d{4}年/, '')}
                  </span>
                </button>

                <button
                  type="button"
                  onClick={() => setSelectingPhase('pick_end')}
                  className={`p-2 rounded-xl border text-left transition-all cursor-pointer ${
                    selectingPhase === 'pick_end'
                      ? 'border-amber-500 bg-amber-50/80 ring-2 ring-amber-200'
                      : 'border-stone-200 bg-stone-50/70 hover:bg-stone-100'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-[9px] font-extrabold text-stone-400">② {endLabel}</span>
                    <span className="text-[9px] font-extrabold px-1.5 py-0.2 rounded-full bg-[#7A9D8C]/15 text-[#4A6B5D]">
                      {draftDiffDays <= 1 ? '日帰り' : `${draftDiffDays - 1}泊${draftDiffDays}日`}
                    </span>
                  </div>
                  <span className="text-xs font-extrabold text-stone-800 block mt-0.5">
                    {selectingPhase === 'pick_end'
                      ? '最終日をタップ...'
                      : formatJapaneseDateWithDay(draftEnd).replace(/^\d{4}年/, '')}
                  </span>
                </button>
              </div>
            </div>
          )}

          {/* 月送りヘッダー */}
          <div className="flex items-center justify-between px-1">
            <button
              type="button"
              onClick={handlePrevMonth}
              className="p-1.5 rounded-xl bg-white hover:bg-stone-100 border border-stone-200 text-stone-700 transition-colors active:scale-95 cursor-pointer"
            >
              <ChevronLeft size={16} />
            </button>
            <span className="text-xs sm:text-sm font-extrabold text-stone-800">
              {viewYear}年 {viewMonth + 1}月
            </span>
            <button
              type="button"
              onClick={handleNextMonth}
              className="p-1.5 rounded-xl bg-white hover:bg-stone-100 border border-stone-200 text-stone-700 transition-colors active:scale-95 cursor-pointer"
            >
              <ChevronRight size={16} />
            </button>
          </div>

          {/* 曜日ヘッダー */}
          <div className="grid grid-cols-7 text-center text-[10px] font-extrabold">
            {WEEKDAY_JA.map((w, idx) => (
              <span
                key={w}
                className={
                  idx === 0 ? 'text-rose-500' : idx === 6 ? 'text-sky-600' : 'text-stone-400'
                }
              >
                {w}
              </span>
            ))}
          </div>

          {/* 日付グリッド（出発日〜最終日の区間がひと目でわかる帯ハイライト表示） */}
          <div className="grid grid-cols-7 gap-y-1.5 text-center bg-white p-2 rounded-2xl border border-stone-200/70">
            {calendarCells.map((cell, idx) => {
              if (!cell) return <div key={`empty_${idx}`} className="h-9" />;
              const isStart = cell.dateStr === draftStart;
              const isEnd = cell.dateStr === draftEnd;
              const isSingleDayRange = isStart && isEnd;
              const isInRange = !singleDateMode && cell.dateStr > draftStart && cell.dateStr < draftEnd;
              const isSelectedEdge = isStart || isEnd;

              return (
                <div
                  key={cell.dateStr}
                  className={`relative h-9 flex items-center justify-center ${
                    isInRange
                      ? 'bg-[#7A9D8C]/20'
                      : isStart && !isSingleDayRange && !singleDateMode
                      ? 'bg-gradient-to-r from-transparent via-[#7A9D8C]/20 to-[#7A9D8C]/20 rounded-l-xl'
                      : isEnd && !isSingleDayRange && !singleDateMode
                      ? 'bg-gradient-to-l from-transparent via-[#7A9D8C]/20 to-[#7A9D8C]/20 rounded-r-xl'
                      : ''
                  }`}
                >
                  <button
                    type="button"
                    onClick={() => handleSelectDateCell(cell.dateStr)}
                    className={`w-full h-9 text-xs font-extrabold flex flex-col items-center justify-center relative transition-all cursor-pointer select-none ${
                      isSelectedEdge
                        ? 'bg-[#7A9D8C] text-white rounded-xl shadow-xs z-10 scale-105 ring-2 ring-white'
                        : isInRange
                        ? 'text-[#2F4F40] font-black'
                        : cell.dow === 0
                        ? 'text-rose-600 hover:bg-stone-100 rounded-xl'
                        : cell.dow === 6
                        ? 'text-sky-600 hover:bg-stone-100 rounded-xl'
                        : 'text-stone-700 hover:bg-stone-100 rounded-xl'
                    }`}
                  >
                    <span className="leading-none">{cell.day}</span>
                    {isSingleDayRange && !singleDateMode && (
                      <span className="text-[7px] leading-none mt-0.5 text-emerald-100 font-extrabold">
                        {selectingPhase === 'pick_end' ? '出発' : '日帰り'}
                      </span>
                    )}
                    {isStart && !isEnd && (
                      <span className="text-[7px] leading-none mt-0.5 text-emerald-100 font-extrabold">出発</span>
                    )}
                    {isEnd && !isStart && (
                      <span className="text-[7px] leading-none mt-0.5 text-emerald-100 font-extrabold">最終</span>
                    )}
                  </button>
                </div>
              );
            })}
          </div>

          {/* 下部：選択区間の確認メッセージ ＆ 決定ボタン */}
          <div className="pt-1 space-y-2">
            <div className="flex items-center justify-between text-[10px] font-bold text-stone-500 px-1">
              <span>
                {selectingPhase === 'pick_end'
                  ? '👆 最終日をタップしてください（同じ日で日帰り）'
                  : '💡 別の日にちをタップするとそのまま区間を選び直せます'}
              </span>
            </div>

            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={handleCancelOpen}
                className="px-3.5 py-2.5 rounded-xl bg-white hover:bg-stone-100 text-stone-600 border border-stone-200 text-xs font-extrabold transition-colors cursor-pointer shrink-0"
              >
                キャンセル
              </button>
              <button
                type="button"
                onClick={handleConfirmDates}
                className="flex-1 py-2.5 px-4 rounded-xl bg-[#7A9D8C] hover:bg-[#688a79] text-white text-xs font-extrabold shadow-sm flex items-center justify-center gap-1.5 transition-all active:scale-98 cursor-pointer"
              >
                <Check size={15} strokeWidth={2.8} />
                <span>
                  {singleDateMode
                    ? `${formatJapaneseDateWithDay(draftStart).replace(/^\d{4}年/, '')} で決定`
                    : `${draftStart.slice(5).replace('-', '/')}〜${draftEnd.slice(5).replace('-', '/')}（${
                        draftDiffDays <= 1 ? '日帰り' : `${draftDiffDays - 1}泊${draftDiffDays}日`
                      }）で決定`}
                </span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ==========================================
// ★ Google AI (Gemini API) コスト削減＆悪用防止エンジン
// ==========================================
// 1. 無料ユーザーの1日あたりの基本AI生成回数上限（いたずら連打・高額請求を100%防止）
const DAILY_AI_BASE_LIMIT = 5;
// 2. 動画広告を1本視聴したときに追加されるボーナス回数
const REWARD_AD_BONUS_COUNT = 3;
// 3. 定番エリア判定リスト（初回はAPIを叩かず高品質データ/キャッシュから0秒・0円で返却）
const POPULAR_CACHED_AREAS = ['京都', '沖縄', '宮古', '石垣', '那覇', '箱根', '神奈川', '北海道', '札幌', '小樽', '函館', '石川', '金沢', '福岡', '博多', '糸島', '広島', '宮島', '尾道', '三重', '伊勢', '志摩', '長野', '軽井沢', '松本', '大分', '別府', '由布院', '湯布院', '鎌倉', '江ノ島', '日光', '鬼怒川', '高山', '白川郷', '香川', '高松', '小豆島', '宮城', '仙台', '松島', '東京', '大阪', '熱海', '伊豆', '草津'];

// ★ 「⚡ 定番エリアは枠消費0」の i ボタンで表示する地方別ガイド一覧
const POPULAR_AREAS_GUIDE = [
  { region: '北海道・東北', areas: ['北海道（札幌・小樽・函館）', '宮城県（仙台・松島）'] },
  { region: '関東', areas: ['東京都', '神奈川県（箱根・鎌倉・江ノ島）', '栃木県（日光・鬼怒川）', '群馬県（草津温泉）'] },
  { region: '中部・北陸', areas: ['石川県（金沢）', '長野県（軽井沢・松本）', '静岡県（熱海・伊豆）', '岐阜県（飛騨高山・白川郷）'] },
  { region: '関西', areas: ['京都府', '大阪府', '三重県（伊勢・志摩）'] },
  { region: '中国・四国', areas: ['広島県（宮島・尾道）', '香川県（高松・小豆島）'] },
  { region: '九州・沖縄', areas: ['福岡県（博多・糸島）', '大分県（別府・由布院）', '沖縄県（那覇・宮古島・石垣島）'] }
];

const getAiQuotaStatus = () => {
  const today = getTodayString();
  const saved = safeParse('tabitabi_ai_quota', { date: today, used: 0, bonus: 0 });
  if (!saved || saved.date !== today) {
    const reset = { date: today, used: 0, bonus: 0 };
    try { localStorage.setItem('tabitabi_ai_quota', JSON.stringify(reset)); } catch (e) {}
    return { ...reset, limit: DAILY_AI_BASE_LIMIT, remaining: DAILY_AI_BASE_LIMIT };
  }
  const limit = DAILY_AI_BASE_LIMIT + (Number(saved.bonus) || 0);
  const used = Number(saved.used) || 0;
  return {
    date: today,
    used,
    bonus: Number(saved.bonus) || 0,
    limit,
    remaining: Math.max(0, limit - used)
  };
};

const consumeAiQuota = () => {
  const current = getAiQuotaStatus();
  if (current.remaining <= 0) return { ok: false, status: current };
  const next = { date: current.date, used: current.used + 1, bonus: current.bonus };
  try { localStorage.setItem('tabitabi_ai_quota', JSON.stringify(next)); } catch (e) {}
  return { ok: true, status: getAiQuotaStatus() };
};

const addRewardAdBonusQuota = () => {
  const current = getAiQuotaStatus();
  const next = { date: current.date, used: current.used, bonus: current.bonus + REWARD_AD_BONUS_COUNT };
  try { localStorage.setItem('tabitabi_ai_quota', JSON.stringify(next)); } catch (e) {}
  return getAiQuotaStatus();
};

// AI生成結果のローカルキャッシュ取得・保存（同じ条件なら2回目以降はAPI代0円）
const getCachedAiResponse = (cacheKey) => {
  const cacheMap = safeParse('tabitabi_ai_plan_cache_v1', {});
  return cacheMap[cacheKey] || null;
};

const setCachedAiResponse = (cacheKey, data) => {
  try {
    const cacheMap = safeParse('tabitabi_ai_plan_cache_v1', {});
    const keys = Object.keys(cacheMap);
    if (keys.length > 40) delete cacheMap[keys[0]];
    cacheMap[cacheKey] = data;
    localStorage.setItem('tabitabi_ai_plan_cache_v1', JSON.stringify(cacheMap));
  } catch (e) {}
};

// Google Gemini API 構造化出力呼び出し（本番はサーバー側の /api/gemini 窓口を経由し、プレビューテスト時は条件反映エンジンへスムーズに連携）
const callGoogleGeminiStructured = async ({ systemPrompt, userPrompt, responseSchema }) => {
  const response = await fetch('/api/gemini', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      prompt: userPrompt,
      systemInstruction: systemPrompt,
      responseMimeType: 'application/json',
      responseSchema
    })
  });

  const result = await response.json();
  if (!response.ok) {
    throw new Error(result?.error || `HTTP ${response.status}`);
  }

  const text = result?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) {
    throw new Error('Gemini API returned empty text');
  }

  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  return JSON.parse(cleaned);
};

// 🎬 動画広告視聴でAI利用回数を＋3回増やすリワード広告モーダル
function RewardVideoAdModal({ onClose, onCompleteReward }) {
  useLockBodyScroll(true);
  const [secondsLeft, setSecondsLeft] = useState(3);
  const [completed, setCompleted] = useState(false);

  useEffect(() => {
    if (secondsLeft <= 0) {
      setCompleted(true);
      return;
    }
    const timer = setTimeout(() => setSecondsLeft(prev => prev - 1), 1000);
    return () => clearTimeout(timer);
  }, [secondsLeft]);

  return (
    <div className="fixed inset-0 bg-black/80 z-[320] flex justify-center items-center p-4 animate-in fade-in" onClick={completed ? onClose : undefined}>
      <div className="bg-stone-900 text-white w-full max-w-sm rounded-[32px] p-6 shadow-2xl border border-stone-700 text-center space-y-4 animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center text-[11px] font-bold text-stone-400">
          <span className="px-2.5 py-0.5 rounded-full bg-amber-500/20 text-amber-300 border border-amber-400/30">
            🎬 リワード動画広告
          </span>
          {completed ? (
            <span className="text-emerald-400 font-extrabold">視聴完了！</span>
          ) : (
            <span>残り {secondsLeft} 秒</span>
          )}
        </div>

        <div className="py-8 px-4 rounded-2xl bg-gradient-to-br from-[#7A9D8C]/30 via-sky-900/40 to-stone-800 border border-white/10 flex flex-col items-center justify-center space-y-2">
          <Sparkles size={36} className="text-amber-400 animate-pulse" />
          <p className="text-sm font-extrabold text-white">たびたび トラベルサポート</p>
          <p className="text-[11px] text-stone-300 leading-relaxed">
            動画を見ると本日のGoogle AIプラン生成枠が<br />
            <span className="text-amber-300 font-extrabold">＋{REWARD_AD_BONUS_COUNT}回</span> すぐに回復します！
          </p>
        </div>

        <div className="w-full h-2 bg-stone-800 rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-amber-400 to-emerald-400 transition-all duration-700"
            style={{ width: `${((3 - secondsLeft) / 3) * 100}%` }}
          />
        </div>

        {completed ? (
          <button
            type="button"
            onClick={() => {
              const nextStatus = addRewardAdBonusQuota();
              if (onCompleteReward) onCompleteReward(nextStatus);
              customAlert(`🎉 AI利用枠が＋${REWARD_AD_BONUS_COUNT}回増えました！（残り${nextStatus.remaining}回）`);
              onClose();
            }}
            className="w-full py-3.5 bg-gradient-to-r from-amber-400 to-amber-500 hover:brightness-105 text-stone-950 font-extrabold rounded-2xl text-xs shadow-lg transition-all active:scale-95"
          >
            🎁 ＋{REWARD_AD_BONUS_COUNT}回のAI利用枠を受け取る
          </button>
        ) : (
          <button
            type="button"
            disabled
            className="w-full py-3.5 bg-stone-800 text-stone-500 font-bold rounded-2xl text-xs cursor-not-allowed"
          >
            動画を再生中...（あと{secondsLeft}秒）
          </button>
        )}
      </div>
    </div>
  );
}

// ✨ AIが考えているときのアニメーションコンポーネント（画面全体を隠さず、何を考えているかステップごとに可視化）
function AiThinkingIndicator({
  variant = 'chat',
  destination = '',
  departurePoint = '',
  days = 2,
  budgetAmount = 35000,
  theme = '',
  transportMethod = '',
  localTransportMethod = '',
  companion = ''
}) {
  const [stepIdx, setStepIdx] = useState(0);

  const cleanOrig = (departurePoint || '出発地').replace(/（.*?）/g, '').trim() || '出発地';
  const cleanDest = (destination || '目的地').trim() || 'ご希望エリア';
  const transLabel = TRANSPORT_METHODS.find(m => m.id === transportMethod)?.short || '最適ルート';
  const localLabel = LOCAL_TRANSPORT_METHODS.find(m => m.id === localTransportMethod)?.short || '現地交通';
  const cleanTheme = (theme || '王道観光＆グルメ').replace(/^[^\s]+\s/, '');

  const detailedSteps = useMemo(
    () => [
      {
        title: `① ルート・移動費の算出（${cleanOrig} ➔ ${cleanDest}）`,
        detail: `${transLabel}での移動時間と、現地の「${localLabel}」ルートを計算中...`
      },
      {
        title: `② テーマ「${cleanTheme}」×「${companion || '同行者'}」に合う名所選定`,
        detail: `${cleanDest}の実在人気スポット・老舗ランチ・カフェを厳選中...`
      },
      {
        title: `③ 全${days}日間のタイムライン＆予算（目安 ¥${Number(budgetAmount || 35000).toLocaleString()}）配分`,
        detail: `朝から夜まで無理のない時間配分と1人あたり費用を組み立て中...`
      }
    ],
    [cleanOrig, cleanDest, transLabel, localLabel, cleanTheme, companion, days, budgetAmount]
  );

  useEffect(() => {
    setStepIdx(0);
    const timer = setInterval(() => {
      setStepIdx(prev => (prev < detailedSteps.length - 1 ? prev + 1 : prev));
    }, 900);
    return () => clearInterval(timer);
  }, [detailedSteps.length, cleanDest, cleanTheme]);

  if (variant === 'card' || variant === 'fullscreen') {
    return (
      <div className="my-2 p-4 rounded-2xl bg-gradient-to-br from-sky-50 via-emerald-50/70 to-white border-2 border-[#7A9D8C]/50 shadow-sm space-y-3 animate-in fade-in duration-200">
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-xl bg-white border border-sky-200 shadow-2xs flex items-center justify-center shrink-0">
              <Sparkles size={16} className="text-[#5E8473] animate-spin" style={{ animationDuration: '2.6s' }} />
            </div>
            <div className="text-left">
              <p className="text-xs font-extrabold text-stone-800 flex items-center gap-1">
                <span>AIがご希望の条件からプランを組み立て中</span>
                <span className="inline-flex items-center gap-0.5">
                  <span className="w-1 h-1 rounded-full bg-[#5E8473] animate-bounce" style={{ animationDelay: '0ms' }} />
                  <span className="w-1 h-1 rounded-full bg-[#5E8473] animate-bounce" style={{ animationDelay: '150ms' }} />
                  <span className="w-1 h-1 rounded-full bg-[#5E8473] animate-bounce" style={{ animationDelay: '300ms' }} />
                </span>
              </p>
              <p className="text-[10px] font-bold text-[#4A6B5D]">
                📍 {cleanDest}（{days <= 1 ? '日帰り' : `${days - 1}泊${days}日`} / 予算¥{Number(budgetAmount || 35000).toLocaleString()}）
              </p>
            </div>
          </div>
          <span className="text-[10px] font-mono font-extrabold text-sky-800 bg-sky-100 px-2 py-0.5 rounded-full shrink-0">
            STEP {stepIdx + 1}/{detailedSteps.length}
          </span>
        </div>

        {/* 進捗バー */}
        <div className="w-full h-1.5 bg-stone-200/80 rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-[#7A9D8C] to-sky-400 transition-all duration-500"
            style={{ width: `${Math.round(((stepIdx + 1) / detailedSteps.length) * 100)}%` }}
          />
        </div>

        {/* 何を考えているか一目でわかるステップリスト */}
        <div className="space-y-1.5 text-left">
          {detailedSteps.map((st, idx) => {
            const isDone = idx < stepIdx;
            const isCurrent = idx === stepIdx;
            return (
              <div
                key={idx}
                className={`px-2.5 py-1.5 rounded-xl border text-[11px] transition-all flex items-start gap-2 ${
                  isCurrent
                    ? 'bg-white border-[#7A9D8C] text-stone-800 shadow-2xs'
                    : isDone
                    ? 'bg-emerald-50/60 border-emerald-200/70 text-emerald-900'
                    : 'bg-white/50 border-stone-200/50 text-stone-400'
                }`}
              >
                <span className="mt-0.5 shrink-0">
                  {isDone ? (
                    <CheckCircle2 size={13} className="text-emerald-600" />
                  ) : isCurrent ? (
                    <div className="w-3.5 h-3.5 border-2 border-[#7A9D8C]/30 border-t-[#7A9D8C] rounded-full animate-spin" />
                  ) : (
                    <Clock size={13} className="text-stone-300" />
                  )}
                </span>
                <div className="min-w-0 flex-1">
                  <p className="font-extrabold leading-tight">{st.title}</p>
                  {isCurrent && (
                    <p className="text-[10px] font-bold text-[#557465] mt-0.5 leading-snug">
                      {st.detail}
                    </p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col items-start animate-in fade-in slide-in-from-bottom-2 duration-200">
      <div className="w-full max-w-[94%] px-3.5 py-3 rounded-2xl rounded-bl-sm bg-gradient-to-r from-stone-100 via-sky-50/80 to-emerald-50/70 border border-sky-200/80 text-stone-800 shadow-2xs space-y-2">
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 rounded-full bg-white border border-sky-200 flex items-center justify-center shrink-0 shadow-2xs">
              <Sparkles size={13} className="text-[#5E8473] animate-spin" style={{ animationDuration: '2.6s' }} />
            </div>
            <span className="text-xs font-extrabold text-[#4A6B5D]">
              AIコンシェルジュが条件を分析中 ({stepIdx + 1}/{detailedSteps.length})
            </span>
          </div>
        </div>
        <div className="space-y-1 pl-1">
          {detailedSteps.map((st, idx) => {
            const isDone = idx < stepIdx;
            const isCurrent = idx === stepIdx;
            return (
              <div
                key={idx}
                className={`flex items-center gap-1.5 text-[11px] ${
                  isCurrent ? 'font-extrabold text-stone-800' : isDone ? 'font-bold text-emerald-700' : 'text-stone-400'
                }`}
              >
                <span>{isDone ? '✓' : isCurrent ? '▶' : '・'}</span>
                <span className="truncate">{st.title}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ★ 写真を同じしおりのメンバー間で高速・低容量で共有するためのクライアント側自動画像圧縮関数
// スマホの数MBある写真を長辺最大1200px・JPEG品質0.82（約100〜150KB）に自動軽量化します
const compressImageFile = (file, maxSide = 1200, quality = 0.82) => {
  return new Promise((resolve) => {
    if (!file || typeof window === 'undefined') {
      resolve('');
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new window.Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > maxSide || height > maxSide) {
          if (width > height) {
            height = Math.round((height * maxSide) / width);
            width = maxSide;
          } else {
            width = Math.round((width * maxSide) / height);
            height = maxSide;
          }
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } else {
          resolve(event.target?.result || URL.createObjectURL(file));
        }
      };
      img.onerror = () => resolve(URL.createObjectURL(file));
      img.src = event.target?.result;
    };
    reader.onerror = () => resolve(URL.createObjectURL(file));
    reader.readAsDataURL(file);
  });
};

