const validateDestinationInput = async (rawInput) => {
  const trimmed = (rawInput || '').trim();
  if (!trimmed) {
    return {
      valid: false,
      reason: 'empty',
      message: '目的地・エリアが未入力です。行き先を入力してください！'
    };
  }

  // 1. 明らかなデタラメ文字列・意味不明な英数字混在・記号のみ・同一文字連打を即座にブロック
  const allowedAlphaTerms = /^(usj|tdl|tds|tokyo|kyoto|osaka|okinawa|hokkaido|hakone|kanazawa|fukuoka|sapporo|naha|kobe|nara|nagoya|hiroshima|sendai|kamakura|nikko|atami|izu|karuizawa|beppu|yufuin)$/i;
  const hasInvalidMix =
    (/[a-zA-Z]/.test(trimmed) && /[ぁ-んァ-ヶ一-龠]/.test(trimmed) && !/USJ|TDL|TDS/i.test(trimmed)) || // 「ふぁえsf」のような日本語＋無意味なアルファベット混在
    (/^[a-zA-Z0-9\s!-/:-@[-`{-~]+$/.test(trimmed) && !allowedAlphaTerms.test(trimmed)) || // 英数字・記号のみ（許可リスト以外）
    /^[0-9０-９\s!-/:-@[-`{-~！？、。・]+$/.test(trimmed) || // 数字や記号のみ
    /^(.)\1+$/.test(trimmed) || // 「あああ」「www」など同じ文字の繰り返し
    /^[ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮんンー]/.test(trimmed) || // 小文字や「ん」から始まる不自然な文字列
    /[ぁぃぅぇぉ]{2,}|[っッ]{2,}|[ー]{3,}/.test(trimmed) || // 小文字の連続（例：「ふぁえ」「ぁぃ」など）
    (/^[ぁ-ん]{1,8}$/.test(trimmed) && /(ふぁ|ふぃ|ふぇ|ふぉ|てゃ|てぃ|てゅ|でゃ|でゅ|ゔ)/.test(trimmed)) || // ひらがなで外来音小文字を含むデタラメ入力
    trimmed.length > 35;

  if (hasInvalidMix || trimmed.length < 2) {
    return {
      valid: false,
      reason: 'gibberish',
      message: `「${trimmed}」に該当する日本の地名・観光地が見つかりませんでした。実在する都道府県・市区町村・観光地名を入力してください！`
    };
  }

  // 2. 内蔵の全国47都道府県・全1,741市区町村・主要観光地リストとの照合
  const normalizedInput = trimmed
    .replace(/\s+/g, '')
    .replace(/(旅行|観光|ツアー|の旅|周辺|エリア|方面|地方|めぐり|巡り|温泉郷)$/g, '');

  // 都道府県名（フルネームおよび「東京」「京都」「北海道」などの略称）チェック
  const matchedPref = PREFECTURES.some(pref => {
    const shortPref = pref.replace(/[都道府県]$/, '');
    return (
      normalizedInput.includes(pref) ||
      normalizedInput.includes(shortPref) ||
      pref.includes(normalizedInput)
    );
  });
  if (matchedPref) return { valid: true };

  // 主要観光地・温泉地・地域名キーワードチェック
  const matchedTourist = KNOWN_TOURIST_KEYWORDS.some(
    kw => normalizedInput.includes(kw) || (normalizedInput.length >= 2 && kw.includes(normalizedInput))
  );
  if (matchedTourist) return { valid: true };

  // 全国1,741市区町村マスター（FULL_MUNICIPALITIES_BY_PREF）との照合
  for (const pref of PREFECTURES) {
    const munis = FULL_MUNICIPALITIES_BY_PREF[pref] || [];
    for (const rawMuni of munis) {
      const cleanMuni = rawMuni.replace(/（.*?）/g, '').trim();
      const baseMuni = cleanMuni.replace(/[市区町村]$/, '');
      if (
        normalizedInput.includes(cleanMuni) ||
        cleanMuni.includes(normalizedInput) ||
        (baseMuni.length >= 2 && normalizedInput.includes(baseMuni))
      ) {
        return { valid: true };
      }
    }
  }

  // 3. 静止リストにない場合でも、実在する駅名・町名かどうかを HeartRails API でリアルタイム照合
  try {
    const searchWord = normalizedInput.replace(/駅$/, '');
    const [stationRes, geoRes] = await Promise.allSettled([
      fetch(`https://express.heartrails.com/api/json?method=getStations&name=${encodeURIComponent(searchWord)}`).then(r => r.json()),
      fetch(`https://geoapi.heartrails.com/api/json?method=Suggest&matching=like&keyword=${encodeURIComponent(searchWord)}`).then(r => r.json())
    ]);

    const stations = stationRes.status === 'fulfilled' ? stationRes.value?.response?.station : null;
    if (Array.isArray(stations) && stations.length > 0) {
      return { valid: true };
    }
    const geoLocations = geoRes.status === 'fulfilled' ? geoRes.value?.response?.location : null;
    if (Array.isArray(geoLocations) && geoLocations.length > 0) {
      return { valid: true };
    }
  } catch (e) {
    // 通信失敗時は下の判定へ進む
  }

  return {
    valid: false,
    reason: 'not_found',
    message: `「${trimmed}」に該当する地名・観光地が見つかりませんでした。実在する都道府県・市区町村・観光地名を入力してください！`
  };
};

// ★ HeartRails Express / HeartRails Geo API 公式クレジット表記コンポーネント（利用規約準拠・リンク付き）
function HeartRailsCreditBadge({ className = '', showGeo = true }) {
  return (
    <div className={`flex items-center justify-end flex-wrap gap-x-2 gap-y-0.5 text-[10px] font-bold text-stone-400 ${className}`}>
      <span>データ提供:</span>
      {showGeo && (
        <>
          <a
            href="https://geoapi.heartrails.com/"
            target="_blank"
            rel="noopener noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="text-[#557465] hover:underline inline-flex items-center gap-0.5"
          >
            <span>HeartRails Geo API</span>
            <ExternalLink size={9} />
          </a>
          <span>/</span>
        </>
      )}
      <a
        href="https://express.heartrails.com/"
        target="_blank"
        rel="noopener noreferrer"
        onClick={(e) => e.stopPropagation()}
        className="text-[#557465] hover:underline inline-flex items-center gap-0.5"
      >
        <span>HeartRails Express</span>
        <ExternalLink size={9} />
      </a>
    </div>
  );
}

// HeartRails Geo API (method=getCities) のレスポンスを都道府県ごとにキャッシュするマップ
const geoApiCityCache = {};

// カタカナをひらがなに変換するヘルパー（よみがな検索用）
const toHiragana = (str = '') =>
  str.replace(/[\u30a1-\u30f6]/g, (m) => String.fromCharCode(m.charCodeAt(0) - 0x60));

// ★ HeartRails Geo API (https://geoapi.heartrails.com/api.html#city) を使った市区町村サジェスト検索コンポーネント
// 都道府県選択時はAPIからその都道府県の全自治体（漢字＋よみがな）を取得し、未選択時も全国検索＆都道府県の自動セットに対応
function MunicipalitySearchInput({
  value,
  onChange,
  prefectureContext = '未設定',
  onSelectPrefecture,
  placeholder = '市区町村 (例: 新宿区 / 横浜市 / 松本市)'
}) {
  const [query, setQuery] = useState(value || '');
  const [isOpen, setIsOpen] = useState(false);
  const [apiCities, setApiCities] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const wrapperRef = useRef(null);

  useEffect(() => {
    setQuery(value || '');
  }, [value]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, []);

  // ローカルフォールバック兼・全国横断検索用のマスターリスト
  const localAllMunicipalities = useMemo(() => {
    const list = [];
    PREFECTURES.forEach((pref) => {
      const munis = FULL_MUNICIPALITIES_BY_PREF[pref] || SAMPLE_MUNICIPALITIES_BY_PREF[pref] || [];
      munis.forEach((rawMuni) => {
        const cleanMuni = rawMuni.replace(/（.*?）/g, '');
        list.push({
          pref,
          city: cleanMuni,
          city_kana: '',
          rawName: rawMuni
        });
      });
    });
    return list;
  }, []);

  // 都道府県が選択されている（または検索語から都道府県が推測できる）場合、HeartRails Geo API (method=getCities) から市区町村一覧を取得
  useEffect(() => {
    const trimmed = (query || '').trim();
    let targetPref =
      prefectureContext && prefectureContext !== '未設定' ? prefectureContext : null;

    // 都道府県が未選択でも、入力文字から該当する都道府県が見つかればその県の公式リストもGeo APIから取得する
    if (!targetPref && trimmed.length >= 1) {
      const matchedLocal = localAllMunicipalities.find(
        (m) => m.city.includes(trimmed) || m.rawName.includes(trimmed)
      );
      if (matchedLocal) {
        targetPref = matchedLocal.pref;
      }
    }

    if (!targetPref) {
      setApiCities([]);
      return;
    }

    if (geoApiCityCache[targetPref]) {
      setApiCities(geoApiCityCache[targetPref]);
      return;
    }

    let cancelled = false;
    setIsLoading(true);
    fetch(
      `https://geoapi.heartrails.com/api/json?method=getCities&prefecture=${encodeURIComponent(
        targetPref
      )}`
    )
      .then((res) => res.json())
      .then((data) => {
        if (cancelled) return;
        const locations = data?.response?.location || [];
        if (Array.isArray(locations) && locations.length > 0) {
          const formatted = locations.map((loc) => ({
            pref: targetPref,
            city: loc.city,
            city_kana: loc.city_kana || '',
            rawName: loc.city
          }));
          geoApiCityCache[targetPref] = formatted;
          setApiCities(formatted);
        } else {
          setApiCities([]);
        }
      })
      .catch(() => {
        if (!cancelled) setApiCities([]);
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [prefectureContext, query, localAllMunicipalities]);

  const filteredCandidates = useMemo(() => {
    const trimmed = (query || '').trim();
    const hiraQuery = toHiragana(trimmed);
    const hasPref = prefectureContext && prefectureContext !== '未設定';

    // HeartRails Geo API から取得した市区町村リストがあれば最優先で使用
    const basePool =
      apiCities.length > 0
        ? hasPref
          ? apiCities
          : [
              ...apiCities,
              ...localAllMunicipalities.filter(
                (m) => !apiCities.some((a) => a.pref === m.pref && a.city === m.city)
              )
            ]
        : hasPref
        ? localAllMunicipalities.filter((item) => item.pref === prefectureContext)
        : localAllMunicipalities;

    if (!trimmed) {
      if (hasPref) return basePool.slice(0, 40);
      const majorCities = [
        '新宿区',
        '渋谷区',
        '港区',
        '横浜市西区',
        '鎌倉市',
        'さいたま市大宮区',
        '札幌市中央区',
        '仙台市青葉区',
        '松本市',
        '長野市',
        '金沢市',
        '名古屋市中村区',
        '京都市中京区',
        '大阪市北区',
        '神戸市中央区',
        '広島市中区',
        '福岡市博多区',
        '那覇市'
      ];
      return localAllMunicipalities.filter((m) => majorCities.includes(m.city)).slice(0, 18);
    }

    const matched = basePool.filter(
      (item) =>
        item.city.includes(trimmed) ||
        item.rawName.includes(trimmed) ||
        (item.city_kana && item.city_kana.includes(hiraQuery)) ||
        item.pref.includes(trimmed)
    );

    const directItem = {
      pref: hasPref ? prefectureContext : '',
      city: trimmed,
      city_kana: '',
      rawName: `${trimmed}（そのまま設定）`,
      isDirect: true
    };

    return matched.length > 0 ? [...matched.slice(0, 30), directItem] : [directItem];
  }, [query, prefectureContext, apiCities, localAllMunicipalities]);

  const handleSelect = (item) => {
    setQuery(item.city);
    onChange(item.city);
    if (item.pref && (!prefectureContext || prefectureContext === '未設定') && onSelectPrefecture) {
      onSelectPrefecture(item.pref);
    }
    setIsOpen(false);
  };

  return (
    <div ref={wrapperRef} className="relative w-full">
      <div className="relative">
        <input
          type="text"
          value={query}
          onFocus={() => setIsOpen(true)}
          onChange={(e) => {
            const nextVal = e.target.value;
            setQuery(nextVal);
            onChange(nextVal);
            setIsOpen(true);
            // 入力された市区町村名が特定の都道府県に一意に一致する場合、未選択なら都道府県も自動補完
            if ((!prefectureContext || prefectureContext === '未設定') && onSelectPrefecture && nextVal.trim().length >= 2) {
              const exactMatches = localAllMunicipalities.filter((m) => m.city === nextVal.trim());
              if (exactMatches.length === 1) {
                onSelectPrefecture(exactMatches[0].pref);
              }
            }
          }}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && filteredCandidates.length > 0) {
              e.preventDefault();
              handleSelect(filteredCandidates[0]);
            }
          }}
          placeholder={placeholder}
          className="w-full p-2 pr-7 bg-white border border-stone-200 rounded-xl text-xs font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
        />
        {query && (
          <button
            type="button"
            onClick={() => {
              setQuery('');
              onChange('');
              setIsOpen(true);
            }}
            className="absolute right-2 top-1/2 -translate-y-1/2 text-stone-400 hover:text-stone-600"
            title="クリア"
          >
            <X size={13} />
          </button>
        )}
      </div>

      {isOpen && (
        <div className="mt-1 bg-white rounded-xl border-2 border-[#7A9D8C]/60 shadow-md overflow-hidden animate-in fade-in duration-100 z-30">
          <div className="px-2.5 py-1.5 bg-stone-50 border-b border-stone-100 flex items-center justify-between text-[10px] font-bold text-stone-500">
            <span className="truncate">
              {prefectureContext && prefectureContext !== '未設定'
                ? `${prefectureContext}の市区町村候補 (Geo API)`
                : '全国の市区町村候補 (よみがな検索可)'}
            </span>
            <div className="flex items-center gap-1.5 shrink-0 ml-1">
              {isLoading && <span className="text-[#7A9D8C] animate-pulse">取得中...</span>}
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="text-stone-400 hover:text-stone-600 font-extrabold"
              >
                閉じる ×
              </button>
            </div>
          </div>

          <div className="max-h-44 overflow-y-auto divide-y divide-stone-100">
            {filteredCandidates.map((item, idx) => (
              <button
                key={`${item.pref}_${item.city}_${idx}`}
                type="button"
                onClick={() => handleSelect(item)}
                className="w-full px-2.5 py-1.5 hover:bg-emerald-50/70 flex items-center justify-between gap-1.5 text-left transition-colors active:bg-emerald-100/60"
              >
                <div className="min-w-0 flex items-center gap-1.5">
                  <span className="text-[11px] shrink-0">📍</span>
                  <div className="min-w-0">
                    <span className="text-xs font-extrabold text-stone-800 block truncate">
                      {item.rawName}
                    </span>
                    {(item.city_kana || (item.pref && (!prefectureContext || prefectureContext === '未設定'))) && (
                      <span className="text-[9px] font-bold text-stone-400 block truncate">
                        {item.city_kana ? `${item.city_kana} ` : ''}
                        {item.pref && (!prefectureContext || prefectureContext === '未設定')
                          ? `（${item.pref}）`
                          : ''}
                      </span>
                    )}
                  </div>
                </div>
                <span className="px-2 py-0.5 rounded-md bg-[#7A9D8C]/15 text-[#4A6B5D] text-[10px] font-extrabold shrink-0">
                  選択
                </span>
              </button>
            ))}
          </div>

          <div className="px-2.5 py-1 bg-stone-50 border-t border-stone-100">
            <HeartRailsCreditBadge showGeo={true} />
          </div>
        </div>
      )}
    </div>
  );
}

// 駅データAPI（HeartRails Express: https://express.heartrails.com/api.html）を使ったインライン候補展開型の駅検索コンポーネント
// （初回登録・プロフィール編集・出発地点設定・予定追加/編集のすべてで共通利用可能）
function StationSearchInput({
  value,
  onChange,
  cityContext = '',
  prefectureContext = '',
  onSelectPrefecture,
  placeholder = '駅名を入力 (例: 東京 / 横浜 / 梅田 / 博多)',
  allowCustomText = false,
  compact = false
}) {
  const [query, setQuery] = useState(value || '');
  const [isOpen, setIsOpen] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const wrapperRef = useRef(null);

  useEffect(() => {
    setQuery(value || '');
  }, [value]);

  // 枠外タップで候補リストを閉じる
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('touchstart', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, []);

  const kanaToHira = (str) =>
    str.replace(/[\u30a1-\u30f6]/g, (match) => String.fromCharCode(match.charCodeAt(0) - 0x60));

  useEffect(() => {
    if (!isOpen) return;
    const trimmed = (query || '').trim();
    if (!trimmed) {
      setSuggestions(
        MOCK_STATIONS.slice(0, 6).map((s) => ({
          label: s.name,
          stationName: s.name.split(' (')[0],
          line: (s.name.split(' (')[1] || '').replace(/\)$/, ''),
          prefecture: ''
        }))
      );
      return;
    }

    const timer = setTimeout(async () => {
      setIsLoading(true);
      try {
        const searchWord = trimmed.replace(/駅$/, '');
        // HeartRails Express 駅名検索API (getStations)
        const apiUrl = `https://express.heartrails.com/api/json?method=getStations&name=${encodeURIComponent(searchWord)}`;
        const response = await fetch(apiUrl);
        const data = await response.json();

        let stations = data?.response?.station || [];
        // 都道府県が指定されていて一致する候補がある場合は優先表示
        if (stations.length > 0 && prefectureContext && prefectureContext !== '未設定') {
          const prefMatched = stations.filter((s) => s.prefecture === prefectureContext);
          const others = stations.filter((s) => s.prefecture !== prefectureContext);
          stations = [...prefMatched, ...others];
        }

        if (stations.length > 0) {
          const seen = new Set();
          const formatted = [];
          stations.forEach((s) => {
            const key = `${s.name}_${s.line}_${s.prefecture}`;
            if (!seen.has(key)) {
              seen.add(key);
              formatted.push({
                label: `${s.name}駅 (${s.line} / ${s.prefecture}${s.prev ? `・隣:${s.prev}` : ''})`,
                stationName: `${s.name}駅`,
                line: s.line,
                prefecture: s.prefecture
              });
            }
          });
          if (allowCustomText) {
            formatted.push({
              label: `「${trimmed}」をそのまま場所として設定`,
              stationName: trimmed,
              line: '自由入力スポット',
              prefecture: '',
              isRawText: true
            });
          }
          setSuggestions(formatted.slice(0, 15));
        } else {
          fallbackSearch(trimmed);
        }
      } catch (error) {
        fallbackSearch(trimmed);
      } finally {
        setIsLoading(false);
      }
    }, 180);

    return () => clearTimeout(timer);
  }, [query, isOpen, prefectureContext, cityContext, allowCustomText]);

  const fallbackSearch = (val) => {
    const lowerVal = val.toLowerCase();
    const hiraVal = kanaToHira(lowerVal);
    const localMatches = MOCK_STATIONS.filter(
      (s) => s.name.includes(val) || s.yomi.includes(lowerVal) || s.yomi.includes(hiraVal)
    ).map((s) => ({
      label: s.name,
      stationName: s.name.split(' (')[0],
      line: (s.name.split(' (')[1] || '').replace(/\)$/, ''),
      prefecture: ''
    }));

    const cleanStation = allowCustomText ? val : `${val.replace(/駅$/, '')}駅`;
    const directItem = {
      label: `${cleanStation} (そのまま設定)`,
      stationName: cleanStation,
      line: '直接入力',
      prefecture: '',
      isRawText: allowCustomText
    };
    setSuggestions(localMatches.length > 0 ? [...localMatches, directItem] : [directItem]);
  };

  const handleSelect = (item) => {
    const baseName = item.stationName || item.label.split(' (')[0];
    const cleanName = item.isRawText ? baseName : baseName.replace(/駅$/, '') + '駅';
    setQuery(cleanName);
    onChange(cleanName);
    if (item.prefecture && (!prefectureContext || prefectureContext === '未設定') && onSelectPrefecture) {
      onSelectPrefecture(item.prefecture);
    }
    setIsOpen(false);
  };

  return (
    <div ref={wrapperRef} className="w-full space-y-1">
      {/* 別のページを開かずそのまま文字入力できる検索ボックス */}
      <div className="relative">
        <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#7A9D8C] pointer-events-none" />
        <input
          type="text"
          value={query}
          onFocus={() => setIsOpen(true)}
          onChange={(e) => {
            setQuery(e.target.value);
            onChange(e.target.value);
            setIsOpen(true);
          }}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && suggestions.length > 0) {
              e.preventDefault();
              handleSelect(suggestions[0]);
            }
          }}
          placeholder={placeholder}
          className={`w-full ${compact ? 'py-2 text-xs' : 'py-2.5 text-xs sm:text-sm'} pl-9 pr-14 bg-white rounded-xl border border-stone-200 focus:border-[#7A9D8C] font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]`}
        />
        {query && (
          <button
            type="button"
            onClick={() => {
              setQuery('');
              onChange('');
              setIsOpen(true);
            }}
            className="absolute right-2 top-1/2 -translate-y-1/2 px-2 py-0.5 rounded-md bg-stone-100 hover:bg-stone-200 text-stone-500 text-[10px] font-bold"
          >
            クリア
          </button>
        )}
      </div>

      {/* 入力欄のすぐ下にインラインで展開される候補リスト（別ページを開かずその場で選択可能） */}
      {isOpen && (
        <div className="bg-white rounded-xl border-2 border-[#7A9D8C]/60 shadow-md overflow-hidden animate-in fade-in duration-100">
          <div className="px-3 py-1.5 bg-stone-50 border-b border-stone-100 flex items-center justify-between text-[10px] font-bold text-stone-500">
            <span className="truncate">
              {query.trim()
                ? `「${query.trim()}」の駅候補`
                : '全国の駅候補（文字入力でリアルタイム検索）'}
            </span>
            <div className="flex items-center gap-2 shrink-0">
              {isLoading && <span className="text-[#7A9D8C] animate-pulse">検索中...</span>}
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="text-stone-400 hover:text-stone-600 font-extrabold"
              >
                閉じる ×
              </button>
            </div>
          </div>

          <div className="max-h-48 overflow-y-auto divide-y divide-stone-100">
            {suggestions.map((item, idx) => (
              <button
                key={idx}
                type="button"
                onClick={() => handleSelect(item)}
                className="w-full px-3 py-2 hover:bg-emerald-50/70 flex items-center justify-between gap-2 text-left transition-colors active:bg-emerald-100/60"
              >
                <div className="min-w-0 flex items-center gap-2">
                  <span className="text-xs shrink-0">{item.isRawText ? '📍' : '🚉'}</span>
                  <div className="min-w-0">
                    <span className="text-xs sm:text-sm font-extrabold text-stone-800 block truncate">
                      {item.stationName}
                    </span>
                    {(item.line || item.prefecture) && (
                      <span className="text-[10px] font-bold text-stone-500 block truncate">
                        {item.line}
                        {item.prefecture ? ` / ${item.prefecture}` : ''}
                      </span>
                    )}
                  </div>
                </div>
                <span className="px-2.5 py-1 rounded-lg bg-[#7A9D8C]/15 text-[#4A6B5D] text-[10px] font-extrabold shrink-0">
                  選択
                </span>
              </button>
            ))}
          </div>

          {/* ドロップダウン下部にもHeartRailsの公式クレジットリンクを明記 */}
          <div className="px-3 py-1 bg-stone-50 border-t border-stone-100">
            <HeartRailsCreditBadge showGeo={false} />
          </div>
        </div>
      )}
    </div>
  );
}

const UserAvatar = ({ user, size = 'w-8 h-8' }) => {
  if (user?.isOfficial || user?.id === OFFICIAL_ACCOUNT_PROFILE.id) {
    return (
      <div className={`${size} rounded-full border-2 border-white bg-gradient-to-br from-[#7A9D8C] to-[#4A6B5B] text-white flex items-center justify-center shadow-sm shrink-0`}>
        <Compass size={14} className="stroke-[2.5]" />
      </div>
    );
  }
  if (user?.avatar) return <img src={user.avatar} alt="avatar" className={`${size} rounded-full object-cover border-2 border-white shadow-sm bg-stone-100 shrink-0`} />;
  return <div className={`${size} rounded-full border-2 border-white text-white flex items-center justify-center text-xs font-bold shadow-sm shrink-0`} style={{ backgroundColor: user?.color || '#7A9D8C' }}>{user?.name?.charAt(0) || '👤'}</div>;
};

// 公式アカウント専用の認証バッジ付きアバター
const OfficialBrandAvatar = ({ size = 'w-10 h-10', iconSize = 18 }) => (
  <div className="relative shrink-0">
    <div className={`${size} rounded-2xl bg-gradient-to-br from-[#7A9D8C] via-[#5E8271] to-[#436052] text-white flex items-center justify-center shadow-sm border-2 border-white`}>
      <Compass size={iconSize} className="stroke-[2.4]" />
    </div>
    <span
      className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-sky-500 text-white flex items-center justify-center border-2 border-white shadow-2xs"
      title="公式認証アカウント"
    >
      <Check size={9} strokeWidth={4} />
    </span>
  </div>
);

// ==========================================
// Root App Component
// ==========================================
// ★ベータ版公開モード：ログイン不要で、初回起動時に「名前・アイコン・最寄り駅」の登録画面を表示します
const BETA_ONBOARDING_DONE_KEY = 'tabitabi_beta_onboarding_v1';

// デフォルトのサンプル旅行を空に設定
const INITIAL_SAMPLE_TRIPS = [];

function BetaWelcomeSetupScreen({ initialUser, onComplete }) {
  useLockBodyScroll(true);
  const [name, setName] = useState(
    initialUser?.name && initialUser.name !== 'たびたろう（開発用）' ? initialUser.name : ''
  );
  const [nameError, setNameError] = useState(false);
  const [residence, setResidence] = useState(initialUser?.residence || '未設定');
  const [city, setCity] = useState(initialUser?.city || '');
  const [station, setStation] = useState(
    initialUser?.station && initialUser?.name !== 'たびたろう（開発用）' ? initialUser.station : ''
  );
  const [avatar, setAvatar] = useState(initialUser?.avatar || MALE_AVATARS[0]);
  const [customAvatar, setCustomAvatar] = useState(null);
  const [legalModalType, setLegalModalType] = useState(null);
  const fileInputRef = useRef(null);
  const nameInputRef = useRef(null);

  const handleStart = (e) => {
    if (e) e.preventDefault();
    if (!name.trim()) {
      setNameError(true);
      customAlert('⚠️ お友達に表示されるニックネームを入力してください！');
      nameInputRef.current?.focus();
      return;
    }
    setNameError(false);
    const cleanStation = station.trim() ? station.trim().replace(/駅$/, '') + '駅' : '';
    const newUser = {
      id: initialUser?.id && initialUser.id !== 'dev_user' ? initialUser.id : 'user_' + generateId(),
      name: name.trim(),
      bio: initialUser?.bio || '',
      email: '',
      password: '',
      passkeys: [],
      residence,
      city: city.trim(),
      station: cleanStation,
      avatar: customAvatar || avatar,
      isGuest: false,
      following: ['m1'],
      followers: [],
      autoMinimizeTrip: true,
      badges: [],
      badgesPublic: false,
      featuredBadgeIds: []
    };
    try {
      localStorage.setItem(BETA_ONBOARDING_DONE_KEY, 'true');
    } catch (err) {}
    onComplete(newUser);
  };

  return (
    <div className="fixed inset-0 w-full h-[100dvh] bg-stone-300 flex justify-center items-center p-3 sm:p-4 overflow-y-auto overscroll-none">
      <div
        style={{ WebkitOverflowScrolling: 'touch', touchAction: 'pan-y' }}
        className="bg-white w-full max-w-md max-h-[94dvh] rounded-[32px] px-4 py-4 sm:p-5 shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in-95 pb-safe my-auto"
      >
        {/* ヘッダー（上部にコンパクトに詰めて配置） */}
        <div className="text-center pb-2 shrink-0">
          <div className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-[#7A9D8C]/15 text-[#4A6B5D] text-[10px] font-extrabold mb-0.5">
            <Sparkles size={11} className="text-[#7A9D8C]" />
            <span>BETA VERSION ・ ログイン不要</span>
          </div>
          <h1 className="text-lg sm:text-xl font-extrabold text-[#7A9D8C] tracking-widest leading-tight">たびたび へようこそ！</h1>
          <p className="text-[11px] text-stone-500 font-bold mt-0.5">
            最初にあなたの名前と出発の基準になる最寄り駅を設定しましょう✈️
          </p>
        </div>

        {/* 無駄な余白を作らず中身に合わせた高さで表示するフォーム本体 */}
        <form
          onSubmit={handleStart}
          className="overflow-y-auto overflow-x-hidden no-scrollbar space-y-2.5 py-1 flex flex-col justify-start"
        >
          {/* 1. アイコン選択（選択中アイコンを大きく表示＋上段：男性風 / 下段：女性風） */}
          <div className="p-3 bg-stone-50 border border-stone-200/80 rounded-2xl shrink-0">
            <div className="flex items-center justify-between gap-3 mb-2.5 px-1">
              <div>
                <label className="text-xs font-extrabold text-stone-700 block">
                  ① アイコンを選ぶ
                </label>
                <span className="text-[10px] font-bold text-stone-400">
                  イラストまたは好きな写真を設定できます
                </span>
              </div>
              <div className="flex items-center gap-2.5">
                <div className="relative w-16 h-16 shrink-0">
                  <img
                    src={customAvatar || avatar}
                    alt="selected avatar"
                    className="w-16 h-16 rounded-full object-cover border-[3px] border-[#7A9D8C] ring-4 ring-[#7A9D8C]/20 shadow-md bg-white transition-all"
                  />
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute -bottom-0.5 -right-0.5 w-6 h-6 rounded-full bg-[#7A9D8C] text-white flex items-center justify-center shadow-sm border-2 border-white active:scale-95"
                    title="自分の写真から選ぶ"
                  >
                    <Camera size={12} />
                  </button>
                  <input
                    type="file"
                    ref={fileInputRef}
                    accept="image/*"
                    className="hidden"
                    onChange={async (e) => {
                      if (e.target.files?.[0]) {
                        const compressed = await compressImageFile(e.target.files[0], 160, 0.72);
                        setCustomAvatar(compressed);
                      }
                    }}
                  />
                </div>
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="text-[11px] text-[#4A6B5D] font-extrabold bg-white px-3 py-1.5 rounded-xl border border-stone-200 hover:bg-stone-100 transition-colors shadow-2xs"
                >
                  📷 写真から選ぶ
                </button>
              </div>
            </div>

            <div className="space-y-1.5">
              {/* 上段：男性風アイコン */}
              <div className="bg-white/90 px-2.5 py-1.5 rounded-xl border border-sky-200/70 flex items-center gap-2">
                <span className="text-[10px] font-extrabold text-sky-700 w-16 shrink-0 whitespace-nowrap leading-tight">
                  👦 メンズ
                </span>
                <div className="flex-1 grid grid-cols-5 gap-1.5 justify-items-center">
                  {MALE_AVATARS.map((url, idx) => {
                    const isSelected = !customAvatar && avatar === url;
                    return (
                      <button
                        key={`male-${idx}`}
                        type="button"
                        onClick={() => {
                          setAvatar(url);
                          setCustomAvatar(null);
                        }}
                        className={`w-10 h-10 rounded-full border-2 transition-all overflow-hidden bg-sky-50 ${
                          isSelected
                            ? 'border-[#7A9D8C] scale-115 ring-3 ring-[#7A9D8C]/40 shadow-sm z-10'
                            : 'border-sky-200/80 opacity-80 hover:opacity-100'
                        }`}
                      >
                        <img src={url} alt={`male-avatar-${idx}`} className="w-full h-full object-cover" />
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* 下段：女性風アイコン */}
              <div className="bg-white/90 px-2.5 py-1.5 rounded-xl border border-rose-200/70 flex items-center gap-2">
                <span className="text-[10px] font-extrabold text-rose-600 w-16 shrink-0 whitespace-nowrap leading-tight">
                  👧 レディース
                </span>
                <div className="flex-1 grid grid-cols-5 gap-1.5 justify-items-center">
                  {FEMALE_AVATARS.map((url, idx) => {
                    const isSelected = !customAvatar && avatar === url;
                    return (
                      <button
                        key={`female-${idx}`}
                        type="button"
                        onClick={() => {
                          setAvatar(url);
                          setCustomAvatar(null);
                        }}
                        className={`w-10 h-10 rounded-full border-2 transition-all overflow-hidden bg-rose-50 ${
                          isSelected
                            ? 'border-[#7A9D8C] scale-115 ring-3 ring-[#7A9D8C]/40 shadow-sm z-10'
                            : 'border-rose-200/80 opacity-80 hover:opacity-100'
                        }`}
                      >
                        <img src={url} alt={`female-avatar-${idx}`} className="w-full h-full object-cover" />
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>

          {/* 2. ニックネーム入力 */}
          <div className={`p-2.5 rounded-2xl shrink-0 transition-all ${
            nameError
              ? 'bg-rose-50/90 border-2 border-rose-400 ring-2 ring-rose-200'
              : 'bg-stone-50 border border-stone-200/80'
          }`}>
            <label className="text-xs font-extrabold text-stone-700 flex items-center justify-between mb-1 pl-0.5">
              <span>② ニックネーム（友達のしおりに表示）</span>
              <span className="text-[10px] font-extrabold text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-200">必須</span>
            </label>
            <input
              ref={nameInputRef}
              type="text"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                if (nameError && e.target.value.trim()) setNameError(false);
              }}
              placeholder="例: たびたろう"
              className={`w-full p-2 bg-white border rounded-xl text-base sm:text-sm font-extrabold text-stone-800 focus:outline-none focus:ring-2 ${
                nameError
                  ? 'border-rose-400 focus:ring-rose-400'
                  : 'border-stone-200 focus:ring-[#7A9D8C]'
              }`}
            />
            {nameError && (
              <p className="mt-1.5 text-[11px] font-extrabold text-rose-600 flex items-center gap-1 pl-0.5 animate-in fade-in">
                <AlertCircle size={13} className="shrink-0 text-rose-500" />
                <span>ニックネームが未入力です。お名前を入力してください！</span>
              </p>
            )}
          </div>

          {/* 3. 自宅・最寄り駅設定（別ページを開かず、すぐ下に駅候補リストを展開） */}
          <div className="p-2.5 bg-stone-50 border border-stone-200/80 rounded-2xl space-y-2 shrink-0">
            <div className="flex items-center justify-between pl-0.5">
              <label className="text-xs font-extrabold text-stone-700 flex items-center gap-1">
                <Navigation size={13} className="text-[#7A9D8C]" />
                <span>③ 普段の出発地点（最寄り駅・エリア）</span>
              </label>
              <span className="text-[10px] font-bold text-stone-400">任意・変更可</span>
            </div>

            <div className="px-2.5 py-1 bg-emerald-50/90 border border-emerald-200/90 rounded-xl flex items-center gap-1.5">
              <span className="text-xs leading-none shrink-0">🔒</span>
              <p className="text-[10px] font-extrabold text-emerald-900 leading-snug">
                最寄り駅・居住地は他のユーザーには一切公開されません。
              </p>
            </div>

            <div className="grid grid-cols-2 gap-1.5">
              <select
                value={residence}
                onChange={(e) => setResidence(e.target.value)}
                className="w-full p-2 bg-white border border-stone-200 rounded-xl text-xs font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              >
                <option value="未設定">🗾 都道府県（未選択）</option>
                {PREFECTURES.map((p) => (
                  <option key={p} value={p}>{p}</option>
                ))}
              </select>
              <MunicipalitySearchInput
                value={city}
                onChange={setCity}
                prefectureContext={residence}
                onSelectPrefecture={(autoPref) => setResidence(autoPref)}
                placeholder="市区町村 (例: 新宿区 / 横浜市 / 大阪市)"
              />
            </div>

            {/* 全国の駅名リアルタイム検索（その場のすぐ下に候補リストを展開） */}
            <StationSearchInput
              value={station}
              onChange={setStation}
              cityContext={city}
              prefectureContext={residence}
              onSelectPrefecture={(autoPref) => setResidence(autoPref)}
            />
          </div>
        </form>

        {/* 下部固定ボタン */}
        <div className="pt-2.5 mt-1 border-t border-stone-100 shrink-0 space-y-1.5">
          <button
            type="button"
            onClick={handleStart}
            className="w-full py-3 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-extrabold rounded-2xl shadow-md text-xs sm:text-sm flex items-center justify-center gap-2 transition-all active:scale-[0.99]"
          >
            <Check size={17} strokeWidth={2.8} />
            <span>この内容で「たびたび」を始める</span>
          </button>
          <div className="flex flex-col items-center gap-0.5 text-[10px] font-bold text-stone-400">
            <div className="flex items-center justify-center gap-3">
              <button type="button" onClick={() => setLegalModalType('terms')} className="underline hover:text-[#7A9D8C]">利用規約</button>
              <span>・</span>
              <button type="button" onClick={() => setLegalModalType('privacy')} className="underline hover:text-[#7A9D8C]">プライバシーポリシー</button>
            </div>
            <HeartRailsCreditBadge className="justify-center text-[9px] opacity-75" />
          </div>
        </div>

        {legalModalType && (
          <div className="fixed inset-0 bg-black/60 z-[300] flex justify-center items-center p-4 animate-in fade-in" onClick={() => setLegalModalType(null)}>
            <div className="bg-white w-full max-w-md rounded-[28px] p-5 shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-3 shrink-0">
                <h3 className="font-extrabold text-sm text-stone-800">
                  {legalModalType === 'terms' ? '📜 利用規約' : '🛡️ プライバシーポリシー'}
                </h3>
                <button type="button" onClick={() => setLegalModalType(null)} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={18} /></button>
              </div>
              <div className="flex-1 overflow-y-auto no-scrollbar text-xs text-stone-600 space-y-2.5 leading-relaxed pr-1">
                {legalModalType === 'terms' ? (
                  <>
                    <p className="font-bold text-stone-800">第1条（ベータ版のご利用について）</p>
                    <p>本アプリ「たびたび」は旅行計画・しおり共有アプリです。AIが提案する店舗・営業時間・料金等は最新情報と異なる場合があるため、公式情報もあわせてご確認ください。</p>
                  </>
                ) : (
                  <>
                    <p className="font-bold text-stone-800">1. 登録情報の取り扱い</p>
                    <p>入力されたニックネーム・最寄り駅・しおりデータは端末内および共有しおり機能のためにのみ使用されます。AI機能利用時は旅行条件テキストをGoogle Gemini APIへ送信します。</p>
                  </>
                )}
              </div>
              <button type="button" onClick={() => setLegalModalType(null)} className="mt-4 w-full py-2.5 bg-[#7A9D8C] text-white font-extrabold rounded-xl text-xs">閉じる</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function TabitabiApp() {
  const [currentUser, setCurrentUser] = useState(() => {
    const isOnboarded = localStorage.getItem(BETA_ONBOARDING_DONE_KEY) === 'true';
    const saved = sanitizeUser(safeParse('tabitabi_user', null));
    // 初回アクセス時（または以前の開発用ダミーユーザーのままの時）は、ベータ版の初回名前・最寄り駅登録画面を表示する
    if (!isOnboarded || !saved) return null;
    return saved;
  });
  const [trips, setTrips] = useState(() => {
    const saved = safeParse('tabitabi_trips', null);
    return Array.isArray(saved) && saved.length > 0 ? saved : INITIAL_SAMPLE_TRIPS;
  });
  const [publicTrips, setPublicTrips] = useState(() => sanitizePublicTrips(safeParse('tabitabi_public_trips', initialPublicTrips)));
  const [notifications, setNotifications] = useState(() => {
    const saved = safeParse('tabitabi_notifications', initialNotifications);
    return Array.isArray(saved)
      ? saved.filter(n => n.id !== 'n1' && n.message !== '温泉ボーイさんがあなたの旅にいいねしました。')
      : initialNotifications;
  });
  const [refreshCount, setRefreshCount] = useState(0);
  
  const [activeTripId, setActiveTripId] = useState(null);
  const [isReadOnlyMode, setIsReadOnlyMode] = useState(false);
  const [minimizedTripId, setMinimizedTripId] = useState(null);
  const [enlargedImageUrl, setEnlargedImageUrl] = useState(null);
  const [toastMsg, setToastMsg] = useState(null);
  const [dashboardState, setDashboardState] = useState({
    activeTab: 'my',
    discoverSort: 'trending',
    selectedRegion: 'すべて',
    searchQuery: '',
    scrollTop: 0,
    windowScrollY: 0
  });

  useEffect(() => {
    globalSetToast = (msg) => {
      setToastMsg(msg);
      setTimeout(() => setToastMsg(null), 3200);
    };
    return () => { globalSetToast = null; };
  }, []);

  // ★ ネット経由で全ユーザーの端末に同じ公式投稿・SNS投稿を配信するクラウド同期関数
  // 1) OFFICIAL_FEED_REMOTE_URL（Supabaseのpublic_tripsテーブルやGitHubのJSON）が設定されていればネットから全員同じ一覧を取得
  // 2) バックエンド未接続時でも、全ユーザーの端末で100%同じ週替わりコースが同じ順番で表示される決定論的同期を実行
  const fetchRemoteOfficialFeed = async (silent = true) => {
    const weeklyAutoCourse = buildAutoPilotWeeklyCourse(0);

    if (OFFICIAL_FEED_REMOTE_URL) {
      try {
        const res = await fetch(OFFICIAL_FEED_REMOTE_URL, { cache: 'no-store' });
        if (!res.ok) throw new Error('Fetch failed');
        const data = await res.json();
        const remoteList = Array.isArray(data) ? data : (Array.isArray(data?.trips) ? data.trips : null);
        if (remoteList && remoteList.length > 0) {
          setPublicTrips(sanitizePublicTrips([weeklyAutoCourse, ...remoteList]));
          return true;
        }
      } catch (e) {
        // 通信オフライン時は共通シードのフォールバックへ進む
      }
    }

    // 全ユーザーの端末でまったく同じラインナップ・同じ並び順になるよう同期
    setPublicTrips(prev => {
      const myLikedIds = new Set(
        (prev || [])
          .filter(t => Array.isArray(t.likedBy) && t.likedBy.includes(currentUser?.id))
          .map(t => t.id)
      );
      const baseFeed = [weeklyAutoCourse, ...initialPublicTrips];
      return baseFeed.map(trip => {
        const existing = (prev || []).find(p => p.id === trip.id);
        const isLiked = myLikedIds.has(trip.id);
        return {
          ...trip,
          likes: existing?.likes ?? trip.likes,
          likedBy: isLiked ? [currentUser?.id] : []
        };
      });
    });

    return true;
  };

  useEffect(() => {
    fetchRemoteOfficialFeed(true);
  }, []);

  useEffect(() => {
    if (currentUser) localStorage.setItem('tabitabi_user', JSON.stringify(currentUser)); else localStorage.removeItem('tabitabi_user');
    localStorage.setItem('tabitabi_trips', JSON.stringify(trips));
    localStorage.setItem('tabitabi_public_trips', JSON.stringify(publicTrips));
    localStorage.setItem('tabitabi_notifications', JSON.stringify(notifications));
  }, [currentUser, trips, publicTrips, notifications]);

  // ★ スマホブラウザ（iOS Safari / Chrome）で空の画面やヘッダーを触ったときに画面全体がバウンス・移動するのを防ぐグローバル設定
  // （ReactのHooksルールに従い、早期リターンより前に常時呼び出す）
  useEffect(() => {
    if (typeof document === 'undefined') return;
    const html = document.documentElement;
    const body = document.body;
    const prevHtmlOverscroll = html.style.overscrollBehavior;
    const prevBodyOverscroll = body.style.overscrollBehavior;
    const prevBodyOverflow = body.style.overflow;
    html.style.overscrollBehavior = 'none';
    body.style.overscrollBehavior = 'none';
    body.style.overflow = 'hidden';

    // ★ iOS Safari / Android 等で入力欄タップ時に勝手に画面がズームされて配置が崩れる現象を防止
    let metaViewport = document.querySelector('meta[name="viewport"]');
    const prevViewportContent = metaViewport ? metaViewport.getAttribute('content') : null;
    if (!metaViewport) {
      metaViewport = document.createElement('meta');
      metaViewport.name = 'viewport';
      document.head.appendChild(metaViewport);
    }
    metaViewport.setAttribute(
      'content',
      'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover'
    );

    const styleEl = document.createElement('style');
    styleEl.setAttribute('data-tabitabi-no-zoom', 'true');
    styleEl.textContent = `
      @media screen and (max-width: 768px) {
        input, select, textarea {
          font-size: 16px !important;
        }
      }
    `;
    document.head.appendChild(styleEl);

    return () => {
      html.style.overscrollBehavior = prevHtmlOverscroll;
      body.style.overscrollBehavior = prevBodyOverscroll;
      body.style.overflow = prevBodyOverflow;
      if (metaViewport && prevViewportContent) {
        metaViewport.setAttribute('content', prevViewportContent);
      }
      if (styleEl && styleEl.parentNode) {
        styleEl.parentNode.removeChild(styleEl);
      }
    };
  }, []);

  // 共有しおり（isSoloTrip === false）を開いている間はクラウドと自動同期する
  // （ReactのHooksルールに従い、if (!currentUser) の早期リターンより前に常時配置）
  useEffect(() => {
    if (!currentUser || !activeTripId || isReadOnlyMode) return;
    const currentOpenTrip = trips.find(t => t.id === activeTripId);
    if (!currentOpenTrip || currentOpenTrip.isSoloTrip) return;

    let cancelled = false;
    const syncOrPull = async () => {
      const remoteTrip = await fetchSharedTripFromCloud(activeTripId);
      if (cancelled) return;
      if (!remoteTrip) {
        // まだクラウド側に存在しない共有しおり（環境変数設定前に作ったしおり等）は自動でクラウドへ初回登録する
        await syncSharedTripToCloud(currentOpenTrip);
        return;
      }
      setTrips(prevTrips =>
        prevTrips.map(t => {
          if (t.id !== activeTripId) return t;
          const merged = mergeCloudTripWithLocalPhotos(remoteTrip, t);
          return JSON.stringify(stripTripPhotosForCloud(merged)) !== JSON.stringify(stripTripPhotosForCloud(t))
            ? merged
            : t;
        })
      );
    };

    syncOrPull();
    const timer = setInterval(syncOrPull, 4500);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [currentUser, activeTripId, isReadOnlyMode, trips]);

  if (!currentUser) {
    const prevSaved = sanitizeUser(safeParse('tabitabi_user', null));
    return (
      <BetaWelcomeSetupScreen
        initialUser={prevSaved}
        onComplete={(newUser) => {
          setCurrentUser(newUser);
        }}
      />
    );
  }

  let activeTrip = trips.find(t => t.id === activeTripId);
  if (!activeTrip && isReadOnlyMode) activeTrip = publicTrips.find(t => t.id === activeTripId);
  const minimizedTrip = trips.find(t => t.id === minimizedTripId) || null;

  if (activeTripId && !activeTrip) {
    setActiveTripId(null);
    return null;
  }

  const handleBackFromTrip = () => {
    if (!isReadOnlyMode && activeTrip && currentUser?.autoMinimizeTrip !== false) {
      setMinimizedTripId(activeTrip.id);
    }
    setActiveTripId(null);
    setIsReadOnlyMode(false);
  };

  const handleUpdateTripWithCloud = (updatedTrip) => {
    if (isReadOnlyMode) return;
    setTrips(prev => prev.map(t => (t.id === updatedTrip.id ? updatedTrip : t)));
    if (!updatedTrip.isSoloTrip) {
      syncSharedTripToCloud(updatedTrip);
    }
  };

  const handleToggleAutoMinimize = () => {
    const nextVal = !(currentUser?.autoMinimizeTrip !== false);
    setCurrentUser({ ...currentUser, autoMinimizeTrip: nextVal });
    if (!nextVal) {
      setMinimizedTripId(null);
    }
    customAlert(nextVal ? 'しおりを閉じたときの自動ミニ化をONにしました' : 'しおりを閉じたときの自動ミニ化をOFFにしました');
  };

  const handlePublishTrip = (publishedData) => setPublicTrips([publishedData, ...publicTrips]);

  const toggleLike = (tripId) => {
    if (currentUser.isGuest) { customAlert('「いいね」をするにはアカウント登録が必要です。\n右上のアイコンから登録してください！'); return; }
    setPublicTrips(publicTrips.map(t => {
      if (t.id === tripId) {
        const hasLiked = t.likedBy?.includes(currentUser.id);
        return { ...t, likes: hasLiked ? t.likes - 1 : t.likes + 1, likedBy: hasLiked ? (t.likedBy || []).filter(id => id !== currentUser.id) : [...(t.likedBy || []), currentUser.id] };
      }
      return t;
    }));
  };

  const handleAddComment = (tripId, text) => {
    if (currentUser.isGuest) { customAlert('コメントするにはアカウント登録が必要です。'); return; }
    setPublicTrips(publicTrips.map(t => {
      if (t.id === tripId) return { ...t, comments: [...(t.comments || []), { id: generateId(), text, authorId: currentUser.id, authorName: currentUser.name, authorAvatar: currentUser.avatar, createdAt: Date.now() }] };
      return t;
    }));
  };

  const upgradeGuestUser = (newUserData) => {
    setCurrentUser(newUserData);
    const updatedTrips = trips.map(t => ({ ...t, members: (t.members || []).map(m => m.id === currentUser.id ? { ...newUserData, color: m.color } : m) }));
    setTrips(updatedTrips);
  };

  const handleToggleFollow = (targetAuthorId, targetAuthorName) => {
    if (!targetAuthorId) return;
    if (currentUser.isGuest) {
      customAlert('フォローするにはアカウント登録が必要です。');
      return;
    }
    if (targetAuthorId === currentUser.id) return;

    const followingList = Array.isArray(currentUser.following) ? currentUser.following : [];
    const isFollowing = followingList.includes(targetAuthorId);
    const nextFollowing = isFollowing
      ? followingList.filter(id => id !== targetAuthorId)
      : [...followingList, targetAuthorId];

    setCurrentUser({ ...currentUser, following: nextFollowing });
    customAlert(isFollowing ? `${targetAuthorName || 'ユーザー'}のフォローを解除しました` : `${targetAuthorName || 'ユーザー'}をフォローしました！`);
  };

  // X風の「引っ張って更新」：端末ごとにバラバラな乱数投稿を作るのではなく、サーバー上の最新フィードと全員同じ状態に同期する
  const handleRefreshPublicTrips = async () => {
    await fetchRemoteOfficialFeed(true);
    setRefreshCount(prev => prev + 1);
  };

  return (
    <div className="fixed inset-0 w-full h-[100dvh] font-sans flex justify-center bg-stone-300 text-stone-800 antialiased selection:bg-[#7A9D8C]/20 overflow-hidden overscroll-none">
      <div className="w-full max-w-md h-full relative shadow-2xl flex flex-col overflow-hidden overscroll-none bg-[#F4F7F5]">
        <div className={activeTripId ? 'hidden' : 'flex-1 flex flex-col h-full overflow-hidden'}>
          <Dashboard 
            currentUser={currentUser} onUpgradeUser={upgradeGuestUser} onLogout={() => setCurrentUser(null)}
            trips={trips} publicTrips={publicTrips} setPublicTrips={setPublicTrips} setTrips={setTrips}
            dashboardState={dashboardState} setDashboardState={setDashboardState}
            onOpenTrip={(id, readOnly = false) => { setIsReadOnlyMode(readOnly); setActiveTripId(id); }} 
            onToggleLike={toggleLike} onToggleFollow={handleToggleFollow} onEnlargeImage={setEnlargedImageUrl}
            onRefreshPublicTrips={handleRefreshPublicTrips}
            notifications={notifications} setNotifications={setNotifications} onAddComment={handleAddComment}
            onCopySave={(newTrip, updatedTrip) => {
              if (newTrip) {
                setTrips([newTrip, ...trips]);
                setDashboardState(prev => ({ ...prev, activeTab: 'my' }));
                setIsReadOnlyMode(false);
                setActiveTripId(newTrip.id);
                customAlert(newTrip.isSoloTrip ? '👤 1人旅のしおりとしてコピーしました！' : '👥 みんなの旅のしおりとしてコピーしました！');
              } else if (updatedTrip) {
                setTrips(trips.map(t => t.id === updatedTrip.id ? updatedTrip : t));
                setDashboardState(prev => ({ ...prev, activeTab: 'my' }));
                setIsReadOnlyMode(false);
                setActiveTripId(updatedTrip.id);
                customAlert('選択したしおりに予定をコピーしました！');
              }
            }}
            isHidden={Boolean(activeTripId)}
          />
        </div>
        {activeTripId && (
          <TripDetail 
            currentUser={currentUser} trip={activeTrip} isReadOnly={isReadOnlyMode} myTrips={trips}
            updateTrip={handleUpdateTripWithCloud}
            onDeleteTrip={(tripIdToDelete) => {
              setTrips(trips.filter(t => t.id !== tripIdToDelete));
              if (minimizedTripId === tripIdToDelete) setMinimizedTripId(null);
              setActiveTripId(null);
              customAlert('しおりを削除しました');
            }}
            onToggleAutoMinimize={handleToggleAutoMinimize}
            onPublish={handlePublishTrip} onBack={handleBackFromTrip} onEnlargeImage={setEnlargedImageUrl}
            onCopySave={(newTrip, updatedTrip) => {
              if (newTrip) {
                setTrips([newTrip, ...trips]);
                setDashboardState(prev => ({ ...prev, activeTab: 'my' }));
                setIsReadOnlyMode(false);
                setActiveTripId(newTrip.id);
                customAlert(newTrip.isSoloTrip ? '👤 1人旅のしおりとしてコピーしました！' : '👥 みんなの旅のしおりとしてコピーしました！');
              } else if (updatedTrip) {
                setTrips(trips.map(t => t.id === updatedTrip.id ? updatedTrip : t));
                setDashboardState(prev => ({ ...prev, activeTab: 'my' }));
                setIsReadOnlyMode(false);
                setActiveTripId(updatedTrip.id);
                customAlert('予定を自分のしおりにコピーしました！');
              }
            }}
            onOpenAuthUpgrade={() => {
              setActiveTripId(null);
              customAlert('右上のプロフィールアイコンから無料アカウント登録ができます！');
            }}
            onAddComment={handleAddComment}
          />
        )}

        {/* LINEのマルチタスクアイコンのように画面のどこにでもドラッグ配置できるミニしおりアイコン（別の自分のしおりを開いている時は非表示） */}
        {minimizedTrip && (!activeTripId || isReadOnlyMode) && (
          <FloatingTripBubble
            trip={minimizedTrip}
            isViewingOtherTrip={Boolean(activeTripId && isReadOnlyMode)}
            onRestore={() => {
              setIsReadOnlyMode(false);
              setActiveTripId(minimizedTrip.id);
            }}
            onClose={() => setMinimizedTripId(null)}
          />
        )}

        {enlargedImageUrl && (
          <div className="fixed inset-0 bg-black/85 z-[300] flex flex-col items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setEnlargedImageUrl(null)}>
            <button className="absolute top-5 right-5 w-10 h-10 rounded-full bg-white/20 text-white flex items-center justify-center hover:bg-white/30 transition-colors"><X size={22} /></button>
            <div className="max-w-md w-full max-h-[75vh] flex flex-col items-center justify-center gap-3" onClick={e => e.stopPropagation()}>
              <img src={enlargedImageUrl} alt="Enlarged view" className="max-w-full max-h-[68vh] rounded-2xl object-contain shadow-2xl animate-in zoom-in-95" />
              <button
                type="button"
                onClick={() => sharePhotoViaNativeSheet(enlargedImageUrl, '旅の思い出写真')}
                className="px-5 py-2.5 rounded-full bg-[#06C755] hover:brightness-95 text-white text-xs font-extrabold flex items-center gap-1.5 shadow-lg active:scale-95 transition-all"
              >
                <Share2 size={14} /> AirDrop / LINE で写真を送る
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
// LINEのマルチタスクアイコンのようにドラッグ移動できるフローティングミニしおりバブル（より小さくコンパクト化）
function FloatingTripBubble({ trip, isViewingOtherTrip, onRestore, onClose }) {
  const [pos, setPos] = useState({ x: 12, y: 96 });
  const dragRef = useRef(null);

  const handleTouchStart = (e) => {
    const t = e.touches[0];
    dragRef.current = { startX: t.clientX - pos.x, startY: t.clientY - pos.y };
  };

  const handleTouchMove = (e) => {
    if (!dragRef.current) return;
    const t = e.touches[0];
    setPos({
      x: Math.max(8, Math.min(window.innerWidth - 145, t.clientX - dragRef.current.startX)),
      y: Math.max(54, Math.min(window.innerHeight - 80, t.clientY - dragRef.current.startY))
    });
  };

  const handleTouchEnd = () => {
    dragRef.current = null;
  };

  return (
    <div
      style={{ left: `${pos.x}px`, top: `${pos.y}px` }}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      className="fixed z-[180] flex items-center gap-1.5 bg-stone-900/90 text-white pl-2.5 pr-1.5 py-1 rounded-full shadow-lg border border-white/20 backdrop-blur-md select-none"
    >
      <button
        type="button"
        onClick={onRestore}
        className="flex items-center gap-1.5 text-left max-w-[115px] cursor-pointer"
      >
        <Compass size={12} className="text-[#7A9D8C] shrink-0" />
        <div className="min-w-0">
          <p className="text-[8px] text-emerald-300 font-bold leading-none">
            {isViewingOtherTrip ? '元のしおりへ' : 'ミニ表示中'}
          </p>
          <p className="text-[10px] font-extrabold truncate leading-tight mt-0.5">{trip.title}</p>
        </div>
      </button>
      <button
        type="button"
        onClick={onClose}
        className="p-0.5 rounded-full hover:bg-white/15 text-stone-300 cursor-pointer"
        title="ミニ表示を閉じる"
      >
        <X size={11} />
      </button>
    </div>
  );
}

function TripCard({ trip, onOpenTrip, isPast = false }) {
  const memberCount = (trip.members || []).length;
  return (
    <div
      onClick={() => onOpenTrip(trip.id, false)}
      className={`bg-white p-4 rounded-3xl border shadow-xs hover:shadow-md transition-all cursor-pointer flex items-center justify-between gap-3 ${
        isPast ? 'border-stone-200/70 opacity-85' : 'border-stone-200/90 hover:border-[#7A9D8C]'
      }`}
    >
      <div className="min-w-0 flex-1 space-y-1">
        <div className="flex items-center gap-1.5 flex-wrap">
          <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-[#7A9D8C]/15 text-[#4A6B5D]">
            {trip.isSoloTrip ? '👤 1人旅' : `👥 共有 (${memberCount}人)`}
          </span>
          <span className="text-[10px] font-bold text-stone-500 flex items-center gap-0.5">
            <MapPin size={11} className="text-[#7A9D8C]" /> {trip.destination || '未設定'}
          </span>
        </div>
        <h3 className="font-extrabold text-sm text-stone-800 truncate">{trip.title}</h3>
        <div className="flex items-center gap-3 text-[11px] font-bold text-stone-400">
          <span className="flex items-center gap-1">
            <Calendar size={11} /> {trip.startDate?.replace(/-/g, '/')} 〜 {trip.endDate?.slice(5).replace('-', '/')}
          </span>
          <span>予定 {(trip.events || []).length}件</span>
        </div>
      </div>
      <div className="flex items-center gap-2 shrink-0">
        <div className="flex -space-x-2">
          {(trip.members || []).slice(0, 3).map((m, idx) => (
            <UserAvatar key={m.id || idx} user={m} size="w-7 h-7" />
          ))}
        </div>
        <ChevronRight size={18} className="text-stone-400" />
      </div>
    </div>
  );
}

function CreateTripWizard({ currentUser, onClose, onComplete }) {
  useLockBodyScroll(true);
  const defaultOrigin = useMemo(() => getHomeDepartureLabel(currentUser), [currentUser]);
  const tripCodeRef = useRef(generateTripCode());
  const [title, setTitle] = useState('');
  const [departurePoint, setDeparturePoint] = useState(defaultOrigin);
  const [saveOriginForNext, setSaveOriginForNext] = useState(false);
  const [destination, setDestination] = useState('');
  const [destinationError, setDestinationError] = useState(false);
  const [destinationErrorMsg, setDestinationErrorMsg] = useState('');
  const [isValidatingDest, setIsValidatingDest] = useState(false);
  const destinationInputRef = useRef(null);
  const [startDate, setStartDate] = useState(getTodayString());
  const [endDate, setEndDate] = useState(getTodayString());
  const [budget, setBudget] = useState(35000);
  const [isSoloTrip, setIsSoloTrip] = useState(false);
  const [myColor, setMyColor] = useState(PRESET_COLORS[0]);
  const [showAiModal, setShowAiModal] = useState(false);

  const handleCreate = async (e) => {
    if (e) e.preventDefault();
    if (isValidatingDest) return;
    const trimmedDest = (destination || '').trim();
    if (!trimmedDest) {
      setDestinationError(true);
      setDestinationErrorMsg('目的地・エリアが未入力です。行き先を入力してください！');
      customAlert('⚠️ 「目的地・エリア」を入力してください！');
      destinationInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => destinationInputRef.current?.focus(), 80);
      return;
    }

    setIsValidatingDest(true);
    const checkResult = await validateDestinationInput(trimmedDest);
    setIsValidatingDest(false);

    if (!checkResult.valid) {
      setDestinationError(true);
      setDestinationErrorMsg(checkResult.message);
      destinationInputRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => destinationInputRef.current?.focus(), 80);
      return;
    }

    setDestinationError(false);
    setDestinationErrorMsg('');

    if (saveOriginForNext && departurePoint.trim()) {
      addSavedDeparturePoint(departurePoint.trim());
    }
    const finalTitle = title.trim() || `${trimmedDest}の旅`;
    const newTrip = {
      id: tripCodeRef.current,
      title: finalTitle,
      departurePoint: departurePoint.trim() || defaultOrigin,
      destination: trimmedDest,
      startDate,
      endDate: endDate >= startDate ? endDate : startDate,
      budget: Math.max(0, Number(budget) || 0),
      members: [{ id: currentUser.id, name: currentUser.name, avatar: currentUser.avatar, color: myColor }],
      isSoloTrip,
      events: [],
      photos: [],
      packingList: [],
      souvenirList: [],
      extraExpenses: []
    };
    onComplete(newTrip);
  };

  return (
    <div className="fixed inset-0 bg-black/55 z-[200] flex justify-center items-start sm:items-center pt-2 sm:pt-4 p-2.5 sm:p-4 overflow-hidden animate-in fade-in" onClick={onClose}>
      <div className="relative bg-white w-full max-w-md rounded-[28px] p-4 sm:p-5 shadow-2xl h-[92dvh] max-h-[92dvh] flex flex-col overflow-hidden animate-in zoom-in-95 pb-safe" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-2.5 shrink-0">
          <h3 className="font-extrabold text-sm sm:text-base text-stone-800 flex items-center gap-1.5">
            <Compass size={18} className="text-[#7A9D8C]" /> 新しい旅のしおりを作成
          </h3>
          <button type="button" onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full cursor-pointer"><X size={20} /></button>
        </div>

        <div className="flex-1 min-h-0 overflow-y-auto no-scrollbar space-y-3 pr-0.5 pb-2">
          <button
            type="button"
            onClick={() => setShowAiModal(true)}
            className="w-full p-3.5 rounded-2xl bg-gradient-to-r from-sky-100 via-emerald-50 to-cyan-100 border border-sky-300/80 text-left flex items-center justify-between gap-2 shadow-2xs hover:brightness-98 active:scale-[0.99] transition-all cursor-pointer"
          >
            <div className="flex items-center gap-2.5 min-w-0 pointer-events-none">
              <div className="w-9 h-9 rounded-xl bg-white flex items-center justify-center text-sky-600 shadow-2xs shrink-0">
                <Sparkles size={18} />
              </div>
              <div className="min-w-0">
                <p className="text-xs font-extrabold text-sky-950">AIにおまかせでプランを提案してもらう</p>
                <p className="text-[10px] font-bold text-sky-800 truncate">条件やチャット相談から自動でしおりを作成</p>
              </div>
            </div>
            <ChevronRight size={16} className="text-sky-700 shrink-0 pointer-events-none" />
          </button>

          <form id="create-trip-form" onSubmit={handleCreate} className="space-y-3">
            <div>
              <label className="text-xs font-extrabold text-stone-600 block mb-1 pl-0.5">旅のタイトル（省略時は目的地から自動設定）</label>
              <input
                type="text"
                value={title}
                onChange={e => setTitle(e.target.value)}
                placeholder="例: 秋の京都グルメ旅"
                className="w-full p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-sm font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
            </div>

            <DepartureSelectorBox
              user={currentUser}
              value={departurePoint}
              onChange={setDeparturePoint}
              saveForNext={saveOriginForNext}
              onChangeSaveForNext={setSaveOriginForNext}
              label="出発地点"
              compact
            />

            <div>
              <label className="text-xs font-extrabold text-stone-700 flex items-center justify-between mb-1 pl-0.5">
                <span className="flex items-center gap-1">
                  <MapPin size={13} className="text-[#7A9D8C] shrink-0" /> 目的地・エリア
                </span>
                <span className="text-[10px] font-extrabold text-rose-500 bg-rose-50 px-2 py-0.5 rounded-full border border-rose-200">
                  必須
                </span>
              </label>
              <input
                ref={destinationInputRef}
                type="text"
                value={destination}
                onChange={e => {
                  setDestination(e.target.value);
                  if (destinationError && e.target.value.trim()) {
                    setDestinationError(false);
                    setDestinationErrorMsg('');
                  }
                }}
                placeholder="例: 京都府 / 箱根 / 沖縄（必須）"
                className={`w-full p-2.5 rounded-xl text-sm font-extrabold text-stone-800 focus:outline-none focus:ring-2 transition-all ${
                  destinationError
                    ? 'bg-rose-50 border-2 border-rose-400 focus:ring-rose-400'
                    : 'bg-stone-50 border border-stone-200 focus:ring-[#7A9D8C]'
                }`}
              />
              {destinationError && (
                <p className="mt-1.5 text-[11px] font-extrabold text-rose-600 flex items-start gap-1 pl-0.5 leading-snug animate-in fade-in">
                  <AlertCircle size={13} className="shrink-0 text-rose-500 mt-0.5" />
                  <span>{destinationErrorMsg || '目的地・エリアが未入力です。行き先を入力してください！'}</span>
                </p>
              )}
            </div>

            <WheelDateRangePicker
              startDate={startDate}
              endDate={endDate}
              onChangeStart={(nextStart) => {
                setStartDate(nextStart);
                if (endDate < nextStart) setEndDate(nextStart);
              }}
              onChangeEnd={(nextEnd) => setEndDate(nextEnd)}
              compact
            />

            {/* 1人あたり予算目安（スライダーバー ＆ 直接手入力対応） */}
            <div className="bg-stone-50/90 p-3 rounded-2xl border border-rose-200/70 space-y-2">
              <div className="flex items-center justify-between gap-1.5 flex-wrap">
                <label className="text-xs font-extrabold text-stone-700 flex items-center gap-1.5">
                  <span className="w-5 h-5 rounded-full bg-rose-100 text-rose-500 flex items-center justify-center text-xs shadow-2xs">
                    🪙
                  </span>
                  <span>1人あたりの予算目安（手入力・バー両対応）</span>
                </label>
                <div className="relative flex items-center">
                  <span className="absolute left-2.5 text-xs font-extrabold text-[#4A6B5D] pointer-events-none">¥</span>
                  <input
                    type="number"
                    inputMode="numeric"
                    min="0"
                    step="1000"
                    value={budget === 0 ? '' : budget}
                    onChange={e => {
                      const raw = e.target.value;
                      setBudget(raw === '' ? 0 : Math.max(0, Number(raw)));
                    }}
                    placeholder="35000"
                    className="w-28 pl-6 pr-2 py-1 rounded-xl bg-white border border-[#7A9D8C]/40 text-sm font-mono font-extrabold text-[#4A6B5D] text-right focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                  />
                </div>
              </div>

              <div className="px-0.5 pt-0.5">
                <input
                  type="range"
                  min="0"
                  max="150000"
                  step="1000"
                  value={Math.min(150000, Math.max(0, Number(budget) || 0))}
                  onChange={e => setBudget(Number(e.target.value))}
                  style={{
                    background: `linear-gradient(to right, #F4A2B8 0%, #7A9D8C ${Math.round(
                      (Math.min(150000, Math.max(0, Number(budget) || 0)) / 150000) * 100
                    )}%, #E7E5E4 ${Math.round(
                      (Math.min(150000, Math.max(0, Number(budget) || 0)) / 150000) * 100
                    )}%, #E7E5E4 100%)`
                  }}
                  className="w-full h-2.5 rounded-full appearance-none cursor-pointer accent-[#7A9D8C]"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setIsSoloTrip(false)}
                className={`p-2.5 rounded-xl border text-xs font-extrabold transition-all cursor-pointer ${
                  !isSoloTrip ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 text-[#4A6B5D]' : 'border-stone-200 bg-white text-stone-500'
                }`}
              >
                <span className="pointer-events-none">👥 みんなで共有</span>
              </button>
              <button
                type="button"
                onClick={() => setIsSoloTrip(true)}
                className={`p-2.5 rounded-xl border text-xs font-extrabold transition-all cursor-pointer ${
                  isSoloTrip ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 text-[#4A6B5D]' : 'border-stone-200 bg-white text-stone-500'
                }`}
              >
                <span className="pointer-events-none">👤 1人旅（自分専用）</span>
              </button>
            </div>
          </form>
        </div>

        <div className="pt-2.5 mt-1 border-t border-stone-100 shrink-0 relative z-20 bg-white">
          <button
            type="button"
            disabled={isValidatingDest}
            onClick={handleCreate}
            className="w-full py-3.5 px-4 bg-[#7A9D8C] hover:bg-[#688a79] disabled:opacity-60 active:scale-[0.99] text-white font-extrabold rounded-2xl text-xs sm:text-sm shadow-sm flex items-center justify-center gap-1.5 transition-all cursor-pointer select-none"
          >
            <Check size={16} strokeWidth={2.8} className="pointer-events-none shrink-0" />
            <span className="pointer-events-none">
              {isValidatingDest ? '目的地を確認中...' : 'この内容でしおりを作成する'}
            </span>
          </button>
        </div>

        {showAiModal && (
          <AiPlanSuggestModal
            currentUser={currentUser}
            onClose={() => setShowAiModal(false)}
            onSelectPlan={(plan) => {
              const isSolo = Boolean(currentUser.isGuest || plan.isSoloPlan);
              const planEvents = (plan.events || []).map(ev => ({
                ...ev,
                id: generateId(),
                status: isSolo ? 'approved' : 'proposed',
                authorId: currentUser.id,
                photos: []
              }));
              setShowAiModal(false);
              onComplete({
                id: tripCodeRef.current,
                title: plan.title || '新しい旅行',
                departurePoint: plan.departurePoint || departurePoint || defaultOrigin,
                destination: plan.destination || '行き先未定',
                startDate: plan.startDate,
                endDate: plan.endDate,
                budget: Number(plan.budget) || 50000,
                members: [{ id: currentUser.id, name: currentUser.name, avatar: currentUser.avatar, color: myColor }],
                isSoloTrip: isSolo,
                events: planEvents,
                photos: []
              });
            }}
          />
        )}
      </div>
    </div>
  );
}

function Dashboard({
  currentUser,
  onUpgradeUser,
  onLogout,
  trips,
  publicTrips,
  setPublicTrips,
  setTrips,
  dashboardState,
  setDashboardState,
  onOpenTrip,
  onToggleLike,
  onToggleFollow,
  onEnlargeImage,
  onRefreshPublicTrips,
  notifications,
  setNotifications,
  onAddComment,
  onCopySave
}) {
  const activeTab = dashboardState?.activeTab || 'my';
  const setActiveTab = (tab) => setDashboardState(prev => ({ ...prev, activeTab: tab }));

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [viewingUserProfile, setViewingUserProfile] = useState(null);
  const [dashboardCopyTarget, setDashboardCopyTarget] = useState(null);
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const [hideChrome, setHideChrome] = useState(false);
  const lastScrollTopRef = useRef(0);
  const scrollContainerRef = useRef(null);

  useEffect(() => {
    setHideChrome(false);
    lastScrollTopRef.current = 0;
  }, [activeTab]);

  // スクロール領域の高さを変えずに transform だけで上下バーを出し入れするため、ガタつきが一切発生しないスクロール検知
  const handleFeedScroll = (e) => {
    const el = e.currentTarget;
    const currentTop = Math.max(0, el.scrollTop);
    const diff = currentTop - lastScrollTopRef.current;

    if (currentTop <= 16) {
      if (hideChrome) setHideChrome(false);
    } else if (diff > 12 && currentTop > 48 && !isFilterOpen) {
      if (!hideChrome) setHideChrome(true);
    } else if (diff < -10) {
      if (hideChrome) setHideChrome(false);
    }
    lastScrollTopRef.current = currentTop;
  };

  const todayStr = getTodayString();
  const upcomingTrips = useMemo(
    () => (trips || []).filter(t => (t.endDate || t.startDate || '') >= todayStr).sort((a, b) => (a.startDate || '').localeCompare(b.startDate || '')),
    [trips, todayStr]
  );
  const pastTrips = useMemo(
    () => (trips || []).filter(t => (t.endDate || t.startDate || '') < todayStr).sort((a, b) => (b.endDate || '').localeCompare(a.endDate || '')),
    [trips, todayStr]
  );

  const handleOpenTripWithScroll = (id, readOnly = false) => {
    onOpenTrip(id, readOnly);
  };

  return (
    <div className="flex-1 flex flex-col h-full overflow-hidden relative">
      {/* 上部ヘッダー（高さを変えずに translateY で滑らかに隠すことでスクロールのガタつきを防止） */}
      <div
        className={`absolute top-0 inset-x-0 bg-white/95 backdrop-blur-md px-5 pt-4 pb-3 shadow-xs z-30 border-b border-stone-100 transition-transform duration-300 ease-out will-change-transform ${
          hideChrome && !isFilterOpen
            ? '-translate-y-full pointer-events-none'
            : 'translate-y-0'
        }`}
      >
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-2">
            <span className="font-extrabold tracking-widest text-xl text-[#7A9D8C]">たびたび</span>
          </div>
          <div className="flex items-center gap-1.5">
            {activeTab === 'discover' && (
              <button
                type="button"
                onClick={() => setIsFilterOpen(prev => !prev)}
                className="p-2 text-stone-500 hover:bg-stone-100 rounded-full transition-colors"
                title="キーワード検索"
              >
                <Search size={19} />
              </button>
            )}
            <button
              type="button"
              onClick={() => {
                setShowNotifications(!showNotifications);
                setNotifications((notifications || []).map(n => ({ ...n, read: true })));
              }}
              className="relative p-2 text-stone-500 hover:bg-stone-100 rounded-full transition-colors"
            >
              <Bell size={20} />
              {(notifications || []).some(n => !n.read) && (
                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full border border-white" />
              )}
            </button>
            <button
              type="button"
              onClick={() => setShowProfileModal(true)}
              className="relative group transition-transform active:scale-95 outline-none"
            >
              <UserAvatar user={currentUser} size="w-9 h-9" />
            </button>
          </div>
        </div>
      </div>

      <div
        ref={activeTab === 'my' || activeTab === 'badges' ? scrollContainerRef : null}
        onScroll={activeTab === 'my' || activeTab === 'badges' ? handleFeedScroll : undefined}
        className={`flex-1 bg-[#F4F7F5] ${activeTab === 'my' || activeTab === 'badges' ? 'overflow-y-auto overscroll-y-contain no-scrollbar pt-16' : 'flex flex-col overflow-hidden'}`}
      >
        {activeTab === 'my' ? (
          <div className="px-5 py-5 pb-28 space-y-5 animate-in fade-in duration-200">
            <div className="flex gap-2.5">
              <button
                type="button"
                onClick={() => setShowCreateModal(true)}
                className="flex-1 py-3.5 bg-[#7A9D8C] text-white font-extrabold rounded-2xl shadow-xs text-xs sm:text-sm flex justify-center items-center gap-1.5 hover:bg-[#688a79] active:scale-[0.99] transition-all"
              >
                <Plus size={17} /> 新しい旅のしおり
              </button>
              <button
                type="button"
                onClick={() => setShowJoinModal(true)}
                className="flex-1 py-3.5 bg-white text-[#7A9D8C] border-2 border-[#7A9D8C] font-extrabold rounded-2xl shadow-xs text-xs sm:text-sm flex justify-center items-center gap-1.5 hover:bg-stone-50 active:scale-[0.99] transition-all"
              >
                <Check size={17} /> コードで参加
              </button>
            </div>

            {trips.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 text-center bg-white rounded-3xl border border-stone-200/70 p-6">
                <div className="w-16 h-16 bg-[#7A9D8C]/10 rounded-3xl flex items-center justify-center mb-3 text-[#7A9D8C]">
                  <Compass size={32} strokeWidth={1.8} />
                </div>
                <h3 className="text-sm font-extrabold text-stone-800 mb-1">まだ旅行のしおりがありません</h3>
                <p className="text-xs text-stone-500 leading-relaxed">
                  「＋ 新しい旅のしおり」から作成するか、<br />友達から届いた招待コード（TABI-XXXX）で参加しましょう！
                </p>
              </div>
            ) : (
              <div className="space-y-5">
                {upcomingTrips.length > 0 && (
                  <div className="space-y-2.5">
                    <h2 className="text-xs font-extrabold text-stone-500 flex items-center gap-1.5 pl-1">
                      <Calendar size={14} className="text-[#7A9D8C]" /> これからの旅 ({upcomingTrips.length})
                    </h2>
                    {upcomingTrips.map(trip => (
                      <TripCard key={trip.id} trip={trip} onOpenTrip={handleOpenTripWithScroll} />
                    ))}
                  </div>
                )}
                {pastTrips.length > 0 && (
                  <div className="space-y-2.5">
                    <h2 className="text-xs font-extrabold text-stone-400 flex items-center gap-1.5 pl-1">
                      <Camera size={14} /> 過去の旅・思い出 ({pastTrips.length})
                    </h2>
                    {pastTrips.map(trip => (
                      <TripCard key={trip.id} trip={trip} onOpenTrip={handleOpenTripWithScroll} isPast />
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        ) : activeTab === 'discover' ? (
          <DiscoverTab
            publicTrips={publicTrips}
            setPublicTrips={setPublicTrips}
            currentUser={currentUser}
            dashboardState={dashboardState}
            setDashboardState={setDashboardState}
            onOpenTrip={handleOpenTripWithScroll}
            onCopyTrip={(tripToCopy) => setDashboardCopyTarget({ type: 'trip', data: tripToCopy })}
            onToggleLike={onToggleLike}
            onToggleFollow={onToggleFollow}
            onOpenUserProfile={setViewingUserProfile}
            onEnlargeImage={onEnlargeImage}
            onRefreshPublicTrips={onRefreshPublicTrips}
            onAddComment={onAddComment}
            scrollContainerRef={scrollContainerRef}
            hideChrome={hideChrome}
            onFeedScroll={handleFeedScroll}
            isFilterOpen={isFilterOpen}
            setIsFilterOpen={setIsFilterOpen}
          />
        ) : (
          <TravelBadgesMapPage
            currentUser={currentUser}
            onUpdateUser={onUpgradeUser}
            onOpenProfile={() => setShowProfileModal(true)}
            hideChrome={hideChrome}
          />
        )}
      </div>

      {/* 下部ボトムナビゲーションバー（スクロール中は下へスッと隠れ、上スクロールで戻る） */}
      <nav
        className={`absolute bottom-0 inset-x-0 bg-white/95 backdrop-blur-md border-t border-stone-200/70 flex justify-around pb-safe z-30 shadow-[0_-2px_10px_rgba(0,0,0,0.03)] transition-transform duration-300 ease-out will-change-transform ${
          hideChrome && !isFilterOpen
            ? 'translate-y-full pointer-events-none'
            : 'translate-y-0'
        }`}
      >
        <button
          type="button"
          onClick={() => setActiveTab('my')}
          className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${
            activeTab === 'my' ? 'text-[#7A9D8C]' : 'text-stone-400 hover:text-stone-600'
          }`}
        >
          <div className={`px-3.5 py-1 rounded-xl transition-colors ${activeTab === 'my' ? 'bg-[#7A9D8C]/15' : ''}`}>
            <Compass size={20} strokeWidth={activeTab === 'my' ? 2.5 : 2} />
          </div>
          <span className="text-[11px] font-extrabold">自分たちの旅</span>
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('discover')}
          className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${
            activeTab === 'discover' ? 'text-[#7A9D8C]' : 'text-stone-400 hover:text-stone-600'
          }`}
        >
          <div className={`px-3.5 py-1 rounded-xl transition-colors ${activeTab === 'discover' ? 'bg-[#7A9D8C]/15' : ''}`}>
            <Globe size={20} strokeWidth={activeTab === 'discover' ? 2.5 : 2} />
          </div>
          <span className="text-[11px] font-extrabold">みんなの旅</span>
        </button>
        <button
          type="button"
          onClick={() => setActiveTab('badges')}
          className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${
            activeTab === 'badges' ? 'text-[#7A9D8C]' : 'text-stone-400 hover:text-stone-600'
          }`}
        >
          <div className={`px-3.5 py-1 rounded-xl transition-colors ${activeTab === 'badges' ? 'bg-[#7A9D8C]/15' : ''}`}>
            <MapPin size={20} strokeWidth={activeTab === 'badges' ? 2.5 : 2} />
          </div>
          <span className="text-[11px] font-extrabold">日本地図</span>
        </button>
      </nav>

      {showCreateModal && (
        <CreateTripWizard
          currentUser={currentUser}
          onClose={() => setShowCreateModal(false)}
          onComplete={(newTrip) => {
            setShowCreateModal(false);
            setTrips([newTrip, ...trips]);
            if (!newTrip.isSoloTrip) {
              syncSharedTripToCloud(newTrip);
            }
            handleOpenTripWithScroll(newTrip.id, false);
          }}
        />
      )}

      {showJoinModal && (
        <JoinTripWizard
          currentUser={currentUser}
          trips={trips}
          setTrips={setTrips}
          onClose={() => setShowJoinModal(false)}
          onOpenTrip={handleOpenTripWithScroll}
        />
      )}

      {showProfileModal && (
        <UserSettingsModal
          currentUser={currentUser}
          publicTrips={publicTrips}
          onToggleFollow={onToggleFollow}
          onUpgradeUser={onUpgradeUser}
          onClose={() => setShowProfileModal(false)}
          onLogout={onLogout}
        />
      )}

      {viewingUserProfile && (
        <PublicUserProfileModal
          userProfile={viewingUserProfile}
          publicTrips={publicTrips}
          currentUser={currentUser}
          onToggleFollow={onToggleFollow}
          onOpenTrip={(id) => {
            setViewingUserProfile(null);
            handleOpenTripWithScroll(id, true);
          }}
          onClose={() => setViewingUserProfile(null)}
        />
      )}

      {dashboardCopyTarget && (
        <CopyModal
          type={dashboardCopyTarget.type}
          sourceData={dashboardCopyTarget.data}
          currentUser={currentUser}
          myTrips={trips}
          onClose={() => setDashboardCopyTarget(null)}
          onComplete={(newTrip, updatedTrip) => {
            if (newTrip && !newTrip.isSoloTrip) {
              syncSharedTripToCloud(newTrip);
            } else if (updatedTrip && !updatedTrip.isSoloTrip) {
              syncSharedTripToCloud(updatedTrip);
            }
            onCopySave(newTrip, updatedTrip);
            setDashboardCopyTarget(null);
          }}
        />
      )}
    </div>
  );
}

function UserSettingsModal({ currentUser, user: userProp, publicTrips = [], onToggleFollow, onOpenUserProfile, onUpgradeUser, onClose, onLogout }) {
  useLockBodyScroll(true);
  const user = currentUser || userProp || {};
  const [currentView, setCurrentView] = useState('menu');
  const [followListTab, setFollowListTab] = useState('following');
  // App Store / Google Play ストア審査対応用の通知・位置情報・お問い合わせステート
  const [notifSettings, setNotifSettings] = useState(() =>
    safeParse('tabitabi_notif_settings', {
      tripReminder: true,
      memberUpdate: true,
      aiTips: false
    })
  );
  const [locationSettings, setLocationSettings] = useState(() =>
    safeParse('tabitabi_location_settings', {
      useNearestStation: true,
      mapNavIntegration: true
    })
  );
  const [contactCategory, setContactCategory] = useState('不具合の報告');
  const [contactBody, setContactBody] = useState('');
  const [name, setName] = useState(user?.isGuest ? '' : (user?.name || ''));
  const [bio, setBio] = useState(user?.bio || '');
  const [userId, setUserId] = useState(user?.isGuest ? '' : (user?.id || ''));
  const [email, setEmail] = useState(user?.email || '');
  const [password, setPassword] = useState(user?.password || (user?.isGuest ? '' : 'password123'));
  const [currentPasswordInput, setCurrentPasswordInput] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmNewPassword, setConfirmNewPassword] = useState('');
  const [passkeys, setPasskeys] = useState(Array.isArray(user?.passkeys) ? user.passkeys : []);
  const [isRegisteringPasskey, setIsRegisteringPasskey] = useState(false);

  // パスワードを忘れた方ページ用のステート
  const [forgotStep, setForgotStep] = useState(1); // 1: メール送信, 2: コード＆新PW入力
  const [resetEmailInput, setResetEmailInput] = useState(user?.email || '');
  const [resetCodeInput, setResetCodeInput] = useState('');
  const [resetNewPwInput, setResetNewPwInput] = useState('');
  const [resetConfirmPwInput, setResetConfirmPwInput] = useState('');

  const [residence, setResidence] = useState(user?.residence || '未設定');
  const [city, setCity] = useState(user?.city || '');
  const [station, setStation] = useState(user?.station || '');
  const [selectedPreset, setSelectedPreset] = useState(user?.avatar || FEMALE_AVATARS[0]);
  const [customAvatar, setCustomAvatar] = useState(null);
  const [showDeleteAccountConfirm, setShowDeleteAccountConfirm] = useState(false);
  const fileInputRef = useRef(null);

  const isIdTaken = ['admin', 'test', 'user'].includes((userId || '').toLowerCase()) && userId !== user?.id;

  // ゲストからGoogle / Apple でワンタップ引き継ぎ登録するハンドラー
  const handleLinkOAuthFromGuest = (providerName) => {
    const newId = `${providerName.toLowerCase()}_${Math.floor(Math.random() * 9000 + 1000)}`;
    if (onUpgradeUser) {
      onUpgradeUser({
        ...user,
        id: newId,
        name: user?.name && user.name !== 'ゲストユーザー' ? user.name : `${providerName}トラベラー`,
        email: providerName === 'Google' ? 'user@gmail.com' : 'user@privaterelay.appleid.com',
        authProvider: providerName,
        isGuest: false
      });
    }
    customAlert(`${providerName}アカウントと連携し、これまでのしおりを引き継ぎました！`);
    setCurrentView('menu');
  };

  const handleSaveSecurity = () => {
    if (!email.trim()) { customAlert('メールアドレスを入力してください'); return; }

    let updatedPassword = password.trim();
    const isTryingToChangePw = Boolean(currentPasswordInput.trim() || newPassword.trim() || confirmNewPassword.trim());

    if (user?.isGuest && !password) {
      if (!newPassword.trim() || newPassword.trim().length < 8) {
        customAlert('8文字以上のパスワードを設定してください');
        return;
      }
      if (newPassword.trim() !== confirmNewPassword.trim()) {
        customAlert('確認用パスワードが一致しません');
        return;
      }
      updatedPassword = newPassword.trim();
    } else if (isTryingToChangePw) {
      if (!currentPasswordInput.trim()) {
        customAlert('パスワードを変更するには「現在のパスワード」を入力してください');
        return;
      }
      if (password && currentPasswordInput.trim() !== password) {
        customAlert('現在のパスワードが正しくありません。忘れた場合は「パスワードを忘れた方はこちら」から再設定してください。');
        return;
      }
      if (newPassword.trim().length < 8) {
        customAlert('新しいパスワードは8文字以上で入力してください');
        return;
      }
      if (newPassword.trim() !== confirmNewPassword.trim()) {
        customAlert('新しいパスワードと確認用パスワードが一致しません');
        return;
      }
      updatedPassword = newPassword.trim();
    }

    setPassword(updatedPassword);
    setCurrentPasswordInput('');
    setNewPassword('');
    setConfirmNewPassword('');

    if (onUpgradeUser) {
      onUpgradeUser({
        ...user,
        email: email.trim(),
        password: updatedPassword,
        passkeys,
        isGuest: user?.isGuest ? false : user?.isGuest
      });
    }
    customAlert(isTryingToChangePw ? 'メールアドレスと新しいパスワードを保存しました！' : 'セキュリティ設定を保存しました！');
    setCurrentView('menu');
  };

  // パスキー（WebAuthn風）の新規登録ハンドラー
  const handleAddPasskey = async () => {
    if (isRegisteringPasskey) return;
    setIsRegisteringPasskey(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 600));
      const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
      const deviceLabel = /iPhone|iPad|Macintosh/.test(ua)
        ? 'Apple iCloud キーチェーン (Face ID / Touch ID)'
        : /Android/.test(ua)
        ? 'Google パスワードマネージャー (生体認証)'
        : 'このデバイスのパスキー (Windows Hello / Touch ID)';

      const newPk = {
        id: 'pk_' + generateId(),
        name: `${deviceLabel}`,
        createdAt: new Date().toLocaleDateString('ja-JP')
      };
      const nextPasskeys = [...passkeys, newPk];
      setPasskeys(nextPasskeys);
      if (onUpgradeUser) {
        onUpgradeUser({ ...user, passkeys: nextPasskeys });
      }
      customAlert('新しいパスキーを登録しました！次回から生体認証等で素早くログインできます。');
    } finally {
      setIsRegisteringPasskey(false);
    }
  };

  const handleRemovePasskey = (pkId) => {
    const nextPasskeys = passkeys.filter(p => p.id !== pkId);
    setPasskeys(nextPasskeys);
    if (onUpgradeUser) {
      onUpgradeUser({ ...user, passkeys: nextPasskeys });
    }
    customAlert('パスキーを削除しました');
  };

  // パスワード再設定完了ハンドラー
  const handleCompletePasswordReset = () => {
    if (!resetCodeInput.trim()) {
      customAlert('メールに届いた6桁の認証コードを入力してください');
      return;
    }
    if (resetNewPwInput.trim().length < 8) {
      customAlert('新しいパスワードは8文字以上で入力してください');
      return;
    }
    if (resetNewPwInput.trim() !== resetConfirmPwInput.trim()) {
      customAlert('確認用パスワードが一致しません');
      return;
    }
    const updatedPw = resetNewPwInput.trim();
    setPassword(updatedPw);
    setCurrentPasswordInput('');
    setNewPassword('');
    setConfirmNewPassword('');
    setResetCodeInput('');
    setResetNewPwInput('');
    setResetConfirmPwInput('');
    setForgotStep(1);
    if (onUpgradeUser) {
      onUpgradeUser({
        ...user,
        email: resetEmailInput.trim() || email.trim(),
        password: updatedPw,
        passkeys,
        isGuest: false
      });
    }
    customAlert('パスワードの再設定が完了しました！');
    setCurrentView('security');
  };

  // IDからユーザー情報（名前・アイコン・自己紹介）を解決するヘルパー
  const resolveUserById = (uid) => {
    const matchedTrip = (publicTrips || []).find(t => (t.authorId || t.members?.[0]?.id) === uid);
    if (matchedTrip) {
      return {
        id: uid,
        name: matchedTrip.authorName || uid,
        avatar: matchedTrip.authorAvatar || FEMALE_AVATARS[0],
        bio: matchedTrip.authorBio || `${matchedTrip.destination || '日本各地'}を旅しています！`
      };
    }
    const PRESET_PROFILES = {
      m1: { id: 'm1', name: 'アクティブ夫婦', avatar: FEMALE_AVATARS[0], bio: '週末は全国の絶景とアクティビティを求めて夫婦で旅しています！' },
      m2: { id: 'm2', name: 'たびたろう', avatar: MALE_AVATARS[1], bio: '温泉と美味しいお酒が大好き。関東近郊のんびり旅メインです♨️' },
      m3: { id: 'm3', name: 'くいしんぼう', avatar: FEMALE_AVATARS[2], bio: '食べるために旅をする！全国のローカルグルメ・カフェを開拓中🍰' },
      m4: { id: 'm4', name: '北陸さんぽ', avatar: FEMALE_AVATARS[3], bio: '北陸の美味しい海鮮と和菓子を探して旅しています🍣' },
      m5: { id: 'm5', name: 'ちゅら旅', avatar: MALE_AVATARS[2], bio: '離島と青い海が大好き！年に3回は沖縄に行きます🌺' }
    };
    return PRESET_PROFILES[uid] || { id: uid, name: uid, avatar: MALE_AVATARS[0], bio: 'たびたびユーザー' };
  };

  const followingIds = Array.isArray(user?.following) ? user.following : [];
  const followerIds = Array.isArray(user?.followers) ? user.followers : [];
  const myPublicPostCount = (publicTrips || []).filter(t => (t.authorId || t.members?.[0]?.id) === user?.id).length;

  const handleSaveProfile = (e) => {
    if (e) e.preventDefault();
    if (!name.trim()) {
      customAlert('ニックネームを入力してください');
      return;
    }
    const cleanStation = station.trim() ? station.trim().replace(/駅$/, '') + '駅' : '';
    if (onUpgradeUser) {
      onUpgradeUser({
        ...user,
        name: name.trim(),
        bio: bio.trim(),
        residence,
        city: city.trim(),
        station: cleanStation,
        avatar: customAvatar || selectedPreset
      });
    }
    customAlert('プロフィール・最寄り駅を保存しました！');
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/55 z-[250] flex justify-center items-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-[28px] p-5 shadow-2xl max-h-[88dvh] flex flex-col overflow-hidden animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-3 shrink-0">
          <h3 className="font-extrabold text-base text-stone-800 flex items-center gap-1.5">
            <User size={18} className="text-[#7A9D8C]" /> プロフィール・最寄り駅設定
          </h3>
          <button onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        <form onSubmit={handleSaveProfile} className="flex-1 overflow-y-auto no-scrollbar space-y-3 pr-0.5 pb-2">
          <div className="flex items-center gap-3 p-3 bg-stone-50 rounded-2xl border border-stone-200/80">
            <img src={customAvatar || selectedPreset} alt="avatar" className="w-14 h-14 rounded-full object-cover border-2 border-[#7A9D8C] bg-white shrink-0" />
            <div className="flex-1 min-w-0">
              <label className="text-[11px] font-bold text-stone-500 block mb-1">ニックネーム</label>
              <input
                type="text"
                value={name}
                onChange={e => setName(e.target.value)}
                className="w-full p-2 bg-white border border-stone-200 rounded-xl text-xs font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
            </div>
          </div>

          <div className="p-3 bg-stone-50 rounded-2xl border border-stone-200/80 space-y-2">
            <label className="text-xs font-extrabold text-stone-700 flex items-center gap-1">
              <Navigation size={13} className="text-[#7A9D8C]" /> 普段の出発地点（最寄り駅・エリア）
            </label>
            <div className="grid grid-cols-2 gap-1.5">
              <select
                value={residence}
                onChange={e => setResidence(e.target.value)}
                className="w-full p-2 bg-white border border-stone-200 rounded-xl text-xs font-extrabold text-stone-800"
              >
                <option value="未設定">🗾 都道府県（未選択）</option>
                {PREFECTURES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
              <MunicipalitySearchInput
                value={city}
                onChange={setCity}
                prefectureContext={residence}
                onSelectPrefecture={setResidence}
              />
            </div>
            <StationSearchInput
              value={station}
              onChange={setStation}
              cityContext={city}
              prefectureContext={residence}
              onSelectPrefecture={setResidence}
            />
          </div>

          <div className="p-3 bg-stone-50 rounded-2xl border border-stone-200/80 flex items-center justify-between">
            <div>
              <p className="text-xs font-extrabold text-stone-800">しおりを閉じたときの自動ミニ化</p>
              <p className="text-[10px] font-bold text-stone-400">画面端にミニアイコンを表示してすぐ戻れるようにする</p>
            </div>
            <button
              type="button"
              onClick={() => {
                if (onUpgradeUser) {
                  onUpgradeUser({ ...user, autoMinimizeTrip: !(user.autoMinimizeTrip !== false) });
                }
              }}
              className={`w-11 h-6 rounded-full p-0.5 transition-colors flex items-center ${
                user.autoMinimizeTrip !== false ? 'bg-[#7A9D8C] justify-end' : 'bg-stone-300 justify-start'
              }`}
            >
              <div className="w-5 h-5 rounded-full bg-white shadow-xs" />
            </button>
          </div>
        </form>

        <div className="pt-3 border-t border-stone-100 shrink-0 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 py-3 bg-stone-100 text-stone-600 font-bold rounded-2xl text-xs">閉じる</button>
          <button type="button" onClick={handleSaveProfile} className="flex-[2] py-3 bg-[#7A9D8C] text-white font-extrabold rounded-2xl text-xs shadow-sm">変更を保存する</button>
        </div>
      </div>
    </div>
  );
}

function PublicUserProfileModal({ userProfile, publicTrips = [], currentUser, onToggleFollow, onOpenTrip, onClose }) {
  useLockBodyScroll(true);
  const userTrips = (publicTrips || []).filter(
    t => (t.authorId || t.members?.[0]?.id) === userProfile?.id || t.authorName === userProfile?.name
  );
  return (
    <div className="fixed inset-0 bg-black/55 z-[250] flex justify-center items-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-[28px] p-5 shadow-2xl max-h-[85dvh] flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-3">
          <div className="flex items-center gap-2.5">
            <img src={userProfile?.avatar || FEMALE_AVATARS[0]} alt="" className="w-11 h-11 rounded-full object-cover border border-stone-200" />
            <div>
              <h3 className="font-extrabold text-sm text-stone-800">{userProfile?.name}</h3>
              <p className="text-[11px] text-stone-500 font-bold">{userProfile?.bio}</p>
            </div>
          </div>
          <button onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-2.5">
          {userTrips.map(t => (
            <div key={t.id} onClick={() => onOpenTrip(t.id)} className="p-3 rounded-2xl bg-stone-50 hover:bg-stone-100 border border-stone-200/80 cursor-pointer">
              <p className="text-xs font-extrabold text-stone-800">{t.title}</p>
              <p className="text-[10px] font-bold text-stone-500 mt-0.5">🗾 {t.destination}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function DiscoverTab({
  publicTrips,
  currentUser,
  dashboardState,
  setDashboardState,
  onOpenTrip,
  onCopyTrip,
  onToggleLike,
  onToggleFollow,
  onOpenUserProfile,
  onEnlargeImage,
  onRefreshPublicTrips,
  scrollContainerRef,
  hideChrome,
  onFeedScroll,
  isFilterOpen,
  setIsFilterOpen
}) {
  const discoverSort = dashboardState?.discoverSort || 'trending';
  const selectedRegion = dashboardState?.selectedRegion || 'すべて';
  const searchQuery = dashboardState?.searchQuery || '';

  const setDiscoverSort = (sort) => setDashboardState(prev => ({ ...prev, discoverSort: sort }));
  const setSelectedRegion = (region) => setDashboardState(prev => ({ ...prev, selectedRegion: region }));
  const setSearchQuery = (q) => setDashboardState(prev => ({ ...prev, searchQuery: q }));

  const [searchInput, setSearchInput] = useState(searchQuery);
  const [reportingTrip, setReportingTrip] = useState(null);
  const [dismissedBanner, setDismissedBanner] = useState(false);

  const PULL_THRESHOLD = 62;
  const pullStartYRef = useRef(null);
  const [pullDistance, setPullDistance] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const tabsList = useMemo(
    () => [
      { id: 'trending', label: '🔥 人気・おすすめ' },
      { id: 'latest', label: '✨ 新着' },
      { id: 'favorites', label: '❤️ お気に入り' }
    ],
    []
  );

  const handleExecuteSearch = (e) => {
    if (e) e.preventDefault();
    setSearchQuery(searchInput.trim());
    setIsFilterOpen(false);
  };

  const handleTouchStart = (e) => {
    if (scrollContainerRef?.current?.scrollTop <= 2 && !isRefreshing) {
      pullStartYRef.current = e.touches[0].clientY;
    } else {
      pullStartYRef.current = null;
    }
  };

  const handleTouchMove = (e) => {
    if (pullStartYRef.current === null || isRefreshing) return;
    const dy = e.touches[0].clientY - pullStartYRef.current;
    if (dy > 0 && scrollContainerRef?.current?.scrollTop <= 2) {
      setPullDistance(Math.min(90, dy * 0.48));
    } else {
      setPullDistance(0);
    }
  };

  const handleTouchEnd = async () => {
    if (pullStartYRef.current === null) return;
    pullStartYRef.current = null;
    if (pullDistance >= PULL_THRESHOLD && !isRefreshing) {
      setIsRefreshing(true);
      if (onRefreshPublicTrips) await onRefreshPublicTrips();
      setTimeout(() => {
        setIsRefreshing(false);
        setPullDistance(0);
      }, 450);
    } else {
      setPullDistance(0);
    }
  };

  const handleMouseDown = () => {};
  const handleMouseMove = () => {};
  const handleMouseUp = () => {};

  const feedItems = useMemo(() => {
    let list = Array.isArray(publicTrips) ? [...publicTrips] : [];
    if (selectedRegion && selectedRegion !== 'すべて') {
      list = list.filter(t => t.region === selectedRegion || (t.destination || '').includes(selectedRegion));
    }
    if (searchQuery.trim()) {
      const q = searchQuery.trim().toLowerCase();
      list = list.filter(
        t =>
          (t.title || '').toLowerCase().includes(q) ||
          (t.destination || '').toLowerCase().includes(q) ||
          (t.description || '').toLowerCase().includes(q) ||
          (t.events || []).some(ev => (ev.title || '').toLowerCase().includes(q) || (ev.location || '').toLowerCase().includes(q))
      );
    }
    if (discoverSort === 'favorites') {
      list = list.filter(t => Array.isArray(t.likedBy) && t.likedBy.includes(currentUser?.id));
    } else if (discoverSort === 'latest') {
      list.sort((a, b) => (b.publishedAt || 0) - (a.publishedAt || 0));
    } else {
      list.sort((a, b) => (b.likes || 0) - (a.likes || 0));
    }
    return list.map(t => ({ type: 'trip', data: t }));
  }, [publicTrips, selectedRegion, searchQuery, discoverSort, currentUser?.id]);

  return (
    <div className="flex-1 flex flex-col h-full overflow-hidden select-none relative">
      {/* ① X（旧Twitter）風のスリムなフラット・アンダーラインタブバー ＋ エリア選択タブ（高さを変えずに translateY で出し入れし、スクロールの引っかかりを解消） */}
      <div
        className={`absolute top-16 inset-x-0 bg-white/95 backdrop-blur-md border-b border-stone-200/80 z-20 transition-transform duration-300 ease-out will-change-transform ${
          hideChrome && !isFilterOpen
            ? '-translate-y-[160%] pointer-events-none'
            : 'translate-y-0'
        }`}
      >
        <div className="flex items-center px-2 border-b border-stone-100">
          {tabsList.map(tab => {
            const isActive = discoverSort === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setDiscoverSort(tab.id)}
                className={`flex-1 py-2.5 text-xs font-extrabold relative transition-colors text-center ${
                  isActive ? 'text-stone-900' : 'text-stone-400 hover:text-stone-600'
                }`}
              >
                <span>{tab.label}</span>
                {isActive && (
                  <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-12 h-[3px] bg-[#7A9D8C] rounded-full" />
                )}
              </button>
            );
          })}
        </div>

        {/* 常時すぐ切り替えられるエリア選択タブ（横スクロールピル） */}
        <div
          data-no-swipe="true"
          style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
          className="px-3 py-1.5 flex items-center gap-1.5 overflow-x-auto no-scrollbar [&::-webkit-scrollbar]:hidden bg-stone-50/60"
        >
          {['すべて', ...REGIONS].map(r => {
            const isSelected = selectedRegion === r;
            return (
              <button
                key={r}
                type="button"
                onClick={() => setSelectedRegion(r)}
                className={`whitespace-nowrap px-3 py-1 text-[11px] font-bold rounded-full border transition-all active:scale-95 shrink-0 ${
                  isSelected
                    ? 'bg-[#7A9D8C] text-white border-[#7A9D8C] shadow-2xs'
                    : 'bg-white text-stone-600 border-stone-200/90 hover:bg-stone-100'
                }`}
              >
                {r === 'すべて' ? '🗾 全国すべて' : r}
              </button>
            );
          })}
        </div>

        {/* キーワード検索が有効なときのコンパクトなステータスバー */}
        {!isFilterOpen && searchQuery.trim() !== '' && (
          <div className="px-4 py-1.5 bg-stone-50 border-t border-stone-100 flex items-center justify-between gap-2 text-[11px]">
            <div className="flex items-center gap-1.5 min-w-0 overflow-hidden">
              <span className="text-stone-400 font-bold shrink-0">検索ワード:</span>
              <span className="px-2 py-0.5 bg-white border border-stone-200 text-stone-700 rounded-full font-bold truncate">
                「{searchQuery}」
              </span>
            </div>
            <button
              type="button"
              onClick={() => {
                setSearchInput('');
                setSearchQuery('');
              }}
              className="text-stone-400 hover:text-stone-600 font-bold underline shrink-0"
            >
              クリア
            </button>
          </div>
        )}

        {/* 右上の「検索」ボタンを押したときだけ展開するキーワード検索ドロワー */}
        {isFilterOpen && (
          <div className="px-4 py-2.5 bg-stone-50/90 border-t border-stone-100 animate-in fade-in slide-in-from-top-1 duration-150">
            <form onSubmit={handleExecuteSearch} className="flex items-center gap-2">
              <div className="relative flex-1">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
                <input
                  type="text"
                  value={searchInput}
                  onChange={e => setSearchInput(e.target.value)}
                  placeholder="行き先・スポット名・キーワードを入力"
                  className="w-full py-1.5 pl-8 pr-7 bg-white rounded-xl text-xs font-bold border border-stone-200 focus:border-[#7A9D8C] focus:outline-none transition-all"
                />
                {(searchInput || searchQuery) && (
                  <button
                    type="button"
                    onClick={() => {
                      setSearchInput('');
                      setSearchQuery('');
                    }}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-stone-400 hover:text-stone-600"
                    title="クリア"
                  >
                    <XCircle size={14} />
                  </button>
                )}
              </div>
              <button
                type="submit"
                className="shrink-0 px-3.5 py-1.5 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-bold rounded-xl text-xs shadow-2xs transition-all active:scale-95"
              >
                検索
              </button>
            </form>
          </div>
        )}
      </div>

      {/* ② 投稿タイムライン領域（上部に固定の余白を持ち、スクロール中にコンテナ高さが変わらないため滑らかにスクロール） */}
      <div
        ref={scrollContainerRef}
        onScroll={onFeedScroll}
        className="flex-1 overflow-y-auto overscroll-y-contain no-scrollbar pt-[136px] pb-28 bg-[#EDF1EE] relative"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {/* ★ X（旧Twitter）風：少しでも引っ張ったら上からスッと降りてくる丸型フローティング更新マーク */}
        <div
          className="pointer-events-none sticky top-0 left-0 right-0 z-30 flex flex-col items-center justify-center overflow-visible"
          style={{
            height: isRefreshing ? '56px' : `${Math.min(72, pullDistance)}px`,
            transition: pullStartYRef.current !== null && !isRefreshing ? 'none' : 'height 0.22s cubic-bezier(0.2, 0.8, 0.2, 1)'
          }}
        >
          {(pullDistance > 3 || isRefreshing) && (
            <div
              style={{
                transform: `translateY(${isRefreshing ? 6 : Math.min(18, pullDistance * 0.22)}px) scale(${
                  isRefreshing ? 1 : Math.min(1.08, 0.65 + (pullDistance / PULL_THRESHOLD) * 0.4)
                })`,
                opacity: isRefreshing ? 1 : Math.min(1, 0.35 + pullDistance / 22)
              }}
              className="flex flex-col items-center gap-1 transition-transform duration-75"
            >
              <div
                className={`w-10 h-10 rounded-full bg-white shadow-lg border flex items-center justify-center transition-colors ${
                  pullDistance >= PULL_THRESHOLD || isRefreshing
                    ? 'border-[#7A9D8C] text-[#7A9D8C] ring-4 ring-[#7A9D8C]/15'
                    : 'border-stone-200 text-stone-500'
                }`}
              >
                {isRefreshing ? (
                  <div className="w-5 h-5 border-[2.5px] border-[#7A9D8C]/25 border-t-[#7A9D8C] rounded-full animate-spin" />
                ) : (
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.6"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="w-5 h-5 transition-transform duration-150"
                    style={{
                      transform: `rotate(${
                        pullDistance >= PULL_THRESHOLD
                          ? 180
                          : Math.min(165, Math.round((pullDistance / PULL_THRESHOLD) * 165))
                      }deg)`
                    }}
                  >
                    <path d="M12 5v14" />
                    <path d="m19 12-7 7-7-7" />
                  </svg>
                )}
              </div>
              <span
                className={`px-2.5 py-0.5 rounded-full text-[10px] font-extrabold shadow-xs border backdrop-blur-xs transition-all ${
                  pullDistance >= PULL_THRESHOLD || isRefreshing
                    ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                    : 'bg-white/95 text-stone-600 border-stone-200/80'
                }`}
              >
                {isRefreshing
                  ? '最新の旅に更新中...'
                  : pullDistance >= PULL_THRESHOLD
                  ? '離して更新！'
                  : '引っ張って更新'}
              </span>
            </div>
          )}
        </div>

        {/* ★ フェーズ1用：一般ユーザー向けの1行スリム案内バー（「配信管理」ボタンを削除し、誰が見てもクリーンな表示に統一） */}
        {!ENABLE_PUBLIC_SNS_FEATURES && SHOW_SNS_COMING_SOON_BANNER && !dismissedBanner && (
          <div className="bg-[#7A9D8C]/15 border-b border-[#7A9D8C]/25 px-4 py-2 flex items-center justify-between gap-2 text-[11px]">
            <div className="flex items-center gap-1.5 min-w-0 flex-1">
              <span className="shrink-0 text-[9px] font-extrabold bg-[#7A9D8C] text-white px-2 py-0.5 rounded-full">
                公式厳選
              </span>
              <span className="font-bold text-stone-700 truncate">
                実録モデルコース配信中（🚧 SNS投稿機能は近日搭載）
              </span>
            </div>
            <button
              type="button"
              onClick={() => setDismissedBanner(true)}
              className="text-stone-400 hover:text-stone-600 p-0.5 shrink-0"
              title="バナーを閉じる"
            >
              <X size={13} />
            </button>
          </div>
        )}

        <div className="px-3 py-3 space-y-3.5">
          {feedItems.length === 0 ? (
            <div className="py-16 text-center text-stone-400 text-xs font-bold flex flex-col items-center gap-2 bg-white rounded-3xl border border-stone-200/80">
              {discoverSort === 'favorites' ? (
                <>
                  <Heart size={28} className="opacity-40 text-red-400" />
                  <span>お気に入り（いいね）した旅がまだありません</span>
                  <span className="text-[11px] text-stone-400 font-normal">気になる投稿のハートボタンを押すとここに保存されます</span>
                </>
              ) : (
                <>
                  <Compass size={28} className="opacity-40" />
                  <span>{discoverSort === 'following' ? 'フォロー中のユーザーの投稿がまだありません' : '該当する旅行が見つかりませんでした'}</span>
                </>
              )}
            </div>
          ) : (
            feedItems.map((item, idx) => {
              const trip = item.data;
              const hasLiked = Array.isArray(trip.likedBy) && trip.likedBy.includes(currentUser.id);
              const authorId = trip.authorId || trip.members?.[0]?.id || `author_${trip.authorName}`;
              const isMe = authorId === currentUser.id;
              const isFollowing = Array.isArray(currentUser.following) && currentUser.following.includes(authorId);
              const isOfficialMode = !ENABLE_PUBLIC_SNS_FEATURES;
              const eventSum = (trip.events || []).reduce((sum, e) => sum + (Number(e.cost) || 0), 0);
              const displayCost = eventSum > 0 ? eventSum : (trip.budget || 0);

              return (
                <article
                  key={trip.id || idx}
                  onClick={() => onOpenTrip(trip.id, true)}
                  className="bg-white rounded-[26px] border border-stone-200/90 shadow-sm hover:shadow-md transition-all cursor-pointer pt-4 pb-3.5 overflow-hidden"
                >
                  {/* 上部：Xのタイムライン風の投稿者ヘッダー */}
                  <div className="px-4 flex items-center justify-between gap-2 mb-2">
                    {isOfficialMode ? (
                      <div className="flex items-center gap-2.5 min-w-0">
                        <OfficialBrandAvatar size="w-9 h-9" iconSize={16} />
                        <div className="min-w-0">
                          <div className="flex items-center gap-1 flex-wrap">
                            <span className="text-xs font-extrabold text-stone-900 truncate">
                              {OFFICIAL_ACCOUNT_PROFILE.name}
                            </span>
                            <span className="text-[10px] font-mono text-stone-400">
                              {OFFICIAL_ACCOUNT_PROFILE.handle}
                            </span>
                            <span className="text-[10px] text-stone-300">·</span>
                            <span className="text-[10px] text-stone-400 font-bold">
                              {trip.startDate?.replace(/-/g, '/')}取材
                            </span>
                          </div>
                          <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="text-[10px] font-extrabold text-[#557465] bg-[#7A9D8C]/12 px-2 py-0.2 rounded-full">
                              🗾 {trip.destination}
                            </span>
                            <span className="text-[10px] font-bold text-stone-400">
                              全{(trip.events || []).length}スポット収録
                            </span>
                          </div>
                        </div>
                      </div>
                    ) : (
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onOpenUserProfile && onOpenUserProfile({
                            id: authorId,
                            name: trip.authorName,
                            avatar: trip.authorAvatar || FEMALE_AVATARS[0],
                            bio: trip.authorBio || `${trip.destination}などを旅しています！`
                          });
                        }}
                        className="flex items-center gap-2.5 text-left group min-w-0 cursor-pointer"
                      >
                        <img src={trip.authorAvatar || FEMALE_AVATARS[0]} className="w-9 h-9 rounded-full border border-stone-100 bg-stone-50 group-hover:ring-2 group-hover:ring-[#7A9D8C] transition-all shrink-0" alt="author" />
                        <div className="min-w-0">
                          <div className="flex items-center gap-1.5">
                            <p className="text-xs font-extrabold text-stone-900 group-hover:text-[#7A9D8C] transition-colors truncate">{trip.authorName}</p>
                            <span className="text-[10px] text-stone-400">· {new Date(trip.publishedAt).toLocaleDateString()}</span>
                          </div>
                          <p className="text-[10px] text-[#557465] font-bold">{trip.destination}</p>
                        </div>
                      </button>
                    )}

                    {ENABLE_PUBLIC_SNS_FEATURES && (
                      <div className="flex items-center gap-1 shrink-0">
                        {!isMe && (
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              onToggleFollow && onToggleFollow(authorId, trip.authorName);
                            }}
                            style={
                              isFollowing
                                ? { backgroundColor: '#7A9D8C', color: '#ffffff', borderColor: '#7A9D8C' }
                                : { backgroundColor: '#ffffff', color: '#44403c', borderColor: '#d6d3d1' }
                            }
                            className="px-3 py-1 rounded-full text-[10px] font-bold border transition-all cursor-pointer flex items-center gap-1 shadow-2xs active:scale-95"
                          >
                            {isFollowing ? <><Check size={11} strokeWidth={3} /> フォロー中</> : '+ フォロー'}
                          </button>
                        )}
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            setReportingTrip(trip);
                          }}
                          className="text-stone-400 hover:text-stone-600 p-1"
                          title="投稿を報告"
                        >
                          <MoreVertical size={15} />
                        </button>
                      </div>
                    )}
                  </div>

                  {/* 本文エリア：タイトル＆説明文＆主な立ち寄り先プレビュー */}
                  <div className="px-4 mb-2.5">
                    <h3 className="font-extrabold text-[15px] text-stone-900 leading-snug mb-1">
                      {trip.title}
                    </h3>
                    {trip.description && (
                      <p className="text-xs text-stone-600 leading-relaxed line-clamp-2 mb-2">
                        {trip.description}
                      </p>
                    )}

                    {/* Xのタイムライン上でどんな行程かわかるコンパクトなルートチップ */}
                    {Array.isArray(trip.events) && trip.events.length > 0 && (
                      <div className="flex items-center gap-1 overflow-x-auto no-scrollbar py-0.5 text-[10px] font-bold text-stone-500">
                        {trip.events.slice(0, 3).map((ev, eIdx) => (
                          <React.Fragment key={ev.id || eIdx}>
                            <span className="whitespace-nowrap bg-stone-100/90 text-stone-700 px-2 py-0.5 rounded-md truncate max-w-[135px]">
                              {ev.time} {ev.location || ev.title}
                            </span>
                            {eIdx < Math.min(2, trip.events.length - 1) && (
                              <span className="text-stone-300 shrink-0">→</span>
                            )}
                          </React.Fragment>
                        ))}
                        {trip.events.length > 3 && (
                          <span className="whitespace-nowrap text-[10px] text-[#7A9D8C] font-extrabold pl-1 shrink-0">
                            +{trip.events.length - 3}件
                          </span>
                        )}
                      </div>
                    )}
                  </div>

                  {/* カバー写真カルーセル */}
                  {trip.covers && trip.covers.length > 0 && (
                    <CoverPhotoCarousel
                      covers={trip.covers}
                      onEnlargeImage={onEnlargeImage}
                      onOpenTrip={() => onOpenTrip(trip.id, true)}
                    />
                  )}

                    {/* 下部アクションバー（いいね・コメント・予算・コピー） */}
                  <div className="px-4 pt-2.5 mt-1 border-t border-stone-100 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onToggleLike(trip.id);
                        }}
                        className="flex items-center gap-1.5 text-stone-500 hover:text-red-500 transition-colors"
                      >
                        <Heart size={17} className={hasLiked ? 'fill-red-500 text-red-500' : ''} />
                        <span className="text-xs font-bold">{trip.likes}</span>
                      </button>

                      {ENABLE_PUBLIC_SNS_FEATURES && (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onOpenTrip(trip.id, true);
                          }}
                          className="flex items-center gap-1.5 text-stone-500 hover:text-[#7A9D8C] transition-colors"
                        >
                          <MessageCircle size={17} />
                          <span className="text-xs font-bold">{(trip.comments || []).length}</span>
                        </button>
                      )}

                      {displayCost > 0 && (
                        <span className="text-[11px] font-bold text-stone-500 flex items-center gap-0.5">
                          <Banknote size={13} className="text-[#7A9D8C]" />
                          ¥{displayCost.toLocaleString()}
                        </span>
                      )}
                    </div>

                    <div className="flex items-center gap-2">
                      {onCopyTrip && (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            onCopyTrip(trip);
                          }}
                          className="px-3 py-1.5 bg-[#7A9D8C]/15 text-[#557465] hover:bg-[#7A9D8C]/25 text-[11px] font-extrabold rounded-full transition-colors flex items-center gap-1 active:scale-95"
                        >
                          <Copy size={12} /> コピーして使う
                        </button>
                      )}
                    </div>
                  </div>
                </article>
              );
            })
          )}
        </div>
      </div>

      {reportingTrip && (
        <ReportModal
          trip={reportingTrip}
          onClose={() => setReportingTrip(null)}
          onSubmit={(reason) => {
            setReportingTrip(null);
            customAlert(`「${reason}」として報告を受け付けました。ご協力ありがとうございます。`);
          }}
        />
      )}
    </div>
  );
}

// みんなの旅カード用の正方形1.5枚見え（ピーキング）横スワイプカルーセル
function CoverPhotoCarousel({ covers, onEnlargeImage, onOpenTrip }) {
  if (!Array.isArray(covers) || covers.length === 0) return null;

  // 1枚だけのときも正方形（aspect-square）で見やすく表示
  if (covers.length === 1) {
    return (
      <div
        className="px-4 pb-2.5 cursor-pointer"
        onClick={(e) => {
          e.stopPropagation();
          if (onOpenTrip) onOpenTrip();
        }}
      >
        <div
          className="w-[74%] aspect-square rounded-2xl bg-stone-100 cursor-pointer relative group overflow-hidden shadow-xs border border-stone-200/60"
          onClick={(e) => {
            e.stopPropagation();
            onEnlargeImage(covers[0]);
          }}
        >
          <img
            src={covers[0]}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
            alt="cover 1"
          />
          <span className="absolute bottom-2.5 right-2.5 bg-black/55 text-white text-[10px] font-bold px-2 py-0.5 rounded-full backdrop-blur-2xs">
            1/1
          </span>
        </div>
      </div>
    );
  }

  // 2枚以上のときは1枚目が約68%幅の正方形、右側に2枚目が半分（合計約1.5枚分）チラ見えして横にスワイプできるカルーセル
  return (
    <div
      data-carousel-area="true"
      data-no-swipe="true"
      className="pb-2.5 select-none"
      onClick={(e) => e.stopPropagation()}
    >
      <div
        style={{ WebkitOverflowScrolling: 'touch', touchAction: 'pan-x pan-y', scrollbarWidth: 'none', msOverflowStyle: 'none' }}
        className="flex gap-2.5 overflow-x-auto no-scrollbar [&::-webkit-scrollbar]:hidden px-4 snap-x snap-mandatory"
      >
        {covers.map((cover, cIdx) => (
          <div
            key={cIdx}
            onClick={(e) => {
              e.stopPropagation();
              onEnlargeImage(cover);
            }}
            className="w-[66%] shrink-0 aspect-square rounded-2xl overflow-hidden bg-stone-100 border border-stone-200/70 shadow-xs relative snap-start cursor-pointer group"
          >
            <img
              src={cover}
              draggable={false}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300 select-none"
              alt={`cover ${cIdx + 1}`}
            />
            <span className="absolute top-2.5 right-2.5 bg-black/60 text-white text-[10px] font-bold px-2 py-0.5 rounded-full backdrop-blur-2xs pointer-events-none">
              {cIdx + 1}/{covers.length}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

// 投稿の報告モーダル
function ReportModal({ trip, onClose, onSubmit }) {
  useLockBodyScroll(true);
  const REPORT_REASONS = [
    'スパム・宣伝目的の投稿',
    '不適切なコンテンツ・公序良俗に反する内容',
    '虚偽の情報・誤解を招く内容',
    '著作権・プライバシーの侵害',
    'その他'
  ];
  const [selectedReason, setSelectedReason] = useState(REPORT_REASONS[0]);
  const [detail, setDetail] = useState('');

  return (
    <div className="fixed inset-0 bg-black/60 z-[260] flex justify-center items-end sm:items-center p-0 sm:p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full sm:max-w-md rounded-t-[32px] sm:rounded-3xl p-6 shadow-2xl animate-in slide-in-from-bottom-full sm:slide-in-from-bottom-0 pb-safe max-h-[85vh] flex flex-col" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-4 shrink-0">
          <h3 className="font-bold text-base text-stone-800 flex items-center gap-2">
            <Flag size={18} className="text-red-500" /> 投稿を報告する
          </h3>
          <button onClick={onClose} className="p-1.5 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar pb-4">
          <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100 mb-4">
            <p className="text-[10px] font-bold text-stone-400 mb-0.5">対象の投稿</p>
            <p className="text-xs font-bold text-stone-700 truncate">{trip.title}（{trip.authorName}）</p>
          </div>

          <label className="block text-xs font-bold text-stone-500 mb-2 pl-1">報告する理由を選択してください</label>
          <div className="space-y-2 mb-4">
            {REPORT_REASONS.map(reason => (
              <button
                key={reason}
                type="button"
                onClick={() => setSelectedReason(reason)}
                className={`w-full p-3.5 rounded-2xl border text-left text-xs font-bold flex items-center justify-between transition-all ${
                  selectedReason === reason
                    ? 'border-red-400 bg-red-50/70 text-red-700 shadow-2xs'
                    : 'border-stone-200 bg-white text-stone-700 hover:bg-stone-50'
                }`}
              >
                <span>{reason}</span>
                <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${selectedReason === reason ? 'border-red-500' : 'border-stone-300'}`}>
                  {selectedReason === reason && <div className="w-2 h-2 rounded-full bg-red-500" />}
                </div>
              </button>
            ))}
          </div>

          <div>
            <label className="block text-xs font-bold text-stone-500 mb-1.5 pl-1">詳細（任意）</label>
            <textarea
              value={detail}
              onChange={e => setDetail(e.target.value)}
              rows="2"
              placeholder="具体的な状況などがあればご記入ください..."
              className="w-full p-3 bg-stone-50 rounded-xl border border-stone-200 text-xs font-bold focus:outline-none focus:ring-2 focus:ring-red-400 resize-none"
            />
          </div>
        </div>

        <div className="pt-3 border-t border-stone-100 flex gap-2 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 py-3 bg-stone-100 text-stone-600 font-bold rounded-2xl text-xs hover:bg-stone-200 transition-colors"
          >
            キャンセル
          </button>
          <button
            type="button"
            onClick={() => onSubmit(selectedReason, detail)}
            className="flex-1 py-3 bg-red-500 text-white font-bold rounded-2xl text-xs shadow-sm hover:bg-red-600 transition-colors"
          >
            報告を送信する
          </button>
        </div>
      </div>
    </div>
  );
}
function TripDetail({ currentUser, trip, isReadOnly, myTrips, updateTrip, onDeleteTrip, onToggleAutoMinimize, onPublish, onBack, onEnlargeImage, onCopySave, onOpenAuthUpgrade, onAddComment }) {
  const generateDateArray = (start, end) => {
    const arr = [];
    let dt = new Date(start);
    const endDt = new Date(end);
    while (dt <= endDt) {
      arr.push(new Date(dt).toISOString().split('T')[0]);
      dt.setDate(dt.getDate() + 1);
    }
    return arr.length > 0 ? arr : [start || getTodayString()];
  };
  const tripDates = generateDateArray(trip.startDate, trip.endDate);

  // 今日の日付が旅行日程に含まれている場合のみ今日を選択し、それ以外は1日目を選択するヘルパー
  const getInitialTripDate = (datesList) => {
    if (!Array.isArray(datesList) || datesList.length === 0) return trip.startDate || getTodayString();
    const todayStr = getTodayString();
    return datesList.includes(todayStr) ? todayStr : datesList[0];
  };

  const [activeTab, setActiveTab] = useState('shiori'); 
  const [selectedDate, setSelectedDate] = useState(() => getInitialTripDate(tripDates));
  const [shioriSubTab, setShioriSubTab] = useState('date'); // 'date' | 'packing' | 'budget'
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [showPublishModal, setShowPublishModal] = useState(false);
  const [showDeleteConfirmModal, setShowDeleteConfirmModal] = useState(false);
  const [copyTarget, setCopyTarget] = useState(null); 
  const [showAiChatModal, setShowAiChatModal] = useState(false);
  const [hideShioriChrome, setHideShioriChrome] = useState(false);
  const lastShioriScrollTopRef = useRef(0);
  const mainScrollRef = useRef(null);

  useEffect(() => {
    setHideShioriChrome(false);
    lastShioriScrollTopRef.current = 0;
  }, [activeTab, selectedDate, shioriSubTab]);

  // しおり詳細画面でのスクロール検知（高さを変えずに translateY で上下バーを出し入れするためガタつきゼロ）
  const handleShioriScroll = (e) => {
    const el = e.currentTarget;
    const currentTop = Math.max(0, el.scrollTop);
    const diff = currentTop - lastShioriScrollTopRef.current;

    if (currentTop <= 16) {
      if (hideShioriChrome) setHideShioriChrome(false);
    } else if (diff > 12 && currentTop > 52) {
      if (!hideShioriChrome) setHideShioriChrome(true);
    } else if (diff < -10) {
      if (hideShioriChrome) setHideShioriChrome(false);
    }
    lastShioriScrollTopRef.current = currentTop;
  };

  // スワイプで戻るジェスチャー（画面左端28pxからの明確な右スワイプのみ反応させ、縦スクロール中の画面ブレを完全防止）
  const swipeStartRef = useRef(null);
  const [swipeOffset, setSwipeOffset] = useState(0);
  const [copiedDrawerCode, setCopiedDrawerCode] = useState(false);
  const [copiedDrawerInviteMsg, setCopiedDrawerInviteMsg] = useState(false);

  const handleSwipeStart = (clientX, clientY, target) => {
    if (target && target.closest('input, textarea, select, [data-no-swipe]')) return;
    if (clientX > 28) {
      swipeStartRef.current = null;
      return;
    }
    swipeStartRef.current = { x: clientX, y: clientY };
  };

  const handleSwipeMove = (clientX, clientY) => {
    if (!swipeStartRef.current) return;
    const dx = clientX - swipeStartRef.current.x;
    const dy = Math.abs(clientY - swipeStartRef.current.y);
    if (dy > 24 && dy > dx) {
      swipeStartRef.current = null;
      setSwipeOffset(0);
      return;
    }
    if (dx > 12 && dy < 30) {
      setSwipeOffset(Math.min(110, dx * 0.6));
    }
  };

  const handleSwipeEnd = (clientX, clientY) => {
    if (!swipeStartRef.current) return;
    const dx = clientX - swipeStartRef.current.x;
    const dy = Math.abs(clientY - swipeStartRef.current.y);
    const shouldGoBack = dx > 65 && dy < 45;
    swipeStartRef.current = null;
    setSwipeOffset(0);
    if (shouldGoBack) {
      onBack();
    }
  };

  // 旅の基本情報（タイトル・行き先・日付）編集用ステート
  const [editTitle, setEditTitle] = useState(trip.title || '');
  const [editDestination, setEditDestination] = useState(trip.destination || '');
  const [editStartDate, setEditStartDate] = useState(trip.startDate || getTodayString());
  const [editEndDate, setEditEndDate] = useState(trip.endDate || trip.startDate || getTodayString());

  useEffect(() => {
    setEditTitle(trip.title || '');
    setEditDestination(trip.destination || '');
    setEditStartDate(trip.startDate || getTodayString());
    setEditEndDate(trip.endDate || trip.startDate || getTodayString());
  }, [trip.id, trip.title, trip.destination, trip.startDate, trip.endDate]);

  const handleSaveTripInfo = () => {
    if (!editTitle.trim()) {
      customAlert('旅のタイトルを入力してください');
      return;
    }
    const validEnd = editEndDate >= editStartDate ? editEndDate : editStartDate;

    // 出発日が変更された場合、既存の予定の日付も新しい日程に合わせてスライド調整する
    const oldStart = new Date(trip.startDate);
    const newStart = new Date(editStartDate);
    const newEnd = new Date(validEnd);
    const dayShift = Math.round((newStart - oldStart) / (1000 * 60 * 60 * 24));

    const updatedEvents = (trip.events || []).map(ev => {
      if (!ev.date) return { ...ev, date: editStartDate };
      const evDt = new Date(ev.date);
      evDt.setDate(evDt.getDate() + dayShift);
      if (evDt < newStart) return { ...ev, date: editStartDate };
      if (evDt > newEnd) return { ...ev, date: validEnd };
      return { ...ev, date: evDt.toISOString().split('T')[0] };
    });

    updateTrip({
      ...trip,
      title: editTitle.trim(),
      destination: editDestination.trim() || '未設定',
      startDate: editStartDate,
      endDate: validEnd,
      events: updatedEvents
    });
    setSelectedDate(editStartDate);
    setEditEndDate(validEnd);
    customAlert('旅の基本情報（名前・行き先・日程）を更新しました！');
  };

  // しおりを開いた際、今日の日付が旅行日程にある場合のみ今日を選択し、日付タブも見える位置へスクロールする
  const dateTabsContainerRef = useRef(null);
  useEffect(() => {
    const targetDate = getInitialTripDate(generateDateArray(trip.startDate, trip.endDate));
    setSelectedDate(targetDate);
    setActiveTab('shiori');
    setShioriSubTab('date');
    setIsSettingsOpen(false);

    setTimeout(() => {
      const activeTabEl = dateTabsContainerRef.current?.querySelector(`[data-date-tab="${targetDate}"]`);
      if (activeTabEl) {
        activeTabEl.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
      }
    }, 120);
  }, [trip.id]);

  // 持ち物カウント（各自の持ち物はログイン中のユーザー自身の分＋みんなの共用分のみを集計）
  const rawPackingItems = Array.isArray(trip.packingList) ? trip.packingList : [];
  const myVisiblePackingItems = rawPackingItems.filter(item =>
    item.category === 'shared' || !item.ownerId || item.ownerId === currentUser?.id
  );
  const isPackingItemCheckedByMe = (item) => {
    if (item.category === 'shared') return Boolean(item.checked);
    if (item.checkedBy && typeof item.checkedBy === 'object') {
      return Boolean(item.checkedBy[currentUser?.id]);
    }
    return Boolean(item.checked);
  };
  const checkedPackingCount = myVisiblePackingItems.filter(isPackingItemCheckedByMe).length;

  return (
    <div
      className="flex-1 flex flex-col h-full overflow-hidden bg-[#F4F7F5] animate-in slide-in-from-right-8 duration-300 relative"
      style={swipeOffset > 0 ? { transform: `translateX(${swipeOffset}px)`, transition: 'none' } : undefined}
      onTouchStart={(e) => handleSwipeStart(e.touches[0].clientX, e.touches[0].clientY, e.target)}
      onTouchMove={(e) => handleSwipeMove(e.touches[0].clientX, e.touches[0].clientY)}
      onTouchEnd={(e) => handleSwipeEnd(e.changedTouches[0].clientX, e.changedTouches[0].clientY)}
    >
      {/* ① 上部エリア（absolute配置＋translateYで滑らかに上下スライドするため、スクロール領域の高さが変わらずガタつきゼロ） */}
      <div
        className={`absolute top-0 inset-x-0 bg-white/95 backdrop-blur-md px-5 pt-4 pb-2.5 shadow-sm z-30 border-b border-stone-100 transition-transform duration-300 ease-out will-change-transform ${
          hideShioriChrome ? '-translate-y-full pointer-events-none' : 'translate-y-0'
        }`}
      >
        <div className="flex justify-between items-center mb-2.5">
          <button onClick={onBack} className="p-1.5 -ml-1.5 text-stone-400 hover:bg-stone-100 rounded-full transition-colors"><ChevronLeft size={24} /></button>
          <h2 className="font-bold text-base text-stone-800 truncate flex-1 text-center px-2">{trip.title}</h2>
          <div className="flex items-center gap-1">
            {/* タイトルを邪魔しない可愛い薄い水色のミニAI相談ボタン */}
            <button
              type="button"
              onClick={() => setShowAiChatModal(true)}
              className="px-2.5 py-1 bg-sky-100/90 hover:bg-sky-200/80 text-sky-800 border border-sky-300/70 rounded-full text-xs font-extrabold flex items-center gap-1 active:scale-95 transition-all"
              title="AIコンシェルジュに文章で相談する"
            >
              <Sparkles size={12} className="text-sky-500" /> AI相談
            </button>
            {isReadOnly ? (
              <button
                onClick={() => setCopyTarget({ type: 'trip', data: trip })}
                className="px-3 py-1.5 bg-[#7A9D8C] text-white hover:bg-[#688a79] rounded-full text-xs font-bold flex items-center gap-1 transition-colors shadow-2xs active:scale-95"
                title="このしおりをコピーして使う"
              >
                <Copy size={13} /> コピー
              </button>
            ) : (
              <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-stone-400 hover:bg-stone-100 rounded-full transition-colors"><MoreVertical size={20} /></button>
            )}
          </div>
        </div>
        
        {activeTab === 'shiori' && (
          <div className="flex items-end justify-between gap-2 pb-0.5">
            {/* 左側：日程（日付）タブ（日数が多い場合はここだけ横スクロール） */}
            <div
              ref={dateTabsContainerRef}
              data-no-swipe="true"
              style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
              className="flex items-end gap-1.5 overflow-x-auto no-scrollbar [&::-webkit-scrollbar]:hidden"
            >
              {tripDates.map((date, idx) => {
                const isSelected = shioriSubTab === 'date' && date === selectedDate;
                const dateObj = new Date(date);
                const isToday = date === getTodayString();
                return (
                  <button
                    key={date}
                    data-date-tab={date}
                    onClick={() => {
                      setShioriSubTab('date');
                      setSelectedDate(date);
                    }}
                    className={`py-1.5 px-2.5 whitespace-nowrap border-b-2 flex flex-col items-center min-w-[54px] rounded-t-xl transition-all ${
                      isSelected ? 'border-[#7A9D8C] bg-[#7A9D8C]/10' : 'border-transparent text-stone-400 hover:bg-stone-50'
                    }`}
                  >
                    <div className="flex items-center gap-1 mb-0.5">
                      <span className={`text-[10px] font-extrabold leading-none ${isSelected ? 'text-[#557465]' : 'text-stone-400'}`}>
                        {idx + 1}日目
                      </span>
                      {isToday && (
                        <span className={`text-[9px] px-1 py-0.2 rounded-full font-bold leading-none ${isSelected ? 'bg-[#7A9D8C] text-white' : 'bg-red-50 text-red-500'}`}>
                          今日
                        </span>
                      )}
                    </div>
                    <span className={`text-xs font-bold leading-tight ${isSelected ? 'text-[#7A9D8C]' : 'text-stone-600'}`}>{`${dateObj.getMonth() + 1}/${dateObj.getDate()}`}</span>
                  </button>
                );
              })}
            </div>

            {/* 右側：右端に固定配置される「持ち物」「予算」タブ（スマホで日付タブを圧迫しないようコンパクト化） */}
            <div className="flex items-end gap-0.5 shrink-0 ml-auto pl-1.5 border-l border-stone-200/80">
              {!isReadOnly && (
                <button
                  type="button"
                  onClick={() => setShioriSubTab('packing')}
                  className={`py-1.5 px-2 sm:px-3 whitespace-nowrap border-b-2 flex items-center gap-1 rounded-t-xl transition-all ${
                    shioriSubTab === 'packing'
                      ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 text-[#557465]'
                      : 'border-transparent text-stone-500 hover:bg-stone-50'
                  }`}
                >
                  <CheckCircle2 size={12} className={shioriSubTab === 'packing' ? 'text-[#7A9D8C]' : 'text-stone-400'} />
                  <span className="text-[11px] sm:text-xs font-extrabold">持ち物</span>
                  {myVisiblePackingItems.length > 0 && (
                    <span className={`text-[9px] px-1 py-0.2 rounded-full font-extrabold ${
                      shioriSubTab === 'packing' ? 'bg-[#7A9D8C] text-white' : 'bg-stone-100 text-stone-500'
                    }`}>
                      {checkedPackingCount}/{myVisiblePackingItems.length}
                    </span>
                  )}
                </button>
              )}

              <button
                type="button"
                onClick={() => setShioriSubTab('budget')}
                className={`py-1.5 px-2 sm:px-3 whitespace-nowrap border-b-2 flex items-center gap-1 rounded-t-xl transition-all ${
                  shioriSubTab === 'budget'
                    ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 text-[#557465]'
                    : 'border-transparent text-stone-500 hover:bg-stone-50'
                }`}
              >
                <Banknote size={13} className={shioriSubTab === 'budget' ? 'text-[#7A9D8C]' : 'text-stone-400'} />
                <span className="text-[11px] sm:text-xs font-extrabold">予算</span>
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ② 中央スクロールエリア（高さを固定維持したまま滑らかな慣性スクロールを実現） */}
      <main
        ref={mainScrollRef}
        onScroll={handleShioriScroll}
        style={{ WebkitOverflowScrolling: 'touch', touchAction: 'pan-y', overscrollBehavior: 'contain' }}
        className={`flex-1 overflow-y-auto overflow-x-hidden overscroll-y-contain z-10 relative no-scrollbar ${
          activeTab === 'shiori' ? 'pt-[108px]' : 'pt-[60px]'
        }`}
      >
        {activeTab === 'shiori' ? (
          shioriSubTab === 'packing' && !isReadOnly ? (
            <PackingListView trip={trip} updateTrip={updateTrip} currentUser={currentUser} isReadOnly={isReadOnly} />
          ) : shioriSubTab === 'budget' ? (
            <BudgetView trip={trip} updateTrip={updateTrip} currentUser={currentUser} isReadOnly={isReadOnly} />
          ) : (
            <Timeline trip={trip} updateTrip={updateTrip} selectedDate={selectedDate} currentUser={currentUser} isReadOnly={isReadOnly} mainScrollRef={mainScrollRef} onCopyEvent={(e) => setCopyTarget({ type: 'event', data: e })} onCopyDay={(dayEvents) => setCopyTarget({ type: 'day', data: dayEvents })} onEnlargeImage={onEnlargeImage} onOpenAiChat={() => setShowAiChatModal(true)} />
          )
        ) : activeTab === 'comments' ? (
          <CommentView trip={trip} currentUser={currentUser} onAddComment={onAddComment} />
        ) : (
          <AlbumView trip={trip} currentUser={currentUser} updateTrip={updateTrip} isReadOnly={isReadOnly} onEnlargeImage={onEnlargeImage} />
        )}
      </main>

      {/* ③ 下部バー（下スクロール時に下へスッと隠れ、上スクロールで即復帰） */}
      {!(isReadOnly && !ENABLE_PUBLIC_SNS_FEATURES) && (
        <nav
          className={`absolute bottom-0 inset-x-0 bg-white/95 backdrop-blur-md border-t border-stone-200/60 flex justify-around pb-safe z-30 transition-transform duration-300 ease-out will-change-transform ${
            hideShioriChrome ? 'translate-y-full pointer-events-none' : 'translate-y-0'
          }`}
        >
          <button onClick={() => setActiveTab('shiori')} className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${activeTab === 'shiori' ? 'text-[#7A9D8C]' : 'text-stone-400'}`}><div className={`p-1 rounded-xl ${activeTab === 'shiori' ? 'bg-[#7A9D8C]/10' : ''}`}><MapIcon size={20} strokeWidth={activeTab === 'shiori' ? 2.5 : 2} /></div><span className="text-xs font-bold">しおり</span></button>
          {!isReadOnly && <button onClick={() => setActiveTab('album')} className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${activeTab === 'album' ? 'text-[#7A9D8C]' : 'text-stone-400'}`}><div className={`p-1 rounded-xl ${activeTab === 'album' ? 'bg-[#7A9D8C]/10' : ''}`}><ImageIcon size={20} strokeWidth={activeTab === 'album' ? 2.5 : 2} /></div><span className="text-xs font-bold">思い出写真</span></button>}
          {isReadOnly && ENABLE_PUBLIC_SNS_FEATURES && <button onClick={() => setActiveTab('comments')} className={`flex-1 py-2.5 flex flex-col justify-center items-center gap-1 transition-colors ${activeTab === 'comments' ? 'text-[#7A9D8C]' : 'text-stone-400'}`}><div className={`p-1 rounded-xl ${activeTab === 'comments' ? 'bg-[#7A9D8C]/10' : ''}`}><MessageSquare size={20} strokeWidth={activeTab === 'comments' ? 2.5 : 2} /></div><span className="text-xs font-bold">コメント ({(trip.comments || []).length})</span></button>}
        </nav>
      )}

      {showAiChatModal && (
        <AiConciergeChatModal
          trip={trip}
          selectedDate={selectedDate}
          tripDates={tripDates}
          isReadOnly={isReadOnly}
          currentUser={currentUser}
          onClose={() => setShowAiChatModal(false)}
          onAddSuggestedEvent={(evData) => {
            const targetDate = evData.date || selectedDate;
            if (isReadOnly) {
              setShowAiChatModal(false);
              setCopyTarget({
                type: 'event',
                data: {
                  id: generateId(),
                  date: targetDate,
                  time: evData.time || '14:00',
                  endTime: evData.endTime || '',
                  title: evData.title,
                  type: evData.type || 'sightseeing',
                  departureOrigin: evData.departureOrigin || '',
                  transportMethod: evData.transportMethod || '',
                  location: evData.location || trip.destination,
                  mapPinQuery: evData.mapPinQuery || evData.location || trip.destination,
                  cost: Number(evData.cost) || 0,
                  memo: evData.memo || '',
                  status: 'approved',
                  authorId: currentUser.id,
                  photos: []
                }
              });
            } else {
              const newEv = {
                id: generateId(),
                date: targetDate,
                time: evData.time || '14:00',
                endTime: evData.endTime || '',
                title: evData.title,
                type: evData.type || 'sightseeing',
                departureOrigin: evData.departureOrigin || '',
                transportMethod: evData.transportMethod || '',
                location: evData.location || trip.destination,
                mapPinQuery: evData.mapPinQuery || evData.location || trip.destination,
                cost: Number(evData.cost) || 0,
                memo: evData.memo || '',
                status: trip.isSoloTrip ? 'approved' : 'proposed',
                authorId: currentUser.id,
                photos: []
              };
              updateTrip({ ...trip, events: [...(trip.events || []), newEv] });
              customAlert(`「${newEv.title}」をしおりに追加しました！`);
            }
          }}
          onApplySuggestedSchedule={(eventsList, mode = 'append', targetDateOverride = null) => {
            if (!Array.isArray(eventsList) || eventsList.length === 0) return;
            const resolvedDate = targetDateOverride || selectedDate;
            const formattedNewEvents = eventsList.map((ev) => ({
              id: generateId(),
              date: ev.date || resolvedDate,
              time: ev.time || '10:00',
              endTime: ev.endTime || '',
              title: ev.title || 'おすすめスポット',
              type: ['transport', 'meal', 'sightseeing', 'active', 'hotel'].includes(ev.type)
                ? ev.type
                : 'sightseeing',
              departureOrigin: ev.departureOrigin || '',
              transportMethod: ev.transportMethod || '',
              location: ev.location || trip.destination,
              mapPinQuery: ev.mapPinQuery || ev.location || trip.destination,
              cost: Number(ev.cost) || 0,
              memo: ev.memo || '',
              status: trip.isSoloTrip ? 'approved' : 'proposed',
              authorId: currentUser.id,
              photos: []
            }));

            if (isReadOnly) {
              setShowAiChatModal(false);
              setCopyTarget({
                type: 'day',
                data: formattedNewEvents
              });
              return;
            }

            if (mode === 'replace_day') {
              const otherDaysEvents = (trip.events || []).filter((e) => e.date !== resolvedDate);
              updateTrip({
                ...trip,
                events: [...otherDaysEvents, ...formattedNewEvents]
              });
              customAlert(`🗓️ この日の予定（全${formattedNewEvents.length}件）をまるごと反映しました！`);
            } else {
              updateTrip({
                ...trip,
                events: [...(trip.events || []), ...formattedNewEvents]
              });
              customAlert(`✨ 提案された${formattedNewEvents.length}件の予定をしおりに追加しました！`);
            }
          }}
        />
      )}

      {isSettingsOpen && !isReadOnly && (
        <div className="fixed inset-0 bg-black/45 z-[150] flex justify-end animate-in fade-in" onClick={() => setIsSettingsOpen(false)}>
          <div className="w-4/5 max-w-sm bg-white h-full shadow-2xl p-6 overflow-y-auto animate-in slide-in-from-right-full pb-safe" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-5"><h3 className="font-bold text-base flex items-center gap-2 text-stone-800"><Info size={18} className="text-[#7A9D8C]" /> 旅の管理・設定</h3><button onClick={() => setIsSettingsOpen(false)} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button></div>

            {/* 旅の基本情報（タイトル・行き先・日程）編集セクション */}
            <div className="mb-6 p-4 bg-stone-50 border border-stone-200/80 rounded-2xl space-y-3">
              <h4 className="font-bold text-xs text-stone-700 flex items-center gap-1.5">
                <Edit2 size={14} className="text-[#7A9D8C]" /> 旅の基本情報を変更
              </h4>
              <div>
                <label className="text-[10px] font-bold text-stone-400 block mb-1">旅行の名前（タイトル）</label>
                <input
                  type="text"
                  value={editTitle}
                  onChange={e => setEditTitle(e.target.value)}
                  placeholder="例: 秋の京都・グルメ旅"
                  className="w-full p-2.5 bg-white border border-stone-200 rounded-xl text-xs font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                />
              </div>
              <div>
                <label className="text-[10px] font-bold text-stone-400 block mb-1">行き先（都道府県・エリア）</label>
                <input
                  type="text"
                  value={editDestination}
                  onChange={e => setEditDestination(e.target.value)}
                  placeholder="例: 神奈川県・箱根"
                  className="w-full p-2.5 bg-white border border-stone-200 rounded-xl text-xs font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                />
              </div>
              <WheelDateRangePicker
                startDate={editStartDate}
                endDate={editEndDate}
                onChangeStart={(nextStart) => {
                  setEditStartDate(nextStart);
                  if (editEndDate < nextStart) setEditEndDate(nextStart);
                }}
                onChangeEnd={(nextEnd) => setEditEndDate(nextEnd)}
                compact
              />
              <button
                type="button"
                onClick={handleSaveTripInfo}
                className="w-full py-2.5 bg-[#7A9D8C] text-white font-bold rounded-xl shadow-2xs hover:bg-[#688a79] transition-colors text-xs flex items-center justify-center gap-1.5 active:scale-95"
              >
                <Check size={14} /> 基本情報の変更を保存
              </button>
            </div>

            {ENABLE_PUBLIC_SNS_FEATURES ? (
              <div className={`mb-6 p-4 border rounded-2xl ${currentUser.isGuest ? 'bg-stone-100 border-stone-200' : 'bg-[#7A9D8C]/10 border-[#7A9D8C]/20'}`}>
                <h4 className={`font-bold text-xs mb-1.5 flex items-center gap-1.5 ${currentUser.isGuest ? 'text-stone-500' : 'text-[#7A9D8C]'}`}><Globe size={15} /> みんなの旅に公開する</h4>
                <p className="text-[10px] text-stone-500 mb-2.5 leading-relaxed">※各予定に貼った写真のうち「公開OK」にした写真や、メモの公開有無を確認画面で選んで投稿できます。</p>
                <button onClick={() => { if (currentUser.isGuest) { customAlert('アカウント登録後にご利用いただけます。'); return; } setIsSettingsOpen(false); setShowPublishModal(true); }} className={`w-full py-2.5 font-bold rounded-xl shadow-sm transition-colors text-xs flex justify-center items-center gap-1.5 ${currentUser.isGuest ? 'bg-stone-300 text-stone-500 cursor-not-allowed' : 'bg-[#7A9D8C] text-white hover:bg-[#688a79]'}`}>{currentUser.isGuest ? 'ゲストは公開できません' : <><Share2 size={14} /> 公開設定・確認へ進む</>}</button>
              </div>
            ) : (
              SHOW_SNS_COMING_SOON_BANNER && (
                <div className="mb-6 p-4 border border-stone-200 bg-stone-50 rounded-2xl">
                  <h4 className="font-bold text-xs mb-1 flex items-center gap-1.5 text-stone-600">
                    <Globe size={15} className="text-[#7A9D8C]" /> みんなの旅への投稿機能（近日公開）
                  </h4>
                  <p className="text-[10px] text-stone-500 leading-relaxed">
                    作成したしおりを「みんなの旅」に一般公開してシェアできるSNS機能は、今後のアップデートで搭載予定です！現在は招待コードを使って同行メンバーと共有できます。
                  </p>
                </div>
              )
            )}
            <div className="mb-6">
              <div className="flex justify-between items-center mb-2">
                <label className="text-[11px] text-stone-400 font-bold">参加メンバー ({(trip.members || []).length}人)</label>
              </div>
              <div className="flex flex-wrap gap-2 mb-3">{(trip.members || []).map((m, i) => (<div key={m.id || i} className="flex items-center gap-1.5 bg-stone-50 border border-stone-200 py-1 px-2.5 rounded-full"><UserAvatar user={m} size="w-5 h-5" /><span className="text-xs font-bold text-stone-700">{m.name}</span></div>))}</div>
              <div className="bg-stone-50 p-3 rounded-2xl border border-stone-200/80 space-y-2">
                <div className="flex items-center justify-between gap-2 bg-white py-1.5 px-3 rounded-xl border border-stone-200/80">
                  <span className="text-xs font-mono font-extrabold tracking-wider text-stone-700 select-all">{trip.id}</span>
                  <button
                    type="button"
                    onClick={() => {
                      copyToClipboard(trip.id, `招待コード「${trip.id}」をコピーしました！`);
                      setCopiedDrawerCode(true);
                      setTimeout(() => setCopiedDrawerCode(false), 3500);
                    }}
                    className={`px-2.5 py-1 rounded-lg text-[10px] font-extrabold flex items-center gap-1 transition-colors ${
                      copiedDrawerCode
                        ? 'bg-[#7A9D8C] text-white'
                        : 'bg-[#7A9D8C]/15 hover:bg-[#7A9D8C]/25 text-[#557465]'
                    }`}
                  >
                    {copiedDrawerCode ? <Check size={12} /> : <Copy size={12} />}
                    <span>{copiedDrawerCode ? '✓ コピー済み' : 'コードのみコピー'}</span>
                  </button>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    copyToClipboard(`「${trip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${trip.id}\n\n▼ アプリをまだ持っていない方はこちら（インストールURL）\nhttps://tabitabi.app/dl`, 'アプリ紹介URL付きの招待文をコピーしました！');
                    setCopiedDrawerInviteMsg(true);
                    setTimeout(() => setCopiedDrawerInviteMsg(false), 3500);
                  }}
                  className={`w-full py-2 px-3 border rounded-xl text-[11px] font-extrabold flex items-center justify-center gap-1.5 transition-colors shadow-2xs ${
                    copiedDrawerInviteMsg
                      ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                      : 'bg-white hover:bg-stone-100 text-[#557465] border-[#7A9D8C]/30'
                  }`}
                >
                  {copiedDrawerInviteMsg ? <Check size={13} /> : <Copy size={13} />}
                  <span>{copiedDrawerInviteMsg ? '✓ 招待文をコピー済み！' : 'アプリ紹介リンク付きで招待文をコピー'}</span>
                </button>
                <div className="grid grid-cols-2 gap-1.5 pt-0.5">
                  <button
                    type="button"
                    onClick={() => {
                      const shareText = `「${trip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${trip.id}\n\n▼ アプリはこちら\nhttps://tabitabi.app/dl`;
                      window.open(`https://line.me/R/msg/text/?${encodeURIComponent(shareText)}`, '_blank', 'noopener,noreferrer');
                    }}
                    className="py-2 px-2.5 bg-[#06C755] hover:brightness-95 text-white rounded-xl text-[11px] font-extrabold flex items-center justify-center gap-1 shadow-2xs active:scale-95 transition-all"
                  >
                    <MessageCircle size={13} /> LINEで送る
                  </button>
                  <button
                    type="button"
                    onClick={async () => {
                      const shareText = `「${trip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${trip.id}\n\n▼ アプリはこちら\nhttps://tabitabi.app/dl`;
                      if (navigator.share) {
                        try {
                          await navigator.share({ title: `${trip.title}のしおり招待`, text: shareText });
                          return;
                        } catch (e) {}
                      }
                      window.open(`https://line.me/R/msg/text/?${encodeURIComponent(shareText)}`, '_blank', 'noopener,noreferrer');
                    }}
                    className="py-2 px-2.5 bg-stone-800 hover:bg-stone-900 text-white rounded-xl text-[11px] font-extrabold flex items-center justify-center gap-1 shadow-2xs active:scale-95 transition-all"
                  >
                    <Share2 size={13} /> 他のアプリで共有
                  </button>
                </div>
              </div>
            </div>
            {(trip.members || []).length === 1 && !trip.isSoloTrip && (<div className="mb-4"><button onClick={() => updateTrip({ ...trip, isSoloTrip: true })} className="w-full py-3 bg-stone-100 text-stone-600 font-bold rounded-xl text-xs flex justify-center items-center gap-2 hover:bg-stone-200 transition-colors">👤 ひとり旅行として確定する（承認省略）</button></div>)}
            {trip.isSoloTrip && (<div className="p-3 bg-stone-100 rounded-xl text-center border border-stone-200 mb-6"><p className="text-xs font-bold text-stone-600">👤 ひとり旅行モード中</p></div>)}

            <div className="pt-5 mt-5 border-t border-stone-200/80">
              <button
                type="button"
                onClick={() => {
                  setIsSettingsOpen(false);
                  setShowDeleteConfirmModal(true);
                }}
                className="w-full py-3 px-4 bg-red-50 hover:bg-red-100 text-red-600 border border-red-200/80 font-bold rounded-2xl text-xs flex items-center justify-center gap-1.5 transition-colors active:scale-95"
              >
                <Trash2 size={15} /> このしおりを削除する
              </button>
            </div>
          </div>
        </div>
      )}

      {showDeleteConfirmModal && (
        <div className="fixed inset-0 bg-black/60 z-[260] flex justify-center items-center p-4 animate-in fade-in" onClick={() => setShowDeleteConfirmModal(false)}>
          <div className="bg-white w-full max-w-sm rounded-[32px] p-6 shadow-2xl animate-in zoom-in-95 text-center" onClick={e => e.stopPropagation()}>
            <div className="w-12 h-12 rounded-full bg-red-50 text-red-500 flex items-center justify-center mx-auto mb-3 border border-red-100">
              <Trash2 size={22} />
            </div>
            <h3 className="font-bold text-base text-stone-800 mb-2">しおりを削除しますか？</h3>
            <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100 mb-3">
              <p className="text-xs font-bold text-stone-800 truncate">{trip.title}</p>
              <p className="text-[10px] text-stone-400 font-bold mt-0.5">
                {trip.destination || '未設定'} / {(trip.events || []).length}件の予定
              </p>
            </div>
            <p className="text-xs text-stone-500 leading-relaxed mb-6">
              削除したしおりや予定・思い出アルバムのデータは元に戻せません。本当によろしいですか？
            </p>
            <div className="flex gap-2.5">
              <button
                type="button"
                onClick={() => setShowDeleteConfirmModal(false)}
                className="flex-1 py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs transition-colors"
              >
                キャンセル
              </button>
              <button
                type="button"
                onClick={() => {
                  setShowDeleteConfirmModal(false);
                  if (onDeleteTrip) onDeleteTrip(trip.id);
                }}
                className="flex-1 py-3 bg-red-500 hover:bg-red-600 text-white font-bold rounded-2xl text-xs shadow-sm transition-colors flex items-center justify-center gap-1"
              >
                <Trash2 size={14} /> 削除する
              </button>
            </div>
          </div>
        </div>
      )}

      {showPublishModal && <PublishModal trip={trip} currentUser={currentUser} onClose={() => setShowPublishModal(false)} onPublish={(p) => { onPublish(p); setShowPublishModal(false); customAlert('「みんなの旅」に公開しました！'); }} />}
      {copyTarget && (
        <CopyModal
          type={copyTarget.type}
          sourceData={copyTarget.data}
          currentUser={currentUser}
          myTrips={myTrips}
          onClose={() => setCopyTarget(null)}
          onOpenRegister={() => {
            setCopyTarget(null);
            if (onOpenAuthUpgrade) onOpenAuthUpgrade();
          }}
          onComplete={(newTrip, updatedTrip) => {
            onCopySave(newTrip, updatedTrip);
            setCopyTarget(null);
          }}
        />
      )}
    </div>
  );
}

// ------------------------------------------
// 思い出アルバム画面 (AlbumView)
// ------------------------------------------
function AlbumView({ trip, currentUser, updateTrip, isReadOnly, onEnlargeImage }) {
  const fileInputRef = useRef(null);
  const allPhotos = useMemo(() => {
    const list = [];
    const seen = new Set();
    (trip.events || []).forEach(ev => {
      (ev.photos || []).forEach(p => {
        if (p?.url && !seen.has(p.id || p.url)) {
          seen.add(p.id || p.url);
          list.push({ ...p, eventTitle: ev.title, eventDate: ev.date });
        }
      });
    });
    (trip.photos || []).forEach(p => {
      if (p?.url && !seen.has(p.id || p.url)) {
        seen.add(p.id || p.url);
        list.push(p);
      }
    });
    return list;
  }, [trip.events, trip.photos]);

  const handleUploadAlbumPhotos = async (e) => {
    if (!e.target.files || isReadOnly) return;
    const files = Array.from(e.target.files);
    const compressedList = await Promise.all(files.map(f => compressImageFile(f, 1200, 0.82)));
    const newPhotos = compressedList.filter(Boolean).map(url => ({
      id: generateId(),
      url,
      createdAt: getTodayString(),
      authorId: currentUser.id,
      authorName: currentUser.name,
      isPublic: true
    }));
    if (newPhotos.length > 0) {
      updateTrip({ ...trip, photos: [...newPhotos, ...(trip.photos || [])] });
      customAlert('思い出アルバムに写真を追加しました！');
    }
    e.target.value = '';
  };

  return (
    <div className="p-5 pb-28 space-y-4 animate-in fade-in duration-200">
      <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100 flex items-center justify-between gap-3">
        <div>
          <h3 className="font-bold text-sm text-stone-800 flex items-center gap-1.5">
            <ImageIcon size={16} className="text-[#7A9D8C]" /> 思い出写真アルバム ({allPhotos.length}枚)
          </h3>
          <p className="text-[11px] text-stone-400 font-bold mt-0.5">
            各予定に貼った写真やアルバム写真がここに集まります
          </p>
        </div>
        {!isReadOnly && (
          <>
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="px-3.5 py-2 bg-[#7A9D8C] hover:bg-[#688a79] text-white rounded-xl text-xs font-extrabold flex items-center gap-1.5 shrink-0 shadow-2xs active:scale-95"
            >
              <Camera size={14} /> 写真を追加
            </button>
            <input
              type="file"
              ref={fileInputRef}
              multiple
              accept="image/*"
              className="hidden"
              onChange={handleUploadAlbumPhotos}
            />
          </>
        )}
      </div>

      {allPhotos.length === 0 ? (
        <div className="bg-white rounded-3xl p-12 text-center border border-dashed border-stone-200">
          <Camera size={32} className="text-stone-300 mx-auto mb-2" />
          <p className="text-xs font-bold text-stone-500">まだ思い出写真がありません</p>
          <p className="text-[11px] text-stone-400 mt-0.5">しおりの各予定カードにある「写真を追加」から登録できます</p>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2.5">
          {allPhotos.map((p, idx) => (
            <div
              key={p.id || idx}
              onClick={() => onEnlargeImage && onEnlargeImage(p.url)}
              className="aspect-square rounded-2xl overflow-hidden bg-stone-100 border border-stone-200/80 relative group cursor-pointer shadow-2xs"
            >
              <img src={p.url} alt="" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" />
              {p.eventTitle && (
                <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/70 via-black/35 to-transparent p-2">
                  <p className="text-[10px] font-bold text-white truncate">{p.eventTitle}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ------------------------------------------
// 持ち物リスト画面 (PackingListView)
// ------------------------------------------
function PackingListView({ trip, updateTrip, currentUser, isReadOnly }) {
  const [newItemText, setNewItemText] = useState('');
  const [category, setCategory] = useState('personal'); // 'personal' | 'shared'
  const [assigneeId, setAssigneeId] = useState(currentUser?.id || '');
  const [filterTab, setFilterTab] = useState('all'); // 'all' | 'personal' | 'shared'

  // 担当者選択モーダル用のステート（新規追加時 または 既存アイテムの担当者変更時）
  const [assigneeModalState, setAssigneeModalState] = useState(null);
  // { mode: 'add', title: string } | { mode: 'edit', item: object } | { mode: 'preset' }

  const DEFAULT_PACKING_PRESETS = [
    { title: 'スマートフォン・充電器', category: 'personal' },
    { title: 'モバイルバッテリー', category: 'personal' },
    { title: '財布・現金・クレジットカード', category: 'personal' },
    { title: '着替え・下着・靴下', category: 'personal' },
    { title: '常備薬・絆創膏', category: 'personal' },
    { title: '歯ブラシ・スキンケア用品', category: 'personal' },
    { title: '折りたたみ傘・雨具', category: 'personal' },
    { title: 'エコバッグ・ビニール袋', category: 'shared' },
    { title: 'ウェットティッシュ・除菌シート', category: 'shared' }
  ];

  const packingList = Array.isArray(trip.packingList) ? trip.packingList : [];
  const tripMembers = Array.isArray(trip.members) && trip.members.length > 0 ? trip.members : [currentUser];

  // 「各自の持ち物」は自分（currentUser.id）の持ち物として独立管理し、チェック状態もユーザーごとに独立させる
  const isItemVisibleForMe = (item) => {
    if (item.category === 'shared') return true;
    return !item.ownerId || item.ownerId === currentUser?.id;
  };

  const isItemCheckedForMe = (item) => {
    if (item.category === 'shared') return Boolean(item.checked);
    if (item.checkedBy && typeof item.checkedBy === 'object') {
      return Boolean(item.checkedBy[currentUser?.id]);
    }
    return Boolean(item.checked);
  };

  const myVisiblePackingList = packingList.filter(isItemVisibleForMe);

  const resolveAssigneeInfo = (selectedId) => {
    if (selectedId === 'unassigned') {
      return { id: 'unassigned', name: '未定（みんなで相談）' };
    }
    const found = tripMembers.find(m => m.id === selectedId) || currentUser;
    return { id: found?.id || currentUser.id, name: found?.name || currentUser.name };
  };

  const handleAddItem = (e) => {
    e.preventDefault();
    if (!newItemText.trim() || isReadOnly) return;

    // 「みんなの共用」が選ばれている場合は、追加ボタンを押した時に担当者選択画面を表示する
    if (!trip.isSoloTrip && category === 'shared') {
      setAssigneeModalState({
        mode: 'add',
        title: newItemText.trim(),
        selectedMemberId: assigneeId || currentUser?.id || 'unassigned'
      });
      return;
    }

    // 「各自の持ち物」は追加した本人（currentUser.id）専用の独立したアイテムとして保存する
    const newItem = {
      id: generateId(),
      title: newItemText.trim(),
      category: 'personal',
      ownerId: currentUser.id,
      ownerName: currentUser.name,
      checked: false,
      checkedBy: { [currentUser.id]: false },
      assigneeId: currentUser.id,
      assigneeName: currentUser.name
    };
    updateTrip({ ...trip, packingList: [...packingList, newItem] });
    setNewItemText('');
  };

  const handleConfirmAssigneeModal = (chosenMemberId) => {
    if (!assigneeModalState) return;
    const assigned = resolveAssigneeInfo(chosenMemberId);
    setAssigneeId(chosenMemberId);

    if (assigneeModalState.mode === 'add') {
      const newItem = {
        id: generateId(),
        title: assigneeModalState.title,
        category: 'shared',
        checked: false,
        assigneeId: assigned.id,
        assigneeName: assigned.name
      };
      updateTrip({ ...trip, packingList: [...packingList, newItem] });
      setNewItemText('');
      customAlert(`「${newItem.title}」を ${assigned.name} さんの担当で追加しました！`);
    } else if (assigneeModalState.mode === 'edit' && assigneeModalState.item) {
      const targetId = assigneeModalState.item.id;
      updateTrip({
        ...trip,
        packingList: packingList.map(item =>
          item.id === targetId
            ? { ...item, assigneeId: assigned.id, assigneeName: assigned.name }
            : item
        )
      });
      customAlert(`「${assigneeModalState.item.title}」の担当を ${assigned.name} に変更しました！`);
    }

    setAssigneeModalState(null);
  };

  const handleAddPresets = () => {
    if (isReadOnly) return;
    const myPersonalTitles = new Set(
      myVisiblePackingList.filter(i => i.category === 'personal').map(i => i.title)
    );
    const sharedTitles = new Set(
      packingList.filter(i => i.category === 'shared').map(i => i.title)
    );

    const additions = DEFAULT_PACKING_PRESETS
      .filter(p => {
        const cat = trip.isSoloTrip ? 'personal' : p.category;
        return cat === 'shared' ? !sharedTitles.has(p.title) : !myPersonalTitles.has(p.title);
      })
      .map(p => {
        const cat = trip.isSoloTrip ? 'personal' : p.category;
        return {
          id: generateId(),
          title: p.title,
          category: cat,
          ownerId: cat === 'personal' ? currentUser.id : null,
          ownerName: cat === 'personal' ? currentUser.name : null,
          checked: false,
          checkedBy: { [currentUser.id]: false },
          assigneeId: currentUser.id,
          assigneeName: currentUser.name
        };
      });
    if (additions.length === 0) {
      customAlert('定番の持ち物はすでにあなたのリストに入っています！');
      return;
    }
    updateTrip({ ...trip, packingList: [...packingList, ...additions] });
    customAlert(`定番の持ち物（${additions.length}件）を追加しました！`);
  };

  const handleToggleItem = (id) => {
    if (isReadOnly) return;
    updateTrip({
      ...trip,
      packingList: packingList.map(item => {
        if (item.id !== id) return item;
        if (item.category === 'shared') {
          return { ...item, checked: !item.checked };
        }
        const currentChecked = isItemCheckedForMe(item);
        return {
          ...item,
          checked: !currentChecked,
          checkedBy: { ...(item.checkedBy || {}), [currentUser.id]: !currentChecked }
        };
      })
    });
  };

  const handleDeleteItem = (id) => {
    if (isReadOnly) return;
    updateTrip({
      ...trip,
      packingList: packingList.filter(item => item.id !== id)
    });
  };

  const filteredItems = myVisiblePackingList.filter(item => {
    if (filterTab === 'all') return true;
    return item.category === filterTab;
  });

  const checkedCount = myVisiblePackingList.filter(isItemCheckedForMe).length;
  const progressPercent = myVisiblePackingList.length > 0 ? Math.round((checkedCount / myVisiblePackingList.length) * 100) : 0;

  return (
    <div className="p-5 pb-28 space-y-4 animate-in fade-in duration-200">
      {/* 準備進捗カード */}
      <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
        <div className="flex justify-between items-center mb-2">
          <div>
            <h3 className="font-bold text-sm text-stone-800 flex items-center gap-1.5">
              <CheckCircle2 size={16} className="text-[#7A9D8C]" /> 持ち物チェックリスト
            </h3>
            <p className="text-[11px] text-stone-400 font-bold mt-0.5">
              {trip.isSoloTrip
                ? '忘れ物がないようにチェックしましょう'
                : '👤 各自の持ち物はあなた専用（他メンバーと独立）で管理されます'}
            </p>
          </div>
          <div className="text-right">
            <span className="text-lg font-extrabold text-[#7A9D8C]">{progressPercent}%</span>
            <p className="text-[10px] font-bold text-stone-400">{checkedCount}/{myVisiblePackingList.length} 完了</p>
          </div>
        </div>
        <div className="w-full h-2.5 bg-stone-100 rounded-full overflow-hidden">
          <div
            className="h-full bg-[#7A9D8C] rounded-full transition-all duration-300"
            style={{ width: `${progressPercent}%` }}
          />
        </div>

        {!isReadOnly && (
          <div className="mt-3 pt-3 border-t border-stone-100 flex justify-between items-center">
            <button
              type="button"
              onClick={handleAddPresets}
              className="px-3 py-1.5 bg-amber-50 hover:bg-amber-100 text-amber-800 border border-amber-200/80 rounded-xl text-[11px] font-bold flex items-center gap-1 transition-colors"
            >
              <Sparkles size={12} className="text-amber-500" /> 定番セットを一括追加
            </button>
            {checkedCount > 0 && (
              <button
                type="button"
                onClick={() =>
                  updateTrip({
                    ...trip,
                    packingList: packingList.map(item => {
                      if (!isItemVisibleForMe(item)) return item;
                      if (item.category === 'shared') return { ...item, checked: false };
                      return {
                        ...item,
                        checked: false,
                        checkedBy: { ...(item.checkedBy || {}), [currentUser.id]: false }
                      };
                    })
                  })
                }
                className="text-[11px] font-bold text-stone-400 hover:text-stone-600 underline"
              >
                チェックをすべて外す
              </button>
            )}
          </div>
        )}
      </div>

      {/* 新規持ち物追加フォーム */}
      {!isReadOnly && (
        <form onSubmit={handleAddItem} className="bg-white p-4 rounded-2xl shadow-xs border border-stone-100 space-y-2.5">
          {!trip.isSoloTrip && (
            <div className="flex items-center justify-between gap-2 flex-wrap">
              <div className="flex bg-stone-100 p-0.5 rounded-xl">
                <button
                  type="button"
                  onClick={() => setCategory('personal')}
                  className={`px-3 py-1 rounded-lg text-[11px] font-bold transition-all ${
                    category === 'personal' ? 'bg-white text-stone-800 shadow-2xs' : 'text-stone-500'
                  }`}
                >
                  👤 各自の持ち物
                </button>
                <button
                  type="button"
                  onClick={() => setCategory('shared')}
                  className={`px-3 py-1 rounded-lg text-[11px] font-bold transition-all ${
                    category === 'shared' ? 'bg-white text-stone-800 shadow-2xs' : 'text-stone-500'
                  }`}
                >
                  👥 みんなの共用
                </button>
              </div>

              {category === 'shared' ? (
                <span className="text-[10px] font-bold text-[#557465] bg-[#7A9D8C]/10 px-2.5 py-1 rounded-lg flex items-center gap-1">
                  <User size={11} className="text-[#7A9D8C]" />
                  全員で共有（追加時に担当を選択）
                </span>
              ) : (
                <span className="text-[10px] font-bold text-stone-500 bg-stone-100 px-2.5 py-1 rounded-lg flex items-center gap-1">
                  🔒 {currentUser?.name}さん専用の持ち物に追加
                </span>
              )}
            </div>
          )}

          <div className="flex gap-2">
            <input
              type="text"
              value={newItemText}
              onChange={e => setNewItemText(e.target.value)}
              placeholder="持ち物を追加（例：モバイルバッテリー、御朱印帳）"
              className="flex-1 p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
            />
            <button
              type="submit"
              disabled={!newItemText.trim()}
              className="px-4 py-2.5 bg-[#7A9D8C] text-white font-bold rounded-xl text-xs shadow-xs hover:bg-[#688a79] disabled:opacity-40 transition-all shrink-0 flex items-center gap-1"
            >
              <Plus size={15} /> 追加
            </button>
          </div>
        </form>
      )}

      {/* フィルタータブ（複数人旅のとき） */}
      {!trip.isSoloTrip && myVisiblePackingList.length > 0 && (
        <div className="flex gap-1.5">
          {[
            { id: 'all', label: `すべて (${myVisiblePackingList.length})` },
            { id: 'personal', label: `👤 自分専用 (${myVisiblePackingList.filter(i => i.category === 'personal').length})` },
            { id: 'shared', label: `👥 みんなの共用 (${myVisiblePackingList.filter(i => i.category === 'shared').length})` }
          ].map(t => (
            <button
              key={t.id}
              type="button"
              onClick={() => setFilterTab(t.id)}
              className={`px-3 py-1.5 rounded-full text-[11px] font-bold border transition-all ${
                filterTab === t.id
                  ? 'bg-stone-800 text-white border-stone-800'
                  : 'bg-white text-stone-600 border-stone-200 hover:bg-stone-50'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      )}

      {/* リスト一覧 */}
      {filteredItems.length === 0 ? (
        <div className="bg-white rounded-3xl p-10 text-center border border-dashed border-stone-200">
          <CheckCircle2 size={30} className="text-stone-300 mx-auto mb-2" />
          <p className="text-xs font-bold text-stone-500 mb-1">まだ持ち物が登録されていません</p>
          <p className="text-[11px] text-stone-400">上の「定番セットを一括追加」または入力欄から追加できます</p>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredItems.map(item => {
            const isChecked = isItemCheckedForMe(item);
            return (
              <div
                key={item.id}
                onClick={() => handleToggleItem(item.id)}
                className={`p-3.5 rounded-2xl border flex items-center justify-between gap-3 transition-all cursor-pointer ${
                  isChecked
                    ? 'bg-stone-50/80 border-stone-200/70 text-stone-400'
                    : 'bg-white border-stone-100 shadow-2xs hover:border-[#7A9D8C]/50 text-stone-800'
                }`}
              >
                <div className="flex items-center gap-3 min-w-0 flex-1">
                  <div
                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 transition-colors ${
                      isChecked ? 'bg-[#7A9D8C] border-[#7A9D8C] text-white' : 'border-stone-300 bg-white'
                    }`}
                  >
                    {isChecked && <Check size={13} strokeWidth={3} />}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className={`text-xs font-bold truncate ${isChecked ? 'line-through text-stone-400' : 'text-stone-800'}`}>
                      {item.title}
                    </p>
                    {!trip.isSoloTrip && (
                      <div className="flex items-center gap-1.5 mt-1">
                        {item.category === 'shared' ? (
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              if (!isReadOnly) {
                                setAssigneeModalState({
                                  mode: 'edit',
                                  item,
                                  selectedMemberId: item.assigneeId || currentUser?.id || 'unassigned'
                                });
                              }
                            }}
                            className="text-[10px] font-bold px-2 py-0.5 rounded-lg bg-blue-50 hover:bg-blue-100 text-blue-600 border border-blue-200/70 inline-flex items-center gap-1 transition-colors active:scale-95"
                            title="タップして担当者を変更"
                          >
                            <span>👥 共用（担当: {item.assigneeName || '未定'}）</span>
                            {!isReadOnly && <Edit2 size={10} className="opacity-70" />}
                          </button>
                        ) : (
                          <span className="text-[9px] font-bold px-2 py-0.5 rounded-md bg-stone-100 text-stone-500 inline-flex items-center gap-1">
                            👤 自分専用（{currentUser?.name}）
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                </div>

                {!isReadOnly && (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteItem(item.id);
                    }}
                    className="p-1.5 text-stone-300 hover:text-red-500 rounded-lg hover:bg-stone-100 transition-colors shrink-0"
                    title="削除"
                  >
                    <Trash2 size={14} />
                  </button>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* 担当メンバー選択モーダル（共用アイテム追加時＆変更時） */}
      {assigneeModalState && (
        <div
          className="fixed inset-0 bg-black/60 z-[260] flex justify-center items-end sm:items-center p-0 sm:p-4 animate-in fade-in"
          onClick={() => setAssigneeModalState(null)}
        >
          <div
            className="bg-white w-full sm:max-w-sm rounded-t-[32px] sm:rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-bottom-full sm:zoom-in-95 pb-safe"
            onClick={e => e.stopPropagation()}
          >
            <div className="flex justify-between items-center mb-3">
              <h3 className="font-bold text-base text-stone-800 flex items-center gap-2">
                <User size={18} className="text-[#7A9D8C]" />
                誰が担当しますか？
              </h3>
              <button
                type="button"
                onClick={() => setAssigneeModalState(null)}
                className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"
              >
                <X size={20} />
              </button>
            </div>

            <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100 mb-4">
              <p className="text-[10px] font-bold text-stone-400 mb-0.5">対象の共用アイテム</p>
              <p className="text-xs font-extrabold text-stone-800 truncate">
                👥 {assigneeModalState.mode === 'add' ? assigneeModalState.title : assigneeModalState.item?.title}
              </p>
            </div>

            <p className="text-[11px] font-bold text-stone-500 mb-2.5 pl-1">
              参加しているメンバーから担当者を選んでください
            </p>

            <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar mb-4">
              {tripMembers.map((member, idx) => {
                const isSelected = assigneeModalState.selectedMemberId === member.id;
                const isMe = member.id === currentUser?.id;
                return (
                  <button
                    key={member.id || idx}
                    type="button"
                    onClick={() => handleConfirmAssigneeModal(member.id)}
                    className={`w-full p-3 rounded-2xl border-2 text-left flex items-center justify-between gap-3 transition-all active:scale-[0.99] ${
                      isSelected
                        ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 shadow-2xs'
                        : 'border-stone-200 bg-white hover:bg-stone-50'
                    }`}
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <UserAvatar user={member} size="w-9 h-9" />
                      <div className="min-w-0">
                        <div className="flex items-center gap-1.5">
                          <span className="text-xs font-extrabold text-stone-800 truncate">
                            {member.name}
                          </span>
                          {isMe && (
                            <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-[#7A9D8C]/15 text-[#557465] shrink-0">
                              あなた
                            </span>
                          )}
                        </div>
                        <p className="text-[10px] text-stone-400 font-bold">
                          タップしてこのメンバーを担当にする
                        </p>
                      </div>
                    </div>
                    <div
                      className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                        isSelected ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'
                      }`}
                    >
                      {isSelected && <Check size={12} strokeWidth={3} />}
                    </div>
                  </button>
                );
              })}

              {/* 担当をまだ決めない（未定）選択肢 */}
              <button
                type="button"
                onClick={() => handleConfirmAssigneeModal('unassigned')}
                className={`w-full p-3 rounded-2xl border-2 border-dashed text-left flex items-center justify-between gap-3 transition-all active:scale-[0.99] ${
                  assigneeModalState.selectedMemberId === 'unassigned'
                    ? 'border-[#7A9D8C] bg-[#7A9D8C]/10'
                    : 'border-stone-300 bg-stone-50/70 hover:bg-stone-100'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-stone-200 text-stone-600 flex items-center justify-center text-xs font-bold shrink-0">
                    ？
                  </div>
                  <div>
                    <p className="text-xs font-extrabold text-stone-700">未定（あとでみんなで決める）</p>
                    <p className="text-[10px] text-stone-400 font-bold">担当者を指定せずにリストへ追加します</p>
                  </div>
                </div>
                <div
                  className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${
                    assigneeModalState.selectedMemberId === 'unassigned' ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'
                  }`}
                >
                  {assigneeModalState.selectedMemberId === 'unassigned' && <Check size={12} strokeWidth={3} />}
                </div>
              </button>
            </div>

            <button
              type="button"
              onClick={() => setAssigneeModalState(null)}
              className="w-full py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs transition-colors"
            >
              キャンセル
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// ------------------------------------------
// 予算・出費管理画面 (BudgetView)
// ------------------------------------------
function BudgetView({ trip, updateTrip, currentUser, isReadOnly }) {
  const [isEditingBudget, setIsEditingBudget] = useState(false);
  const [budgetDraft, setBudgetDraft] = useState(String(trip.budget || 50000));
  const [expenseTitle, setExpenseTitle] = useState('');
  const [expenseAmount, setExpenseAmount] = useState('');
  const [expenseCategory, setExpenseCategory] = useState('meal');

  // おみやげ追加用ステート
  const [souvenirTarget, setSouvenirTarget] = useState('自分用');
  const [souvenirTitle, setSouvenirTitle] = useState('');
  const [souvenirAmount, setSouvenirAmount] = useState('');

  const SOUVENIR_TARGETS = ['自分用', '家族・実家', '職場・学校', '友達', 'その他'];
  const QUICK_SOUVENIR_PRESETS = [
    { label: '＋ 職場・ばらまき用 (¥3,000)', target: '職場・学校', title: '職場・ばらまき用お菓子', amount: 3000 },
    { label: '＋ 家族・実家用 (¥3,000)', target: '家族・実家', title: '家族・実家用おみやげ', amount: 3000 },
    { label: '＋ 友達用 (¥2,000)', target: '友達', title: '友達用おみやげ', amount: 2000 },
    { label: '＋ 自分へのご褒美 (¥3,000)', target: '自分用', title: '自分用ご当地グルメ・雑貨', amount: 3000 }
  ];

  const events = Array.isArray(trip.events) ? trip.events : [];
  const extraExpenses = Array.isArray(trip.extraExpenses) ? trip.extraExpenses : [];
  const souvenirList = Array.isArray(trip.souvenirList) ? trip.souvenirList : [];
  const memberCount = Math.max(1, (trip.members || []).length);

  // タイムラインの予定から自動計算
  const approvedEventCost = events
    .filter(e => e.status !== 'proposed')
    .reduce((sum, e) => sum + (Number(e.cost) || 0), 0);
  const proposedEventCost = events
    .filter(e => e.status === 'proposed')
    .reduce((sum, e) => sum + (Number(e.cost) || 0), 0);
  const eventsOnlyTotal = approvedEventCost + proposedEventCost;
  const souvenirCostTotal = isReadOnly ? 0 : souvenirList.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  const extraCostTotal = isReadOnly ? 0 : extraExpenses.reduce((sum, ex) => sum + (Number(ex.amount) || 0), 0);

  const totalEstimated = isReadOnly ? eventsOnlyTotal : (eventsOnlyTotal + souvenirCostTotal + extraCostTotal);
  const targetBudget = Number(trip.budget) || 0;
  const remaining = targetBudget - totalEstimated;
  const usageRatio = targetBudget > 0 ? Math.min(100, Math.round((totalEstimated / targetBudget) * 100)) : 0;
  const isOverBudget = targetBudget > 0 && totalEstimated > targetBudget;

  // カテゴリ別集計（閲覧専用＝みんなの旅では予定内の金額のみ集計し、おみやげ枠は除外）
  const categoryBreakdown = useMemo(() => {
    const map = { meal: 0, sightseeing: 0, transport: 0, active: 0, hotel: 0, souvenir: souvenirCostTotal };
    events.forEach(ev => {
      const c = Number(ev.cost) || 0;
      if (c > 0) {
        const key = map[ev.type] !== undefined ? ev.type : 'sightseeing';
        map[key] += c;
      }
    });
    if (!isReadOnly) {
      extraExpenses.forEach(ex => {
        const c = Number(ex.amount) || 0;
        if (c > 0) {
          const key = map[ex.category] !== undefined ? ex.category : 'sightseeing';
          map[key] += c;
        }
      });
    }
    const categories = isReadOnly
      ? QUICK_TAGS
      : [...QUICK_TAGS, { id: 'souvenir', label: '🎁 おみやげ', icon: Heart }];
    return categories.map(tag => ({
      ...tag,
      amount: map[tag.id] || 0,
      percent: totalEstimated > 0 ? Math.round(((map[tag.id] || 0) / totalEstimated) * 100) : 0
    }));
  }, [events, extraExpenses, souvenirCostTotal, totalEstimated, isReadOnly]);

  // ★「みんなの旅（閲覧モード）」のときは、予定に記載されている金額の合計と予定ごとの金額一覧・カテゴリ内訳のみをシンプルに表示
  if (isReadOnly) {
    return (
      <div className="p-5 pb-28 space-y-4 animate-in fade-in duration-200">
        <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
          <span className="text-[11px] font-bold text-stone-400 block mb-1">
            このしおりの予定に記載されている金額の合計（1人あたり）
          </span>
          <div className="flex items-baseline justify-between gap-2 flex-wrap">
            <div className="flex items-baseline gap-2 flex-wrap">
              <span className="text-3xl font-extrabold text-stone-900">
                ¥{eventsOnlyTotal.toLocaleString()}<span className="text-sm font-bold text-stone-500 ml-0.5">/人</span>
              </span>
              <span className="text-xs font-extrabold text-[#557465] bg-[#7A9D8C]/15 px-2.5 py-1 rounded-full">
                × {memberCount}人 {memberCount > 1 ? `（計 ¥${(eventsOnlyTotal * memberCount).toLocaleString()}）` : ''}
              </span>
            </div>
            <span className="text-xs font-bold text-stone-500 bg-stone-100 px-3 py-1 rounded-full">
              全 {events.length} 件の予定
            </span>
          </div>
          <p className="text-[11px] text-stone-500 mt-2 leading-relaxed">
            ※どのくらいの費用でどんな体験・食事・宿泊ができるかの目安としてご確認いただけます。
          </p>
        </div>

        {/* 予定ごとの金額明細リスト */}
        <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
          <h4 className="font-bold text-xs text-stone-700 mb-3 flex items-center gap-1.5">
            <Banknote size={14} className="text-[#7A9D8C]" /> 予定ごとの金額一覧
          </h4>
          {events.length === 0 ? (
            <p className="text-xs text-stone-400 font-bold text-center py-6">予定が登録されていません</p>
          ) : (
            <div className="divide-y divide-stone-100">
              {events.map((ev, idx) => {
                const tagInfo = QUICK_TAGS.find(t => t.id === ev.type) || QUICK_TAGS[2];
                const TagIcon = tagInfo.icon;
                const costNum = Number(ev.cost) || 0;
                return (
                  <div key={ev.id || idx} className="py-2.5 flex items-center justify-between gap-3 text-xs">
                    <div className="flex items-center gap-2.5 min-w-0 flex-1">
                      <div className="w-7 h-7 rounded-xl bg-[#7A9D8C]/10 text-[#7A9D8C] flex items-center justify-center shrink-0">
                        <TagIcon size={14} />
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="font-bold text-stone-800 truncate">{ev.title}</p>
                        <p className="text-[10px] text-stone-400 font-bold">
                          {ev.date ? `${ev.date.slice(5).replace('-', '/')} ` : ''}{ev.time || ''} {ev.location ? `・ ${ev.location}` : ''}
                        </p>
                      </div>
                    </div>
                    <div className="text-right shrink-0">
                      <span className={`font-extrabold ${costNum > 0 ? 'text-stone-800' : 'text-stone-400'}`}>
                        {costNum > 0 ? `¥${costNum.toLocaleString()}/人` : '¥0'}
                      </span>
                      {costNum > 0 && (
                        <span className="text-[10px] font-bold text-[#557465] ml-1">
                          ×{memberCount}人
                        </span>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* カテゴリ別の費用内訳 */}
        <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
          <h4 className="font-bold text-xs text-stone-700 mb-3 flex items-center gap-1.5">
            <Activity size={14} className="text-[#7A9D8C]" /> カテゴリ別の費用内訳
          </h4>
          <div className="space-y-2.5">
            {categoryBreakdown.map(cat => {
              const CatIcon = cat.icon;
              return (
                <div key={cat.id} className="space-y-1">
                  <div className="flex justify-between items-center text-xs font-bold">
                    <span className="flex items-center gap-1.5 text-stone-700">
                      <CatIcon size={13} className="text-[#7A9D8C]" /> {cat.label}
                    </span>
                    <span className="text-stone-800">
                      ¥{cat.amount.toLocaleString()} <span className="text-[10px] text-stone-400">({cat.percent}%)</span>
                    </span>
                  </div>
                  <div className="w-full h-1.5 bg-stone-100 rounded-full overflow-hidden">
                    <div
                      className="h-full rounded-full bg-[#7A9D8C]/80"
                      style={{ width: `${cat.percent}%` }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  const handleSaveTargetBudget = () => {
    const nextVal = Math.max(0, Number(budgetDraft) || 0);
    updateTrip({ ...trip, budget: nextVal });
    setIsEditingBudget(false);
    customAlert('目標予算を更新しました！');
  };

  // おみやげの追加・プリセット追加・購入チェック・削除
  const handleAddSouvenir = (e) => {
    e.preventDefault();
    const amountNum = Number(souvenirAmount);
    if (!amountNum || amountNum <= 0 || isReadOnly) return;
    const finalTitle = souvenirTitle.trim() || `${souvenirTarget}のおみやげ`;
    const newItem = {
      id: generateId(),
      target: souvenirTarget,
      title: finalTitle,
      amount: amountNum,
      purchased: false
    };
    updateTrip({ ...trip, souvenirList: [...souvenirList, newItem] });
    setSouvenirTitle('');
    setSouvenirAmount('');
    customAlert(`「${finalTitle} (¥${amountNum.toLocaleString()})」をおみやげ予算に追加しました！`);
  };

  const handleQuickAddSouvenir = (preset) => {
    if (isReadOnly) return;
    const newItem = {
      id: generateId(),
      target: preset.target,
      title: preset.title,
      amount: preset.amount,
      purchased: false
    };
    updateTrip({ ...trip, souvenirList: [...souvenirList, newItem] });
    customAlert(`「${preset.title} (¥${preset.amount.toLocaleString()})」を追加しました！`);
  };

  const handleSetRoughSouvenirBudget = (roughAmount) => {
    if (isReadOnly) return;
    const newItem = {
      id: generateId(),
      target: 'その他',
      title: 'おみやげ予算枠（まとめ予算）',
      amount: roughAmount,
      purchased: false
    };
    updateTrip({ ...trip, souvenirList: [...souvenirList, newItem] });
    customAlert(`おみやげ予算枠として ¥${roughAmount.toLocaleString()} を追加しました！`);
  };

  const handleToggleSouvenirPurchased = (id) => {
    if (isReadOnly) return;
    updateTrip({
      ...trip,
      souvenirList: souvenirList.map(item => item.id === id ? { ...item, purchased: !item.purchased } : item)
    });
  };

  const handleDeleteSouvenir = (id) => {
    if (isReadOnly) return;
    updateTrip({
      ...trip,
      souvenirList: souvenirList.filter(item => item.id !== id)
    });
  };

  const handleAddExtraExpense = (e) => {
    e.preventDefault();
    const amountNum = Number(expenseAmount);
    if (!expenseTitle.trim() || !amountNum || amountNum <= 0 || isReadOnly) return;
    const newExp = {
      id: generateId(),
      title: expenseTitle.trim(),
      amount: amountNum,
      category: expenseCategory,
      paidBy: currentUser?.name || 'メンバー',
      createdAt: getTodayString()
    };
    updateTrip({ ...trip, extraExpenses: [newExp, ...extraExpenses] });
    setExpenseTitle('');
    setExpenseAmount('');
    customAlert('出費メモを追加しました');
  };

  const handleDeleteExtraExpense = (id) => {
    if (isReadOnly) return;
    updateTrip({ ...trip, extraExpenses: extraExpenses.filter(ex => ex.id !== id) });
  };

  return (
    <div className="p-5 pb-28 space-y-4 animate-in fade-in duration-200">
      {/* 予算サマリーカード */}
      <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
        <div className="flex justify-between items-start mb-3">
          <div>
            <span className="text-[11px] font-bold text-stone-400 block mb-0.5">現在の予定＋おみやげ＋出費合計（1人あたり × 参加人数）</span>
            <div className="flex items-baseline gap-2 flex-wrap">
              <span className={`text-2xl font-extrabold ${isOverBudget ? 'text-red-500' : 'text-stone-900'}`}>
                ¥{totalEstimated.toLocaleString()}<span className="text-xs font-bold text-stone-500 ml-0.5">/人</span>
              </span>
              <span className="text-xs font-extrabold text-[#557465] bg-[#7A9D8C]/15 px-2.5 py-0.5 rounded-full">
                × {memberCount}人 {memberCount > 1 ? `（全員計 ¥${(totalEstimated * memberCount).toLocaleString()}）` : ''}
              </span>
              {targetBudget > 0 && (
                <span className="text-xs font-bold text-stone-400">
                  / 1人予算 ¥{targetBudget.toLocaleString()}
                </span>
              )}
            </div>
          </div>

          {!isReadOnly && (
            <button
              type="button"
              onClick={() => {
                setBudgetDraft(String(trip.budget || 50000));
                setIsEditingBudget(!isEditingBudget);
              }}
              className="px-3 py-1.5 rounded-xl bg-stone-100 hover:bg-stone-200 text-stone-700 text-[11px] font-bold flex items-center gap-1 transition-colors"
            >
              <Edit2 size={12} /> 予算変更
            </button>
          )}
        </div>

        {isEditingBudget && !isReadOnly && (
          <div className="mb-4 p-3 bg-stone-50 rounded-2xl border border-[#7A9D8C]/40 flex items-center gap-2 animate-in fade-in">
            <input
              type="number"
              value={budgetDraft}
              onChange={e => setBudgetDraft(e.target.value)}
              className="flex-1 p-2 bg-white border border-stone-200 rounded-xl text-xs font-bold"
              placeholder="目標予算 (円)"
            />
            <button
              type="button"
              onClick={handleSaveTargetBudget}
              className="px-3.5 py-2 bg-[#7A9D8C] text-white rounded-xl text-xs font-bold"
            >
              保存
            </button>
          </div>
        )}

        {/* プログレスバー */}
        {targetBudget > 0 && (
          <>
            <div className="w-full h-3 bg-stone-100 rounded-full overflow-hidden mb-2">
              <div
                className={`h-full rounded-full transition-all duration-300 ${
                  isOverBudget ? 'bg-red-500' : usageRatio > 85 ? 'bg-amber-500' : 'bg-[#7A9D8C]'
                }`}
                style={{ width: `${usageRatio}%` }}
              />
            </div>
            <div className="flex justify-between items-center text-[11px] font-bold">
              <span className="text-stone-400">消化率 {usageRatio}%</span>
              {remaining >= 0 ? (
                <span className="text-[#557465]">あと ¥{remaining.toLocaleString()} 余裕あり</span>
              ) : (
                <span className="text-red-500">予算を ¥{Math.abs(remaining).toLocaleString()} オーバー中</span>
              )}
            </div>
          </>
        )}

        {/* 確定分 / 提案中 / おみやげ / その他 の4分割内訳 */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mt-4 pt-4 border-t border-stone-100 text-center">
          <div className="bg-stone-50 p-2.5 rounded-2xl">
            <p className="text-[10px] font-bold text-stone-400 mb-0.5">確定した予定</p>
            <p className="text-xs font-extrabold text-stone-800">¥{approvedEventCost.toLocaleString()}</p>
          </div>
          <div className="bg-amber-50/70 p-2.5 rounded-2xl">
            <p className="text-[10px] font-bold text-amber-700 mb-0.5">💡 提案中の予定</p>
            <p className="text-xs font-extrabold text-amber-800">¥{proposedEventCost.toLocaleString()}</p>
          </div>
          <div className="bg-rose-50/70 p-2.5 rounded-2xl border border-rose-100/80">
            <p className="text-[10px] font-bold text-rose-600 mb-0.5">🎁 おみやげ予算</p>
            <p className="text-xs font-extrabold text-rose-700">¥{souvenirCostTotal.toLocaleString()}</p>
          </div>
          <div className="bg-stone-50 p-2.5 rounded-2xl">
            <p className="text-[10px] font-bold text-stone-400 mb-0.5">その他の出費</p>
            <p className="text-xs font-extrabold text-stone-800">¥{extraCostTotal.toLocaleString()}</p>
          </div>
        </div>
      </div>

      {/* 🎁 おみやげ予算・買い物リスト（ワンタップで簡単追加） */}
      <div className="bg-white p-5 rounded-3xl shadow-xs border border-rose-100 space-y-3.5">
        <div className="flex justify-between items-center">
          <div>
            <h4 className="font-bold text-sm text-stone-800 flex items-center gap-1.5">
              <span className="text-base">🎁</span> おみやげ予算・買い物リスト
            </h4>
            <p className="text-[11px] text-stone-400 font-bold mt-0.5">
              ワンタップで全体の予算におみやげ代を組み込めます
            </p>
          </div>
          <div className="text-right">
            <span className="text-sm font-extrabold text-rose-600">¥{souvenirCostTotal.toLocaleString()}</span>
            <p className="text-[10px] font-bold text-stone-400">{souvenirList.length}件</p>
          </div>
        </div>

        {!isReadOnly && (
          <>
            {/* ざっくりおみやげ予算枠ボタン＆定番プリセット */}
            <div className="bg-rose-50/50 p-3 rounded-2xl border border-rose-100/80 space-y-2.5">
              <div className="flex items-center justify-between flex-wrap gap-1.5">
                <span className="text-[10px] font-bold text-rose-700">⚡ ざっくりおみやげ予算枠を追加：</span>
                <div className="flex gap-1.5">
                  {[3000, 5000, 10000].map(amt => (
                    <button
                      key={amt}
                      type="button"
                      onClick={() => handleSetRoughSouvenirBudget(amt)}
                      className="px-2.5 py-1 bg-white hover:bg-rose-500 text-rose-600 hover:text-white border border-rose-200 rounded-lg text-[10px] font-extrabold transition-colors shadow-2xs active:scale-95"
                    >
                      ＋¥{amt.toLocaleString()}
                    </button>
                  ))}
                </div>
              </div>

              <div className="pt-2 border-t border-rose-100/80">
                <span className="text-[10px] font-bold text-stone-500 block mb-1.5">渡す相手別・ワンタップ追加：</span>
                <div className="flex flex-wrap gap-1.5">
                  {QUICK_SOUVENIR_PRESETS.map((preset, idx) => (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => handleQuickAddSouvenir(preset)}
                      className="px-2.5 py-1.5 bg-white hover:bg-rose-50 text-stone-700 border border-stone-200/90 rounded-xl text-[10px] font-bold transition-all active:scale-95 shadow-2xs"
                    >
                      {preset.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* 個別のおみやげ入力フォーム */}
            <form onSubmit={handleAddSouvenir} className="space-y-2 pt-1">
              <div className="flex gap-1.5 overflow-x-auto no-scrollbar pb-0.5">
                {SOUVENIR_TARGETS.map(target => (
                  <button
                    key={target}
                    type="button"
                    onClick={() => setSouvenirTarget(target)}
                    className={`px-2.5 py-1 rounded-lg text-[10px] font-bold shrink-0 border transition-all ${
                      souvenirTarget === target
                        ? 'bg-rose-500 text-white border-rose-500'
                        : 'bg-stone-50 text-stone-600 border-stone-200 hover:bg-stone-100'
                    }`}
                  >
                    {target}
                  </button>
                ))}
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={souvenirTitle}
                  onChange={e => setSouvenirTitle(e.target.value)}
                  placeholder={`${souvenirTarget}のおみやげ名 (省略可)`}
                  className="flex-1 p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-rose-400"
                />
                <input
                  type="number"
                  value={souvenirAmount}
                  onChange={e => setSouvenirAmount(e.target.value)}
                  placeholder="金額(円)"
                  className="w-24 p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-rose-400"
                />
                <button
                  type="submit"
                  disabled={!souvenirAmount}
                  className="px-3.5 py-2.5 bg-rose-500 text-white font-bold rounded-xl text-xs shadow-xs hover:bg-rose-600 disabled:opacity-40 transition-all shrink-0 flex items-center gap-1"
                >
                  <Plus size={14} /> 追加
                </button>
              </div>
            </form>
          </>
        )}

        {/* おみやげリスト一覧 */}
        {souvenirList.length === 0 ? (
          <div className="p-4 rounded-2xl bg-stone-50 border border-dashed border-stone-200 text-center text-[11px] font-bold text-stone-400">
            まだおみやげ予算が登録されていません
          </div>
        ) : (
          <div className="space-y-2 pt-1">
            {souvenirList.map(item => (
              <div
                key={item.id}
                onClick={() => handleToggleSouvenirPurchased(item.id)}
                className={`p-3 rounded-2xl border flex items-center justify-between gap-2 transition-all cursor-pointer ${
                  item.purchased
                    ? 'bg-stone-50/80 border-stone-200/70 text-stone-400'
                    : 'bg-white border-rose-100 shadow-2xs hover:border-rose-300 text-stone-800'
                }`}
              >
                <div className="flex items-center gap-2.5 min-w-0 flex-1">
                  <div
                    className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 transition-colors ${
                      item.purchased ? 'bg-rose-500 border-rose-500 text-white' : 'border-stone-300 bg-white'
                    }`}
                  >
                    {item.purchased && <Check size={12} strokeWidth={3} />}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1.5">
                      <span className="text-[9px] font-bold px-1.5 py-0.2 rounded bg-rose-50 text-rose-600 shrink-0">
                        {item.target}
                      </span>
                      <p className={`text-xs font-bold truncate ${item.purchased ? 'line-through text-stone-400' : 'text-stone-800'}`}>
                        {item.title}
                      </p>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <span className="text-xs font-extrabold text-rose-600">¥{Number(item.amount).toLocaleString()}</span>
                  {!isReadOnly && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteSouvenir(item.id);
                      }}
                      className="p-1 text-stone-300 hover:text-red-500 rounded-lg"
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* カテゴリ別の費用内訳 */}
      <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100">
        <h4 className="font-bold text-xs text-stone-700 mb-3 flex items-center gap-1.5">
          <Activity size={14} className="text-[#7A9D8C]" /> カテゴリ別の費用内訳
        </h4>
        <div className="space-y-2.5">
          {categoryBreakdown.map(cat => {
            const CatIcon = cat.icon;
            return (
              <div key={cat.id} className="space-y-1">
                <div className="flex justify-between items-center text-xs font-bold">
                  <span className="flex items-center gap-1.5 text-stone-700">
                    <CatIcon size={13} className={cat.id === 'souvenir' ? 'text-rose-500' : 'text-[#7A9D8C]'} /> {cat.label}
                  </span>
                  <span className="text-stone-800">
                    ¥{cat.amount.toLocaleString()} <span className="text-[10px] text-stone-400">({cat.percent}%)</span>
                  </span>
                </div>
                <div className="w-full h-1.5 bg-stone-100 rounded-full overflow-hidden">
                  <div
                    className={`h-full rounded-full ${cat.id === 'souvenir' ? 'bg-rose-400' : 'bg-[#7A9D8C]/80'}`}
                    style={{ width: `${cat.percent}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* その他の出費メモ（食べ歩き・タクシー割り勘など） */}
      {!isReadOnly && (
        <div className="bg-white p-5 rounded-3xl shadow-xs border border-stone-100 space-y-3">
          <h4 className="font-bold text-xs text-stone-700 flex items-center gap-1.5">
            <Banknote size={14} className="text-[#7A9D8C]" /> タイムライン外の出費メモを追加
          </h4>
          <form onSubmit={handleAddExtraExpense} className="space-y-2">
            <div className="flex gap-1.5 overflow-x-auto no-scrollbar pb-0.5">
              {QUICK_TAGS.map(tag => {
                const TagIcon = tag.icon;
                return (
                  <button
                    key={tag.id}
                    type="button"
                    onClick={() => setExpenseCategory(tag.id)}
                    className={`px-2.5 py-1 rounded-lg text-[10px] font-bold flex items-center gap-1 shrink-0 border transition-all ${
                      expenseCategory === tag.id
                        ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                        : 'bg-stone-50 text-stone-600 border-stone-200'
                    }`}
                  >
                    <TagIcon size={11} /> {tag.label}
                  </button>
                );
              })}
            </div>
            <div className="flex gap-2">
              <input
                type="text"
                value={expenseTitle}
                onChange={e => setExpenseTitle(e.target.value)}
                placeholder="項目（例：コインロッカー・飲み物）"
                className="flex-1 p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
              <input
                type="number"
                value={expenseAmount}
                onChange={e => setExpenseAmount(e.target.value)}
                placeholder="金額(円)"
                className="w-24 p-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
              <button
                type="submit"
                disabled={!expenseTitle.trim() || !expenseAmount}
                className="px-3.5 py-2.5 bg-[#7A9D8C] text-white font-bold rounded-xl text-xs shadow-xs hover:bg-[#688a79] disabled:opacity-40 transition-all shrink-0"
              >
                追加
              </button>
            </div>
          </form>

          {extraExpenses.length > 0 && (
            <div className="space-y-1.5 pt-2 border-t border-stone-100">
              {extraExpenses.map(ex => (
                <div key={ex.id} className="flex items-center justify-between text-xs py-1.5 px-2.5 bg-stone-50 rounded-xl">
                  <div className="min-w-0 flex-1">
                    <span className="font-bold text-stone-800">{ex.title}</span>
                    <span className="text-[10px] text-stone-400 ml-2">({ex.paidBy})</span>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <span className="font-extrabold text-stone-700">¥{Number(ex.amount).toLocaleString()}</span>
                    <button
                      type="button"
                      onClick={() => handleDeleteExtraExpense(ex.id)}
                      className="text-stone-300 hover:text-red-500"
                    >
                      <Trash2 size={13} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function CopyModal({ type, sourceData, currentUser, myTrips, onClose, onOpenRegister, onComplete }) {
  useLockBodyScroll(true);
  const [step, setStep] = useState(1);
  const [createdGroupTrip, setCreatedGroupTrip] = useState(null);
  const [copiedCode, setCopiedCode] = useState(false);
  const [copiedInviteMsg, setCopiedInviteMsg] = useState(false);

  // ★ 1人旅 / 複数人（グループ）旅の選択ステート
  const [copyMode, setCopyMode] = useState('solo'); // 'solo' | 'group'
  const [showGuestPrompt, setShowGuestPrompt] = useState(false);

  // 過去の旅を除外し、現在選択されているスタイル（1人旅 / みんなの旅）に一致するこれからの旅のみを抽出
  const todayStr = getTodayString();
  const filteredTargetTrips = useMemo(() => {
    return (myTrips || []).filter(t => {
      const endDate = t.endDate || t.startDate || '';
      if (endDate < todayStr) return false; // 過去のしおりは除外
      return copyMode === 'solo' ? Boolean(t.isSoloTrip) : !t.isSoloTrip;
    });
  }, [myTrips, copyMode, todayStr]);

  const [selectedTripId, setSelectedTripId] = useState(() => {
    if (type === 'trip') return 'new';
    const initialSoloTrips = (myTrips || []).filter(t => (t.endDate || t.startDate || '') >= todayStr && Boolean(t.isSoloTrip));
    return initialSoloTrips.length > 0 ? initialSoloTrips[0].id : 'new';
  });

  // スタイル切り替え時、選択中のしおりが現在のスタイルに含まれない場合は自動でリセット
  useEffect(() => {
    if (selectedTripId !== 'new' && !filteredTargetTrips.some(t => t.id === selectedTripId)) {
      setSelectedTripId('new');
    }
  }, [copyMode, filteredTargetTrips, selectedTripId]);

  const [newTripTitle, setNewTripTitle] = useState(
    type === 'trip'
      ? `${sourceData.title || '新しい旅行'}（コピー）`
      : type === 'event'
      ? `${sourceData.title || 'お出かけ'}の旅`
      : '新しい旅行計画'
  );
  const [newStartDate, setNewStartDate] = useState(getTodayString());

  const buildNewTripMembers = () => {
    return [{ ...currentUser, color: PRESET_COLORS[0] }];
  };

  // 時間調整用のステート
  const [customEventTime, setCustomEventTime] = useState(
    type === 'event' ? (sourceData.time || '12:00') : '12:00'
  );
  const [customEventTimesMap, setCustomEventTimesMap] = useState(() => {
    const initialMap = {};
    const list = type === 'trip' ? (sourceData.events || []) : (type === 'day' ? (sourceData || []) : []);
    list.forEach((ev, idx) => {
      initialMap[ev.id || idx] = ev.time || '12:00';
    });
    return initialMap;
  });

  const targetTrip = myTrips.find(t => t.id === selectedTripId);

  const generateDateList = (start, end) => {
    const arr = [];
    let dt = new Date(start);
    const endDt = new Date(end || start);
    let safety = 0;
    while (dt <= endDt && safety < 30) {
      arr.push(new Date(dt).toISOString().split('T')[0]);
      dt.setDate(dt.getDate() + 1);
      safety++;
    }
    return arr.length > 0 ? arr : [getTodayString()];
  };

  const targetDates = useMemo(() => {
    if (selectedTripId === 'new') return [newStartDate];
    if (targetTrip) return generateDateList(targetTrip.startDate, targetTrip.endDate);
    return [getTodayString()];
  }, [selectedTripId, targetTrip, newStartDate]);

  const [selectedDate, setSelectedDate] = useState(targetDates[0] || getTodayString());

  useEffect(() => {
    if (targetDates.length > 0 && !targetDates.includes(selectedDate)) {
      setSelectedDate(targetDates[0]);
    }
  }, [targetDates]);

  const handleSave = () => {
    const isSoloMode = copyMode === 'solo';
    if (!isSoloMode && currentUser?.isGuest) {
      setShowGuestPrompt(true);
      return;
    }

    const parseSafeDate = (dateStr) => {
      const d = new Date(dateStr || getTodayString());
      return isNaN(d.getTime()) ? new Date(getTodayString()) : d;
    };

    if (type === 'trip') {
      if (selectedTripId === 'new') {
        const start = parseSafeDate(newStartDate);
        const origStart = parseSafeDate(sourceData.startDate || getTodayString());
        const origEnd = parseSafeDate(sourceData.endDate || sourceData.startDate || getTodayString());
        const diffDays = Math.max(0, Math.round((origEnd - origStart) / (1000 * 60 * 60 * 24)));
        const end = new Date(start);
        end.setDate(end.getDate() + diffDays);
        const endStr = end.toISOString().split('T')[0];

        const shiftedEvents = (sourceData.events || []).map((ev, idx) => {
          const evDate = parseSafeDate(ev.date || sourceData.startDate || getTodayString());
          const dayOffset = Math.max(0, Math.round((evDate - origStart) / (1000 * 60 * 60 * 24)));
          const newEvDate = new Date(start);
          newEvDate.setDate(newEvDate.getDate() + dayOffset);
          return {
            ...ev,
            id: generateId(),
            date: newEvDate.toISOString().split('T')[0],
            time: customEventTimesMap[ev.id || idx] || ev.time || '12:00',
            status: isSoloMode ? 'approved' : 'proposed',
            authorId: currentUser.id,
            photos: []
          };
        });

        const totalEventsCost = shiftedEvents.reduce((sum, e) => sum + (Number(e.cost) || 0), 0);

        const newTripObj = {
          id: generateTripCode(),
          title: newTripTitle.trim() || `${sourceData.title || '旅行計画'}（コピー）`,
          destination: sourceData.destination || '未設定',
          startDate: newStartDate,
          endDate: endStr,
          budget: totalEventsCost > 0 ? totalEventsCost : (Number(sourceData.budget) || 50000),
          members: buildNewTripMembers(),
          isSoloTrip: isSoloMode,
          events: shiftedEvents,
          photos: [],
          packingList: [],
          extraExpenses: [],
          souvenirList: []
        };

        if (!isSoloMode) {
          setCreatedGroupTrip(newTripObj);
          setStep(2);
          return;
        }
        onComplete(newTripObj, null);
      } else if (targetTrip) {
        const origStart = parseSafeDate(sourceData.startDate || getTodayString());
        const targetStart = parseSafeDate(targetTrip.startDate);
        const targetEnd = parseSafeDate(targetTrip.endDate);

        const mergedEvents = (sourceData.events || []).map((ev, idx) => {
          const evDate = parseSafeDate(ev.date || sourceData.startDate || getTodayString());
          const dayOffset = Math.max(0, Math.round((evDate - origStart) / (1000 * 60 * 60 * 24)));
          const mappedDate = new Date(targetStart);
          mappedDate.setDate(mappedDate.getDate() + dayOffset);
          const finalDate = mappedDate <= targetEnd ? mappedDate.toISOString().split('T')[0] : targetTrip.endDate;
          return {
            ...ev,
            id: generateId(),
            date: finalDate,
            time: customEventTimesMap[ev.id || idx] || ev.time || '12:00',
            status: targetTrip.isSoloTrip ? 'approved' : 'proposed',
            authorId: currentUser.id,
            photos: []
          };
        });

        onComplete(null, { ...targetTrip, events: [...(targetTrip.events || []), ...mergedEvents] });
      }
      return;
    }

    const rawEvents = type === 'event' ? [sourceData] : (Array.isArray(sourceData) ? sourceData : []);

    if (selectedTripId === 'new') {
      const newEvents = rawEvents.map((e, idx) => ({
        ...e,
        id: generateId(),
        date: newStartDate,
        time: type === 'event' ? customEventTime : (customEventTimesMap[e.id || idx] || e.time || '12:00'),
        status: isSoloMode ? 'approved' : 'proposed',
        authorId: currentUser.id
      }));
      const newTripObj = {
        id: generateTripCode(),
        title: newTripTitle.trim() || '新しい旅行計画',
        destination: rawEvents[0]?.location || '行き先未定',
        startDate: newStartDate,
        endDate: newStartDate,
        budget: 50000,
        members: buildNewTripMembers(),
        isSoloTrip: isSoloMode,
        events: newEvents,
        photos: []
      };
      if (!isSoloMode) {
        setCreatedGroupTrip(newTripObj);
        setStep(2);
        return;
      }
      onComplete(newTripObj, null);
    } else if (targetTrip) {
      const newEvents = rawEvents.map((e, idx) => ({
        ...e,
        id: generateId(),
        date: selectedDate,
        time: type === 'event' ? customEventTime : (customEventTimesMap[e.id || idx] || e.time || '12:00'),
        status: targetTrip.isSoloTrip ? 'approved' : 'proposed',
        authorId: currentUser.id
      }));
      onComplete(null, { ...targetTrip, events: [...(targetTrip.events || []), ...newEvents] });
    }
  };

  const multiEventsList = type === 'trip' ? (sourceData.events || []) : (type === 'day' ? (sourceData || []) : []);

  const handleCopyInviteCode = () => {
    if (!createdGroupTrip) return;
    copyToClipboard(
      createdGroupTrip.id,
      `招待コード「${createdGroupTrip.id}」をコピーしました！`
    );
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 3500);
  };

  const handleCopyInviteWithAppUrl = () => {
    if (!createdGroupTrip) return;
    const inviteText = `「${createdGroupTrip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${createdGroupTrip.id}\n\n▼ アプリをまだ持っていない方はこちら（インストールURL）\nhttps://tabitabi.app/dl`;
    copyToClipboard(
      inviteText,
      'アプリ紹介URL付きの招待文をコピーしました！'
    );
    setCopiedInviteMsg(true);
    setTimeout(() => setCopiedInviteMsg(false), 3500);
  };

  const handleShareCopiedTripLine = () => {
    if (!createdGroupTrip) return;
    const inviteText = `「${createdGroupTrip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${createdGroupTrip.id}\n\n▼ アプリはこちら\nhttps://tabitabi.app/dl`;
    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(inviteText)}`, '_blank', 'noopener,noreferrer');
  };

  const handleShareCopiedTripNative = async () => {
    if (!createdGroupTrip) return;
    const inviteText = `「${createdGroupTrip.title}」の旅行計画を一緒に作ろう！✈️\n\n▼ 招待コード\n${createdGroupTrip.id}\n\n▼ アプリはこちら\nhttps://tabitabi.app/dl`;
    if (navigator.share) {
      try {
        await navigator.share({ title: `${createdGroupTrip.title}の招待コード`, text: inviteText });
        return;
      } catch (e) {}
    }
    handleShareCopiedTripLine();
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-[200] flex justify-center items-end sm:items-center p-0 sm:p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full sm:max-w-md rounded-t-[32px] sm:rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-bottom-full sm:zoom-in-95 max-h-[88vh] flex flex-col pb-safe" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-4 shrink-0">
          <h3 className="font-bold text-lg text-stone-800 flex items-center gap-2">
            <Copy size={18} className="text-[#7A9D8C]" />
            {step === 2
              ? 'メンバーの招待・共有コード'
              : type === 'trip'
              ? 'しおりをコピーして使う'
              : type === 'day'
              ? '1日分の予定をコピー'
              : 'この予定をコピー'}
          </h3>
          <button onClick={onClose} className="p-1.5 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        {step === 2 && createdGroupTrip ? (
          <div className="space-y-4 text-center animate-in slide-in-from-right-4 py-2">
            <div className="bg-[#7A9D8C]/10 p-5 rounded-3xl border border-[#7A9D8C]/20 space-y-2.5">
              <p className="text-xs font-bold text-[#7A9D8C]">コピーしたしおりの共有・招待コード</p>
              <div className="flex items-center justify-between gap-2 bg-white py-2.5 px-3.5 rounded-2xl border border-stone-200/80 shadow-2xs">
                <span className="text-lg sm:text-xl font-mono font-extrabold tracking-widest text-stone-800 select-all flex-1 text-center pl-2">
                  {createdGroupTrip.id}
                </span>
                <button
                  type="button"
                  onClick={handleCopyInviteCode}
                  className={`shrink-0 px-3 py-2 rounded-xl text-xs font-extrabold flex items-center gap-1 transition-colors active:scale-95 ${
                    copiedCode
                      ? 'bg-[#7A9D8C] text-white'
                      : 'bg-[#7A9D8C]/15 hover:bg-[#7A9D8C]/25 text-[#557465]'
                  }`}
                >
                  {copiedCode ? <Check size={14} /> : <Copy size={14} />}
                  <span>{copiedCode ? '✓ コピー済み' : 'コピー'}</span>
                </button>
              </div>
              <button
                type="button"
                onClick={handleCopyInviteWithAppUrl}
                className={`w-full py-2.5 px-3 rounded-xl text-xs font-extrabold flex items-center justify-center gap-1.5 transition-all active:scale-95 border ${
                  copiedInviteMsg
                    ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                    : 'bg-white hover:bg-stone-50 text-[#557465] border-[#7A9D8C]/30 shadow-2xs'
                }`}
              >
                {copiedInviteMsg ? <Check size={14} /> : <Copy size={14} />}
                <span>{copiedInviteMsg ? '✓ 招待文をコピー済み！' : 'アプリ紹介リンク付きで招待文をコピー'}</span>
              </button>
              <div className="grid grid-cols-2 gap-2 pt-0.5">
                <button
                  type="button"
                  onClick={handleShareCopiedTripLine}
                  className="py-2.5 px-3 rounded-xl bg-[#06C755] hover:brightness-95 text-white font-extrabold text-xs flex items-center justify-center gap-1.5 shadow-2xs active:scale-95 transition-all"
                >
                  <MessageCircle size={14} /> LINEで送る
                </button>
                <button
                  type="button"
                  onClick={handleShareCopiedTripNative}
                  className="py-2.5 px-3 rounded-xl bg-stone-800 hover:bg-stone-900 text-white font-extrabold text-xs flex items-center justify-center gap-1.5 shadow-2xs active:scale-95 transition-all"
                >
                  <Share2 size={14} /> 他のアプリで共有
                </button>
              </div>
            </div>
            <p className="text-xs text-stone-500 leading-relaxed">
              友達やパートナーにこのコードを共有すると、<br />コピーしたしおりを一緒に編集できるようになります。<br />
              <span className="text-[11px] text-stone-400">（※しおり右上のメニューからいつでも再確認できます）</span>
            </p>
            <div className="pt-2">
              <button
                type="button"
                onClick={() => onComplete(createdGroupTrip, null)}
                className="w-full py-3.5 bg-[#7A9D8C] text-white font-bold rounded-2xl shadow-sm text-sm flex items-center justify-center gap-2 hover:bg-[#688a79] transition-colors"
              >
                コピーしたしおりを開く <ChevronRight size={16} />
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="flex-1 overflow-y-auto no-scrollbar space-y-4 pb-4">
              <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100">
                <p className="text-[10px] font-bold text-stone-400 mb-0.5">コピーする内容</p>
                <p className="text-xs font-bold text-stone-700 truncate">
                  {type === 'trip'
                    ? `${sourceData.title}（全${(sourceData.events || []).length}件の予定）`
                    : type === 'day'
                    ? `選択した日の予定（${(sourceData || []).length}件）`
                    : `${sourceData.title}`}
                </p>
              </div>

              {/* ★ 「1人旅 / 複数人（グループ）旅」選択UI（常時表示し、コピー先候補も連動して切り替わる） */}
              <div>
                <label className="block text-xs font-bold text-stone-500 mb-2 pl-1">
                  旅のスタイルを選択してください
                </label>
                <div className="grid grid-cols-2 gap-2.5">
                  <button
                    type="button"
                    onClick={() => {
                      setCopyMode('solo');
                      setShowGuestPrompt(false);
                    }}
                    className={`p-3.5 rounded-2xl border-2 text-left transition-all flex flex-col justify-between ${
                      copyMode === 'solo'
                        ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 shadow-2xs'
                        : 'border-stone-200 bg-white hover:bg-stone-50'
                    }`}
                  >
                    <div className="flex items-center justify-between w-full mb-1.5">
                      <span className="text-lg">👤</span>
                      <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${copyMode === 'solo' ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'}`}>
                        {copyMode === 'solo' && <Check size={10} strokeWidth={3} />}
                      </div>
                    </div>
                    <p className={`text-xs font-extrabold ${copyMode === 'solo' ? 'text-[#557465]' : 'text-stone-800'}`}>
                      1人旅としてコピー
                    </p>
                    <p className="text-[10px] text-stone-400 font-bold mt-0.5 leading-snug">
                      自分専用のしおり（承認なしで即確定）
                    </p>
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      if (currentUser?.isGuest) {
                        setShowGuestPrompt(true);
                        return;
                      }
                      setCopyMode('group');
                      setShowGuestPrompt(false);
                    }}
                    className={`p-3.5 rounded-2xl border-2 text-left transition-all flex flex-col justify-between ${
                      copyMode === 'group'
                        ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 shadow-2xs'
                        : 'border-stone-200 bg-white hover:bg-stone-50'
                    }`}
                  >
                    <div className="flex items-center justify-between w-full mb-1.5">
                      <span className="text-lg">👥</span>
                      <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${copyMode === 'group' ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'}`}>
                        {copyMode === 'group' && <Check size={10} strokeWidth={3} />}
                      </div>
                    </div>
                    <p className={`text-xs font-extrabold ${copyMode === 'group' ? 'text-[#557465]' : 'text-stone-800'}`}>
                      みんなの旅としてコピー
                    </p>
                    <p className="text-[10px] text-stone-400 font-bold mt-0.5 leading-snug">
                      複数人用（予定は提案中になり承認が必要）
                    </p>
                  </button>
                </div>

                {/* ゲスト利用時に「みんなの旅としてコピー」を選んだ場合の案内バナー */}
                {showGuestPrompt && currentUser?.isGuest && (
                  <div className="mt-2.5 p-3.5 bg-red-50 border border-red-200 rounded-2xl animate-in fade-in space-y-2">
                    <div className="flex items-start gap-2 text-red-600">
                      <AlertCircle size={16} className="shrink-0 mt-0.5" />
                      <p className="text-xs font-bold leading-relaxed">
                        複数人でのしおり作成・コピーにはアカウント登録（無料）が必要です。
                      </p>
                    </div>
                    {onOpenRegister && (
                      <button
                        type="button"
                        onClick={onOpenRegister}
                        className="w-full py-2 bg-red-500 hover:bg-red-600 text-white font-bold rounded-xl text-xs transition-colors shadow-2xs"
                      >
                        無料アカウント登録・ログインへ進む
                      </button>
                    )}
                  </div>
                )}
              </div>

              {selectedTripId === 'new' && (
                <div className="bg-stone-50 p-4 rounded-2xl border border-stone-200/80 space-y-3 animate-in fade-in">
                  <div>
                    <label className="text-[10px] font-bold text-stone-400 block mb-1">新しいしおりの名前</label>
                    <input
                      type="text"
                      value={newTripTitle}
                      onChange={e => setNewTripTitle(e.target.value)}
                      className="w-full p-2.5 bg-white border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-stone-400 block mb-1">日程（出発日・最終日）</label>
                    {(() => {
                      const parseSafe = (s) => {
                        const d = new Date(s || getTodayString());
                        return isNaN(d.getTime()) ? new Date(getTodayString()) : d;
                      };
                      const origStart = parseSafe(sourceData?.startDate || getTodayString());
                      const origEnd = parseSafe(sourceData?.endDate || sourceData?.startDate || getTodayString());
                      const diffDays = type === 'trip' ? Math.max(0, Math.round((origEnd - origStart) / 86400000)) : 0;
                      const calcEnd = new Date(parseSafe(newStartDate));
                      calcEnd.setDate(calcEnd.getDate() + diffDays);
                      const copyEndDateStr = calcEnd.toISOString().split('T')[0];

                      return (
                        <WheelDateRangePicker
                          startDate={newStartDate}
                          endDate={copyEndDateStr}
                          onChangeStart={(nextStart) => setNewStartDate(nextStart)}
                          onChangeEnd={(nextEnd) => {
                            if (nextEnd < newStartDate) setNewStartDate(nextEnd);
                          }}
                          compact
                        />
                      );
                    })()}
                  </div>
                </div>
              )}

              <div>
                <div className="flex items-center justify-between mb-2 pl-1">
                  <label className="block text-xs font-bold text-stone-500">
                    コピー先のしおり（{copyMode === 'solo' ? '👤 1人旅のみ' : '👥 参加中の共有しおりのみ'}）
                  </label>
                  <span className="text-[10px] font-bold text-stone-400">※過去の旅は非表示</span>
                </div>
                <div className="space-y-2">
                  <button
                    type="button"
                    onClick={() => setSelectedTripId('new')}
                    className={`w-full p-3.5 rounded-2xl border-2 border-dashed text-left transition-all flex items-center justify-between gap-2 ${
                      selectedTripId === 'new'
                        ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 text-[#557465]'
                        : 'border-stone-300 bg-stone-50/70 text-stone-600 hover:bg-stone-100'
                    }`}
                  >
                    <div className="flex items-center gap-2.5">
                      <div className={`w-7 h-7 rounded-full flex items-center justify-center ${selectedTripId === 'new' ? 'bg-[#7A9D8C] text-white' : 'bg-white text-stone-500 border border-stone-200'}`}>
                        <Plus size={15} />
                      </div>
                      <div>
                        <p className="text-xs font-bold">新しいしおりを作成してコピー</p>
                        <p className="text-[10px] text-stone-400 font-medium">
                          {copyMode === 'solo' ? '👤 1人旅のしおりとして新規作成' : '👥 みんなの旅（複数人用）として新規作成'}
                        </p>
                      </div>
                    </div>
                    <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${selectedTripId === 'new' ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'}`}>
                      {selectedTripId === 'new' && <Check size={12} strokeWidth={3} />}
                    </div>
                  </button>

                  {filteredTargetTrips.length === 0 ? (
                    <div className="p-3.5 rounded-2xl bg-stone-50 border border-stone-200/70 text-center text-[11px] font-bold text-stone-400">
                      {copyMode === 'solo'
                        ? '進行中・これからの「1人旅のしおり」はありません'
                        : '進行中・これからの「共有のしおり（みんなの旅）」はありません'}
                    </div>
                  ) : (
                    filteredTargetTrips.map(t => {
                      const isSelected = selectedTripId === t.id;
                      return (
                        <button
                          key={t.id}
                          type="button"
                          onClick={() => setSelectedTripId(t.id)}
                          className={`w-full p-3.5 rounded-2xl border text-left transition-all flex items-center justify-between gap-2 ${
                            isSelected
                              ? 'border-[#7A9D8C] bg-[#7A9D8C]/10 shadow-2xs'
                              : 'border-stone-200 bg-white hover:bg-stone-50'
                          }`}
                        >
                          <div className="min-w-0 flex-1">
                            <div className="flex items-center gap-1.5">
                              <p className={`text-xs font-bold truncate ${isSelected ? 'text-[#557465]' : 'text-stone-800'}`}>{t.title}</p>
                              <span className="text-[9px] font-bold px-2 py-0.5 rounded-full bg-stone-100 text-stone-500 shrink-0">
                                {t.isSoloTrip ? '👤 1人旅' : `👥 共有（${(t.members || []).length}人）`}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 text-[10px] text-stone-400 font-bold mt-0.5">
                              <span className="flex items-center gap-0.5"><MapPin size={10} />{t.destination || '未設定'}</span>
                              <span className="flex items-center gap-0.5"><Calendar size={10} />{t.startDate?.replace(/-/g, '/')}〜</span>
                            </div>
                          </div>
                          <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${isSelected ? 'border-[#7A9D8C] bg-[#7A9D8C] text-white' : 'border-stone-300'}`}>
                            {isSelected && <Check size={12} strokeWidth={3} />}
                          </div>
                        </button>
                      );
                    })
                  )}
                </div>
              </div>

              {selectedTripId !== 'new' && (
                <div>
                  <label className="block text-xs font-bold text-stone-500 mb-2 pl-1">追加する日程（何日目）を選択</label>
                  <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                    {targetDates.map((d, idx) => (
                      <button
                        key={d}
                        type="button"
                        onClick={() => setSelectedDate(d)}
                        className={`px-3.5 py-2 rounded-xl border text-xs font-bold whitespace-nowrap transition-all ${
                          selectedDate === d
                            ? 'bg-[#7A9D8C] text-white border-[#7A9D8C] shadow-2xs'
                            : 'bg-white text-stone-600 border-stone-200 hover:bg-stone-50'
                        }`}
                      >
                        {idx + 1}日目 ({d.slice(5).replace('-', '/')})
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div>
                <label className="block text-xs font-bold text-stone-500 mb-2 pl-1">
                  予定の時間を設定（変更可能）
                </label>
                {type === 'event' ? (
                  <div className="bg-stone-50 p-3.5 rounded-2xl border border-stone-200/80 flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2 text-xs font-bold text-stone-700">
                      <Clock size={15} className="text-[#7A9D8C]" />
                      <span>開始時間</span>
                    </div>
                    <input
                      type="time"
                      value={customEventTime}
                      onChange={e => setCustomEventTime(e.target.value)}
                      className="px-3 py-2 bg-white border border-stone-200 rounded-xl text-xs font-mono font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                    />
                  </div>
                ) : (
                  <div className="bg-stone-50 p-3 rounded-2xl border border-stone-200/80 space-y-2 max-h-44 overflow-y-auto no-scrollbar">
                    {multiEventsList.length === 0 ? (
                      <p className="text-[11px] text-stone-400 font-bold text-center py-2">コピー対象の予定がありません</p>
                    ) : (
                      multiEventsList.map((ev, idx) => {
                        const key = ev.id || idx;
                        return (
                          <div key={key} className="bg-white p-2.5 rounded-xl border border-stone-100 flex items-center justify-between gap-2">
                            <span className="text-xs font-bold text-stone-700 truncate flex-1">{ev.title}</span>
                            <input
                              type="time"
                              value={customEventTimesMap[key] || ev.time || '12:00'}
                              onChange={e => setCustomEventTimesMap(prev => ({ ...prev, [key]: e.target.value }))}
                              className="px-2 py-1 bg-stone-50 border border-stone-200 rounded-lg text-[11px] font-mono font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] shrink-0"
                            />
                          </div>
                        );
                      })
                    )}
                  </div>
                )}
              </div>
            </div>

            <div className="pt-3 border-t border-stone-100 flex gap-2 shrink-0">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs transition-colors"
              >
                キャンセル
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="flex-[2] py-3 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-bold rounded-2xl text-xs shadow-sm transition-colors flex items-center justify-center gap-1.5"
              >
                <Check size={15} /> コピーして保存する
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function Timeline({ trip, updateTrip, selectedDate, currentUser, isReadOnly, mainScrollRef, onCopyEvent, onCopyDay, onEnlargeImage, onOpenAiChat }) {
  const [showAddForm, setShowAddForm] = useState(false);
  const [insertIndex, setInsertIndex] = useState(null);
  const [insertDefaultTime, setInsertDefaultTime] = useState(null);
  const [insertRouteContext, setInsertRouteContext] = useState(null);
  // ★ 隣り合う予定間（どちらも移動でない場合）の「＋移動手段を追加」クイック選択ドロワー用ステート
  const [transportInsertState, setTransportInsertState] = useState(null);
  // { idx, prevEvent, nextEvent, startTime, endTime, selectedOptionId, customCost }
  const [showAiSuggestModal, setShowAiSuggestModal] = useState(false);
  const [aiInitialData, setAiInitialData] = useState(null);
  const [eventToDelete, setEventToDelete] = useState(null);
  const [nowTick, setNowTick] = useState(() => Date.now());
  const eventRefsMap = useRef({});
  // 同じ日を開いている間に30秒タイマーで勝手に再スクロールして画面がガタつくのを防ぐフラグ
  const lastAutoScrolledKeyRef = useRef('');

  // 30秒ごとに現在時刻を再計算してリアルタイムにポワンポワン位置を更新
  useEffect(() => {
    const interval = setInterval(() => setNowTick(Date.now()), 30000);
    return () => clearInterval(interval);
  }, []);

  const currentEvents = (trip.events || []).filter(e => e.date === selectedDate);
  currentEvents.sort((a, b) => (a.time || '').localeCompare(b.time || ''));

  const timeToMinutes = (t) => {
    if (!t || !t.includes(':')) return null;
    const [h, m] = t.split(':').map(Number);
    if (isNaN(h) || isNaN(m)) return null;
    return h * 60 + m;
  };

  // ★ 今日の日付と選択中の日付が一致している日のみ、現在時刻に一番近い予定＆進行度（Yahoo!乗換案内風）を算出する
  const isTodaySelected = selectedDate === getTodayString();
  const nowDateObj = new Date(nowTick);
  const currentNowMinutes = nowDateObj.getHours() * 60 + nowDateObj.getMinutes();
  const currentNowTimeStr = `${String(nowDateObj.getHours()).padStart(2, '0')}:${String(nowDateObj.getMinutes()).padStart(2, '0')}`;

  const closestEventId = useMemo(() => {
    if (currentEvents.length === 0) return null;
    let bestId = currentEvents[0].id;
    let minDiff = Infinity;
    currentEvents.forEach(ev => {
      const evMinutes = timeToMinutes(ev.time);
      if (evMinutes === null) return;
      const diff = Math.abs(evMinutes - currentNowMinutes);
      if (diff < minDiff) {
        minDiff = diff;
        bestId = ev.id;
      }
    });
    return bestId;
  }, [currentEvents, currentNowMinutes]);

  // ★ 今日の日付と一致しているときのみ、しおりを開いた初回1回だけ現在時刻に一番近い予定まで穏やかにスクロールする
  // （一番下の予定でもスクロールしすぎて下端がガタつかないよう maxScrollTop で安全にクランプ）
  useEffect(() => {
    if (!isTodaySelected || !closestEventId) return;
    const scrollKey = `${trip.id}_${selectedDate}`;
    if (lastAutoScrolledKeyRef.current === scrollKey) return;

    const timer = setTimeout(() => {
      const container = mainScrollRef?.current;
      const targetEl = eventRefsMap.current[closestEventId];
      if (!container || !targetEl) return;

      lastAutoScrolledKeyRef.current = scrollKey;

      // 先頭の予定（1件目）が一番近い場合は無理にスクロールせず最上部のまま表示
      if (currentEvents[0]?.id === closestEventId) {
        container.scrollTo({ top: 0, behavior: 'auto' });
        return;
      }

      const containerRect = container.getBoundingClientRect();
      const targetRect = targetEl.getBoundingClientRect();
      const relativeTop = targetRect.top - containerRect.top + container.scrollTop;

      // 画面の上から約28%の位置に合わせるが、一番下の予定のときに下端を超えないよう maxScroll で確実に制限する
      const maxScroll = Math.max(0, container.scrollHeight - container.clientHeight - 16);
      const desiredScroll = Math.max(0, Math.min(maxScroll, Math.round(relativeTop - container.clientHeight * 0.28)));

      if (Math.abs(container.scrollTop - desiredScroll) > 24) {
        container.scrollTo({ top: desiredScroll, behavior: 'smooth' });
      }
    }, 220);

    return () => clearTimeout(timer);
  }, [trip.id, selectedDate, isTodaySelected, closestEventId]);

  // 2つの予定の時間から中間の時間を計算する関数（例: 10:30 と 12:00 → 11:15）
  const getMidpointTime = (timeA, timeB) => {
    const toMinutes = (t) => {
      if (!t || !t.includes(':')) return 12 * 60;
      const [h, m] = t.split(':').map(Number);
      return (isNaN(h) ? 12 : h) * 60 + (isNaN(m) ? 0 : m);
    };
    const minA = toMinutes(timeA);
    const minB = timeB ? toMinutes(timeB) : minA + 60;
    const mid = minB > minA ? Math.round((minA + minB) / 2) : Math.min(23 * 60 + 55, minA + 30);
    const roundedMid = Math.round(mid / 5) * 5;
    const hh = String(Math.floor(roundedMid / 60) % 24).padStart(2, '0');
    const mm = String(roundedMid % 60).padStart(2, '0');
    return `${hh}:${mm}`;
  };

  const handleOpenInsertBetween = (idx, prevEvent, nextEvent) => {
    const midTime = getMidpointTime(prevEvent?.time, nextEvent?.time);
    setTransportInsertState(null);
    setInsertIndex(idx);
    setInsertDefaultTime(midTime);
    setInsertRouteContext({
      time: midTime,
      prevTitle: prevEvent?.title || '',
      prevLocation: prevEvent?.location || prevEvent?.title || '',
      prevTime: prevEvent?.time || '',
      nextTitle: nextEvent?.title || '',
      nextLocation: nextEvent?.location || nextEvent?.title || '',
      nextTime: nextEvent?.time || ''
    });
    setAiInitialData(null);
    setShowAddForm(false);
  };

  // ★ 前後の予定地から最適な移動手段を選択して挿入するハンドラー
  const handleOpenTransportInsertBetween = (idx, prevEvent, nextEvent) => {
    const startT = prevEvent?.endTime || getMidpointTime(prevEvent?.time, nextEvent?.time);
    const endT = nextEvent?.time && nextEvent.time > startT ? nextEvent.time : getMidpointTime(startT, nextEvent?.time);
    const candidates = buildOptimalRouteCandidates(prevEvent, nextEvent, trip.localTransportMethod || 'public_transit');
    const defaultOpt =
      candidates.find(c => c.badge.includes('おすすめ')) || candidates[0];
    setInsertIndex(null);
    setShowAddForm(false);
    setTransportInsertState({
      idx,
      prevEvent,
      nextEvent,
      startTime: startT,
      endTime: endT,
      selectedOptionId: defaultOpt.id,
      customCost: String(defaultOpt.cost)
    });
  };

  // 写真削除の確認モーダル用ステート
  const [photoToDelete, setPhotoToDelete] = useState(null); // { eventId, photo }

  // 投稿した本人かどうか判定するヘルパー
  const isMyPhoto = (photo) => {
    if (!photo || !currentUser) return false;
    if (photo.authorId) return photo.authorId === currentUser.id;
    if (photo.authorName) {
      return (
        photo.authorName === currentUser.name ||
        currentUser.name.startsWith(photo.authorName) ||
        photo.authorName.startsWith(currentUser.name)
      );
    }
    return true;
  };

  const handleAddEventPhoto = (eventId, photoUrl) => {
    const newPhotoObj = {
      id: generateId(),
      url: photoUrl,
      createdAt: getTodayString(),
      eventId,
      authorId: currentUser.id,
      authorName: currentUser.name,
      isPublic: true
    };
    const updatedEvents = (trip.events || []).map(ev => {
      if (ev.id === eventId) {
        return { ...ev, photos: [...(ev.photos || []), newPhotoObj] };
      }
      return ev;
    });
    const updatedTripPhotos = [newPhotoObj, ...(trip.photos || [])];
    updateTrip({ ...trip, events: updatedEvents, photos: updatedTripPhotos });
    customAlert('予定に思い出の写真を追加しました！');
  };

  const handleToggleEventPhotoPublic = (eventId, photoId) => {
    const updatedEvents = (trip.events || []).map(ev => {
      if (ev.id !== eventId) return ev;
      return {
        ...ev,
        photos: (ev.photos || []).map(p =>
          p.id === photoId ? { ...p, isPublic: p.isPublic === false ? true : false } : p
        )
      };
    });
    updateTrip({ ...trip, events: updatedEvents });
  };

  const handleDeleteEventPhoto = (eventId, photoId) => {
    const updatedEvents = (trip.events || []).map(ev => {
      if (ev.id !== eventId) return ev;
      return {
        ...ev,
        photos: (ev.photos || []).filter(p => p.id !== photoId)
      };
    });
    const updatedTripPhotos = (trip.photos || []).filter(p => p.id !== photoId);
    updateTrip({ ...trip, events: updatedEvents, photos: updatedTripPhotos });
    customAlert('思い出写真を削除しました');
  };

  return (
    <div className="p-4 sm:p-5 pb-28">
      {isReadOnly && currentEvents.length > 0 && (
        <div className="mb-4 flex justify-end">
          <button onClick={() => onCopyDay(currentEvents)} className="px-3 py-1.5 bg-[#7A9D8C]/10 text-[#7A9D8C] rounded-full text-xs font-bold flex items-center gap-1 hover:bg-[#7A9D8C]/20 transition-colors">
            <Copy size={12} /> この日の予定をコピー
          </button>
        </div>
      )}

      <div className="relative pt-1">
        {/* 左側の時間軸の縦線（時刻のすぐ右を貫くライン） */}
        {(currentEvents.length > 0 || showAddForm || insertIndex !== null) && (
          <div className="absolute left-[47px] top-3 bottom-3 w-[2px] bg-stone-200/90 rounded-full pointer-events-none" />
        )}

        <div className="space-y-1.5">
          {currentEvents.length === 0 && !showAddForm && insertIndex === null ? (
            <div className="text-stone-400 text-xs font-bold py-12 flex flex-col items-center justify-center gap-1.5 bg-white/70 rounded-3xl border border-dashed border-stone-200">
              <Compass size={24} className="opacity-40 mb-0.5 text-[#7A9D8C]" />
              <span>この日の予定はまだありません。</span>
            </div>
          ) : (
            currentEvents.map((event, idx) => {
              const nextEvent = currentEvents[idx + 1];
              const suggestedMidTime = nextEvent ? getMidpointTime(event.time, nextEvent.time) : null;
              const isClosestNow = event.id === closestEventId;
              const canInsertAfter = !isReadOnly && idx < currentEvents.length - 1;
              // ★ 隣り合う予定（この予定 と 次の予定）のどちらも「移動 (transport)」カードでなければ移動手段追加ボタンを表示
              const canInsertTransportBetween =
                canInsertAfter && event.type !== 'transport' && nextEvent?.type !== 'transport';

              // Yahoo!乗換案内風：現在時刻がこの予定と次の予定の間の区間に位置しているか判定（0.0〜1.0の進行度）
              const evMin = timeToMinutes(event.time);
              const nextMin = nextEvent ? timeToMinutes(nextEvent.time) : null;
              const isPassedEvent = evMin !== null && currentNowMinutes > evMin;
              const isBetweenThisAndNext =
                evMin !== null &&
                nextMin !== null &&
                nextMin > evMin &&
                currentNowMinutes > evMin &&
                currentNowMinutes < nextMin;
              const betweenProgress = isBetweenThisAndNext
                ? Math.min(0.86, Math.max(0.22, (currentNowMinutes - evMin) / (nextMin - evMin)))
                : null;

              // ★ 予定の点（ピコンピコン）とは別に、現在時刻のタイムライン位置に置く丸枠なしキャリーケース（🧳）の位置判定
              const firstMin = timeToMinutes(currentEvents[0]?.time);
              const lastMin = timeToMinutes(currentEvents[currentEvents.length - 1]?.time);
              const showSuitcaseAtTop =
                idx === 0 && firstMin !== null && currentNowMinutes <= firstMin;
              const showSuitcaseOnCardTime =
                evMin !== null && currentNowMinutes === evMin && idx > 0;
              const showSuitcaseAtBottom =
                idx === currentEvents.length - 1 &&
                lastMin !== null &&
                currentNowMinutes > lastMin;

              const suitcasePositionProgress = showSuitcaseAtTop
                ? 0.02
                : showSuitcaseOnCardTime
                ? 0.35
                : betweenProgress !== null
                ? betweenProgress
                : showSuitcaseAtBottom
                ? 0.88
                : null;

              const prevEvent = idx > 0 ? currentEvents[idx - 1] : null;

              return (
                <React.Fragment key={event.id}>
                  <div
                    ref={el => {
                      if (el) eventRefsMap.current[event.id] = el;
                    }}
                  >
                    <EventCard
                      event={event}
                      prevEvent={prevEvent}
                      nextEvent={nextEvent}
                      trip={trip}
                      isReadOnly={isReadOnly}
                      currentUser={currentUser}
                      isClosestNow={isClosestNow}
                      isPassedEvent={isPassedEvent}
                      betweenNowProgress={betweenProgress}
                      suitcasePositionProgress={suitcasePositionProgress}
                      currentNowTimeStr={currentNowTimeStr}
                      insertButtonSlot={
                        canInsertAfter && insertIndex !== idx && transportInsertState?.idx !== idx ? (
                          <div className="flex flex-col items-start gap-1 select-none">
                            {/* ★ 隣り合う予定がどちらも「移動」でない場合、左のタイムライン上の「＋」ボタンの真上に「＋移動方法を追加」ボタンを配置 */}
                            {canInsertTransportBetween && (
                              <button
                                type="button"
                                onClick={() => handleOpenTransportInsertBetween(idx, event, nextEvent)}
                                className="px-2 py-0.5 rounded-full bg-sky-50 hover:bg-sky-600 text-sky-700 hover:text-white border border-sky-300/90 text-[9px] font-extrabold flex items-center gap-0.5 transition-all whitespace-nowrap shadow-xs active:scale-95 cursor-pointer z-20"
                                title="前後の目的地から最適な移動方法を選択して追加"
                              >
                                <Car size={9} className="shrink-0" />
                                <span>＋移動方法を追加</span>
                              </button>
                            )}

                            <button
                              type="button"
                              onClick={() => handleOpenInsertBetween(idx, event, nextEvent)}
                              className="group/ins relative flex items-center focus:outline-none cursor-pointer"
                              title={`${suggestedMidTime ? `${suggestedMidTime}頃に` : ''}この間に予定を追加・AI提案`}
                            >
                              {/* 左のピル型バッジ（時刻＋追加アイコン） */}
                              <div className="flex items-center gap-1 pl-1.5 pr-1 py-0.5 rounded-full bg-white group-hover/ins:bg-[#7A9D8C] text-[#557465] group-hover/ins:text-white border border-[#7A9D8C]/55 group-hover/ins:border-[#7A9D8C] shadow-xs transition-all active:scale-95 z-10">
                                <span className="text-[9px] font-mono font-extrabold tracking-tighter leading-none">
                                  {suggestedMidTime || ''}
                                </span>
                                <span className="w-3.5 h-3.5 rounded-full bg-[#7A9D8C]/15 group-hover/ins:bg-white/25 flex items-center justify-center">
                                  <Plus size={10} strokeWidth={3} className="text-[#7A9D8C] group-hover/ins:text-white" />
                                </span>
                              </div>

                              {/* 右の予定カードと予定カードの「ちょうど間」へスッと伸びる点線コネクタ＆追加ラベル */}
                              <div className="flex items-center pointer-events-none">
                                <div className="w-2.5 border-t-2 border-dashed border-[#7A9D8C]/55 group-hover/ins:border-[#7A9D8C] transition-colors" />
                                <span className="px-2 py-0.5 rounded-full bg-[#F4F7F5] group-hover/ins:bg-[#7A9D8C] text-[9px] font-extrabold text-[#557465] group-hover/ins:text-white border border-[#7A9D8C]/35 transition-all whitespace-nowrap shadow-2xs">
                                  ＋ここに予定を追加
                                </span>
                              </div>
                            </button>
                          </div>
                        ) : null
                      }
                      onApprove={() => updateTrip({ ...trip, events: (trip.events || []).map(e => e.id === event.id ? { ...e, status: 'approved' } : e) })}
                      onUpdateEvent={(updatedFields) => updateTrip({ ...trip, events: (trip.events || []).map(e => e.id === event.id ? { ...e, ...updatedFields } : e) })}
                      onUpdateMemo={(newMemo) => updateTrip({ ...trip, events: (trip.events || []).map(e => e.id === event.id ? { ...e, memo: newMemo } : e) })}
                      onDelete={() => setEventToDelete(event)}
                      onCopy={() => onCopyEvent(event)}
                      onAddPhoto={(url) => handleAddEventPhoto(event.id, url)}
                      onTogglePhotoPublic={(photoId) => handleToggleEventPhotoPublic(event.id, photoId)}
                      onRequestDeletePhoto={(photo) => {
                        if (!isMyPhoto(photo)) {
                          customAlert('他のメンバーが投稿した写真は削除できません');
                          return;
                        }
                        setPhotoToDelete({ eventId: event.id, photo });
                      }}
                      canDeletePhoto={isMyPhoto}
                      onEnlargeImage={onEnlargeImage}
                    />
                  </div>

                  {/* 予定間の「＋」ボタンを押した時だけ展開されるインライン追加フォーム（スマホでは横幅いっぱいに広げて入力しやすく表示） */}
                  {canInsertAfter && insertIndex === idx && (
                    <div className="pl-0 sm:pl-[56px] py-1.5 relative z-20 animate-in fade-in slide-in-from-top-2">
                      <div className="hidden sm:block absolute left-[43px] top-5 w-2.5 h-2.5 rounded-full bg-[#7A9D8C] ring-4 ring-[#F4F7F5]" />
                      <InlineEventForm
                        onSave={(newEv) => {
                          updateTrip({ ...trip, events: [...(trip.events || []), newEv] });
                          setInsertIndex(null);
                          setInsertDefaultTime(null);
                          setInsertRouteContext(null);
                          setAiInitialData(null);
                        }}
                        onCancel={() => {
                          setInsertIndex(null);
                          setInsertDefaultTime(null);
                          setInsertRouteContext(null);
                          setAiInitialData(null);
                        }}
                        date={selectedDate}
                        trip={trip}
                        currentUser={currentUser}
                        initialData={aiInitialData || { time: insertDefaultTime }}
                        routeContext={insertRouteContext}
                        onOpenAiSuggest={() => setShowAiSuggestModal(true)}
                        onOpenAiChat={() => onOpenAiChat && onOpenAiChat()}
                      />
                    </div>
                  )}

                  {/* ★ 左のタイムライン上の「＋」ボタンの真上に「＋ここに移動方法を追加」とワンタップ即挿入チップを配置 */}
                  {canInsertAfter && insertIndex !== idx && transportInsertState?.idx !== idx && (
                    <div className="relative pl-[2px] py-1 z-20 flex flex-col items-start gap-1 select-none">
                      {canInsertTransportBetween && (() => {
                        const quickRoutes = buildOptimalRouteCandidates(
                          event,
                          nextEvent,
                          trip.localTransportMethod || 'public_transit'
                        );
                        const quickStartT = event?.endTime || getMidpointTime(event?.time, nextEvent?.time);
                        const quickEndT =
                          nextEvent?.time && nextEvent.time > quickStartT
                            ? nextEvent.time
                            : getMidpointTime(quickStartT, nextEvent?.time);
                        const fromSpotObj = normalizeConcreteEventSpot(event, trip.destination);
                        const toSpotObj = normalizeConcreteEventSpot(nextEvent, trip.destination);
                        const fromClean = (fromSpotObj.location || event.title || '出発地').replace(/（.*?）/g, '');
                        const toClean = (toSpotObj.location || nextEvent.title || '目的地').replace(/（.*?）/g, '');

                        const handleQuickOneTapInsert = (cand) => {
                          const newTransportEv = {
                            id: generateId(),
                            date: selectedDate,
                            time: quickStartT || '12:00',
                            endTime: quickEndT || '',
                            title: `${fromClean}から${toClean}へ${cand.methodName.split('・')[0]}で移動`,
                            type: 'transport',
                            departureOrigin: fromClean,
                            transportMethod: cand.transportMethod,
                            location: toClean,
                            mapPinQuery: toSpotObj.mapPinQuery || toClean,
                            cost: Number(cand.cost) || 0,
                            memo: cand.memo,
                            status: trip.isSoloTrip ? 'approved' : 'proposed',
                            authorId: currentUser.id,
                            photos: []
                          };
                          updateTrip({ ...trip, events: [...(trip.events || []), newTransportEv] });
                          customAlert(`🚗「${fromClean} ➔ ${toClean}（${cand.icon}${cand.methodName.split('・')[0]}）」を追加しました！`);
                        };

                        return (
                          <div className="flex items-center gap-1 flex-wrap">
                            {/* 左のタイムライン軸上の「＋」ピルの真上に揃えて配置される「＋ここに移動方法を追加」ボタン */}
                            <button
                              type="button"
                              onClick={() => handleOpenTransportInsertBetween(idx, event, nextEvent)}
                              className="group/tr relative flex items-center focus:outline-none cursor-pointer"
                              title="前後の目的地から最適な移動方法を選択して追加"
                            >
                              <div className="flex items-center gap-1 pl-1.5 pr-1 py-0.5 rounded-full bg-sky-50 group-hover/tr:bg-sky-600 text-sky-700 group-hover/tr:text-white border border-sky-300/90 group-hover/tr:border-sky-600 shadow-xs transition-all active:scale-95 z-10">
                                <span className="text-[9px] font-mono font-extrabold tracking-tighter leading-none">
                                  {quickStartT || suggestedMidTime || ''}
                                </span>
                                <span className="w-3.5 h-3.5 rounded-full bg-sky-200/70 group-hover/tr:bg-white/25 flex items-center justify-center">
                                  <Car size={9} strokeWidth={2.8} className="text-sky-700 group-hover/tr:text-white" />
                                </span>
                              </div>
                              <div className="flex items-center pointer-events-none">
                                <div className="w-2.5 border-t-2 border-dashed border-sky-300 group-hover/tr:border-sky-600 transition-colors" />
                                <span className="px-2 py-0.5 rounded-full bg-sky-50 group-hover/tr:bg-sky-600 text-[9px] font-extrabold text-sky-800 group-hover/tr:text-white border border-sky-300/80 transition-all whitespace-nowrap shadow-2xs">
                                  ＋ここに移動方法を追加
                                </span>
                              </div>
                            </button>

                            {/* 1タップで即座に移動カードを挿入できるクイックチップ（電車・車・徒歩） */}
                            <div className="flex items-center gap-1 pl-0.5">
                              {quickRoutes.slice(0, 3).map((cand) => (
                                <button
                                  key={cand.id}
                                  type="button"
                                  onClick={() => handleQuickOneTapInsert(cand)}
                                  className="px-1.5 py-0.5 rounded-full bg-white hover:bg-sky-600 text-stone-600 hover:text-white border border-stone-200/90 hover:border-sky-600 text-[9px] font-extrabold flex items-center gap-0.5 shadow-2xs transition-all active:scale-95 cursor-pointer"
                                  title={`1タップで「${cand.methodName}（目安¥${cand.cost.toLocaleString()}）」を即追加`}
                                >
                                  <span>{cand.icon}</span>
                                  <span>{cand.methodName.split('・')[0]}</span>
                                  <span className="text-[8px] opacity-75">
                                    {cand.cost > 0 ? `¥${cand.cost}` : '¥0'}
                                  </span>
                                </button>
                              ))}
                            </div>
                          </div>
                        );
                      })()}

                      {/* その真下に並ぶ「＋ここに予定を追加」ボタン */}
                      <button
                        type="button"
                        onClick={() => handleOpenInsertBetween(idx, event, nextEvent)}
                        className="group/ins relative flex items-center focus:outline-none cursor-pointer"
                        title={`${suggestedMidTime ? `${suggestedMidTime}頃に` : ''}この間に予定を追加・AI提案`}
                      >
                        <div className="flex items-center gap-1 pl-1.5 pr-1 py-0.5 rounded-full bg-white group-hover/ins:bg-[#7A9D8C] text-[#557465] group-hover/ins:text-white border border-[#7A9D8C]/55 group-hover/ins:border-[#7A9D8C] shadow-xs transition-all active:scale-95 z-10">
                          <span className="text-[9px] font-mono font-extrabold tracking-tighter leading-none">
                            {suggestedMidTime || ''}
                          </span>
                          <span className="w-3.5 h-3.5 rounded-full bg-[#7A9D8C]/15 group-hover/ins:bg-white/25 flex items-center justify-center">
                            <Plus size={10} strokeWidth={3} className="text-[#7A9D8C] group-hover/ins:text-white" />
                          </span>
                        </div>
                        <div className="flex items-center pointer-events-none">
                          <div className="w-2.5 border-t-2 border-dashed border-[#7A9D8C]/55 group-hover/ins:border-[#7A9D8C] transition-colors" />
                          <span className="px-2 py-0.5 rounded-full bg-[#F4F7F5] group-hover/ins:bg-[#7A9D8C] text-[9px] font-extrabold text-[#557465] group-hover/ins:text-white border border-[#7A9D8C]/35 transition-all whitespace-nowrap shadow-2xs">
                            ＋ここに予定を追加
                          </span>
                        </div>
                      </button>
                    </div>
                  )}

                  {/* ★「＋ここに移動方法を追加」ボタンを押した時に前後の目的地から最適な交通手段＆おおよその金額候補を選べるインラインパネル */}
                  {canInsertTransportBetween && transportInsertState?.idx === idx && (() => {
                    const routeCandidates = buildOptimalRouteCandidates(
                      event,
                      nextEvent,
                      trip.localTransportMethod || 'public_transit'
                    );
                    const selectedRoute =
                      routeCandidates.find(c => c.id === transportInsertState.selectedOptionId) ||
                      routeCandidates[0];
                    const fromSpot = normalizeConcreteEventSpot(event, trip.destination);
                    const toSpot = normalizeConcreteEventSpot(nextEvent, trip.destination);
                    const fromName = (fromSpot.location || event.title || '出発地').replace(/（.*?）/g, '');
                    const toName = (toSpot.location || nextEvent.title || '目的地').replace(/（.*?）/g, '');

                    return (
                      <div className="pl-0 sm:pl-[56px] py-1.5 relative z-20 animate-in fade-in slide-in-from-top-2">
                        <div className="bg-white p-3.5 rounded-2xl shadow-md border-2 border-sky-400 space-y-2.5">
                          <div className="flex items-center justify-between gap-2">
                            <span className="text-xs font-extrabold text-sky-900 flex items-center gap-1.5">
                              <Car size={14} className="text-sky-600" />
                              前後の目的地から最適な移動手段を選択
                            </span>
                            <button
                              type="button"
                              onClick={() => setTransportInsertState(null)}
                              className="px-2 py-0.5 rounded-full bg-stone-100 hover:bg-rose-50 text-stone-500 hover:text-rose-600 text-[10px] font-extrabold flex items-center gap-0.5"
                            >
                              <X size={12} /> 閉じる
                            </button>
                          </div>

                          {/* 前後のルート表示バー */}
                          <div className="px-3 py-2 bg-sky-50 border border-sky-200/80 rounded-xl flex items-center justify-between gap-2 text-[11px] font-extrabold text-sky-950">
                            <div className="flex items-center gap-1.5 min-w-0 truncate">
                              <span className="truncate">📍 {fromName}</span>
                              <span className="text-sky-500 shrink-0">→</span>
                              <span className="truncate">🏁 {toName}</span>
                            </div>
                            <a
                              href={`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(fromName)}&destination=${encodeURIComponent(toName)}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="shrink-0 px-2 py-0.5 rounded-lg bg-white border border-sky-200 text-sky-700 text-[10px] font-extrabold flex items-center gap-0.5 hover:bg-sky-100"
                            >
                              <ExternalLink size={10} /> 経路確認
                            </a>
                          </div>

                          {/* 交通手段の候補カード一覧 */}
                          <div className="grid grid-cols-2 gap-1.5">
                            {routeCandidates.map(cand => {
                              const isSelected = selectedRoute.id === cand.id;
                              return (
                                <button
                                  key={cand.id}
                                  type="button"
                                  onClick={() =>
                                    setTransportInsertState(prev => ({
                                      ...prev,
                                      selectedOptionId: cand.id,
                                      customCost: String(cand.cost)
                                    }))
                                  }
                                  className={`p-2.5 rounded-xl border text-left transition-all cursor-pointer active:scale-95 ${
                                    isSelected
                                      ? 'border-sky-500 bg-sky-50/90 ring-2 ring-sky-200 shadow-2xs'
                                      : 'border-stone-200 bg-white hover:bg-stone-50'
                                  }`}
                                >
                                  <div className="flex items-center justify-between gap-1 mb-0.5">
                                    <span className="text-[9px] font-extrabold px-1.5 py-0.2 rounded-full bg-sky-100 text-sky-800">
                                      {cand.badge}
                                    </span>
                                    <span className="text-[10px] font-mono font-bold text-stone-500">
                                      約{cand.durationMins}分
                                    </span>
                                  </div>
                                  <p className="text-xs font-extrabold text-stone-800 flex items-center gap-1 mt-0.5">
                                    <span>{cand.icon}</span>
                                    <span className="truncate">{cand.methodName}</span>
                                  </p>
                                  <p className="text-[10px] font-bold text-sky-800 mt-0.5">
                                    目安: {cand.cost === 0 ? '¥0（無料）' : `約¥${cand.cost.toLocaleString()}/人`}
                                  </p>
                                </button>
                              );
                            })}
                          </div>

                          {/* 時間＆おおよその交通費（予算候補）ワンタップ選択 */}
                          <div className="p-2.5 bg-stone-50 rounded-xl border border-stone-200/80 space-y-2">
                            <div className="grid grid-cols-3 gap-2">
                              <div>
                                <label className="text-[10px] font-extrabold text-stone-500 block mb-0.5">出発時間</label>
                                <input
                                  type="time"
                                  value={transportInsertState.startTime}
                                  onChange={e =>
                                    setTransportInsertState(prev => ({ ...prev, startTime: e.target.value }))
                                  }
                                  className="w-full h-8 px-2 bg-white border border-stone-200 rounded-lg text-xs font-mono font-extrabold"
                                />
                              </div>
                              <div>
                                <label className="text-[10px] font-extrabold text-stone-500 block mb-0.5">到着時間</label>
                                <input
                                  type="time"
                                  value={transportInsertState.endTime}
                                  onChange={e =>
                                    setTransportInsertState(prev => ({ ...prev, endTime: e.target.value }))
                                  }
                                  className="w-full h-8 px-2 bg-white border border-stone-200 rounded-lg text-xs font-mono font-extrabold"
                                />
                              </div>
                              <div>
                                <label className="text-[10px] font-extrabold text-stone-500 block mb-0.5">1人交通費(円)</label>
                                <input
                                  type="number"
                                  inputMode="numeric"
                                  value={transportInsertState.customCost}
                                  onChange={e =>
                                    setTransportInsertState(prev => ({ ...prev, customCost: e.target.value }))
                                  }
                                  className="w-full h-8 px-2 bg-white border border-stone-200 rounded-lg text-xs font-mono font-extrabold text-sky-900"
                                />
                              </div>
                            </div>

                            <div className="flex items-center justify-between gap-1.5 flex-wrap pt-0.5">
                              <span className="text-[10px] font-extrabold text-stone-500">
                                💡 おおよその金額候補（タップで反映）:
                              </span>
                              <div className="flex items-center gap-1 flex-wrap">
                                {selectedRoute.costOptions.map(amt => (
                                  <button
                                    key={amt}
                                    type="button"
                                    onClick={() =>
                                      setTransportInsertState(prev => ({ ...prev, customCost: String(amt) }))
                                    }
                                    className={`px-2 py-0.5 rounded-lg text-[10px] font-extrabold border transition-all cursor-pointer ${
                                      Number(transportInsertState.customCost) === amt
                                        ? 'bg-sky-600 text-white border-sky-600'
                                        : 'bg-white text-stone-700 border-stone-200 hover:bg-sky-50'
                                    }`}
                                  >
                                    ¥{amt.toLocaleString()}
                                  </button>
                                ))}
                              </div>
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => {
                                setAiInitialData({
                                  time: transportInsertState.startTime,
                                  endTime: transportInsertState.endTime,
                                  type: 'transport',
                                  departureOrigin: fromName,
                                  transportMethod: selectedRoute.transportMethod,
                                  location: toName,
                                  mapPinQuery: toName,
                                  title: selectedRoute.title,
                                  cost: Number(transportInsertState.customCost) || 0,
                                  memo: selectedRoute.memo
                                });
                                setTransportInsertState(null);
                                setInsertIndex(idx);
                              }}
                              className="px-3 py-2 bg-stone-100 hover:bg-stone-200 text-stone-700 rounded-xl text-[11px] font-extrabold transition-colors"
                            >
                              詳細編集して追加
                            </button>
                            <button
                              type="button"
                              onClick={() => {
                                const newTransportEv = {
                                  id: generateId(),
                                  date: selectedDate,
                                  time: transportInsertState.startTime || '12:00',
                                  endTime: transportInsertState.endTime || '',
                                  title: selectedRoute.title,
                                  type: 'transport',
                                  departureOrigin: fromName,
                                  transportMethod: selectedRoute.transportMethod,
                                  location: toName,
                                  mapPinQuery: toName,
                                  cost: Number(transportInsertState.customCost) || 0,
                                  memo: selectedRoute.memo,
                                  status: trip.isSoloTrip ? 'approved' : 'proposed',
                                  authorId: currentUser.id,
                                  photos: []
                                };
                                updateTrip({ ...trip, events: [...(trip.events || []), newTransportEv] });
                                setTransportInsertState(null);
                                customAlert(`🚗「${selectedRoute.title}」を追加しました！`);
                              }}
                              className="flex-1 py-2 bg-sky-600 hover:bg-sky-700 text-white rounded-xl text-xs font-extrabold shadow-xs flex items-center justify-center gap-1 transition-all active:scale-95 cursor-pointer"
                            >
                              <Check size={14} /> この移動手段をしおりに追加
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })()}
                </React.Fragment>
              );
            })
          )}
          {showAddForm && !isReadOnly && (
            <div className="pl-0 sm:pl-[56px] relative z-20 animate-in fade-in slide-in-from-top-2">
              <div className="hidden sm:block absolute left-[43px] top-5 w-2.5 h-2.5 rounded-full bg-[#7A9D8C] ring-4 ring-[#F4F7F5]" />
              <InlineEventForm
                onSave={(e) => {
                  updateTrip({ ...trip, events: [...(trip.events || []), e] });
                  setShowAddForm(false);
                  setAiInitialData(null);
                  setInsertRouteContext(null);
                }}
                onCancel={() => {
                  setShowAddForm(false);
                  setAiInitialData(null);
                  setInsertRouteContext(null);
                }}
                date={selectedDate}
                trip={trip}
                currentUser={currentUser}
                initialData={aiInitialData}
                routeContext={insertRouteContext}
                onOpenAiSuggest={() => setShowAiSuggestModal(true)}
                onOpenAiChat={() => onOpenAiChat && onOpenAiChat()}
              />
            </div>
          )}
        </div>
      </div>

      {!isReadOnly && !showAddForm && (
        <div className="mt-3.5 pl-0 sm:pl-[56px] space-y-2">
          {/* メイン：自分で予定を追加するボタン */}
          <button
            type="button"
            onClick={() => {
              setInsertIndex(null);
              const lastEvent = currentEvents[currentEvents.length - 1];
              const nextTime = (lastEvent?.endTime || lastEvent?.time) ? getMidpointTime(lastEvent.endTime || lastEvent.time, null) : '12:00';
              setInsertRouteContext(
                lastEvent
                  ? {
                      time: nextTime,
                      prevTitle: lastEvent.title || '',
                      prevLocation: lastEvent.location || lastEvent.title || '',
                      prevTime: lastEvent.endTime || lastEvent.time || '',
                      nextTitle: '',
                      nextLocation: '',
                      nextTime: ''
                    }
                  : null
              );
              setAiInitialData({ time: nextTime });
              setShowAddForm(true);
            }}
            className="w-full py-3.5 bg-[#7A9D8C] hover:bg-[#688a79] text-white rounded-2xl text-xs font-extrabold flex items-center justify-center gap-1.5 shadow-sm transition-all active:scale-[0.99]"
          >
            <Plus size={16} strokeWidth={2.5} /> 予定を追加する
          </button>

          {/* サブ：可愛い薄い水色のミニAI相談＆スポット候補ポップアップボタン */}
          <div className="flex items-center justify-end gap-1.5 pt-0.5">
            <span className="text-[10px] font-bold text-stone-400 mr-0.5">迷ったときは:</span>
            <button
              type="button"
              onClick={() => onOpenAiChat && onOpenAiChat()}
              className="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-700 border border-sky-200 rounded-full text-[10px] font-bold flex items-center gap-1 transition-colors shadow-2xs active:scale-95"
            >
              <MessageCircle size={11} className="text-sky-500" /> AIに相談
            </button>
            <button
              type="button"
              onClick={() => {
                const lastEvent = currentEvents[currentEvents.length - 1];
                const nextTime = (lastEvent?.endTime || lastEvent?.time) ? getMidpointTime(lastEvent.endTime || lastEvent.time, null) : '13:30';
                setInsertRouteContext(
                  lastEvent
                    ? {
                        time: nextTime,
                        prevTitle: lastEvent.title || '',
                        prevLocation: lastEvent.location || lastEvent.title || '',
                        prevTime: lastEvent.endTime || lastEvent.time || '',
                        nextTitle: '',
                        nextLocation: '',
                        nextTime: ''
                      }
                    : null
                );
                setShowAiSuggestModal(true);
              }}
              className="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-700 border border-sky-200 rounded-full text-[10px] font-bold flex items-center gap-1 transition-colors shadow-2xs active:scale-95"
            >
              <Sparkles size={11} className="text-sky-500" /> スポット候補
            </button>
          </div>
        </div>
      )}

      {showAiSuggestModal && (
        <EventAiSuggestModal
          trip={trip}
          routeContext={insertRouteContext}
          onClose={() => setShowAiSuggestModal(false)}
          onSelect={(suggestedEvent) => {
            setAiInitialData(suggestedEvent);
            setShowAiSuggestModal(false);
            if (insertIndex === null) {
              setShowAddForm(true);
            }
          }}
        />
      )}

      {/* 予定の削除確認モーダル */}
      {eventToDelete && (
        <div
          className="fixed inset-0 bg-black/60 z-[260] flex justify-center items-center p-4 animate-in fade-in"
          onClick={() => setEventToDelete(null)}
        >
          <div
            className="bg-white w-full max-w-sm rounded-[32px] p-6 shadow-2xl animate-in zoom-in-95 text-center"
            onClick={e => e.stopPropagation()}
          >
            <div className="w-12 h-12 rounded-full bg-red-50 text-red-500 flex items-center justify-center mx-auto mb-3 border border-red-100">
              <Trash2 size={22} />
            </div>
            <h3 className="font-bold text-base text-stone-800 mb-2">この予定を削除しますか？</h3>
            <div className="bg-stone-50 p-3.5 rounded-2xl border border-stone-100 mb-4 text-left">
              {eventToDelete.time && (
                <p className="text-[10px] font-bold text-[#7A9D8C] flex items-center gap-1 mb-0.5">
                  <Clock size={11} /> {eventToDelete.time}
                </p>
              )}
              <p className="text-xs font-bold text-stone-800">{eventToDelete.title}</p>
              {eventToDelete.location && (
                <p className="text-[10px] text-stone-500 font-bold mt-1 flex items-center gap-1">
                  <MapPin size={10} className="text-red-500" /> {eventToDelete.location}
                </p>
              )}
            </div>
            <p className="text-xs text-stone-500 leading-relaxed mb-5">
              削除した予定は元に戻せません。よろしいですか？
            </p>
            <div className="flex gap-2.5">
              <button
                type="button"
                onClick={() => setEventToDelete(null)}
                className="flex-1 py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs transition-colors"
              >
                キャンセル
              </button>
              <button
                type="button"
                onClick={() => {
                  updateTrip({
                    ...trip,
                    events: (trip.events || []).filter(e => e.id !== eventToDelete.id)
                  });
                  setEventToDelete(null);
                  customAlert('予定を削除しました');
                }}
                className="flex-1 py-3 bg-red-500 hover:bg-red-600 text-white font-bold rounded-2xl text-xs shadow-sm transition-colors flex items-center justify-center gap-1"
              >
                <Trash2 size={14} /> 削除する
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 予定内の思い出写真 削除確認モーダル */}
      {photoToDelete && (
        <div
          className="fixed inset-0 bg-black/60 z-[270] flex justify-center items-center p-4 animate-in fade-in"
          onClick={() => setPhotoToDelete(null)}
        >
          <div
            className="bg-white w-full max-w-sm rounded-[32px] p-6 shadow-2xl animate-in zoom-in-95 text-center"
            onClick={e => e.stopPropagation()}
          >
            <div className="w-12 h-12 rounded-full bg-red-50 text-red-500 flex items-center justify-center mx-auto mb-3 border border-red-100">
              <Trash2 size={22} />
            </div>
            <h3 className="font-bold text-base text-stone-800 mb-2">この写真を削除しますか？</h3>
            <div className="w-28 h-28 rounded-2xl overflow-hidden mx-auto mb-3 border border-stone-200 shadow-xs bg-stone-100">
              <img src={photoToDelete.photo.url} alt="削除対象の写真" className="w-full h-full object-cover" />
            </div>
            <p className="text-xs text-stone-500 leading-relaxed mb-5">
              削除すると、しおりと旅の思い出アルバムの両方からこの写真が消去されます。よろしいですか？
            </p>
            <div className="flex gap-2.5">
              <button
                type="button"
                onClick={() => setPhotoToDelete(null)}
                className="flex-1 py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs transition-colors"
              >
                キャンセル
              </button>
              <button
                type="button"
                onClick={() => {
                  handleDeleteEventPhoto(photoToDelete.eventId, photoToDelete.photo.id);
                  setPhotoToDelete(null);
                }}
                className="flex-1 py-3 bg-red-500 hover:bg-red-600 text-white font-bold rounded-2xl text-xs shadow-sm transition-colors flex items-center justify-center gap-1"
              >
                <Trash2 size={14} /> 削除する
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function PublishModal({ trip, currentUser, onClose, onPublish }) {
  useLockBodyScroll(true);
  const [step, setStep] = useState(1);
  const [selectedImages, setSelectedImages] = useState(() => {
    // 初期状態で各予定の公開OKな写真があれば最大4枚までカバー候補にもセット可能にする
    const eventUrls = [];
    (trip.events || []).forEach(ev => {
      (ev.photos || []).forEach(p => {
        if (p.isPublic !== false && p.url && !eventUrls.includes(p.url)) {
          eventUrls.push(p.url);
        }
      });
    });
    return eventUrls.slice(0, 4);
  });
  const [region, setRegion] = useState(REGIONS[1]);
  const [description, setDescription] = useState('');
  // デフォルトでは予定のメモを共有しない（個人情報や予約番号保護のため false）
  const [shareMemos, setShareMemos] = useState(false);

  // 各予定に紐づく写真のうち「みんなの旅」に一緒に公開する写真IDのセット（初期値は各写真の isPublic !== false のもの）
  const [selectedEventPhotoIds, setSelectedEventPhotoIds] = useState(() => {
    const ids = [];
    (trip.events || []).forEach(ev => {
      (ev.photos || []).forEach(p => {
        if (p.isPublic !== false && p.id) ids.push(p.id);
      });
    });
    return ids;
  });

  const fileInputRef = useRef(null);

  const eventsWithMemos = useMemo(
    () => (trip.events || []).filter(e => e.memo && e.memo.trim().length > 0),
    [trip.events]
  );

  const eventsWithPhotos = useMemo(
    () => (trip.events || []).filter(e => Array.isArray(e.photos) && e.photos.length > 0),
    [trip.events]
  );

  const toggleEventPhotoSelection = (photoId) => {
    setSelectedEventPhotoIds(prev =>
      prev.includes(photoId) ? prev.filter(id => id !== photoId) : [...prev, photoId]
    );
  };

  const handleImageUpload = async (e) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const compressedUrls = await Promise.all(files.map(file => compressImageFile(file, 1200, 0.82)));
      setSelectedImages([...selectedImages, ...compressedUrls.filter(Boolean)].slice(0, 4));
    }
  };

  const handleProceedToConfirm = () => {
    if (selectedImages.length === 0) {
      customAlert('公開用のカバー写真を1枚以上選んでください。');
      return;
    }
    setStep(2);
  };

  const handleFinalPublish = () => {
    // 各予定に紐づく写真のうち、ユーザーが公開を選択した写真（selectedEventPhotoIdsに含まれるもの）だけを残して公開する
    const sanitizedEvents = (trip.events || []).map(({ photos, memo, ...eventRest }) => {
      const publicPhotos = Array.isArray(photos)
        ? photos
            .filter(p => selectedEventPhotoIds.includes(p.id))
            .map(p => ({ ...p, isPublic: true }))
        : [];
      return {
        ...eventRest,
        memo: shareMemos ? (memo || '') : '',
        status: 'approved',
        authorId: currentUser.id,
        photos: publicPhotos
      };
    });

    // 公開時の予算は予定内に記載されている金額の合計のみを記録する
    const totalEventsCost = sanitizedEvents.reduce((sum, ev) => sum + (Number(ev.cost) || 0), 0);

    onPublish({
      id: 'PUB-' + generateId(),
      title: trip.title,
      description,
      destination: trip.destination,
      region,
      startDate: trip.startDate,
      endDate: trip.endDate,
      budget: totalEventsCost,
      authorId: currentUser.id,
      authorName: currentUser.name,
      authorAvatar: currentUser.avatar,
      authorBio: currentUser.bio || '',
      covers: selectedImages,
      likes: 0,
      views: 0,
      likedBy: [],
      publishedAt: Date.now(),
      members: [{ id: currentUser.id, name: currentUser.name, color: '#7A9D8C' }],
      events: sanitizedEvents,
      packingList: [],
      extraExpenses: [],
      souvenirList: []
    });
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-[200] flex justify-center items-end sm:items-center p-0 sm:p-6 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full sm:max-w-md rounded-t-[32px] sm:rounded-3xl p-6 max-h-[90vh] overflow-y-auto pb-safe animate-in slide-in-from-bottom-full sm:slide-in-from-bottom-0" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-5">
          <h3 className="font-bold text-base text-stone-800 flex items-center gap-2">
            <Globe size={18} className="text-[#7A9D8C]" />
            {step === 1 ? 'しおりを「みんなの旅」に公開' : '投稿内容の最終確認'}
          </h3>
          <button onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        {step === 1 ? (
          <div className="animate-in fade-in">
            <div className="mb-4">
              <label className="block text-xs font-bold text-stone-500 mb-1.5">地域エリア</label>
              <div className="flex flex-wrap gap-1.5">
                {REGIONS.map(r => (
                  <button
                    key={r}
                    type="button"
                    onClick={() => setRegion(r)}
                    className={`px-3 py-1 text-xs font-bold rounded-full border transition-colors ${region === r ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]' : 'bg-white text-stone-600 border-stone-200'}`}
                  >
                    {r}
                  </button>
                ))}
              </div>
            </div>

            <div className="mb-4">
              <label className="block text-xs font-bold text-stone-500 mb-1.5">旅の説明・おすすめポイント</label>
              <textarea
                value={description}
                onChange={e => setDescription(e.target.value)}
                rows="3"
                placeholder="旅の感想やおすすめポイントなど..."
                className="w-full p-3 bg-stone-50 rounded-xl border border-stone-200 text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] resize-none"
              />
            </div>

            <div className="mb-5">
              <div className="flex justify-between items-end mb-2">
                <label className="block text-xs font-bold text-stone-500">公開用のカバー写真を選択 (最大4枚)</label>
                <span className="text-xs font-bold text-[#7A9D8C]">{selectedImages.length}/4枚</span>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {selectedImages.map((url, idx) => (
                  <div key={idx} className="relative aspect-square rounded-2xl overflow-hidden border border-stone-200 shadow-sm group">
                    <img src={url} alt="preview" className="w-full h-full object-cover" />
                    <button
                      type="button"
                      onClick={() => setSelectedImages(selectedImages.filter((_, i) => i !== idx))}
                      className="absolute top-2 right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center shadow-md hover:bg-red-600"
                    >
                      <Trash2 size={12} />
                    </button>
                  </div>
                ))}
                {selectedImages.length < 4 && (
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="aspect-square rounded-2xl border-2 border-dashed border-stone-300 bg-stone-50 flex flex-col items-center justify-center text-stone-400 hover:bg-stone-100 transition-colors"
                  >
                    <Plus size={22} className="mb-1" />
                    <span className="text-[10px] font-bold">写真を選ぶ</span>
                  </button>
                )}
                <input type="file" multiple accept="image/*" ref={fileInputRef} className="hidden" onChange={handleImageUpload} />
              </div>
            </div>

            {/* 各予定の写真を「みんなの旅」に載せるかどうかの個別選択セクション */}
            <div className="mb-5 p-4 rounded-2xl border border-stone-200 bg-stone-50/90 space-y-3">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-stone-800 flex items-center gap-1.5">
                  <Camera size={14} className="text-[#7A9D8C]" />
                  各予定の写真を「みんなの旅」に公開する
                </label>
                <span className="text-[11px] font-bold text-[#557465] bg-[#7A9D8C]/15 px-2.5 py-0.5 rounded-full">
                  {selectedEventPhotoIds.length}枚を公開
                </span>
              </div>
              <p className="text-[10px] text-stone-500 leading-relaxed">
                公開したい写真をタップして選択できます。チェックした写真は「みんなの旅」の各予定カード内に表示され、どんな場所・料理だったのかが他の人にも伝わります！
              </p>

              {eventsWithPhotos.length === 0 ? (
                <div className="p-3 bg-white rounded-xl border border-stone-200/70 text-[11px] text-stone-400 font-bold text-center">
                  まだ各予定に貼られた写真がありません（予定カードの「思い出の写真を貼る」から追加できます）
                </div>
              ) : (
                <div className="space-y-2.5 max-h-52 overflow-y-auto no-scrollbar pr-0.5">
                  {eventsWithPhotos.map(ev => (
                    <div key={ev.id} className="bg-white p-3 rounded-xl border border-stone-200/80 space-y-2">
                      <p className="text-[11px] font-bold text-stone-700 truncate">
                        {ev.time} {ev.title}
                      </p>
                      <div className="flex gap-2 overflow-x-auto no-scrollbar pb-0.5">
                        {(ev.photos || []).map(p => {
                          const isSelected = selectedEventPhotoIds.includes(p.id);
                          return (
                            <button
                              key={p.id}
                              type="button"
                              onClick={() => toggleEventPhotoSelection(p.id)}
                              className={`relative w-16 h-16 rounded-xl overflow-hidden border-2 shrink-0 transition-all ${
                                isSelected
                                  ? 'border-[#7A9D8C] ring-2 ring-[#7A9D8C]/30'
                                  : 'border-stone-200 opacity-50 grayscale-[40%]'
                              }`}
                            >
                              <img src={p.url} alt="event" className="w-full h-full object-cover" />
                              <span
                                className={`absolute top-1 right-1 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold shadow-xs ${
                                  isSelected ? 'bg-[#7A9D8C] text-white' : 'bg-black/50 text-white'
                                }`}
                              >
                                {isSelected ? <Check size={11} strokeWidth={3} /> : ''}
                              </span>
                              <span className={`absolute bottom-0 inset-x-0 text-[8px] font-bold py-0.5 text-center ${
                                isSelected ? 'bg-[#7A9D8C]/90 text-white' : 'bg-stone-800/75 text-stone-200'
                              }`}>
                                {isSelected ? '🌐公開' : '🔒非公開'}
                              </span>
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* メモ共有の選択項目（デフォルトはOFF） */}
            <div className="mb-6 p-4 rounded-2xl border border-stone-200 bg-stone-50/90">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <label className="text-xs font-bold text-stone-800 flex items-center gap-1.5 mb-1">
                    <FileText size={14} className="text-[#7A9D8C]" />
                    予定のメモ内容も一緒に共有する
                  </label>
                  <p className="text-[10px] text-stone-500 leading-relaxed">
                    予約番号や個人情報が含まれる場合があるため、<strong>初期設定では「共有しない（非公開）」</strong>になっています。
                    {eventsWithMemos.length > 0 && `（現在 ${eventsWithMemos.length}件の予定にメモがあります）`}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => setShareMemos(!shareMemos)}
                  className={`w-12 h-7 rounded-full transition-colors p-1 shrink-0 flex items-center ${shareMemos ? 'bg-[#7A9D8C] justify-end' : 'bg-stone-300 justify-start'}`}
                >
                  <div className="w-5 h-5 rounded-full bg-white shadow-sm" />
                </button>
              </div>
              <div className="mt-2.5 pt-2.5 border-t border-stone-200/70 flex items-center justify-between text-[11px] font-bold">
                <span className="text-stone-500">現在の設定：</span>
                {shareMemos ? (
                  <span className="text-amber-700 bg-amber-100 px-2.5 py-0.5 rounded-full">メモを公開する</span>
                ) : (
                  <span className="text-[#557465] bg-[#7A9D8C]/15 px-2.5 py-0.5 rounded-full flex items-center gap-1">
                    <Check size={11} strokeWidth={3} /> メモは共有しない（推奨・安全）
                  </span>
                )}
              </div>
            </div>

            <button
              type="button"
              onClick={handleProceedToConfirm}
              className="w-full py-3.5 bg-[#7A9D8C] text-white font-bold rounded-2xl shadow-md hover:bg-[#688a79] transition-all text-sm flex justify-center items-center gap-1.5"
            >
              <span>確認画面へ進む</span>
              <ChevronRight size={16} />
            </button>
          </div>
        ) : (
          <div className="space-y-4 animate-in slide-in-from-right-4">
            <div className="p-3.5 bg-amber-50/90 border border-amber-200 rounded-2xl flex items-start gap-2.5">
              <AlertCircle size={18} className="text-amber-600 shrink-0 mt-0.5" />
              <div className="text-xs text-amber-900 leading-relaxed">
                <p className="font-bold mb-0.5">公開前の最終チェック</p>
                <p className="text-[11px] text-amber-800">以下の内容で「みんなの旅」に投稿されます。個人情報が含まれていないかご確認ください。</p>
              </div>
            </div>

            <div className="bg-stone-50 p-4 rounded-2xl border border-stone-200 space-y-3 text-xs">
              <div>
                <span className="text-[10px] font-bold text-stone-400 block mb-0.5">タイトル / エリア</span>
                <p className="font-bold text-stone-800 text-sm">{trip.title} <span className="text-xs text-[#7A9D8C] ml-1">（{region}・{trip.destination}）</span></p>
              </div>

              {description && (
                <div>
                  <span className="text-[10px] font-bold text-stone-400 block mb-0.5">旅の説明</span>
                  <p className="text-stone-700 font-medium whitespace-pre-wrap bg-white p-2.5 rounded-xl border border-stone-100">{description}</p>
                </div>
              )}

              <div>
                <span className="text-[10px] font-bold text-stone-400 block mb-1">公開される予定数</span>
                <p className="font-bold text-stone-700">全 {(trip.events || []).length} 件（メモ公開: {shareMemos ? 'あり' : 'なし'}）</p>
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="flex-1 py-3 bg-stone-100 hover:bg-stone-200 text-stone-600 font-bold rounded-2xl text-xs"
              >
                戻る
              </button>
              <button
                type="button"
                onClick={handleFinalPublish}
                className="flex-[2] py-3 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-bold rounded-2xl text-xs shadow-sm"
              >
                この内容で公開する
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function JoinTripWizard({ currentUser, trips, setTrips, onClose, onOpenTrip }) {
  useLockBodyScroll(true);
  const [step, setStep] = useState(1);
  const [joinCode, setJoinCode] = useState('');
  const [foundTrip, setFoundTrip] = useState(null);
  const [myColor, setMyColor] = useState(PRESET_COLORS[1]);
  const [isSearching, setIsSearching] = useState(false);
  const [joinErrorMsg, setJoinErrorMsg] = useState('');
  const [diagResult, setDiagResult] = useState(null);

  useEffect(() => {
    let mounted = true;
    diagnoseSupabaseConnection().then(res => {
      if (mounted) setDiagResult(res);
    });
    return () => { mounted = false; };
  }, []);

  const handleCheckCode = async () => {
    const code = normalizeInviteCode(joinCode);
    if (!code || isSearching) return;
    setJoinCode(code);
    setJoinErrorMsg('');
    setIsSearching(true);
    try {
      const localExisting = trips.find(t => normalizeInviteCode(t.id) === code);
      if (localExisting) {
        setFoundTrip(localExisting);
        setStep(2);
        return;
      }
      const cloudTrip = await fetchSharedTripFromCloud(code);
      if (cloudTrip) {
        setFoundTrip(cloudTrip);
        setStep(2);
      } else {
        const diag = await diagnoseSupabaseConnection();
        setDiagResult(diag);
        if (!diag.ok) {
          setJoinErrorMsg(diag.message);
        } else {
          setJoinErrorMsg(
            `招待コード「${code}」のしおりがクラウドに見つかりませんでした。\n① 作ってくれた友達が「👤1人旅」ではなく「👥みんなで共有」で作っているか\n② 友達のスマホで一度そのしおりを開き直したか\nを確認してください！`
          );
        }
      }
    } finally {
      setIsSearching(false);
    }
  };

  const handleJoin = async () => {
    const isAlreadyMember = (foundTrip.members || []).some(m => m.id === currentUser.id);
    const updatedTrip = {
      ...foundTrip,
      isSoloTrip: false,
      members: isAlreadyMember
        ? foundTrip.members
        : [...(foundTrip.members || []), { id: currentUser.id, name: currentUser.name, avatar: currentUser.avatar, color: myColor }]
    };
    if (trips.some(t => t.id === updatedTrip.id)) {
      setTrips(trips.map(t => (t.id === updatedTrip.id ? updatedTrip : t)));
    } else {
      setTrips([updatedTrip, ...trips]);
    }
    await syncSharedTripToCloud(updatedTrip);
    onOpenTrip(updatedTrip.id, false);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-[200] flex justify-center items-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-[32px] p-6 shadow-2xl animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-lg text-stone-800">{step === 1 ? '招待コードで参加' : 'カラーの選択'}</h3>
          <button onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        {step === 1 ? (
          <div className="space-y-3.5">
            {diagResult && (
              <div className={`p-3 rounded-2xl border text-[11px] font-bold leading-relaxed ${
                diagResult.ok
                  ? 'bg-emerald-50 border-emerald-200 text-emerald-900'
                  : 'bg-amber-50 border-amber-300 text-amber-900'
              }`}>
                <p className="font-extrabold flex items-center gap-1">
                  <span>{diagResult.ok ? '✅ クラウド共有：接続OK' : '⚠️ クラウド共有の診断結果'}</span>
                </p>
                <p className="mt-0.5 text-[10px] opacity-90">{diagResult.message}</p>
              </div>
            )}

            <div>
              <div className="flex items-center justify-between mb-1.5 px-1">
                <label className="text-[11px] font-extrabold text-stone-500">
                  招待コード（最大13文字）
                </label>
                <span className="text-[10px] font-mono font-bold text-stone-400">
                  {joinCode.length}/13文字
                </span>
              </div>
              <input
                type="text"
                maxLength={13}
                value={joinCode}
                onChange={(e) => {
                  const raw = e.target.value.toUpperCase().replace(/[ー−―‐]/g, '-');
                  const match = raw.match(/TABI-[A-Z0-9]{0,8}/);
                  const nextVal = match ? match[0].slice(0, 13) : raw.replace(/[^A-Z0-9-]/g, '').slice(0, 13);
                  setJoinCode(nextVal);
                  if (joinErrorMsg) setJoinErrorMsg('');
                }}
                placeholder="例: TABI-XXXXXXXX"
                className="w-full p-3.5 bg-stone-50 border border-stone-200 rounded-xl uppercase font-mono text-center text-sm font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
            </div>

            {joinErrorMsg && (
              <div className="p-3 bg-rose-50 border border-rose-200 rounded-2xl text-xs font-bold text-rose-700 whitespace-pre-wrap leading-relaxed">
                {joinErrorMsg}
              </div>
            )}

            <button
              onClick={handleCheckCode}
              disabled={!joinCode.trim() || isSearching}
              className="w-full py-3.5 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-bold rounded-2xl shadow-sm text-sm disabled:opacity-50 transition-all"
            >
              {isSearching ? 'クラウドからしおりを検索中...' : 'しおりを探す'}
            </button>
          </div>
        ) : (
          <div>
            <div className="mb-4 p-3 bg-stone-50 rounded-2xl border border-stone-200/80 text-center">
              <p className="text-[10px] font-bold text-stone-400">参加するしおり</p>
              <p className="text-sm font-extrabold text-stone-800 truncate">{foundTrip?.title}</p>
              <p className="text-[11px] font-bold text-[#557465] mt-0.5">🗾 {foundTrip?.destination || '未設定'}</p>
            </div>
            <div className="mb-6"><label className="text-[11px] text-stone-500 font-bold mb-2 block text-center">あなたのメンバーカラー</label><div className="flex gap-2.5 justify-center">{PRESET_COLORS.map(color => (<button key={color} onClick={() => setMyColor(color)} className={`w-8 h-8 rounded-full transition-transform ${myColor === color ? 'scale-110 ring-2 ring-offset-2 ring-stone-700' : 'opacity-60'}`} style={{ backgroundColor: color }} />))}</div></div>
            <button onClick={handleJoin} className="w-full py-3.5 bg-[#7A9D8C] text-white font-bold rounded-2xl shadow-sm text-sm">参加する</button>
          </div>
        )}
      </div>
    </div>
  );
}

// タイムライン内で予定を直接追加・差し込むフォーム
function InlineEventForm({ onSave, onCancel, date, trip, currentUser, initialData, routeContext, onOpenAiSuggest, onOpenAiChat }) {
  const defaultOrigin = useMemo(() => getHomeDepartureLabel(currentUser), [currentUser]);
  const addMinutesToTimeStr = (tStr, minsToAdd = 60) => {
    if (!tStr || !tStr.includes(':')) return '13:00';
    const [h, m] = tStr.split(':').map(Number);
    const total = ((isNaN(h) ? 12 : h) * 60 + (isNaN(m) ? 0 : m) + minsToAdd) % (24 * 60);
    return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
  };
  const initialStart = initialData?.time || routeContext?.time || '12:00';
  const [time, setTime] = useState(initialStart);
  const [endTime, setEndTime] = useState(initialData?.endTime || addMinutesToTimeStr(initialStart, 60));
  const [title, setTitle] = useState(initialData?.title || '');
  const [type, setType] = useState(initialData?.type || 'sightseeing');
  const [departureOrigin, setDepartureOrigin] = useState(
    initialData?.departureOrigin || routeContext?.prevLocation || trip.departurePoint || defaultOrigin
  );
  const [saveOriginForNext, setSaveOriginForNext] = useState(false);
  const [transportMethod, setTransportMethod] = useState(initialData?.transportMethod || trip.transportMethod || 'shinkansen_train');
  const [location, setLocation] = useState(initialData?.location || '');
  const [mapPinQuery, setMapPinQuery] = useState(initialData?.mapPinQuery || '');
  const [showMapPicker, setShowMapPicker] = useState(false);
  const [mapSearchInput, setMapSearchInput] = useState('');
  const [cost, setCost] = useState(initialData?.cost ? String(initialData.cost) : '');
  const [memo, setMemo] = useState(initialData?.memo || '');

  useEffect(() => {
    if (initialData) {
      if (initialData.time) {
        setTime(initialData.time);
        if (!initialData.endTime) {
          setEndTime(addMinutesToTimeStr(initialData.time, 60));
        }
      }
      if (initialData.endTime !== undefined) setEndTime(initialData.endTime);
      if (initialData.title !== undefined) setTitle(initialData.title);
      if (initialData.type) setType(initialData.type);
      if (initialData.departureOrigin !== undefined) setDepartureOrigin(initialData.departureOrigin);
      if (initialData.transportMethod !== undefined) setTransportMethod(initialData.transportMethod);
      if (initialData.location !== undefined) setLocation(initialData.location);
      if (initialData.mapPinQuery !== undefined) setMapPinQuery(initialData.mapPinQuery);
      if (initialData.cost !== undefined) setCost(String(initialData.cost));
      if (initialData.memo !== undefined) setMemo(initialData.memo);
    }
  }, [initialData]);

  // Googleマップの共有URLや座標・キーワードからピン用の検索クエリを抽出するヘルパー
  const extractPinQuery = (rawInput) => {
    const val = (rawInput || '').trim();
    if (!val) return '';
    const atCoordMatch = val.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
    if (atCoordMatch) return `${atCoordMatch[1]},${atCoordMatch[2]}`;
    const placeMatch = val.match(/\/place\/([^/?]+)/);
    if (placeMatch) return decodeURIComponent(placeMatch[1].replace(/\+/g, ' '));
    const qMatch = val.match(/[?&](?:q|query)=([^&]+)/);
    if (qMatch) return decodeURIComponent(qMatch[1].replace(/\+/g, ' '));
    return val;
  };

  const activePinTarget = extractPinQuery(mapPinQuery || location || title || trip.destination || '東京駅');

  const handleLockPin = () => {
    const target = extractPinQuery(mapSearchInput || location || title || trip.destination);
    if (!target) {
      customAlert('検索したい場所名や住所、またはGoogleマップの共有リンクを入力してください');
      return;
    }
    setMapPinQuery(target);
    if (!location.trim()) {
      setLocation(target);
    }
    customAlert(`📍「${target}」にGoogleマップのピンを固定しました！`);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const isTransport = type === 'transport';
    if (isTransport && saveOriginForNext && departureOrigin.trim()) {
      addSavedDeparturePoint(departureOrigin.trim());
      customAlert(`📍「${departureOrigin.trim()}」を次の旅行でも使える出発地点に登録しました！`);
    }
    const selectedTag = QUICK_TAGS.find(t => t.id === type) || QUICK_TAGS[2];
    const finalTitle = title.trim() || selectedTag.defaultTitle;
    const finalLocation = location.trim() || mapPinQuery.trim();
    const finalPinQuery = extractPinQuery(mapPinQuery.trim() || finalLocation);
    onSave({
      id: generateId(),
      date,
      time: time || '12:00',
      endTime: endTime || '',
      title: finalTitle,
      type,
      departureOrigin: isTransport ? departureOrigin.trim() : '',
      transportMethod: isTransport ? transportMethod : '',
      location: finalLocation,
      mapPinQuery: finalPinQuery,
      cost: Number(cost) || 0,
      memo: memo.trim(),
      status: trip.isSoloTrip ? 'approved' : 'proposed',
      authorId: currentUser.id,
      photos: []
    });
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white p-4 rounded-2xl shadow-md border-2 border-[#7A9D8C] space-y-3 relative">
      {/* 最上段：左にタイトル、右上に独立したわかりやすい「× 閉じる」ボタン */}
      <div className="flex justify-between items-center gap-2">
        <span className="text-xs font-extrabold text-[#557465] flex items-center gap-1">
          <Plus size={15} className="text-[#7A9D8C]" strokeWidth={2.8} /> 新しい予定を入力
        </span>
        <button
          type="button"
          onClick={onCancel}
          className="px-2.5 py-1 rounded-full bg-stone-100 hover:bg-rose-50 text-stone-600 hover:text-rose-600 border border-stone-200/80 hover:border-rose-200 text-[11px] font-extrabold flex items-center gap-1 transition-all active:scale-95 shrink-0 shadow-2xs"
          title="入力フォームを閉じる"
        >
          <X size={14} strokeWidth={2.6} />
          <span>閉じる</span>
        </button>
      </div>

      {/* 2段目：スポット候補ポップアップ・AI相談ボタン */}
      {(onOpenAiSuggest || onOpenAiChat) && (
        <div className="flex items-center gap-1.5 flex-wrap">
          {onOpenAiSuggest && (
            <button
              type="button"
              onClick={onOpenAiSuggest}
              className="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-700 border border-sky-200 rounded-full text-[10px] font-extrabold flex items-center gap-1 transition-colors active:scale-95"
            >
              <Sparkles size={11} className="text-sky-500" /> スポット候補を見る
            </button>
          )}
          {onOpenAiChat && (
            <button
              type="button"
              onClick={onOpenAiChat}
              className="px-2.5 py-1 bg-sky-50 hover:bg-sky-100 text-sky-700 border border-sky-200 rounded-full text-[10px] font-bold flex items-center gap-1 transition-colors active:scale-95"
            >
              <MessageCircle size={11} className="text-sky-500" /> AI相談
            </button>
          )}
        </div>
      )}

      {routeContext && (routeContext.prevLocation || routeContext.nextLocation) && (
        <div className="px-3 py-2 bg-sky-50/70 border border-sky-200/70 rounded-xl text-[10px] font-bold text-sky-900 flex items-center justify-between gap-2">
          <div className="truncate">
            <span>📍 前後のルート: </span>
            {routeContext.prevLocation && <span>{routeContext.prevTime} {routeContext.prevLocation}</span>}
            {routeContext.nextLocation && <span> → {routeContext.nextTime} {routeContext.nextLocation}</span>}
          </div>
          {onOpenAiSuggest && (
            <button
              type="button"
              onClick={onOpenAiSuggest}
              className="shrink-0 text-[10px] font-extrabold text-sky-700 underline hover:text-sky-900"
            >
              周辺を提案
            </button>
          )}
        </div>
      )}

      {/* カテゴリ選択（5つすべてがスマホ画面幅にピタッと収まる5列グリッド） */}
      <div className="grid grid-cols-5 gap-1">
        {QUICK_TAGS.map(tag => {
          const TagIcon = tag.icon;
          const active = type === tag.id;
          return (
            <button
              key={tag.id}
              type="button"
              onClick={() => setType(tag.id)}
              className={`py-2 px-1 rounded-xl text-[11px] font-extrabold flex flex-col sm:flex-row items-center justify-center gap-0.5 sm:gap-1 border transition-all whitespace-nowrap ${
                active
                  ? 'bg-[#7A9D8C] text-white border-[#7A9D8C] shadow-2xs'
                  : 'bg-stone-50 text-stone-600 border-stone-200 hover:bg-stone-100'
              }`}
            >
              <TagIcon size={13} className="shrink-0" />
              <span>{tag.label}</span>
            </button>
          );
        })}
      </div>

      {/* ★「移動」ボタンを押したときだけ初めて新幹線・車などの交通手段ボタンと出発地点が出てくる（移動以外のタブでは非表示） */}
      {type === 'transport' && (
        <div className="space-y-2.5 p-3 bg-sky-50/60 border border-sky-200/80 rounded-2xl animate-in fade-in slide-in-from-top-1 duration-150">
          <div>
            <label className="text-[11px] font-extrabold text-sky-900 flex items-center gap-1 mb-1.5 pl-0.5">
              <span>🚆 交通手段を選択（移動タブ専用）</span>
            </label>
            <div className="grid grid-cols-3 gap-1.5">
              {TRANSPORT_METHODS.map(m => (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => setTransportMethod(m.id)}
                  className={`py-2 px-2 rounded-xl text-[11px] font-extrabold border transition-all whitespace-nowrap flex items-center justify-center gap-1 active:scale-95 ${
                    transportMethod === m.id
                      ? 'bg-[#5E8473] text-white border-[#5E8473] shadow-2xs'
                      : 'bg-white text-stone-600 border-stone-200 hover:bg-stone-100'
                  }`}
                >
                  <span>{m.label.split(' ')[0]}</span>
                  <span>{m.short}</span>
                </button>
              ))}
            </div>
          </div>

          <DepartureSelectorBox
            user={currentUser}
            value={departureOrigin}
            onChange={setDepartureOrigin}
            saveForNext={saveOriginForNext}
            onChangeSaveForNext={setSaveOriginForNext}
            extraQuickPoint={routeContext?.prevLocation || ''}
            extraQuickLabel="前の予定地"
            label="この移動の出発地点"
            compact
          />
        </div>
      )}

      {/* ★ 1段目：開始時間 ＆ 終わりの時間（両方記録でき、ワンタップで所要時間も調整可能） */}
      <div className="p-2.5 bg-stone-50/90 border border-stone-200/80 rounded-2xl space-y-2">
        <div className="grid grid-cols-2 gap-2.5">
          <div className="min-w-0">
            <label className="text-[11px] font-extrabold text-stone-600 flex items-center gap-1 mb-1 pl-0.5">
              <Clock size={12} className="text-[#7A9D8C]" /> 開始時間
            </label>
            <input
              type="time"
              value={time}
              onChange={e => {
                const nextStart = e.target.value;
                setTime(nextStart);
                if (endTime && endTime < nextStart) {
                  setEndTime(addMinutesToTimeStr(nextStart, 60));
                }
              }}
              className="w-full min-w-0 h-10 px-2.5 bg-white border border-stone-200 rounded-xl text-sm font-mono font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] appearance-none"
            />
          </div>
          <div className="min-w-0">
            <div className="flex items-center justify-between mb-1 px-0.5">
              <label className="text-[11px] font-extrabold text-stone-600 flex items-center gap-1">
                <Clock size={12} className="text-sky-600" /> 終わりの時間
              </label>
              {endTime && (
                <button
                  type="button"
                  onClick={() => setEndTime('')}
                  className="text-[10px] font-bold text-stone-400 hover:text-rose-500"
                >
                  クリア
                </button>
              )}
            </div>
            <input
              type="time"
              value={endTime}
              onChange={e => setEndTime(e.target.value)}
              className="w-full min-w-0 h-10 px-2.5 bg-white border border-stone-200 rounded-xl text-sm font-mono font-extrabold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] appearance-none"
            />
          </div>
        </div>

        {/* 開始時間からワンタップで終わりの時間を計算できるクイックボタン */}
        <div className="flex items-center justify-between gap-1 pt-0.5">
          <span className="text-[10px] font-bold text-stone-400 pl-0.5">所要時間から終了をセット:</span>
          <div className="flex items-center gap-1">
            {[
              { mins: 30, label: '+30分' },
              { mins: 60, label: '+1時間' },
              { mins: 90, label: '+1.5時間' },
              { mins: 120, label: '+2時間' }
            ].map(preset => {
              const targetEnd = addMinutesToTimeStr(time, preset.mins);
              const isMatched = endTime === targetEnd;
              return (
                <button
                  key={preset.mins}
                  type="button"
                  onClick={() => setEndTime(targetEnd)}
                  className={`px-2 py-0.5 rounded-lg text-[10px] font-extrabold border transition-all active:scale-95 ${
                    isMatched
                      ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                      : 'bg-white text-stone-600 border-stone-200 hover:bg-stone-100'
                  }`}
                >
                  {preset.label}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* ★ 2段目：予定のタイトル ＆ 1人予算（円） */}
      <div className="grid grid-cols-3 gap-2">
        <div className="col-span-2 min-w-0">
          <label className="text-[11px] font-extrabold text-stone-500 block mb-1 pl-0.5">
            予定のタイトル
          </label>
          <input
            type="text"
            value={title}
            onChange={e => setTitle(e.target.value)}
            placeholder={
              type === 'transport'
                ? '例: 新幹線で金沢へ移動'
                : '例: 近江町市場で海鮮丼ランチ'
            }
            className="w-full h-10 px-3 bg-stone-50 border border-stone-200 rounded-xl text-sm font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
          />
        </div>
        <div className="min-w-0">
          <label className="text-[11px] font-extrabold text-stone-500 block mb-1 pl-0.5">
            1人予算 (円)
          </label>
          <input
            type="number"
            inputMode="numeric"
            value={cost}
            onChange={e => setCost(e.target.value)}
            placeholder="0"
            className="w-full min-w-0 h-10 px-2.5 bg-stone-50 border border-stone-200 rounded-xl text-sm font-mono font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
          />
        </div>
      </div>

      {/* ★「移動」予定のときは、出発地〜目的地と交通手段からおおよその交通費候補を理由付きで提示し、ワンタップで予算にそのまま組み込める */}
      {type === 'transport' && (
        <div className="p-3 bg-sky-50/80 border border-sky-200/90 rounded-2xl space-y-2 animate-in fade-in duration-150">
          <div className="flex items-center justify-between gap-2 flex-wrap">
            <span className="text-[11px] font-extrabold text-sky-950 flex items-center gap-1">
              <Banknote size={13} className="text-sky-600 shrink-0" />
              <span>出発地〜目的地の交通手段別・予算候補（タップで予算に反映）</span>
            </span>
            <a
              href={`https://transit.yahoo.co.jp/search/result?from=${encodeURIComponent(
                (departureOrigin || '').replace(/（.*?）/g, '').trim()
              )}&to=${encodeURIComponent((location || title || trip.destination || '').replace(/（.*?）/g, '').trim())}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-[10px] font-extrabold text-sky-700 bg-white px-2 py-0.5 rounded-lg border border-sky-200 hover:bg-sky-100 inline-flex items-center gap-0.5 shrink-0"
            >
              <ExternalLink size={10} /> 乗換案内で正確運賃を見る
            </a>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-1.5">
            {estimateTransportCostCandidates(departureOrigin, location || title || trip.destination, transportMethod).map((cand, idx) => {
              const isSelectedCost = Number(cost) === cand.amount && cost !== '';
              return (
                <button
                  key={idx}
                  type="button"
                  onClick={() => {
                    setCost(String(cand.amount));
                    if (!title.trim()) {
                      const cleanOrig = (departureOrigin || '出発地').replace(/（.*?）/g, '').trim();
                      const cleanDest = (location || trip.destination || '目的地').replace(/（.*?）/g, '').trim();
                      const methodShort = TRANSPORT_METHODS.find(m => m.id === transportMethod)?.short || '移動';
                      setTitle(`${cleanOrig}から${cleanDest}へ${methodShort}`);
                    }
                  }}
                  className={`p-2 rounded-xl text-left border transition-all active:scale-95 cursor-pointer flex items-center justify-between sm:flex-col sm:items-start gap-1 ${
                    isSelectedCost
                      ? 'bg-sky-600 text-white border-sky-600 shadow-2xs'
                      : 'bg-white hover:bg-sky-100/70 text-stone-800 border-sky-200/90'
                  }`}
                >
                  <div className="min-w-0">
                    <span className={`text-[10px] font-extrabold block truncate ${isSelectedCost ? 'text-sky-100' : 'text-sky-800'}`}>
                      {cand.label}
                    </span>
                    {cand.note && (
                      <span className={`text-[9px] font-bold block truncate ${isSelectedCost ? 'text-white/85' : 'text-stone-400'}`}>
                        {cand.note}
                      </span>
                    )}
                  </div>
                  <span className={`text-xs font-mono font-extrabold shrink-0 ${isSelectedCost ? 'text-white' : 'text-sky-900'}`}>
                    ¥{cand.amount.toLocaleString()}<span className="text-[9px] font-normal">/人</span>
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* ★ 3段目：場所・駅・スポット名 ＆ すぐ近くに「🗺️ Googleマップでピンを指定・確認」ボタンを配置 */}
      <div className="space-y-1.5">
        <div className="flex items-center justify-between gap-2">
          <label className="text-[11px] font-extrabold text-stone-500 pl-0.5">
            {type === 'transport' ? '到着地・駅・空港名' : '場所・駅・スポット名'}
          </label>
          {mapPinQuery && (
            <span className="text-[10px] font-extrabold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full">
              📍 ピン固定中: {mapPinQuery.slice(0, 12)}
            </span>
          )}
        </div>

        <input
          type="text"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          placeholder="例: 福井県立恐竜博物館 / 芦原温泉駅"
          className="w-full h-10 px-3 bg-stone-50 border border-stone-200 rounded-xl text-sm font-bold text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
        />

        {/* 場所入力欄のすぐ下に配置された「🗺️ Googleマップでピンを指定・確認」ボタン */}
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={() => {
              if (!showMapPicker && !mapSearchInput) {
                setMapSearchInput(mapPinQuery || location || title || '');
              }
              setShowMapPicker(!showMapPicker);
            }}
            className={`flex-1 py-2 px-3 rounded-xl text-xs font-extrabold border flex items-center justify-center gap-1.5 transition-all active:scale-[0.99] shadow-2xs ${
              mapPinQuery
                ? 'bg-emerald-50 text-emerald-800 border-emerald-300'
                : showMapPicker
                ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                : 'bg-stone-50 hover:bg-stone-100 text-stone-700 border-stone-200'
            }`}
          >
            <MapPin size={13} className={mapPinQuery ? 'text-rose-500 fill-rose-500' : showMapPicker ? 'text-white' : 'text-[#7A9D8C]'} />
            <span>
              {showMapPicker
                ? '🗺️ Googleマッププレビューを閉じる ▲'
                : mapPinQuery
                ? `🗺️ Googleマップのピンを変更・確認 (${mapPinQuery.slice(0, 10)})`
                : '🗺️ Googleマップでピンを指定・確認'}
            </span>
          </button>

          {(location || mapPinQuery || title) && (
            <a
              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
                extractPinQuery(mapPinQuery || location || title)
              )}`}
              target="_blank"
              rel="noopener noreferrer"
              className="py-2 px-2.5 rounded-xl bg-white hover:bg-stone-50 text-stone-700 border border-stone-200 text-[11px] font-extrabold flex items-center gap-1 shrink-0 shadow-2xs active:scale-95"
              title="Googleマップアプリ・別タブで開く"
            >
              <ExternalLink size={12} className="text-[#7A9D8C]" />
              <span>開く</span>
            </a>
          )}
        </div>

        {showMapPicker && (
          <div className="p-3 bg-stone-50 rounded-2xl border border-stone-200/90 space-y-2.5 animate-in fade-in">
            <div className="flex items-center justify-between">
              <span className="text-[11px] font-extrabold text-stone-700 flex items-center gap-1">
                <MapPin size={13} className="text-rose-500" /> Googleマップでピンを立てて保存
              </span>
              {mapPinQuery && (
                <button
                  type="button"
                  onClick={() => {
                    setMapPinQuery('');
                    customAlert('固定ピンを解除しました');
                  }}
                  className="text-[10px] font-bold text-stone-400 hover:text-rose-500 underline"
                >
                  ピン解除
                </button>
              )}
            </div>

            <div className="flex gap-1.5">
              <input
                type="text"
                value={mapSearchInput}
                onChange={e => setMapSearchInput(e.target.value)}
                placeholder="店名・住所・座標(35.01,135.76)・マップURLを貼付"
                className="flex-1 p-2 bg-white border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
              <button
                type="button"
                onClick={handleLockPin}
                className="px-3 py-2 bg-[#7A9D8C] hover:bg-[#688a79] text-white font-extrabold rounded-xl text-[11px] shrink-0 flex items-center gap-1 shadow-2xs active:scale-95"
              >
                <MapPin size={12} /> ピンを固定
              </button>
            </div>

            <div className="w-full h-44 rounded-xl overflow-hidden border border-stone-200 bg-stone-100 relative shadow-inner">
              <iframe
                title="Google Map Pin Preview"
                width="100%"
                height="100%"
                style={{ border: 0 }}
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                src={`https://maps.google.com/maps?q=${encodeURIComponent(
                  extractPinQuery(mapSearchInput || activePinTarget)
                )}&t=m&z=15&output=embed&iwloc=near`}
              />
            </div>

            <div className="flex items-center justify-between gap-2 text-[10px] text-stone-500 leading-snug">
              <span>💡 Googleマップの共有リンクや座標を貼っても固定できます</span>
              <a
                href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
                  extractPinQuery(mapSearchInput || activePinTarget)
                )}`}
                target="_blank"
                rel="noopener noreferrer"
                className="shrink-0 px-2 py-1 bg-white border border-stone-200 rounded-lg font-bold text-stone-700 hover:bg-stone-100 flex items-center gap-0.5"
              >
                <ExternalLink size={10} /> 別タブで探す
              </a>
            </div>
          </div>
        )}
      </div>

      <div>
        <label className="text-[10px] font-bold text-stone-400 block mb-0.5">メモ（やりたいこと・予約番号など）</label>
        <textarea
          value={memo}
          onChange={e => setMemo(e.target.value)}
          rows="2"
          placeholder="予約番号やメモを入力..."
          className="w-full p-2 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] resize-none"
        />
      </div>

      <div className="flex gap-2 pt-1">
        <button
          type="button"
          onClick={onCancel}
          className="flex-1 py-2.5 bg-stone-100 text-stone-600 rounded-xl text-xs font-bold hover:bg-stone-200 transition-colors"
        >
          キャンセル
        </button>
        <button
          type="submit"
          className="flex-[2] py-2.5 bg-[#7A9D8C] text-white rounded-xl text-xs font-bold shadow-sm hover:bg-[#688a79] transition-colors flex items-center justify-center gap-1"
        >
          <Check size={14} /> 予定を追加
        </button>
      </div>
    </form>
  );
}

// タイムライン内の単体スポットAI提案モーダル（前後の時間・場所反映＆Googleマップ確認リンク付き）
function EventAiSuggestModal({ trip, routeContext, onClose, onSelect }) {
  useLockBodyScroll(true);
  const dest = trip.destination || '京都府';
  const targetTime = routeContext?.time || '13:30';
  const targetHour = Number((targetTime || '13:30').split(':')[0]) || 13;
  const defaultCat =
    targetHour >= 11 && targetHour <= 13
      ? 'ご当地ランチ'
      : targetHour >= 14 && targetHour <= 16
      ? 'カフェ・甘味処'
      : '絶景・写真スポット';

  const [category, setCategory] = useState(defaultCat);
  const [customAiSpots, setCustomAiSpots] = useState(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [quotaStatus, setQuotaStatus] = useState(() => getAiQuotaStatus());
  const [showRewardAd, setShowRewardAd] = useState(false);
  const CATEGORIES = ['カフェ・甘味処', '絶景・写真スポット', 'ご当地ランチ', 'お土産・雑貨屋', '癒やし・足湯'];

  const routeAreaHint = routeContext?.prevLocation || routeContext?.nextLocation || dest;
  const routeNotePrefix =
    routeContext && (routeContext.prevLocation || routeContext.nextLocation)
      ? `【📍${routeContext.prevLocation || '出発地'}${routeContext.nextLocation ? ` → ${routeContext.nextLocation}` : ''} の移動ルート周辺・${targetTime}頃】`
      : '';

  // ジャンル切り替え時はまずキャッシュ（コスト0円）を表示
  useEffect(() => {
    const cacheKey = `spot_${dest}_${routeAreaHint}_${category}_${targetTime}`;
    const cached = getCachedAiResponse(cacheKey);
    setCustomAiSpots(cached || null);
  }, [dest, routeAreaHint, category, targetTime]);

  const handleGenerateByGemini = async () => {
    const cacheKey = `spot_${dest}_${routeAreaHint}_${category}_${targetTime}`;
    const cached = getCachedAiResponse(cacheKey);
    if (cached) {
      setCustomAiSpots(cached);
      customAlert('⚡ 保存済みキャッシュから高速表示しました（AI枠消費なし）');
      return;
    }

    const quotaCheck = consumeAiQuota();
    setQuotaStatus(quotaCheck.status);
    if (!quotaCheck.ok) {
      setShowRewardAd(true);
      return;
    }

    setIsAiLoading(true);
    try {
      const schema = {
        type: "ARRAY",
        items: {
          type: "OBJECT",
          properties: {
            title: { type: "STRING" },
            location: { type: "STRING" },
            type: { type: "STRING" },
            time: { type: "STRING" },
            cost: { type: "INTEGER" },
            memo: { type: "STRING" }
          },
          propertyOrdering: ["title", "location", "type", "time", "cost", "memo"]
        }
      };
      const aiSpots = await callGoogleGeminiStructured({
        systemPrompt: "あなたは日本の旅行ガイドAIです。実在する評価の高い店舗・観光スポットを3件、JSON配列で返してください。typeは meal, sightseeing, active のいずれかにしてください。",
        userPrompt: `エリア:${dest}（${routeAreaHint}周辺）、時間帯:${targetTime}頃、ジャンル:${category}。${routeNotePrefix}で立ち寄りやすい実在スポット3選を提案してください。`,
        responseSchema: schema
      });
      if (Array.isArray(aiSpots) && aiSpots.length > 0) {
        setCustomAiSpots(aiSpots);
        setCachedAiResponse(cacheKey, aiSpots);
        customAlert('✨ Google AIで最新スポット候補を生成しました！');
      }
    } catch (e) {
      customAlert('通信状況により定番キャッシュデータを表示しています');
    } finally {
      setIsAiLoading(false);
    }
  };

  const spotSuggestions = useMemo(() => {
    if (Array.isArray(customAiSpots) && customAiSpots.length > 0) return customAiSpots;
    const SPOT_BY_AREA = {
      '京都': {
        'カフェ・甘味処': [
          { title: '中村藤吉本店 宇治本店（生茶ゼリイ）', location: '中村藤吉本店', time: targetTime, cost: 1650, memo: `${routeNotePrefix}【★4.4 / レビュー4,200件超】安政元年創業の老舗茶商。竹筒に入った名物「生茶ゼリイ［抹茶］」は濃厚な抹茶の旨味と白玉が絶品。` },
          { title: 'ぎおん徳屋（本わらびもち）', location: 'ぎおん徳屋', time: targetTime, cost: 1500, memo: `${routeNotePrefix}【★4.4 / 食べログ百名店】注文ごとに練り上げるトロトロの本わらびもちが名物。花見小路近くで観光の合間に最適。` },
          { title: 'アラビカ京都 東山（% ARABICA）', location: 'アラビカ京都 東山', time: targetTime, cost: 700, memo: `${routeNotePrefix}【★4.3 / 八坂の塔すぐそば】世界的に人気のスペシャルティコーヒー専門店。濃厚なカフェラテ片手に東山散策が定番。` }
        ],
        '絶景・写真スポット': [
          { title: '伏見稲荷大社 千本鳥居', location: '伏見稲荷大社', time: targetTime, cost: 0, memo: `${routeNotePrefix}【★4.6 / 世界的人気の絶景】朱色の鳥居がどこまでも連なる幻想的な参道。四ツ辻まで登ると京都市街を一望できます。` },
          { title: '南禅寺 水路閣（レトロ赤レンガアーチ）', location: '南禅寺 水路閣', time: targetTime, cost: 0, memo: `${routeNotePrefix}【★4.5 / 明治の近代化遺産】境内に佇むローマ水道橋風のレンガアーチ。どこを切り取っても絵になるフォトスポット。` },
          { title: '法観寺 八坂の塔（東山通り）', location: '法観寺 八坂の塔', time: targetTime, cost: 0, memo: `${routeNotePrefix}【★4.4 / 京都らしい風情No.1】石畳の坂道の先に五重塔がそびえる定番アングル。夕暮れ時のマジックアワーが特に美しい。` }
        ],
        'ご当地ランチ': [
          { title: '南禅寺 順正（名物・京ゆどうふ）', location: '南禅寺 順正', time: targetTime, cost: 3500, memo: `${routeNotePrefix}【★4.3 / 登録有形文化財の庭園】美しい回遊式庭園を眺めながら、滑らかな京ゆどうふや田楽を味わえる老舗名店。` },
          { title: '山元麺蔵（手打ち京うどん・土ゴボウ天）', location: '山元麺蔵', time: targetTime, cost: 1600, memo: `${routeNotePrefix}【★4.5 / 京都屈指の行列店】力強いコシと喉越しの手打ちうどんに、香ばしい土ゴボウ天ぷらが相性抜群。` },
          { title: '先斗町 柚子元（名物・柚子鍋＆餃子）', location: '先斗町 柚子元', time: targetTime, cost: 2200, memo: `${routeNotePrefix}【★4.2 / 爽やかな柚子の香り】風情ある先斗町の人気店。香り高い柚子スープの麺類や名物餃子が口コミで評判。` }
        ],
        'お土産・雑貨屋': [
          { title: '錦市場商店街（京の台所食べ歩き＆お土産）', location: '錦市場', time: targetTime, cost: 2000, memo: `${routeNotePrefix}【★4.3 / 約400mのアーケード】京漬物、だし巻き卵、豆乳ドーナツなど京都の味覚と手土産が一度に揃う名所。` },
          { title: 'よーじや 祇園本店（あぶらとり紙・限定コスメ）', location: 'よーじや 祇園本店', time: targetTime, cost: 1500, memo: `${routeNotePrefix}【★4.2 / 京都土産の定番】定番のあぶらとり紙はもちろん、まゆごもりシリーズのハンドクリームや限定雑貨が人気。` }
        ],
        '癒やし・足湯': [
          { title: '嵐山駅 駅の足湯（天然温泉＆京友禅の光林）', location: '嵐山駅はんなり・ほっこりスクエア', time: targetTime, cost: 300, memo: `${routeNotePrefix}【★4.3 / オリジナルタオル付き】歩き疲れた足を嵐山温泉の足湯でリフレッシュ。駅構内の「キモノフォレスト」も必見。` },
          { title: '京都嵐山温泉 風風の湯（日帰り天然温泉）', location: '京都嵐山温泉 風風の湯', time: targetTime, cost: 1300, memo: `${routeNotePrefix}【★4.1 / 渡月橋すぐそば】露天風呂やサウナを備えた日帰り温泉施設。観光の締めくくりにさっぱり汗を流せます。` }
        ]
      }
    };

    const areaKey = Object.keys(SPOT_BY_AREA).find(k => dest.includes(k) || routeAreaHint.includes(k));
    if (areaKey && SPOT_BY_AREA[areaKey][category]) {
      return SPOT_BY_AREA[areaKey][category].map(item => ({
        ...item,
        type: category.includes('ランチ') || category.includes('カフェ') ? 'meal' : category.includes('癒やし') ? 'active' : 'sightseeing'
      }));
    }

    const cleanArea = (routeAreaHint || dest).replace(/[都道府県]$/, '') || '現地';
    return [
      {
        title: `${cleanArea}周辺 高評価${category}（★4.4人気店）`,
        location: `${cleanArea} ${category.split('・')[0]}`,
        type: category.includes('ランチ') || category.includes('カフェ') ? 'meal' : 'sightseeing',
        time: targetTime,
        cost: 1800,
        memo: `${routeNotePrefix}【★4.4 / 立ち寄りやすい名店】前後の予定の移動ルート上で無理なく立ち寄れる${cleanArea}エリアの人気${category}スポット。`
      },
      {
        title: `${cleanArea} 老舗・隠れ家${category.split('・')[0]}`,
        location: `${cleanArea} 老舗 ${category.split('・')[0]}`,
        type: category.includes('ランチ') || category.includes('カフェ') ? 'meal' : 'sightseeing',
        time: targetTime,
        cost: 1500,
        memo: `${routeNotePrefix}【★4.3 / 落ち着いた空間】${targetTime}頃の休憩・立ち寄りにぴったりな高評価スポット。`
      },
      {
        title: `${cleanArea} 定番の${category}名所`,
        location: `${cleanArea} 観光 ${category.split('・')[0]}`,
        type: category.includes('癒やし') ? 'active' : 'sightseeing',
        time: targetTime,
        cost: 2200,
        memo: `${routeNotePrefix}【★4.5 / 初めてならここ】写真映えする看板メニューや景色が揃う定番スポット。`
      }
    ];
  }, [dest, category, targetTime, routeAreaHint, routeNotePrefix, customAiSpots]);

  return (
    <div className="fixed inset-0 bg-black/50 z-[250] flex justify-center items-center p-4 animate-in fade-in" onClick={onClose}>
      <div className="bg-white w-full max-w-md rounded-[32px] p-6 shadow-2xl max-h-[85vh] overflow-y-auto no-scrollbar" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-2">
          <h3 className="font-bold text-base text-stone-800 flex items-center gap-1.5">
            <Sparkles size={18} className="text-sky-500" /> AIおすすめスポット提案 ({dest})
          </h3>
          <button onClick={onClose} className="p-1 text-stone-400 hover:bg-stone-100 rounded-full"><X size={20} /></button>
        </div>

        {/* API節約＆残り回数バー */}
        <div className="mb-3 px-3 py-2 rounded-2xl bg-stone-50 border border-stone-200/80 flex items-center justify-between gap-2 text-[10px] font-bold">
          <span className="text-emerald-700 flex items-center gap-1">
            ⚡ 初回表示は定番キャッシュ（AI枠消費0）
          </span>
          <div className="flex items-center gap-1.5 shrink-0">
            {quotaStatus.remaining > 0 ? (
              <span className="px-2.5 py-0.5 rounded-full bg-sky-50 border border-sky-200 text-sky-800 font-extrabold">
                ✨ AI残り {quotaStatus.remaining}回
              </span>
            ) : (
              <button
                type="button"
                onClick={() => setShowRewardAd(true)}
                className="px-2.5 py-0.5 rounded-full bg-amber-400 hover:bg-amber-500 text-stone-950 font-extrabold shadow-2xs animate-pulse cursor-pointer"
              >
                🎬 残り0回（動画で+{REWARD_AD_BONUS_COUNT}回復活）
              </button>
            )}
          </div>
        </div>

        {routeContext && (routeContext.prevLocation || routeContext.nextLocation) && (
          <div className="mb-3 p-3 bg-sky-50 border border-sky-200/80 rounded-2xl text-[11px] font-bold text-sky-900 space-y-0.5">
            <p className="text-[10px] text-sky-600 font-extrabold">⏱️ 前後の予定・ルートを自動反映中（{targetTime}頃）</p>
            <p className="truncate">
              {routeContext.prevLocation ? `${routeContext.prevTime} ${routeContext.prevLocation}` : '出発'}
              {routeContext.nextLocation ? ` → ${routeContext.nextTime} ${routeContext.nextLocation}` : ''}
            </p>
          </div>
        )}

        <div className="flex items-center justify-between gap-2 mb-3">
          <p className="text-xs text-stone-500">気になるジャンルを選ぶと予定へ反映できます。</p>
          <button
            type="button"
            disabled={isAiLoading}
            onClick={handleGenerateByGemini}
            className="shrink-0 px-2.5 py-1.5 rounded-xl bg-sky-100 hover:bg-sky-200 text-sky-900 border border-sky-300 text-[10px] font-extrabold flex items-center gap-1 disabled:opacity-50"
          >
            <Sparkles size={11} className="text-sky-600" />
            {isAiLoading ? 'Google AI生成中...' : 'Google AIで深掘り生成'}
          </button>
        </div>

        <div className="flex flex-wrap gap-1.5 mb-4">
          {CATEGORIES.map(c => (
            <button
              key={c}
              type="button"
              onClick={() => setCategory(c)}
              className={`px-3 py-1.5 rounded-full text-xs font-bold border transition-all ${
                category === c
                  ? 'bg-[#5E8473] text-white border-[#5E8473] shadow-2xs'
                  : 'bg-stone-50 text-stone-600 border-stone-200 hover:bg-stone-100'
              }`}
            >
              {c}
            </button>
          ))}
        </div>

        <div className="space-y-3">
          {spotSuggestions.map((spot, idx) => (
            <div key={idx} className="p-3.5 rounded-2xl bg-stone-50 border border-stone-200/80 space-y-2">
              <div className="flex justify-between items-start gap-2">
                <div>
                  <h4 className="font-bold text-xs text-stone-800">{spot.title}</h4>
                  <p className="text-[10px] text-stone-500 font-bold mt-0.5 flex items-center gap-1">
                    <MapPin size={10} className="text-red-500" /> {spot.location} / 目安 ¥{spot.cost.toLocaleString()}
                  </p>
                </div>
                <a
                  href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(spot.location)}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="px-2.5 py-1.5 rounded-xl bg-emerald-50 hover:bg-emerald-100 text-emerald-700 border border-emerald-200/80 text-[10px] font-bold flex items-center gap-1 shrink-0 transition-colors"
                >
                  <ExternalLink size={11} /> マップで確認
                </a>
              </div>
              <p className="text-[11px] text-stone-600 bg-white p-2 rounded-xl border border-stone-100">{spot.memo}</p>
              <button
                type="button"
                onClick={() => onSelect(spot)}
                className="w-full py-2.5 bg-gradient-to-r from-sky-100 via-sky-200/80 to-cyan-100 hover:brightness-95 text-sky-900 border border-sky-300/80 font-extrabold rounded-xl text-xs transition-all flex items-center justify-center gap-1 shadow-2xs active:scale-[0.99]"
              >
                <Plus size={14} className="text-sky-600" /> この予定を追加フォームに反映
              </button>
            </div>
          ))}
        </div>

        {showRewardAd && (
          <RewardVideoAdModal
            onClose={() => setShowRewardAd(false)}
            onCompleteReward={(next) => setQuotaStatus(next)}
          />
        )}
      </div>
    </div>
  );
}

// ------------------------------------------
// タイムラインの各予定カード (EventCard)
// ------------------------------------------
function EventCard({ event, prevEvent = null, nextEvent = null, trip, isReadOnly, currentUser, isClosestNow = false, isPassedEvent = false, betweenNowProgress = null, suitcasePositionProgress = null, currentNowTimeStr = '', insertButtonSlot = null, onApprove, onUpdateEvent, onUpdateMemo, onDelete, onCopy, onAddPhoto, onTogglePhotoPublic, onRequestDeletePhoto, canDeletePhoto, onEnlargeImage }) {
  const defaultOrigin = useMemo(() => getHomeDepartureLabel(currentUser), [currentUser]);
  const addMinutesToTime = (tStr, minsToAdd = 60) => {
    if (!tStr || !tStr.includes(':')) return '13:00';
    const [h, m] = tStr.split(':').map(Number);
    const total = ((isNaN(h) ? 12 : h) * 60 + (isNaN(m) ? 0 : m) + minsToAdd) % (24 * 60);
    return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
  };
  const [isEditingEvent, setIsEditingEvent] = useState(false);
  const [editTime, setEditTime] = useState(event.time || '12:00');
  const [editEndTime, setEditEndTime] = useState(event.endTime || '');
  const [editTitle, setEditTitle] = useState(event.title || '');
  const [editType, setEditType] = useState(event.type || 'sightseeing');
  const [editDepartureOrigin, setEditDepartureOrigin] = useState(event.departureOrigin || trip.departurePoint || defaultOrigin);
  const [editTransportMethod, setEditTransportMethod] = useState(event.transportMethod || trip.transportMethod || 'shinkansen_train');
  const [editLocation, setEditLocation] = useState(event.location || '');
  const [editMapPinQuery, setEditMapPinQuery] = useState(event.mapPinQuery || '');
  const [showEditMapPicker, setShowEditMapPicker] = useState(false);
  const [editCost, setEditCost] = useState(event.cost ? String(event.cost) : '');
  const [editMemo, setEditMemo] = useState(event.memo || '');

  const [isMemoOpen, setIsMemoOpen] = useState(false);
  const [isEditingMemo, setIsEditingMemo] = useState(false);
  const [memoText, setMemoText] = useState(event.memo || '');
  const photoInputRef = useRef(null);

  useEffect(() => {
    setMemoText(event.memo || '');
    setEditTime(event.time || '12:00');
    setEditEndTime(event.endTime || '');
    setEditTitle(event.title || '');
    setEditType(event.type || 'sightseeing');
    setEditDepartureOrigin(event.departureOrigin || trip.departurePoint || defaultOrigin);
    setEditTransportMethod(event.transportMethod || trip.transportMethod || 'shinkansen_train');
    setEditLocation(event.location || '');
    setEditMapPinQuery(event.mapPinQuery || '');
    setEditCost(event.cost ? String(event.cost) : '');
    setEditMemo(event.memo || '');
  }, [event, trip.departurePoint, trip.transportMethod, defaultOrigin]);

  const parsePinQuery = (rawInput) => {
    const val = (rawInput || '').trim();
    if (!val) return '';
    const atCoordMatch = val.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
    if (atCoordMatch) return `${atCoordMatch[1]},${atCoordMatch[2]}`;
    const placeMatch = val.match(/\/place\/([^/?]+)/);
    if (placeMatch) return decodeURIComponent(placeMatch[1].replace(/\+/g, ' '));
    const qMatch = val.match(/[?&](?:q|query)=([^&]+)/);
    if (qMatch) return decodeURIComponent(qMatch[1].replace(/\+/g, ' '));
    return val;
  };

  const handleSaveFullEventEdit = (e) => {
    e.preventDefault();
    const isTransport = editType === 'transport';
    const selectedTag = QUICK_TAGS.find(t => t.id === editType) || QUICK_TAGS[2];
    const finalTitle = editTitle.trim() || selectedTag.defaultTitle;
    const finalLocation = editLocation.trim() || editMapPinQuery.trim();
    const finalPinQuery = parsePinQuery(editMapPinQuery.trim() || finalLocation);
    if (onUpdateEvent) {
      onUpdateEvent({
        time: editTime || '12:00',
        endTime: editEndTime || '',
        title: finalTitle,
        type: editType,
        departureOrigin: isTransport ? editDepartureOrigin.trim() : '',
        transportMethod: isTransport ? editTransportMethod : '',
        location: finalLocation,
        mapPinQuery: finalPinQuery,
        cost: Number(editCost) || 0,
        memo: editMemo.trim()
      });
    }
    setIsEditingEvent(false);
    setShowEditMapPicker(false);
    customAlert('予定の内容を更新しました！');
  };

  const tagInfo = QUICK_TAGS.find(t => t.id === event.type) || QUICK_TAGS[2];
  const TagIcon = tagInfo.icon;
  const isTransportEvent = event.type === 'transport';
  const author = (isReadOnly && !ENABLE_PUBLIC_SNS_FEATURES)
    ? { id: OFFICIAL_ACCOUNT_PROFILE.id, name: 'たびたび公式', color: '#7A9D8C', isOfficial: true }
    : ((trip.members || []).find(m => m.id === event.authorId) || { name: trip.authorName || currentUser?.name || 'メンバー', color: '#7A9D8C', avatar: trip.authorAvatar || currentUser?.avatar });
  const isProposed = event.status === 'proposed' && !trip.isSoloTrip && !isReadOnly;
  const memberCount = Math.max(1, (trip.members || []).length);

  // カテゴリごとの淡いパステル背景色とアイコン色
  const tagStyleMap = {
    transport: 'bg-sky-50 text-sky-600 border-sky-200',
    meal: 'bg-orange-50 text-orange-500 border-orange-100',
    sightseeing: 'bg-emerald-50 text-[#557465] border-emerald-100',
    active: 'bg-amber-50 text-amber-600 border-amber-100',
    hotel: 'bg-indigo-50 text-indigo-500 border-indigo-100'
  };
  const iconBadgeStyle = tagStyleMap[event.type] || tagStyleMap.sightseeing;

  const handleSaveMemo = () => {
    if (onUpdateMemo) onUpdateMemo(memoText);
    setIsEditingMemo(false);
    setIsMemoOpen(Boolean(memoText.trim()));
    customAlert('メモを保存しました');
  };

  // ★「群馬」「群馬県」などの県名のみの表記を具体的な場所名（草津温泉 湯畑・元祖 水沢うどん 大澤屋・伊香保温泉 石段街など）に自動変換し、Googleマップリンクを維持
  const concreteSpot = useMemo(
    () => normalizeConcreteEventSpot(event, trip?.destination),
    [event, trip?.destination]
  );
  const displaySpotLocation = concreteSpot.location;
  const resolvedMapDestination = parsePinQuery(
    concreteSpot.mapPinQuery || displaySpotLocation || event.title
  );

  const handleOpenNavigation = () => {
    const dest = encodeURIComponent(resolvedMapDestination);
    const travelMode =
      event.transportMethod === 'car'
        ? '&travelmode=driving'
        : event.transportMethod === 'shinkansen_train' || event.transportMethod === 'highway_bus'
        ? '&travelmode=transit'
        : '';
    // originを指定しない（またはCurrent Location）ことで、Googleマップが必ず端末の「現在地」を起点として経路ナビを起動する
    const navUrl = `https://www.google.com/maps/dir/?api=1&destination=${dest}${travelMode}`;
    window.open(navUrl, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="relative flex items-stretch group">
      {/* ① 左側：開始〜終了時刻表示＋タイムライン軸＋一番近い予定のピコンピコン点＋別要素の丸枠なしキャリーケース（🧳） */}
      <div className="w-[56px] shrink-0 flex flex-col justify-between select-none relative">
        {isPassedEvent && (
          <div
            className="absolute left-[47px] top-4 w-[2px] bg-sky-400/80 rounded-full pointer-events-none z-[5]"
            style={{
              height: betweenNowProgress !== null ? `${Math.round(betweenNowProgress * 100)}%` : '100%'
            }}
          />
        )}

        <div className={`flex items-start ${isTransportEvent ? 'pt-2' : 'pt-3'}`}>
          <div className="w-[40px] pr-1.5 text-right flex flex-col items-end">
            <span
              className={`text-[12px] font-extrabold font-mono tracking-tight leading-none ${
                isClosestNow ? 'text-sky-600' : 'text-stone-700'
              }`}
            >
              {event.time || '--:--'}
            </span>
            {event.endTime && (
              <span className="text-[9px] font-bold font-mono text-stone-400 leading-tight mt-0.5">
                ~{event.endTime}
              </span>
            )}
          </div>
          {/* 予定カードのタイムライン上の点（現在時刻に一番近い予定の点はピコンピコン波紋アニメーション） */}
          <div className="w-[16px] flex justify-center items-center relative z-10 mt-0.5">
            {isClosestNow ? (
              <div className="relative flex items-center justify-center w-4 h-4" title="現在時刻に一番近い予定">
                <span
                  className="absolute inline-flex w-6 h-6 rounded-full bg-sky-400/60 animate-ping"
                  style={{ animationDuration: '1.6s' }}
                />
                <span
                  className="absolute inline-flex w-4 h-4 rounded-full bg-sky-300/75 animate-pulse"
                  style={{ animationDuration: '1.2s' }}
                />
                <span className="relative inline-flex w-3 h-3 rounded-full bg-sky-500 border-2 border-white shadow-[0_0_10px_rgba(14,165,233,0.9)]" />
              </div>
            ) : (
              <div
                className={`w-2.5 h-2.5 rounded-full ring-4 ring-[#F4F7F5] transition-transform group-hover:scale-125 ${
                  isProposed
                    ? 'bg-amber-400'
                    : isPassedEvent
                    ? 'bg-sky-400'
                    : isTransportEvent
                    ? 'bg-sky-500'
                    : 'bg-[#7A9D8C]'
                }`}
              />
            )}
          </div>
        </div>

        {/* 予定の点とは別に、現在時刻のタイムライン軸上に直接配置される丸枠なしのキャリーケース（🧳） */}
        {suitcasePositionProgress !== null && (
          <div
            className="absolute left-[48px] -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none select-none flex items-center"
            style={{ top: `${Math.round(suitcasePositionProgress * 100)}%` }}
            title={`現在時刻 (${currentNowTimeStr})`}
          >
            <span className="text-[17px] leading-none block">🧳</span>
          </div>
        )}

        {insertButtonSlot && (
          <div className="absolute -bottom-[11px] left-[2px] z-30">
            {insertButtonSlot}
          </div>
        )}
      </div>

      {/* ③ 右側：予定カード本体（未承認「💡提案中の予定」カードは少し右側にずらして配置し、確定予定と一目で区別できるようにする） */}
      <div
        className={`flex-1 min-w-0 rounded-2xl shadow-xs border transition-all ${
          isProposed && !isEditingEvent ? 'ml-3.5 sm:ml-5' : ''
        } ${
          isEditingEvent
            ? 'bg-white p-3 border-2 border-[#7A9D8C] shadow-md'
            : isTransportEvent
            ? isProposed
              ? 'bg-amber-50/40 px-2.5 py-1.5 border-amber-300'
              : 'bg-sky-50/60 px-2.5 py-1.5 border-sky-200/90 hover:border-sky-300'
            : isClosestNow
            ? 'bg-white p-3 border-sky-300 ring-2 ring-sky-100/80 shadow-sm'
            : isProposed
            ? 'bg-amber-50/20 p-3 border-amber-300'
            : 'bg-white p-3 border-stone-200/80 hover:border-stone-300'
        }`}
      >
        {isEditingEvent && !isReadOnly ? (
          <form onSubmit={handleSaveFullEventEdit} className="space-y-3 animate-in fade-in">
            <div className="flex justify-between items-center">
              <span className="text-xs font-extrabold text-[#7A9D8C] flex items-center gap-1">
                <Edit2 size={13} /> 予定の内容を編集
              </span>
              <button
                type="button"
                onClick={() => setIsEditingEvent(false)}
                className="px-2.5 py-1 rounded-full bg-stone-100 hover:bg-rose-50 text-stone-600 hover:text-rose-600 border border-stone-200/80 text-[11px] font-extrabold flex items-center gap-1"
              >
                <X size={13} /> 閉じる
              </button>
            </div>

            <div className="grid grid-cols-5 gap-1">
              {QUICK_TAGS.map(tag => {
                const TIcon = tag.icon;
                const active = editType === tag.id;
                return (
                  <button
                    key={tag.id}
                    type="button"
                    onClick={() => setEditType(tag.id)}
                    className={`py-1.5 px-1 rounded-xl text-[10px] font-extrabold flex flex-col sm:flex-row items-center justify-center gap-0.5 border transition-all whitespace-nowrap ${
                      active
                        ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                        : 'bg-stone-50 text-stone-600 border-stone-200 hover:bg-stone-100'
                    }`}
                  >
                    <TIcon size={12} />
                    <span>{tag.label}</span>
                  </button>
                );
              })}
            </div>

            {/* 編集時も「移動」を選んだときだけ出発地点＆交通手段を表示 */}
            {editType === 'transport' && (
              <div className="space-y-2 p-2.5 bg-sky-50/60 border border-sky-200/80 rounded-2xl animate-in fade-in duration-150">
                <div>
                  <label className="text-[10px] font-extrabold text-sky-900 block mb-1 pl-0.5">
                    🚆 交通手段を選択（移動タブ専用）
                  </label>
                  <div className="grid grid-cols-3 gap-1">
                    {TRANSPORT_METHODS.map(m => (
                      <button
                        key={m.id}
                        type="button"
                        onClick={() => setEditTransportMethod(m.id)}
                        className={`py-1.5 px-1.5 rounded-xl text-[10px] font-extrabold border transition-all whitespace-nowrap flex items-center justify-center gap-1 ${
                          editTransportMethod === m.id
                            ? 'bg-[#5E8473] text-white border-[#5E8473]'
                            : 'bg-white text-stone-600 border-stone-200'
                        }`}
                      >
                        <span>{m.label.split(' ')[0]}</span>
                        <span>{m.short}</span>
                      </button>
                    ))}
                  </div>
                </div>
                <DepartureSelectorBox
                  user={currentUser}
                  value={editDepartureOrigin}
                  onChange={setEditDepartureOrigin}
                  label="この移動の出発地点"
                  compact
                />
              </div>
            )}

            <div className="p-2.5 bg-stone-50/90 border border-stone-200/80 rounded-2xl space-y-2">
              <div className="grid grid-cols-2 gap-2">
                <div className="min-w-0">
                  <label className="text-[10px] font-extrabold text-stone-600 block mb-0.5">開始時間</label>
                  <input
                    type="time"
                    value={editTime}
                    onChange={e => setEditTime(e.target.value)}
                    className="w-full min-w-0 h-9 px-2 bg-white border border-stone-200 rounded-xl text-xs font-mono font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] appearance-none"
                  />
                </div>
                <div className="min-w-0">
                  <div className="flex items-center justify-between mb-0.5">
                    <label className="text-[10px] font-extrabold text-stone-600">終わりの時間</label>
                    {editEndTime && (
                      <button type="button" onClick={() => setEditEndTime('')} className="text-[9px] font-bold text-stone-400 hover:text-rose-500">クリア</button>
                    )}
                  </div>
                  <input
                    type="time"
                    value={editEndTime}
                    onChange={e => setEditEndTime(e.target.value)}
                    className="w-full min-w-0 h-9 px-2 bg-white border border-stone-200 rounded-xl text-xs font-mono font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] appearance-none"
                  />
                </div>
              </div>
              <div className="flex items-center justify-between gap-1">
                <span className="text-[9px] font-bold text-stone-400">所要時間で終了セット:</span>
                <div className="flex items-center gap-1">
                  {[
                    { mins: 30, label: '+30分' },
                    { mins: 60, label: '+1時間' },
                    { mins: 90, label: '+1.5時間' },
                    { mins: 120, label: '+2時間' }
                  ].map(preset => {
                    const targetEnd = addMinutesToTime(editTime, preset.mins);
                    return (
                      <button
                        key={preset.mins}
                        type="button"
                        onClick={() => setEditEndTime(targetEnd)}
                        className={`px-1.5 py-0.5 rounded text-[9px] font-extrabold border ${
                          editEndTime === targetEnd
                            ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                            : 'bg-white text-stone-600 border-stone-200'
                        }`}
                      >
                        {preset.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-2">
              <div className="col-span-2 min-w-0">
                <label className="text-[10px] font-bold text-stone-400 block mb-0.5">予定のタイトル</label>
                <input
                  type="text"
                  value={editTitle}
                  onChange={e => setEditTitle(e.target.value)}
                  placeholder="予定のタイトル"
                  className="w-full h-9 px-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                />
              </div>
              <div className="min-w-0">
                <label className="text-[10px] font-bold text-stone-400 block mb-0.5">1人予算 (円)</label>
                <input
                  type="number"
                  inputMode="numeric"
                  value={editCost}
                  onChange={e => setEditCost(e.target.value)}
                  placeholder="0"
                  className="w-full min-w-0 h-9 px-2 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                />
              </div>
            </div>

            {editType === 'transport' && (
              <div className="p-2.5 bg-sky-50/80 border border-sky-200/90 rounded-xl space-y-1.5">
                <div className="flex items-center justify-between gap-1">
                  <span className="text-[10px] font-extrabold text-sky-950">
                    💰 出発地〜目的地の交通費候補（タップで予算に組み込む）:
                  </span>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-1">
                  {estimateTransportCostCandidates(editDepartureOrigin, editLocation || editTitle || trip.destination, editTransportMethod).map((cand, idx) => {
                    const isSelectedCost = Number(editCost) === cand.amount && editCost !== '';
                    return (
                      <button
                        key={idx}
                        type="button"
                        onClick={() => setEditCost(String(cand.amount))}
                        className={`px-2.5 py-1.5 rounded-lg text-left border transition-all flex items-center justify-between sm:flex-col sm:items-start ${
                          isSelectedCost
                            ? 'bg-sky-600 text-white border-sky-600'
                            : 'bg-white hover:bg-sky-100/60 text-sky-950 border-sky-200'
                        }`}
                      >
                        <span className="text-[10px] font-extrabold truncate">{cand.label}</span>
                        <span className={`text-[11px] font-mono font-extrabold ${isSelectedCost ? 'text-white' : 'text-sky-800'}`}>
                          ¥{cand.amount.toLocaleString()}
                        </span>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {/* 場所・駅・スポット名 ＆ すぐ近くにGoogleマップピン指定・確認ボタンを配置 */}
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-stone-400 block">場所・駅・スポット名</label>
              <input
                type="text"
                value={editLocation}
                onChange={(e) => setEditLocation(e.target.value)}
                placeholder="例: 福井県立恐竜博物館 / 駅名"
                className="w-full h-9 px-2.5 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
              />
              <button
                type="button"
                onClick={() => setShowEditMapPicker(!showEditMapPicker)}
                className={`w-full py-1.5 px-3 rounded-xl text-[11px] font-extrabold border flex items-center justify-center gap-1.5 transition-all ${
                  editMapPinQuery
                    ? 'bg-emerald-50 text-emerald-700 border-emerald-300'
                    : showEditMapPicker
                    ? 'bg-[#7A9D8C] text-white border-[#7A9D8C]'
                    : 'bg-stone-50 text-stone-700 border-stone-200 hover:bg-stone-100'
                }`}
              >
                <MapPin size={12} className={editMapPinQuery ? 'text-rose-500 fill-rose-500' : showEditMapPicker ? 'text-white' : 'text-[#7A9D8C]'} />
                <span>{editMapPinQuery ? `🗺️ ピン固定済: ${editMapPinQuery.slice(0, 12)}` : '🗺️ Googleマップでピンを指定・確認'}</span>
              </button>

              {showEditMapPicker && (
                <div className="p-3 bg-stone-50 rounded-2xl border border-stone-200 space-y-2">
                  <input
                    type="text"
                    value={editMapPinQuery}
                    onChange={e => setEditMapPinQuery(e.target.value)}
                    placeholder="ピンを立てる住所・座標(35.01,135.76)・マップURL"
                    className="w-full p-2 bg-white border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C]"
                  />
                  <div className="w-full h-40 rounded-xl overflow-hidden border border-stone-200 bg-stone-100">
                    <iframe
                      title="Edit Map Pin Preview"
                      width="100%"
                      height="100%"
                      style={{ border: 0 }}
                      loading="lazy"
                      src={`https://maps.google.com/maps?q=${encodeURIComponent(
                        parsePinQuery(editMapPinQuery || editLocation || editTitle || trip.destination || '東京駅')
                      )}&t=m&z=15&output=embed&iwloc=near`}
                    />
                  </div>
                </div>
              )}
            </div>

            <div>
              <label className="text-[10px] font-bold text-stone-400 block mb-0.5">メモ</label>
              <textarea
                value={editMemo}
                onChange={e => setEditMemo(e.target.value)}
                rows="3"
                placeholder="メモを入力..."
                className="w-full p-2 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] resize-none"
              />
            </div>

            <div className="flex gap-2 pt-1">
              <button
                type="button"
                onClick={() => setIsEditingEvent(false)}
                className="flex-1 py-2.5 bg-stone-100 text-stone-600 rounded-xl text-xs font-bold hover:bg-stone-200 transition-colors"
              >
                キャンセル
              </button>
              <button
                type="submit"
                className="flex-[2] py-2.5 bg-[#7A9D8C] text-white rounded-xl text-xs font-bold shadow-sm hover:bg-[#688a79] transition-colors flex items-center justify-center gap-1"
              >
                <Check size={14} /> 変更を保存する
              </button>
            </div>
          </form>
        ) : isTransportEvent ? (
          /* ★ 移動専用のスリム＆シンプル表示（どこから ➔ どこまで・何で移動するかが一目でわかるルートバー） */
          (() => {
            const methodMeta =
              TRANSPORT_METHODS.find(m => m.id === event.transportMethod) ||
              (/飛行機|空港|LCC|フライト/.test(event.title || '')
                ? TRANSPORT_METHODS[2]
                : /バス/.test(event.title || '')
                ? TRANSPORT_METHODS[3]
                : /フェリー|船/.test(event.title || '')
                ? TRANSPORT_METHODS[4]
                : /徒歩|自転車|散策|歩き/.test(event.title || '')
                ? TRANSPORT_METHODS[5]
                : /車|レンタカー|タクシー|ドライブ/.test(event.title || '')
                ? TRANSPORT_METHODS[1]
                : TRANSPORT_METHODS[0]);
            const methodEmoji = methodMeta.label.split(' ')[0] || '🚆';
            const methodShort = methodMeta.short || '移動';

            // 1) タイトル（「AからBへ」「A→B」「A〜B」）や前後の予定から「出発地」と「到着地」をきれいに抽出
            const cleanPlaceName = (str) =>
              (str || '')
                .replace(/（.*?）/g, '')
                .replace(/\(.*?\)/g, '')
                .replace(/(へ|まで)?(新幹線|電車|JR|特急|飛行機|バス|高速バス|夜行バス|車|レンタカー|タクシー|フェリー|船|徒歩|自転車|ドライブ|移動).*$/, '')
                .replace(/到着.*$/, '')
                .trim();

            const titleRouteMatch =
              (event.title || '').match(/^(.+?)から(.+?)(?:へ|まで|$)/) ||
              (event.title || '').match(/^(.+?)\s*(?:→|➔|⇒|〜|~|-)\s*(.+)$/);

            const fallbackPrevPlace =
              prevEvent?.location ||
              prevEvent?.title ||
              trip.departurePoint ||
              defaultOrigin;
            const fallbackNextPlace =
              nextEvent?.location ||
              nextEvent?.title ||
              trip.destination ||
              '目的地';

            const fromPlace =
              cleanPlaceName(event.departureOrigin) ||
              (titleRouteMatch ? cleanPlaceName(titleRouteMatch[1]) : '') ||
              cleanPlaceName(fallbackPrevPlace) ||
              '出発地';

            const toPlace =
              cleanPlaceName(event.location) ||
              (titleRouteMatch ? cleanPlaceName(titleRouteMatch[2]) : '') ||
              cleanPlaceName(fallbackNextPlace) ||
              '目的地';

            const handleOpenRouteNav = (e) => {
              e.stopPropagation();
              const travelMode =
                methodMeta.id === 'car'
                  ? '&travelmode=driving'
                  : methodMeta.id === 'bicycle_walk'
                  ? '&travelmode=walking'
                  : '&travelmode=transit';
              const navUrl =
                fromPlace && toPlace && fromPlace !== toPlace
                  ? `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(fromPlace)}&destination=${encodeURIComponent(toPlace)}${travelMode}`
                  : `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(toPlace || resolvedMapDestination)}${travelMode}`;
              window.open(navUrl, '_blank', 'noopener,noreferrer');
            };

            return (
              <div className="space-y-1">
                <div className="flex items-center justify-between gap-1.5">
                  {/* 左：交通手段ピル ＋ 「出発地 ➔ 目的地」のシンプルルート表示 */}
                  <div
                    onClick={() => { if (!isReadOnly) setIsEditingEvent(true); }}
                    className={`flex items-center gap-1.5 min-w-0 flex-1 flex-wrap ${!isReadOnly ? 'cursor-pointer hover:opacity-85' : ''}`}
                    title={!isReadOnly ? 'タップして移動区間・手段を編集' : undefined}
                  >
                    {/* 何で移動するか */}
                    <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded-md bg-sky-600 text-white text-[10px] font-extrabold shrink-0 shadow-2xs">
                      <span>{methodEmoji}</span>
                      <span>{methodShort}</span>
                    </span>

                    {/* どこから ➔ どこまで */}
                    <div className="inline-flex items-center gap-1 bg-white px-2 py-0.5 rounded-lg border border-sky-200/90 min-w-0 max-w-full shadow-2xs">
                      <span className="text-[11px] font-extrabold text-stone-800 truncate max-w-[92px] sm:max-w-[135px]">
                        {fromPlace}
                      </span>
                      <span className="text-sky-600 font-black text-xs shrink-0 px-0.5">➔</span>
                      <span className="text-[11px] font-extrabold text-sky-950 truncate max-w-[92px] sm:max-w-[135px]">
                        {toPlace}
                      </span>
                    </div>

                    {/* 金額（1人あたり × 参加人数） */}
                    {Number(event.cost) > 0 && (
                      <span className="text-[10px] font-extrabold text-sky-900 bg-white/90 px-1.5 py-0.5 rounded-md border border-sky-200/80 shrink-0">
                        ¥{Number(event.cost).toLocaleString()}/人{memberCount > 1 ? `×${memberCount}` : ''}
                      </span>
                    )}
                  </div>

                  {/* 右：承認・経路ナビ・編集・削除 */}
                  <div className="flex items-center gap-0.5 shrink-0">
                    {isProposed && (
                      <button
                        type="button"
                        onClick={onApprove}
                        className="px-2 py-0.5 bg-amber-500 hover:bg-amber-600 text-white rounded-md text-[9px] font-extrabold flex items-center gap-0.5 shadow-2xs transition-colors"
                        title="この移動予定を承認"
                      >
                        <Check size={10} strokeWidth={3} /> 承認
                      </button>
                    )}

                    <button
                      type="button"
                      onClick={handleOpenRouteNav}
                      className="px-2 py-0.5 bg-white hover:bg-blue-50 text-blue-600 rounded-lg text-[10px] font-extrabold inline-flex items-center gap-0.5 border border-blue-200 transition-all active:scale-95 shrink-0 cursor-pointer"
                      title={`${fromPlace}から${toPlace}までの経路ナビを起動`}
                    >
                      <Navigation size={10} className="shrink-0" /> 経路
                    </button>

                    {isReadOnly ? (
                      <button
                        type="button"
                        onClick={onCopy}
                        className="px-1.5 py-0.5 bg-[#7A9D8C]/10 hover:bg-[#7A9D8C]/20 text-[#557465] rounded text-[9px] font-bold"
                      >
                        コピー
                      </button>
                    ) : (
                      <>
                        <button
                          type="button"
                          onClick={() => setIsEditingEvent(true)}
                          className="text-stone-400 hover:text-[#7A9D8C] p-0.5 rounded hover:bg-white/70 transition-colors"
                          title="移動予定を編集"
                        >
                          <Edit2 size={12} />
                        </button>
                        <button
                          type="button"
                          onClick={onDelete}
                          className="text-stone-300 hover:text-red-500 p-0.5 rounded hover:bg-white/70 transition-colors"
                          title="削除"
                        >
                          <Trash2 size={12} />
                        </button>
                      </>
                    )}
                  </div>
                </div>

                {/* 移動メモがある場合のみ、1行のスリムな折りたたみバーを表示 */}
                {event.memo && (
                  <div>
                    {isMemoOpen ? (
                      <div className="p-2 bg-white/90 rounded-lg border border-sky-200 text-[11px] text-stone-700 space-y-1">
                        <div className="flex justify-between items-center text-[9px] font-bold text-sky-700">
                          <span>移動メモ</span>
                          <button type="button" onClick={() => setIsMemoOpen(false)} className="text-stone-400 hover:text-stone-600">
                            閉じる ▲
                          </button>
                        </div>
                        <p className="whitespace-pre-wrap leading-relaxed">{event.memo}</p>
                      </div>
                    ) : (
                      <button
                        type="button"
                        onClick={() => setIsMemoOpen(true)}
                        className="text-[10px] text-stone-500 hover:text-stone-700 font-bold flex items-center gap-1 truncate max-w-full text-left"
                      >
                        <FileText size={10} className="text-sky-600 shrink-0" />
                        <span className="truncate">{event.memo}</span>
                        <span className="text-[9px] text-stone-400 shrink-0">▼</span>
                      </button>
                    )}
                  </div>
                )}
              </div>
            );
          })()
        ) : (
          <>
            {isClosestNow && (
              <div className="mb-1.5 flex items-center justify-between bg-sky-50 border border-sky-200/80 px-2.5 py-1 rounded-xl">
                <span className="text-[10px] font-extrabold text-sky-700 flex items-center gap-1">
                  <Clock size={11} className="text-sky-500" /> 現在時刻に一番近い予定
                </span>
                {event.date === getTodayString() && (
                  <span className="text-[9px] font-bold text-sky-600 bg-white px-2 py-0.2 rounded-full border border-sky-200/60">
                    今日
                  </span>
                )}
              </div>
            )}

            {isProposed && (
              <div className="mb-2 flex items-center justify-between bg-amber-50 border border-amber-200/80 px-2.5 py-1 rounded-xl">
                <span className="text-[10px] font-bold text-amber-800 flex items-center gap-1">
                  💡 提案中の予定
                </span>
                <button
                  type="button"
                  onClick={onApprove}
                  className="px-2.5 py-0.5 bg-amber-500 hover:bg-amber-600 text-white rounded-lg text-[10px] font-bold flex items-center gap-1 shadow-2xs transition-colors"
                >
                  <Check size={11} strokeWidth={3} /> 承認
                </button>
              </div>
            )}

            {/* メイン行：上段にアイコン・時間帯・操作ボタンをまとめ、予定タイトルにはカードの横幅いっぱいを確保して不自然な改行を防止 */}
            <div className="space-y-1.5">
              <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2 min-w-0">
                  <div className={`w-7 h-7 rounded-full border flex items-center justify-center shrink-0 ${iconBadgeStyle}`}>
                    <TagIcon size={14} strokeWidth={2.2} />
                  </div>
                  <span className="text-[10px] font-extrabold text-stone-500 bg-stone-100 px-2 py-0.5 rounded-md shrink-0">
                    {tagInfo.label}
                  </span>
                  {event.endTime && (
                    <span className="text-[10px] font-mono font-extrabold text-[#557465] bg-[#7A9D8C]/12 px-1.5 py-0.5 rounded shrink-0">
                      {event.time}〜{event.endTime}
                    </span>
                  )}
                </div>

                {/* 右上アクション（コピー / 鉛筆編集 / 削除 / 作成者アイコン） */}
                <div className="flex items-center gap-0.5 shrink-0">
                  {isReadOnly ? (
                    <button
                      type="button"
                      onClick={onCopy}
                      className="px-2 py-0.5 bg-[#7A9D8C]/10 hover:bg-[#7A9D8C]/20 text-[#557465] rounded-lg text-[10px] font-bold flex items-center gap-1 transition-colors"
                      title="この予定をコピー"
                    >
                      <Copy size={11} /> コピー
                    </button>
                  ) : (
                    <>
                      <button
                        type="button"
                        onClick={() => setIsEditingEvent(true)}
                        className="text-stone-400 hover:text-[#7A9D8C] p-1 rounded-lg hover:bg-stone-50 transition-colors"
                        title="予定・メモを編集"
                      >
                        <Edit2 size={13} />
                      </button>
                      <button
                        type="button"
                        onClick={onDelete}
                        className="text-stone-300 hover:text-red-500 p-1 rounded-lg hover:bg-stone-50 transition-colors"
                        title="予定を削除"
                      >
                        <Trash2 size={13} />
                      </button>
                    </>
                  )}
                  <UserAvatar user={author} size="w-5 h-5" />
                </div>
              </div>

              {/* 予定タイトル：右端までフル幅を使い、自然な単語区切りでゆったり表示 */}
              <h4
                onClick={() => { if (!isReadOnly) setIsEditingEvent(true); }}
                style={{ wordBreak: 'keep-all', overflowWrap: 'anywhere' }}
                className={`w-full font-extrabold text-sm text-stone-800 leading-snug ${!isReadOnly ? 'cursor-pointer hover:text-[#557465] transition-colors' : ''}`}
                title={!isReadOnly ? 'タップして予定を編集' : undefined}
              >
                {event.title}
              </h4>

              {/* 予定名の下：場所（ピン指定時は下線付きGoogleマップリンク） / 予算 ＋ ナビボタン */}
              <div className="pt-0.5 flex flex-wrap items-center justify-between gap-1.5 text-[11px] font-bold text-stone-600">
                <div className="flex flex-wrap items-center gap-x-1.5 gap-y-0.5 min-w-0">
                  {(displaySpotLocation || event.mapPinQuery) && (
                    <a
                      href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(resolvedMapDestination)}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={(e) => e.stopPropagation()}
                      className="inline-flex items-center gap-0.5 text-stone-800 hover:text-[#4A6B5D] max-w-full truncate transition-colors"
                      title={`Googleマップで「${displaySpotLocation}」を開く`}
                    >
                      <MapPin size={11} className="text-rose-500 fill-rose-500 shrink-0" />
                      <span className="truncate underline decoration-2 underline-offset-2 decoration-[#7A9D8C]">
                        {displaySpotLocation}
                      </span>
                    </a>
                  )}

                  {(displaySpotLocation || event.mapPinQuery) && Number(event.cost) > 0 && (
                    <span className="text-stone-300 font-normal">/</span>
                  )}

                  {Number(event.cost) > 0 && (
                    <span className="inline-flex items-center gap-0.5 text-stone-700 font-extrabold">
                      <span>¥{Number(event.cost).toLocaleString()}</span>
                      {memberCount > 1 && <span className="text-[10px] text-[#557465]">(×{memberCount}人)</span>}
                    </span>
                  )}
                </div>

                {/* 現在地から目的地までの経路案内を起動する「ナビ」ボタン */}
                {(event.location || event.mapPinQuery || event.title) && (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleOpenNavigation();
                    }}
                    className="ml-auto px-3 py-1 bg-blue-50 hover:bg-blue-100 text-blue-600 rounded-xl text-xs font-extrabold inline-flex items-center gap-1 border border-blue-200 transition-all active:scale-95 shrink-0 shadow-2xs cursor-pointer"
                    title="現在地から目的地までのGoogleマップ経路ナビを起動"
                  >
                    <Navigation size={12} className="shrink-0" /> ナビ
                  </button>
                )}
              </div>
            </div>

            {/* ② 「メモ（大きめ比率 flex-1）」と「写真を追加（shrink-0）」を常に1列に横並び配置 */}
            {(event.memo || isEditingMemo || !isReadOnly || (Array.isArray(event.photos) && event.photos.length > 0)) && (
              <div className="mt-2 pt-2 border-t border-stone-100 space-y-2">
                {!isEditingMemo && (event.memo || !isReadOnly) && (
                  <div className="flex items-stretch gap-1.5">
                    {/* 左側：メモ領域（大きめ比率 flex-1） */}
                    {event.memo ? (
                      isMemoOpen ? (
                        <div className="flex-1 min-w-0 p-2.5 bg-stone-50 rounded-xl border border-stone-200/80 text-xs text-stone-700 space-y-1">
                          <div className="flex justify-between items-center text-[10px] font-bold text-stone-400">
                            <span className="flex items-center gap-1 text-[#557465]">
                              <FileText size={11} className="text-[#7A9D8C]" /> メモ
                            </span>
                            <div className="flex items-center gap-2">
                              {!isReadOnly && (
                                <button
                                  type="button"
                                  onClick={() => setIsEditingMemo(true)}
                                  className="text-[#7A9D8C] hover:underline font-extrabold"
                                >
                                  編集
                                </button>
                              )}
                              <button
                                type="button"
                                onClick={() => setIsMemoOpen(false)}
                                className="text-stone-400 hover:text-stone-600 font-extrabold"
                              >
                                閉じる ▲
                              </button>
                            </div>
                          </div>
                          <p className="whitespace-pre-wrap leading-relaxed text-[11px]">{event.memo}</p>
                        </div>
                      ) : (
                        <button
                          type="button"
                          onClick={() => setIsMemoOpen(true)}
                          className="flex-1 min-w-0 py-2 px-3 bg-stone-50 hover:bg-stone-100 rounded-xl border border-stone-200/80 flex items-center justify-between gap-2 text-xs font-bold text-stone-700 text-left transition-colors cursor-pointer"
                        >
                          <span className="flex items-center gap-1.5 min-w-0 flex-1">
                            <FileText size={13} className="text-[#7A9D8C] shrink-0" />
                            <span className="truncate">{event.memo}</span>
                          </span>
                          <span className="text-[10px] font-extrabold text-[#557465] shrink-0">メモ ▼</span>
                        </button>
                      )
                    ) : (
                      !isReadOnly && (
                        <button
                          type="button"
                          onClick={() => setIsEditingMemo(true)}
                          className="flex-1 min-w-0 py-2 px-3 bg-stone-50/80 hover:bg-stone-100 rounded-xl border border-dashed border-stone-300 flex items-center justify-between gap-2 text-xs font-extrabold text-stone-500 hover:text-stone-700 text-left transition-colors cursor-pointer"
                        >
                          <span className="flex items-center gap-1.5 truncate">
                            <FileText size={13} className="text-[#7A9D8C] shrink-0" />
                            <span className="truncate">メモ</span>
                          </span>
                          <span className="text-[10px] text-stone-400 font-bold shrink-0">＋追加入力</span>
                        </button>
                      )
                    )}

                    {/* 右側：写真を追加ボタン（コンパクト比率 shrink-0 で同じ1列に配置） */}
                    {!isReadOnly && (
                      <button
                        type="button"
                        onClick={() => photoInputRef.current?.click()}
                        className="shrink-0 py-2 px-2.5 rounded-xl bg-stone-50 hover:bg-stone-100 border border-stone-200/80 text-[11px] font-extrabold text-stone-600 hover:text-stone-800 inline-flex items-center justify-center gap-1 transition-colors cursor-pointer active:scale-95"
                      >
                        <Camera size={13} className="text-[#7A9D8C] shrink-0" />
                        <span className="whitespace-nowrap">写真を追加</span>
                      </button>
                    )}
                  </div>
                )}

                {isEditingMemo && (
                  <div className="space-y-1.5">
                    <div className="flex items-stretch gap-1.5">
                      <textarea
                        value={memoText}
                        onChange={e => setMemoText(e.target.value)}
                        rows="2"
                        placeholder="メモや予約番号を入力..."
                        className="flex-1 min-w-0 p-2 bg-stone-50 border border-stone-200 rounded-xl text-xs font-bold focus:outline-none focus:ring-2 focus:ring-[#7A9D8C] resize-none"
                      />
                      {!isReadOnly && (
                        <button
                          type="button"
                          onClick={() => photoInputRef.current?.click()}
                          className="shrink-0 px-2.5 rounded-xl bg-stone-50 hover:bg-stone-100 border border-stone-200 text-[10px] font-extrabold text-stone-600 inline-flex flex-col items-center justify-center gap-1"
                        >
                          <Camera size={13} className="text-[#7A9D8C]" />
                          <span className="whitespace-nowrap">写真を追加</span>
                        </button>
                      )}
                    </div>
                    <div className="flex justify-end gap-1.5">
                      <button
                        type="button"
                        onClick={() => {
                          setMemoText(event.memo || '');
                          setIsEditingMemo(false);
                        }}
                        className="px-2.5 py-1 rounded-lg bg-stone-100 text-stone-600 text-[10px] font-bold"
                      >
                        キャンセル
                      </button>
                      <button
                        type="button"
                        onClick={handleSaveMemo}
                        className="px-2.5 py-1 rounded-lg bg-[#7A9D8C] text-white text-[10px] font-bold"
                      >
                        保存
                      </button>
                    </div>
                  </div>
                )}

                {Array.isArray(event.photos) && event.photos.length > 0 && (
                  <div className="flex gap-2 overflow-x-auto no-scrollbar pb-0.5">
                    {event.photos.map((photo, pIdx) => (
                      <div
                        key={photo.id || pIdx}
                        className="relative w-16 h-16 rounded-xl overflow-hidden border border-stone-200 bg-stone-100 shrink-0 group/ph"
                      >
                        <img
                          src={photo.url}
                          alt="event memory"
                          onClick={() => onEnlargeImage && onEnlargeImage(photo.url)}
                          className="w-full h-full object-cover cursor-pointer"
                        />
                        {!isReadOnly && canDeletePhoto && canDeletePhoto(photo) && (
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              if (onRequestDeletePhoto) onRequestDeletePhoto(photo);
                            }}
                            className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 text-white flex items-center justify-center hover:bg-red-500 transition-colors"
                            title="写真を削除"
                          >
                            <Trash2 size={10} />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {!isReadOnly && (
                  <input
                    type="file"
                    ref={photoInputRef}
                    accept="image/*"
                    className="hidden"
                    onChange={async (e) => {
                      if (e.target.files?.[0]) {
                        const compressedUrl = await compressImageFile(e.target.files[0], 1200, 0.82);
                        if (compressedUrl && onAddPhoto) {
                          onAddPhoto(compressedUrl);
                        }
                        e.target.value = '';
                      }
                    }}
                  />
                )}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

