      '奈良', '吉野', '明日香', '法隆寺', '斑鳩', '十津川', '洞川温泉',
      '白浜', '南紀白浜', '高野山', '那智勝浦', '熊野本宮', '串本', '友ヶ島',
      '鳥取', '皆生温泉', '米子', '境港', '大山', '三朝温泉', '倉吉', '浦富',
      '出雲', '松江', '玉造温泉', '石見銀山', '足立美術館', '津和野', '隠岐',
